package com.pvp.leaderboard.lobby;

/**
 * Account-build types a player can advertise / fight as. Multi-select at
 * the gate (≥1 required) and rendered as cyan chips on each roster row.
 * This enum is the wire format on both sides — the server stores the
 * player's advertised builds, and the sender picks one of the opponent's
 * advertised builds when issuing an invite.
 *
 * <p><b>Declaration order is load-bearing.</b> Determines on-screen order
 * for the gate's toggle column AND the per-row chip strip (Main → Zerker
 * → Pure). {@code EnumSet} iteration follows declaration order, so the
 * current-style bar's build CSV always renders Main-first.
 */
public enum BuildType
{
    MAIN("Main"),
    ZERKER("Zerker"),
    PURE("Pure");

    public final String label;

    BuildType(String label)
    {
        this.label = label;
    }
}

package com.pvp.leaderboard.lobby;

/**
 * A pending mutual-confirm fight session. Created when either side enters
 * the mutual-confirm phase (sender's invite was accepted, OR receiver
 * clicked Accept Fight, OR the queue paired the two players). Pushed by the
 * server via {@code lobby/fight_proposed} to <b>both</b> sides; both must
 * confirm via {@code lobby/confirm} within {@link #confirmMs} or the
 * session ends with both players returned to the lobby (no penalty).
 *
 * <p>This type is the immutable bundle of context for the session. The
 * panel tracks {@code iConfirmed} / {@code peerConfirmed} as <b>local</b>
 * UI state separate from this — those flags are derived from the server's
 * push events ({@link LobbyEventListener#onFightConfirmedByPeer},
 * {@link LobbyEventListener#onMatchFound}) and from the local user clicking
 * the confirm button. Timer ownership lives in the service implementation,
 * keeping this type a pure data carrier.
 */
public final class FightSession
{
    /** The confirm window when the push does not carry a usable one. */
    public static final long CONFIRM_MS = 120_000L;

    public final String fightId;
    public final LobbyMember opponent;
    public final Style style;
    public final BuildType build;
    public final String location;
    public final long confirmByMs;
    /** How long the players have to confirm, counted from when the push arrives. */
    public final long confirmMs;

    /** A session with the {@link #CONFIRM_MS} confirm window. */
    public FightSession(String fightId, LobbyMember opponent, Style style, BuildType build,
                        String location, long confirmByMs)
    {
        this(fightId, opponent, style, build, location, confirmByMs, CONFIRM_MS);
    }

    public FightSession(String fightId, LobbyMember opponent, Style style, BuildType build,
                        String location, long confirmByMs, long confirmMs)
    {
        this.fightId = fightId;
        this.opponent = opponent;
        this.style = style;
        this.build = build;
        this.location = location;
        this.confirmByMs = confirmByMs;
        this.confirmMs = confirmMs;
    }
}

package com.pvp.leaderboard.lobby;

import java.util.*;

/**
 * Localized message lookup for {@code error/lobby} envelope codes. The
 * server sends a debug {@code message} field too but it's English-only
 * and subject to change without notice — the plugin must never display
 * the raw {@code message} directly, only the localized one from here.
 *
 * <p>Unknown codes fall back to a generic "Something went wrong" so a
 * server that introduces a new error code without a plugin release
 * doesn't surface a raw enum to the user.
 */
public final class LobbyErrors
{
    /** Generic fallback for codes the plugin's version of the map
     *  doesn't recognise. Intentionally vague — we don't know what
     *  happened, only that something failed. */
    public static final String UNKNOWN_FALLBACK = "Something went wrong. Try again in a moment.";

    /** {@code FIGHT_SESSION_EXPIRED}, and the queue's idle {@code reason} {@code expired}. */
    public static final String MATCH_EXPIRED = "Your match expired before both players confirmed.";

    /** Stable code → user-facing string map. Keep in sync with the
     *  server-side error enum every time a new code is added. */
    private static final Map<String, String> MESSAGES;
    static
    {
        Map<String, String> m = new HashMap<>();
        // ---- Join validation ----
        m.put("UNKNOWN_REGION",
            "That region isn't supported. Pick one from the dropdown and try again.");
        m.put("INVALID_STYLE",
            "One of your selected styles isn't supported. Reset options and try again.");
        m.put("INVALID_BUILD",
            "Your build pick isn't supported. Reset options and try again.");
        m.put("INVALID_LOCATION",
            "That fight location isn't supported. Pick a different one.");
        m.put("INVALID_DISPLAY_RANK",
            "Your rank range is invalid. Adjust the rank slider and try again.");
        m.put("SMURF_GUARD",
            "You need 20 kills or deaths in this style before you can queue for it. "
            + "Play casual PvP to build up your match count.");

        // ---- Invite / accept / confirm ----
        m.put("PEER_NOT_IN_LOBBY",
            "That player just left the lobby. Pick someone else.");
        m.put("RANK_OUT_OF_RANGE",
            "That player is outside your rank range. Widen your rank slider or pick someone else.");
        m.put("BLOCKED",
            "You can't fight this player — one of you has blocked the other.");
        m.put("DUPLICATE_INVITE",
            "You already have an outstanding invite to that player. Wait for the timer to expire "
            + "or cancel it from the lobby.");
        m.put("INVITE_EXPIRED",
            "That invite expired before you could accept it.");
        m.put("MATCHMAKING_SUSPENDED",
            "That player is suspended from matchmaking right now.");
        m.put("FIGHT_SESSION_EXPIRED", MATCH_EXPIRED);
        m.put("SELF_INVITE",
            "You can't fight your own account.");

        // ---- Protocol / transport ----
        m.put("INVALID_MESSAGE",
            "The plugin sent a message the server didn't understand. This is a plugin bug — please report it.");
        m.put("UNKNOWN_COMMAND",
            "The plugin sent a command the server doesn't support. The server may be older than your plugin "
            + "build — try again later.");

        MESSAGES = Collections.unmodifiableMap(m);
    }

    /** Look up the localized message for {@code code}, or
     *  {@link #UNKNOWN_FALLBACK} if the code is unrecognised / null /
     *  empty. Never returns {@code null}. */
    public static String forCode(String code)
    {
        if (code == null || code.isEmpty()) return UNKNOWN_FALLBACK;
        String msg = MESSAGES.get(code);
        return msg != null ? msg : UNKNOWN_FALLBACK;
    }

    /** Returns {@code true} if {@code code} is one the plugin knows about
     *  — useful for tests that want to assert wire-side codes have
     *  matching client-side translations (i.e. that we don't ship a
     *  build whose error UX is half-localized). */
    public static boolean isKnown(String code)
    {
        return code != null && MESSAGES.containsKey(code);
    }
}

package com.pvp.leaderboard.lobby;

import java.util.*;

/**
 * Server-push callbacks the panel registers with a {@link LobbyService} via
 * {@link LobbyService#setListener}. Every callback is invoked on Swing's
 * event-dispatch thread (EDT) — implementations of {@link LobbyService}
 * MUST marshal via {@code SwingUtilities.invokeLater} so listeners can
 * directly mutate Swing components.
 *
 * <p>Mirrors the server-to-client lobby command set ({@code lobby/roster},
 * {@code lobby/invite_received}, etc.). Method names follow the
 * {@code onSomething} convention rather than mirroring the wire command
 * names verbatim, because some events have no 1-to-1 wire equivalent
 * (e.g. {@link #onFightConfirmedByPeer} maps to
 * {@code lobby/fight_confirmed_by_peer} but is named for what the panel
 * does with it).
 *
 * <p>All methods are {@code default} no-ops so implementations override
 * only the events they care about (e.g. unit tests that only assert one
 * callback fires).
 */
public interface LobbyEventListener
{

    /** An invite — either one the local user sent and the opponent
     *  accepted, OR one the local user just accepted — has transitioned to
     *  the mutual-confirm phase. Panel switches to its ConfirmFight
     *  view. Both players see this event simultaneously. */
    default void onFightProposed(FightSession session) {}

    /** The peer has confirmed the active fight session, but the local user
     *  hasn't yet. Panel flips the ConfirmFight subheader from
     *  "Waiting on other player" to "Confirmed by other player" (or shows
     *  "Confirmed by other player" if the local user is the slow one). */
    default void onFightConfirmedByPeer(String fightId) {}

    /** Both players have confirmed; here's the meeting world and place.
     *  Panel transitions to its terminal Meet-At view. */
    default void onMatchFound(MatchInfo match) {}

    /** The confirm window elapsed without both players confirming.
     *  Panel returns the user to the lobby with no penalty. */
    default void onFightSessionExpired(String fightId) {}

    /** An operation failed with a stable error code from the server's
     *  error envelope (e.g. {@code INVITE_EXPIRED}, {@code RANK_OUT_OF_RANGE},
     *  {@code BLOCKED}). Panel renders human-readable text via
     *  {@link LobbyErrors} — never the raw code. */
    default void onError(String code, String message) {}

    /** Authoritative snapshot of canonical player IDs (lowercased display
     *  names) the local user has blocked. Pushed once on join and after
     *  every block/unblock the server applies. Panel uses this to gray
     *  out matching rows in the roster. */
    default void onBlockListSnapshot(Set<String> blockedIds) {}

    /** Cross-device delta: the local user (on another device or this one)
     *  just blocked {@code playerId}. Panel adds to its block set and
     *  re-renders the row. Mostly redundant with {@link #onBlockListSnapshot}
     *  since the server also re-pushes the full snapshot, but the delta
     *  arrives first so the UI feels snappier. */
    default void onBlockAdded(String playerId) {}

    /** Cross-device delta inverse of {@link #onBlockAdded}. Panel removes
     *  {@code playerId} from its block set and re-renders the row. */
    default void onBlockRemoved(String playerId) {}
}

package com.pvp.leaderboard.lobby;

import java.util.*;

/**
 * One row in the lobby roster. Server is source of truth; the panel
 * only reads this type and never mutates it.
 *
 * <p><b>Identity model</b>:
 * <ul>
 *   <li>{@link #playerId} — canonical, lowercased display name.
 *   Stable wire identifier used as the {@code to_player_id} /
 *   {@code blocked_player_id} value on outbound cmds and as the
 *   panel's map key for outgoing-invite and block-list state.</li>
 *   <li>{@link #name} — the display-cased name the player shows up as
 *   in-game (e.g. {@code "Toyco"} when {@link #playerId} is
 *   {@code "toyco"}). What the UI renders.</li>
 * </ul>
 *
 * <p>Instances are immutable — every field is {@code final} and the
 * {@link #styles}/{@link #builds} sets are wrapped in
 * {@link Collections#unmodifiableSet}.
 */
public final class LobbyMember
{

    public final String playerId;
    public final String name;
    public final Set<Style> styles;
    public final Set<BuildType> builds;
    /** All-time peak rank index (0..24) for the viewer's sort bucket. The
     *  big rank label rendered on each card. **Display-only** — never
     *  used as a matchmaking gate. -1 means no peak has been computed
     *  yet (brand-new player with no completed matches in this bucket). */
    public final int peakRankIdx;
    public final String region;

    /** Backwards-compatible ctor — defaults the new slider-bound fields
     *  to {@link #UNKNOWN_RANK_IDX}. Kept so test fixtures, the
     *  self-preview builder, and the lookup-row constructors don't
     *  have to thread two more args through every call site. */
    public LobbyMember(String playerId, String name, Set<Style> styles, Set<BuildType> builds,
                       int peakRankIdx, String region)
    {
        this.playerId = playerId;
        this.name = name;
        this.styles = styles == null
            ? Collections.unmodifiableSet(EnumSet.noneOf(Style.class))
            : Collections.unmodifiableSet(EnumSet.copyOf(styles));
        this.builds = builds == null
            ? Collections.unmodifiableSet(EnumSet.noneOf(BuildType.class))
            : Collections.unmodifiableSet(EnumSet.copyOf(builds));
        this.peakRankIdx = peakRankIdx;
        this.region = region;
    }
}

package com.pvp.leaderboard.lobby;

import java.util.*;
import java.util.logging.*;
import javax.inject.*;
import net.runelite.client.config.*;

/**
 * Persisted lobby gate preferences — region, advertised styles, advertised
 * builds, rank slider bounds, a "user already finished gate setup" sticky
 * flag, and a "user explicitly left the lobby" opt-out flag (suppresses
 * zero-config auto-join until a manual re-join).
 *
 * <p>The matchmaking panel reads through this on construction so a user who
 * has previously completed the gate is dropped straight into the lobby on
 * subsequent logins, with their picks pre-restored. {@link
 * com.pvp.leaderboard.ui.MatchmakingLobbyPanel#resetGateOptions()} writes
 * through to {@link #clear()} so the explicit "I want to re-pick" path
 * forgets everything.
 *
 * <p>Backed by RuneLite's {@link ConfigManager} — the values land in the
 * active RuneLite profile's config alongside the existing
 * {@code PvPLeaderboard.*} settings. The keys deliberately don't carry
 * {@code @ConfigItem} annotations because we don't want them to surface in
 * the RuneLite settings panel; they're hidden runtime state, not a user
 * setting.
 *
 * <p>An {@link #inMemory()} factory returns a no-op variant that keeps the
 * panel building without a real {@code ConfigManager} (unit tests, the
 * existing {@link com.pvp.leaderboard.lobby.NoOpLobby}-only call
 * sites). The in-memory variant simulates a fresh "no preferences yet" user
 * — every getter returns its supplied default and setters write to a local
 * map that's discarded when the JVM exits.
 */
@Singleton
public class LobbyPrefs
{
    private static final Logger LOG = Logger.getLogger(LobbyPrefs.class.getName());

    /** Same group used by {@link com.pvp.leaderboard.config.PvPLeaderboardConfig}
     *  so the values share a profile namespace with the existing
     *  user-facing settings. */
    public static final String CONFIG_GROUP = "PvPLeaderboard";

    public static final String KEY_REGION = "lobbyRegion";

    /** Plan 10 F.1 (2026-09-21): the queue's own picks — the wait preference
     *  (seconds, one of QueueService.WAIT_CHOICES; also the server-side
     *  shared pref) and the optional rank range for the queue, kept apart
     *  from the lobby slider so the two features never fight over one key. */
    public static final String KEY_WAIT = "queueWaitPrefS";
    public static final String KEY_RANGE_ON = "queueRangeEnabled";
    public static final String KEY_MIN_RANK = "queueMinRankIdx";
    public static final String KEY_MAX_RANK = "queueMaxRankIdx";

    /** The side panel's "Show streaks" switch. Not a lobby key: {@link #clear()} leaves it. */
    public static final String KEY_STREAKS = "sidePanelShowStreaks";;

    /** {@code null} ⇒ in-memory mode. */
    private final ConfigManager configManager;
    /** Backing store for in-memory mode. {@code null} when {@link #configManager}
     *  is non-null — we always use one or the other. */
    private final Map<String, String> memoryStore;

    @Inject
    public LobbyPrefs(ConfigManager configManager)
    {
        this.configManager = configManager;
        memoryStore = null;
    }

    private LobbyPrefs()
    {
        configManager = null;
        memoryStore = new HashMap<>();
    }

    /** No-persistence variant for unit tests + null-config call sites. The
     *  returned instance behaves identically to a fresh user (every getter
     *  returns its supplied default until a setter is called); writes are
     *  scoped to the returned instance and never escape the JVM. */
    public static LobbyPrefs inMemory()
    {
        return new LobbyPrefs();
    }

    // -------------------- Queue (Plan 10 F.1) --------------------

    public int getWaitPrefS(int defaultValue)
    {
        return readInt(KEY_WAIT, defaultValue);
    }

    public void setWaitPrefS(int seconds)
    {
        writeRaw(KEY_WAIT, Integer.toString(seconds));
    }

    public boolean getRangeOn()
    {
        return "true".equals(readRaw(KEY_RANGE_ON));
    }

    public void setRangeOn(boolean enabled)
    {
        writeRaw(KEY_RANGE_ON, Boolean.toString(enabled));
    }

    public int getMinRank(int defaultValue)
    {
        return readInt(KEY_MIN_RANK, defaultValue);
    }

    public void setMinRank(int idx)
    {
        writeRaw(KEY_MIN_RANK, Integer.toString(idx));
    }

    public int getMaxRank(int defaultValue)
    {
        return readInt(KEY_MAX_RANK, defaultValue);
    }

    public void setMaxRank(int idx)
    {
        writeRaw(KEY_MAX_RANK, Integer.toString(idx));
    }

    // -------------------- Side panel --------------------

    public boolean getShowStreaks()
    {
        return "true".equalsIgnoreCase(readRaw(KEY_STREAKS));
    }

    public void setShowStreaks(boolean shown)
    {
        writeRaw(KEY_STREAKS, Boolean.toString(shown));
    }

    // -------------------- Region --------------------

    public String getRegion(String defaultValue)
    {
        String raw = readRaw(KEY_REGION);
        return (raw == null || raw.isEmpty()) ? defaultValue : raw;
    }

    public void setRegion(String region)
    {
        writeRaw(KEY_REGION, region == null ? "" : region);
    }

    // -------------------- Internals --------------------

    private String readRaw(String key)
    {
        try
        {
            if (configManager != null)
            {
                return configManager.getConfiguration(CONFIG_GROUP, key);
            }
            return memoryStore.get(key);
        }
        catch (RuntimeException e)
        {
            LOG.log(Level.WARNING, "LobbyPreferences read failed for key " + key, e);
            return null;
        }
    }

    private void writeRaw(String key, String value)
    {
        try
        {
            if (configManager != null)
            {
                if (value == null)
                {
                    configManager.unsetConfiguration(CONFIG_GROUP, key);
                }
                else
                {
                    configManager.setConfiguration(CONFIG_GROUP, key, value);
                }
                return;
            }
            if (value == null)
            {
                memoryStore.remove(key);
            }
            else
            {
                memoryStore.put(key, value);
            }
        }
        catch (RuntimeException e)
        {
            LOG.log(Level.WARNING, "LobbyPreferences write failed for key " + key, e);
        }
    }

    private int readInt(String key, int defaultValue)
    {
        String raw = readRaw(key);
        if (raw == null || raw.isEmpty()) return defaultValue;
        try
        {
            return Integer.parseInt(raw.trim());
        }
        catch (NumberFormatException e)
        {
            return defaultValue;
        }
    }
}

