package com.pvp.leaderboard.lobby;

import java.util.*;

/**
 * Wire-protocol codec for the lobby's {@code location} field.
 *
 * <p>The {@link MatchmakingLobbyPanel}'s sub-location pickers
 * surface display strings — {@code "Arena"} / {@code "Wildy"} /
 * {@code "FFA Portal"} for NH and {@code "Wilderness"} /
 * {@code "Clan Wars"} for Multi — while the backend's
 * {@code ALLOWED_LOCATIONS_BY_STYLE} validator
 * (in {@code backend/core/lobby.py}) expects a tight canonical enum
 * {@code {arena, wildy, ffa, wilderness, clan_wars, none}} on the
 * wire. Without translation the picker would send {@code "FFA Portal"}
 * and the server would reject the invite with {@code INVALID_LOCATION}
 * before the row was even minted (operator report 2026-05-25 — exact
 * symptom on the screenshot of the {@code "That fight location isn't
 * supported. Pick a different one."} toast).
 *
 * <p>This codec is the single point of conversion at the wire
 * boundary in {@link WebSocketLobbyService}. The {@link
 * MatchmakingLobbyPanel}'s in-memory {@link OutgoingInvite} /
 * {@link IncomingInvite} / {@link FightSession} continue to carry
 * <strong>display</strong> strings so the existing UI render paths
 * ({@code inviteLabel}, {@code formatSetup},
 * {@code meetAtPlace}) read cleanly without churn.
 *
 * <p><strong>Symmetry with the backend.</strong> The backend has a
 * <em>lenient</em> validator layer (commit
 * {@code p2-lobby-location-display-aliases}, 2026-05-25) that also
 * accepts the plugin's display strings as aliases — kept as
 * defense-in-depth + back-compat for older plugin builds. With this
 * codec live, the wire is canonical end-to-end and the backend's
 * lenient layer is a no-op for new clients.
 *
 * <p><strong>Veng / DMM convention.</strong> Those styles have no
 * sub-location picker — the panel passes {@code null} or
 * {@code ""} when constructing invites. The backend's canonical
 * sentinel for "world-only, no sub-location" is the literal string
 * {@code "none"}. {@link #toCanonical} maps both
 * {@code (VENG, null)} and {@code (DMM, "")} (and every combination
 * thereof) to {@code "none"}; {@link #toDisplay} maps {@code "none"}
 * back to {@code ""} so the panel's render path falls through to
 * {@code inviteLabel}'s "PvP World" / "DMM World"
 * per-style default.
 */
public final class PlaceCodec
{

    /** canonical wire string → display string for the panel. */
    private static final Map<String, String> TO_DISPLAY;

    static
    {
        Map<String, String> c2d = new HashMap<>();
        c2d.put("arena",      "Arena");
        c2d.put("wildy",      "Wildy");
        c2d.put("ffa",        "FFA Portal");
        c2d.put("wilderness", "Wilderness");
        c2d.put("clan_wars",  "Clan Wars");
        // "none" is the world-only sentinel — render as empty so the
        // panel's existing inviteLabel(...) chooses the
        // "PvP World" / "DMM World" per-style default.
        c2d.put("none",       "");
        TO_DISPLAY = Collections.unmodifiableMap(c2d);
    }

    /**
     * Converts a server-canonical wire string back into the
     * picker-side display string the panel renders.
     *
     * <p>{@code null} / empty / unrecognised inputs pass through
     * (empty stays empty; unrecognised renders verbatim so it
     * surfaces in CloudWatch-via-debug-logs rather than vanishing).
     */
    public static String toDisplay(String canonOrNull)
    {
        if (canonOrNull == null)
        {
            return "";
        }
        String hit = TO_DISPLAY.get(canonOrNull);
        return hit != null ? hit : canonOrNull;
    }
}

package com.pvp.leaderboard.lobby;

import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import javax.inject.*;
import javax.swing.*;

/**
 * Production {@link JoinGate} backed by
 * {@link PvpApi#getProfile}. Wires the local player's
 * {@code cumulative_stats.<bucket>} to per-{@link Style} match counts +
 * exposes an hourly auto-refresh.
 *
 * <p><b>Lifecycle.</b>
 * <ol>
 *   <li>{@link #configure} is called once from {@code
 *   PvPLeaderboardPlugin.startUp()} to wire the {@link Supplier} that
 *   resolves the local player's name at refresh time. Held as a
 *   {@link Supplier} rather than a snapshot value because the player
 *   name is unavailable until {@code GameState.LOGGED_IN} fires (the
 *   plugin's {@code startUp()} can run before login).</li>
 *   <li>{@link #onLogin} fires from {@code onGameStateChanged
 *   LOGGED_IN}; kicks off an immediate refresh and starts the hourly
 *   auto-refresh timer.</li>
 *   <li>{@link #onLogout} fires from {@code LOGIN_SCREEN}; cancels the
 *   timer and clears the count map (returning to "unknown" state).
 *   Listeners stay registered until {@link #removeListener}.</li>
 * </ol>
 */
@Singleton
public final class ProfileGate implements JoinGate
{
    private final PvpApi pvpApi;
    private final ScheduledExecutorService scheduler;

    /** Listeners notified on the EDT after every state mutation (refresh
     *  start, refresh complete, counts changed). {@link CopyOnWriteArrayList}
     *  so {@code addListener} during a fire callback doesn't trip
     *  ConcurrentModificationException. */
    private final CopyOnWriteArrayList<Runnable> listeners = new CopyOnWriteArrayList<>();

    /** Resolves at refresh time — see class javadoc for why this isn't a
     *  snapshot value. {@code volatile} since {@link #configure} writes from
     *  the plugin's startup thread and {@link #refresh} reads from the
     *  scheduler thread / EDT. */
    private volatile Supplier<String> nameSupplier;

    /** Guard against concurrent in-flight refreshes. CAS-incremented at
     *  {@link #refresh()} entry; cleared in the completion callback. */
    private final AtomicBoolean refreshing = new AtomicBoolean(false);

    /** Synchronised on {@code this} for read+write because the EnumMap
     *  isn't thread-safe and listeners may read it from the EDT while
     *  the refresh callback writes from an OkHttp dispatcher thread. */
    private final EnumMap<Style, Integer> counts = new EnumMap<>(Style.class);

    /** Consecutive soft-404 refreshes ({@code /user} returned "player
     *  not found"). Drives the geometric backoff in
     *  {@link #softBackOff()}; reset by a successful refresh
     *  and by {@link #onLogin()}.
     *
     *  <p>A soft 404 is a stable condition — an account the backend
     *  has never seen stays unknown until it plays a match — but the
     *  refresh path deliberately doesn't treat it as a success, so
     *  without this counter the gate sat on the 60 s fast-retry for
     *  the whole session. Each of those retries passes
     *  {@code forceRefresh=true}, which bypasses the profile cache,
     *  so it was an uncacheable API call every minute per client. */
    private final AtomicInteger softMisses = new AtomicInteger();

    /** Active auto-refresh handle; null when {@link #onLogout()} or no
     *  login has occurred. */
    private ScheduledFuture<?> autoRefresh;

    /** {@code true} between {@link #onLogin()} and {@link #onLogout()}.
     *  Independent of whether a refresh has completed — flips
     *  synchronously when the plugin reports the game-state change so
     *  the panel can swap its "Please log into the game" notice without
     *  waiting for the first network roundtrip. {@code volatile} since
     *  reads come from the EDT and writes from the plugin's game-event
     *  thread. */
    private volatile boolean loggedIn;

    @Inject
    public ProfileGate(PvpApi pvpApi,
                                    ScheduledExecutorService scheduler)
    {
        if (pvpApi == null) throw new IllegalArgumentException("pvpDataService is required");
        if (scheduler == null) throw new IllegalArgumentException("scheduler is required");
        this.pvpApi = pvpApi;
        this.scheduler = scheduler;
    }

    /** Wire the player-name supplier — must be called once before the
     *  first {@link #onLogin()}. Idempotent on repeat calls (just
     *  overwrites). */
    public void configure(Supplier<String> nameSupplier)
    {
        this.nameSupplier = nameSupplier;
    }

    /** Called by the plugin on {@code GameState.LOGGED_IN}. Schedules the
     *  hourly auto-refresh + kicks off an immediate first refresh.
     *  Idempotent: a second call (e.g. on character-switch) replaces the
     *  existing schedule without stacking. */
    public synchronized void onLogin()
    {
        cancelAutoRefreshLocked();
        loggedIn = true;
        // Fresh session — a new character may well be one the backend
        // knows, so don't inherit the previous account's backoff.
        softMisses.set(0);
        // Fast-retry schedule for the initial-fetch window: every
        // minute until the first refresh succeeds. The refresh()
        // success path replaces this with the {@link
        // #RECHECK_MS} hourly schedule. Without the
        // fast-retry, a failed initial fetch would leave the user
        // waiting an hour for the next attempt (and the gate stuck
        // on "Please log into the game" the whole time).
        autoRefresh = scheduler.scheduleAtFixedRate(
            this::autoTick,
            RETRY_MIN_MS,
            RETRY_MIN_MS,
            TimeUnit.MILLISECONDS);
        // Initial fetch — without this the panel would have no counts to
        // show until the first fast-retry tick. refresh() fires
        // listeners on entry, which is what swaps the panel from
        // "Please log into the game" → the real gate UI.
        refresh();
    }

    /** Called by the plugin on {@code GameState.LOGIN_SCREEN}. Cancels
     *  the auto-refresh + clears cached counts so the next user logging
     *  in on the same client doesn't see the previous user's counts. */
    public synchronized void onLogout()
    {
        cancelAutoRefreshLocked();
        loggedIn = false;
        synchronized (counts)
        {
            counts.clear();
        }
        // Drop the mod bit — without this, a non-mod logging in on the
        // same client right after a moderator would inherit the [MOD]
        // chip on their self-preview until the first /user fetch
        // completed.
        fireOnEdt();
    }

    private void cancelAutoRefreshLocked()
    {
        if (autoRefresh != null)
        {
            autoRefresh.cancel(false);
            autoRefresh = null;
        }
    }

    /** Auto-refresh tick handler. Skips if there's already a refresh in
     *  flight (manual refresh racing with the scheduler) to keep the
     *  network footprint to "at most one in-flight at a time". */
    private void autoTick()
    {
        if (refreshing.get()) return;
        refresh();
    }

    @Override
    public Map<Style, Integer> getMatchCounts()
    {
        synchronized (counts)
        {
            return Collections.unmodifiableMap(new EnumMap<>(counts));
        }
    }

    @Override
    public boolean isLoggedIn() { return loggedIn; }

    @Override
    public void refresh()
    {
        if (!refreshing.compareAndSet(false, true))
        {
            // Already in flight — debounce. The in-flight call will fire
            // listeners on its own completion path.
            return;
        }
        fireOnEdt(); // refreshing=true

        Supplier<String> nameSup = nameSupplier;
        String name = nameSup != null ? nameSup.get() : null;
        if (name == null || name.trim().isEmpty())
        {
            // Pre-login refresh attempt — bail cleanly. We do NOT
            // promote the autoRefresh schedule to hourly here; the
            // fast-retry schedule from onLogin() will fire again in
            // RETRY_MIN_MS so the count auto-populates
            // as soon as the local player name resolves. (Previously
            // refresh() unconditionally promoted to hourly at entry,
            // which meant a single failed initial attempt locked the
            // user out of auto-refresh for an hour.)
            refreshing.set(false);
            fireOnEdt();
            return;
        }

        // forceRefresh=true bypasses PvpApi's 30s local TTL —
        // we want the freshest read. Server-side CloudFront cache (60s)
        // still applies, which is fine; the user can't refresh faster
        // than that and get materially newer data anyway.
        pvpApi.getProfile(name, true)
            .whenComplete((profile, ex) ->
            {
                try
                {
                    if (ex != null)
                    {
                        // Don't clear counts — stale counts are better
                        // than empty ones (user already saw them; this
                        // would just flicker them to "Unknown" then
                        // back). Just don't update lastRefreshEpochMs
                        // and don't promote the schedule — the
                        // fast-retry tick will try again in 1 min.
                        return;
                    }
                    if (profile == null)
                    {
                        // Soft 404 from the API — player profile doesn't
                        // exist yet (e.g. brand-new account with zero
                        // matches). Surface zeros in the UI but do NOT
                        // treat this as a successful refresh: promoting
                        // to the hourly schedule here left new players
                        // stuck below THRESHOLD until they restarted
                        // RuneLite or clicked Refresh count manually.
                        applyAllZero();
                        softBackOff();
                        return;
                    }
                    applyProfile(profile);
                    softMisses.set(0);
                    // First-success / manual-refresh promote: switch to
                    // the hourly cadence and reset the clock so the
                    // next auto-tick is 1h from now (not 1h from the
                    // previous tick). Was at refresh() entry — that
                    // version unconditionally promoted even on failure
                    // paths, which broke the initial-fetch retry loop.
                    promoteToHourlyScheduleLocked();
                }
                catch (Exception e)
                {
                }
                finally
                {
                    refreshing.set(false);
                    fireOnEdt();
                }
            });
    }

    /** Widens the retry interval after repeated soft-404s, doubling
     *  each time up to the {@link #RECHECK_MS} cap.
     *
     *  <p>The first miss is left alone on the fast retry: that's the
     *  case this schedule exists for (a brand-new account whose first
     *  match is about to land), and it's worth one prompt re-check.
     *  It's the indefinite repetition that had to stop — the interval
     *  now reaches the hourly cap after ~6 misses, so an account the
     *  backend simply doesn't know costs the same as any other idle
     *  client instead of an uncacheable request every minute.
     *
     *  <p>No-op when logged out: {@link #cancelAutoRefreshLocked()}
     *  has already torn the schedule down and re-arming here would
     *  leak a task onto RuneLite's client-wide executor. */
    private synchronized void softBackOff()
    {
        int misses = softMisses.incrementAndGet();
        if (misses < 2) return;
        if (!loggedIn) return;
        long interval = RETRY_MIN_MS;
        for (int i = 1; i < misses && interval < RECHECK_MS; i++)
        {
            interval *= 2;
        }
        if (interval > RECHECK_MS) interval = RECHECK_MS;
        cancelAutoRefreshLocked();
        autoRefresh = scheduler.scheduleAtFixedRate(
            this::autoTick, interval, interval, TimeUnit.MILLISECONDS);
    }

    /** Replace the active {@link #autoRefresh} with the long-period
     *  hourly schedule. Called only from the success path of
     *  {@link #refresh()} so first-success transitions us off the
     *  fast-retry cadence and manual refreshes reset the hourly clock
     *  in one place. No-op if logged out (cancelAutoRefreshLocked has
     *  already nulled out the schedule). */
    private synchronized void promoteToHourlyScheduleLocked()
    {
        if (!loggedIn) return;
        cancelAutoRefreshLocked();
        autoRefresh = scheduler.scheduleAtFixedRate(
            this::autoTick,
            RECHECK_MS,
            RECHECK_MS,
            TimeUnit.MILLISECONDS);
    }

    private void applyProfile(JsonObject profile)
    {
        if (profile == null)
        {
            applyAllZero();
            return;
        }
        // Parse is_mod before any cumulative_stats early-return so a
        // mod account still surfaces the [MOD] chip on the self-preview
        // row even when match counts are absent (brand-new account,
        // partial profile payload, etc.). Strict-boolean only — mirrors
        // WebSocketLobbyService.parseMember's wire contract.
        JsonObject cum = JsonLenient.optObject(profile, "cumulative_stats");
        if (cum == null)
        {
            zeroCounts();
            return;
        }
        // Per-bucket rank lives in a separate top-level object on the
        // {@code /user} endpoint — NOT inside {@code cumulative_stats}.
        // See {@code PvpApi.extractTierFromUserResponse}: the
        // per-bucket shape is {@code {"rank": "Adamant", "division":
        // 2, "mmr": ...}} where {@code rank} is the family name and
        // {@code division} is 1–3 (absent / non-1–3 for the
        // single-division "3rd Age" tier). Earlier draft of this
        // method read {@code cumulative_stats.<bucket>.tier} which
        // doesn't exist on this endpoint (only the S3 shard payload
        // has a {@code tier} field) — meaning {@link
        // #rankIdxByStyle} would stay empty and the self-preview
        // row's name rendered in plain white. Fixed by reading from
        // {@code buckets.<bucket>} instead.
        EnumMap<Style, Integer> nextCounts = new EnumMap<>(Style.class);
        for (Style s : Style.values())
        {
            JsonObject b = JsonLenient.optObject(cum, bucketFor(s));
            int total = 0;
            if (b != null)
            {
                // Defensive ints — backend has been seen to return both
                // numeric primitives and Decimal-typed values depending
                // on the path through the Lambda; getAsInt() handles
                // both via Gson's coercion.
                int wins = JsonLenient.optInt(b, "wins", 0);
                int losses = JsonLenient.optInt(b, "losses", 0);
                int ties = JsonLenient.optInt(b, "ties", 0);
                total = wins + losses + ties;
                if (total < 0) total = 0;
            }
            nextCounts.put(s, total);
        }
        synchronized (counts)
        {
            counts.clear();
            counts.putAll(nextCounts);
        }
    }

    private void applyAllZero()
    {
        zeroCounts();
    }

    /** Clears match counts + rank indices without touching {@link #isMod}.
     *  Used when {@code cumulative_stats} is absent but {@code is_mod}
     *  was still parsed from the top-level profile object. */
    private void zeroCounts()
    {
        synchronized (counts)
        {
            counts.clear();
            for (Style s : Style.values()) counts.put(s, 0);
            // Soft-404 / brand-new player: leave rankIdxByStyle empty.
            // The self-preview row falls back to "rank unknown" and
            // suppresses the rank chip rather than showing a default
            // Bronze 3.
        }
    }

    private static String bucketFor(Style s)
    {
        // Lowercased style name → cumulative_stats bucket key. Locked
        // to a switch instead of {@code s.name().toLowerCase()} so
        // future enum renames (e.g. NH → "Nh") don't silently break the
        // wire mapping.
        switch (s)
        {
            case NH: return "nh";
            case VENG: return "veng";
            case MULTI: return "multi";
            case DMM: return "dmm";
            default: return null;
        }
    }

    @Override
    public void addListener(Runnable listener)
    {
        if (listener != null) listeners.add(listener);
    }

    @Override
    public void removeListener(Runnable listener)
    {
        if (listener != null) listeners.remove(listener);
    }

    private void fireOnEdt()
    {
        if (listeners.isEmpty()) return;
        if (SwingUtilities.isEventDispatchThread())
        {
            fireAll();
        }
        else
        {
            SwingUtilities.invokeLater(this::fireAll);
        }
    }

    private void fireAll()
    {
        for (Runnable r : listeners)
        {
            try { r.run(); }
            catch (Exception e) { }
        }
    }
}

package com.pvp.leaderboard.lobby;

/**
 * Fight styles the lobby supports. Matches the server's
 * {@code ALLOWED_STYLES = {nh,veng,multi,dmm}} validation set.
 *
 * <p>Declaration order is the on-screen order used by the pre-lobby
 * gate's style-toggle row and the per-row chip strip — keep it stable
 * so the UI doesn't reflow on enum reordering. {@code EnumSet}
 * iteration also follows declaration order, so any CSV rendering of
 * "selected styles" reads NH-first / DMM-last by default.
 *
 * <p>Field {@link #label} is intentionally {@code public final} (not
 * encapsulated) — these are tight-knit value types, the existing
 * rendering code accesses {@code style.label} directly, and switching
 * to a getter would buy nothing but verbosity at call sites.
 */
public enum Style
{
    NH("NH"),
    VENG("Veng"),
    MULTI("Multi"),
    DMM("DMM");

    public final String label;

    Style(String label)
    {
        this.label = label;
    }
}

package com.pvp.leaderboard.lobby;

import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.service.socket.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import javax.inject.*;
import javax.swing.*;
import lombok.extern.slf4j.*;
import static com.pvp.leaderboard.util.JsonLenient.*;
import static javax.swing.SwingUtilities.*;

/**
 * Production {@link LobbyService} that adapts the wire protocol to the
 * panel's domain types.
 *
 * <p>Two key concerns this class owns:
 * <ol>
 *   <li><b>Wire ↔ domain marshalling</b>: server pushes are flat (e.g.
 *   {@code lobby/invite_received} carries
 *   {@code from_player_id + from_name + sender_styles + ...}, not a
 *   nested {@code sender} object). This service holds an in-memory
 *   roster cache keyed by canonical {@code player_id} and reconstructs
 *   {@link LobbyMember} instances for the panel's nested
 *   {@link IncomingInvite#sender} / {@link FightSession#opponent} /
 *   {@link MatchInfo#opponent} fields. If a flat payload references a
 *   player id not in the cache (rare — only if the push arrives before
 *   the {@code lobby/roster} that introduced the member), the service
 *   falls back to a synthetic {@link LobbyMember} built from whatever
 *   fields the push carried.</li>
 *
 *   <li><b>Reconnect re-join</b>: caches the last {@link #joinLobby}
 *   args and re-sends them via {@link SocketMgr#addConnectListener}
 *   on every socket open so server-side state rebuilds without the
 *   panel knowing about reconnects.</li>
 * </ol>
 *
 * <p><b>Threading</b>: server pushes arrive on OkHttp's dispatcher
 * thread via {@link SocketBus}; this service marshals every
 * {@link LobbyEventListener} callback through
 * {@link SwingUtilities#invokeLater} per the {@link LobbyService}
 * contract. The injected {@link SocketMgr} is thread-safe and
 * {@link #send(String, JsonObject)} just hands off to its internal
 * {@code WebSocket.send(String)} which is thread-safe.
 *
 * <p><b>Stale roster</b>: a {@code lobby/roster} with {@code stale: true}
 * or without {@code members} re-issues {@code lobby/join} after a
 * growing, jittered delay ({@link #STALE_REJOIN_BASE_MS} doubling up to
 * {@link #STALE_REJOIN_MAX_MS}), one at a time.
 */
@Slf4j
@Singleton
public class WebSocketLobbyService implements LobbyService
{
    private final SocketMgr socket;
    private final SocketBus bus;

    /** Buffered {@code fight_session_id} awaiting a healthy socket so its
     *  {@code lobby/confirm} can finally land. Populated by
     *  {@link #confirmFight()} when the socket is closed at send time
     *  (e.g. the user clicked Confirm Fight during the 1-3 s window
     *  between {@code onClose} and the next {@code onOpen}); flushed
     *  by {@link #flushConfirm()} from the connect listener and
     *  cleared by {@link #handleFightProposed}, {@link #handleMatchFound},
     *  and {@link #handleSessionExpired} when the session it refers to
     *  is no longer current. {@code volatile} since
     *  {@code SocketMgr} invokes the connect listener on the
     *  OkHttp dispatcher thread while {@code confirmFight()} is called
     *  from the Swing EDT. */
    private volatile String heldConfirm;

    private volatile LobbyEventListener listener;
    private volatile boolean started = false;

    @Inject
    public WebSocketLobbyService(SocketMgr socket, SocketBus bus)
    {
        this.socket = socket;
        this.bus = bus;
    }

    static final int QUEUE_MAX = 16;
    /** {@code queue/matched} opponent by {@code fight_session_id}. */
    private final Map<String, LobbyMember> queueOpps = new ConcurrentHashMap<>();

    @Override
    public void setListener(LobbyEventListener listener)
    {
        this.listener = listener;
    }

    @Override
    public synchronized void start()
    {
        if (started) return;
        started = true;
        bus.register("lobby/block_list_snapshot",     this::handleBlockListSnapshot);
        bus.register("lobby/block_added",             this::handleBlockAdded);
        bus.register("lobby/block_removed",           this::handleBlockRemoved);
        bus.register("lobby/fight_proposed",          this::handleFightProposed);
        bus.register("lobby/fight_confirmed_by_peer", this::handleFightConfirmedByPeer);
        bus.register("lobby/match_found",             this::handleMatchFound);
        bus.register("lobby/session_expired",         this::handleSessionExpired);
        bus.register("error/lobby",                   this::handleError);
        bus.register("queue/matched",                 this::handleQueueMatched);
        socket.addConnectListener(this::flushConfirm);
    }

    @Override
    public synchronized void stop()
    {
    }

    @Override
    public void confirmFight()
    {
        // The panel works against a "one fight at a time" model — there's
        // no concept of overlapping confirm windows in the UI — so the
        // service caches the most recently proposed session id and uses
        // it here. The server-side state machine enforces the same rule:
        // joining a fight removes you from the lobby, so overlapping
        // sessions for one user are impossible.
        String sid = liveFightId;
        if (sid == null)
        {
            return;
        }
        var d = new JsonObject();
        d.addProperty("fight_session_id", sid);
        boolean sent = socket.send("lobby/confirm", d);
        if (sent)
        {
            // Successful send wins over any stale buffer entry — if the
            // user double-clicked Confirm during a brief reconnect,
            // only the surviving send carries forward.
            heldConfirm = null;
        }
        else
        {
            // Socket was closed at send time (the SocketMgr
            // backoff ladder runs 1-2-4-8 s; if Confirm is clicked
            // during that window the frame is silently dropped today,
            // which surfaced as the "30-second confirm window expired"
            // QA report). Buffer the session id so the connect
            // listener can flush it on the next onOpen — bounded by
            // the server's confirm window via
            // handleSessionExpired clearing the buffer.
            heldConfirm = sid;
        }
    }

    /** Connect-listener callback: drains any {@link
     *  #heldConfirm} buffered while the socket was
     *  closed. Runs on OkHttp's dispatcher thread alongside
     *  {@link #replayJoinOnReconnect()}; safe because the buffer is
     *  volatile and the failure mode (re-buffer + retry on next open)
     *  is idempotent. */
    private void flushConfirm()
    {
        String sid = heldConfirm;
        if (sid == null) return;
        // Drop the buffer first to avoid re-entry if the send below
        // races a fresh confirmFight() call (e.g. user clicked Confirm
        // again during the flush). The buffer is repopulated below if
        // the send fails — single-writer semantics.
        heldConfirm = null;
        var d = new JsonObject();
        d.addProperty("fight_session_id", sid);
        if (socket.send("lobby/confirm", d))
        {
        }
        else
        {
            // The socket closed again between onOpen firing and our
            // send. Re-buffer so the next open retries. Bounded by
            // the server's confirm window — handleSessionExpired
            // clears the buffer once the server gives up.
            heldConfirm = sid;
        }
    }

    @Override
    public void blockById(String playerId)
    {
        if (playerId == null) return;
        String trimmed = playerId.trim();
        if (trimmed.isEmpty()) return;
        var d = new JsonObject();
        d.addProperty("blocked_player_id", trimmed);
        socket.send("lobby/block", d);
    }

    @Override
    public void unblockById(String playerId)
    {
        if (playerId == null) return;
        String trimmed = playerId.trim();
        if (trimmed.isEmpty()) return;
        var d = new JsonObject();
        d.addProperty("blocked_player_id", trimmed);
        socket.send("lobby/unblock", d);
    }

    /** Pass-through to {@link SocketMgr#isConnected()}. The
     *  panel's reconnect banner reads this to decide whether to show
     *  the countdown — the wire state is the single source of truth
     *  for "are we online", not anything cached in this service. */
    @Override
    public boolean isConnected()
    {
        return socket.isConnected();
    }

    /** Pass-through to {@link SocketMgr#getRetryAtMs()}.
     *  Drives the 1Hz countdown on the panel's reconnect banner.
     *  Returning {@code 0} suppresses the banner; any non-zero value
     *  is interpreted as "retry scheduled at that wall-clock time". */
    @Override
    public long getRetryAtMs()
    {
        return socket.getRetryAtMs();
    }

    // ---------------------------------------------------------------
    // Inbound: server -> panel (all dispatched on EDT)
    // ---------------------------------------------------------------

    /** Most recently proposed fight session id; used by
     *  {@link #confirmFight()} since the panel's API doesn't take an
     *  explicit id. Set on {@code lobby/fight_proposed}, cleared on
     *  {@code lobby/match_found} / {@code lobby/session_expired}. */
    private volatile String liveFightId;

    private void handleBlockListSnapshot(JsonObject data)
    {
        // Backend pushes data={"blocked": [{player_id, name}, ...]} per
        // get_block_list (backend/core/lobby.py). Older builds emitted a
        // flat string array under "blocked_player_ids" — accept either
        // shape so a partial deploy doesn't drop blocks silently.
        Set<String> ids = new HashSet<>();
        for (JsonElement el : optArray(data, "blocked"))
        {
            if (el == null || el.isJsonNull()) continue;
            String pid = el.isJsonObject() ? optString(el.getAsJsonObject(), "player_id") : str(el);
            if (pid != null && !pid.isEmpty()) ids.add(pid);
        }
        if (ids.isEmpty())
        {
            ids.addAll(parseStrings(data, "blocked_player_ids"));
        }
        LobbyEventListener l = listener;
        if (l == null) return;
        Set<String> snapshot = Collections.unmodifiableSet(ids);
        invokeLater(() -> l.onBlockListSnapshot(snapshot));
    }

    private void handleBlockAdded(JsonObject data)
    {
        String pid = optString(data, "blocked_player_id");
        if (pid.isEmpty()) return;
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onBlockAdded(pid));
    }

    private void handleBlockRemoved(JsonObject data)
    {
        String pid = optString(data, "blocked_player_id");
        if (pid.isEmpty()) return;
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onBlockRemoved(pid));
    }

    private void handleFightProposed(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        // A new fight is being proposed — any confirm buffered against
        // a *previous* (now-defunct) session is stale. Drop it so a
        // belated flush doesn't try to confirm a session the server
        // has already torn down.
        if (heldConfirm != null
            && !heldConfirm.equals(sid))
        {
            heldConfirm = null;
        }
        liveFightId = sid;
        Style style = parseStyle(optString(data, "style"));
        BuildType build = parseBuild(optString(data, "build"));
        if (style == null || build == null) return;
        // Inbound wire-protocol boundary — see handleInviteReceived.
        String location = PlaceCodec.toDisplay(optString(data, "location"));
        // Canonical wire field per BACKEND_HANDOFF_LOBBY.md §FightSession
        // is `confirm_expires_at_epoch_ms`. The plugin previously read
        // the wrong key (`expires_at_epoch_ms`, the IncomingInvite
        // field), which silently defaulted the deadline to 0L and made
        // the panel's 1-Hz fight tick exit the Confirm-Fight card on
        // its very first tick — the user saw the popup vanish before
        // they could click anything (QA bug 2026-05-25). Read the
        // canonical key first; fall back to the legacy name so a
        // partial backend deploy doesn't strand every fight; and if
        // BOTH are missing/zero, synthesise now + the confirm window
        // keyed to the local clock so the user still gets a usable popup.
        //
        // NOTE: the panel no longer trusts this absolute deadline for
        // the confirm countdown — MatchmakingLobbyPanel.LocalFightState
        // counts the confirm window off a monotonic clock so a wrong /
        // skewed client wall clock can't cut the window short. This
        // value is retained only as the server's advisory deadline.
        long windowMs = confirmMs(data);
        long expiresAt = optLong(data, "confirm_expires_at_epoch_ms", 0);
        if (expiresAt <= 0L) expiresAt = optLong(data, "expires_at_epoch_ms", 0);
        if (expiresAt <= 0L)
        {
            long synth = System.currentTimeMillis() + windowMs;
            log.warn("WebSocketLobbyService.handleFightProposed: missing confirm_expires_at_epoch_ms (and legacy expires_at_epoch_ms) on lobby/fight_proposed sid={} - synthesising local-clock deadline now+{}ms={} so the Confirm-Fight card doesn't insta-exit",
                sid, windowMs, synth);
            expiresAt = synth;
        }
        LobbyMember opponent = resolveOpponent(data);
        if (opponent == null) return;
        var session = new FightSession(sid, opponent, style, build, location, expiresAt, windowMs);
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onFightProposed(session));
    }

    private void handleFightConfirmedByPeer(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onFightConfirmedByPeer(sid));
    }

    private void handleMatchFound(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        Style style = parseStyle(optString(data, "style"));
        BuildType build = parseBuild(optString(data, "build"));
        if (style == null || build == null) return;
        // Inbound wire-protocol boundary — see handleInviteReceived.
        String location = PlaceCodec.toDisplay(optString(data, "location"));
        String world = optString(data, "world");
        String meetingPlace = optString(data, "meeting_place");
        LobbyMember opponent = resolveOpponent(data);
        queueOpps.remove(sid);
        if (opponent == null) return;
        // Server has already deleted both LobbyMembers rows + the
        // session at this point — the lobby state is consumed, clear
        // our local session-id cache. Also drop any buffered confirm
        // for this session: the match landed, so a late flush would
        // be a no-op at best, an error/lobby at worst.
        liveFightId = null;
        if (sid.equals(heldConfirm)) heldConfirm = null;
        var match = new MatchInfo(sid, opponent, style, build, location, world, meetingPlace);
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onMatchFound(match));
    }

    private void handleSessionExpired(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        if (sid.isEmpty()) return;
        if (sid.equals(liveFightId)) liveFightId = null;
        queueOpps.remove(sid);
        // The confirm window elapsed — any buffered confirm against
        // this session is moot, drop it so a future reconnect doesn't
        // ship a confirm for a session that no longer exists.
        if (sid.equals(heldConfirm)) heldConfirm = null;
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onFightSessionExpired(sid));
    }

    private void handleError(JsonObject data)
    {
        String code = optString(data, "code");
        String message = optString(data, "message");
        // Surfaced at WARN because error/lobby pushes are exceptional
        // by definition — the user is going to ask why their fight
        // button didn't work, and the answer is almost always in this
        // single log line (RANK_OUT_OF_RANGE, BLOCKED, SMURF_GUARD…).
        log.warn("WebSocketLobbyService: error/lobby code={} message={}", code, message);
        LobbyEventListener l = listener;
        if (l == null) return;
        invokeLater(() -> l.onError(code, message));
    }

    // ---------------------------------------------------------------
    // Parsing helpers
    // ---------------------------------------------------------------

    /** Returns the opponent {@link LobbyMember} for a
     *  {@code fight_proposed} / {@code match_found} push: the
     *  {@code queue/matched} opponent of that session when one arrived,
     *  else the side whose {@code player_id} (or, without ids, name) is
     *  not {@link SocketMgr#getActiveName()}, its roster row when
     *  cached. When neither side is recognised: the roster row of either
     *  side, else player_a's id + name on the wire; {@code null} without
     *  ids. */
    private LobbyMember resolveOpponent(JsonObject data)
    {
        LobbyMember queued = queueOpps.get(optString(data, "fight_session_id"));
        if (queued != null) return queued;
        String a = optString(data, "player_a_player_id");
        String b = optString(data, "player_b_player_id");
        String aName = optString(data, "player_a_name");
        String bName = optString(data, "player_b_name");
        String self = NameUtils.canonicalKey(socket.getActiveName());
        if (a.isEmpty() || b.isEmpty())
        {
            if (self.isEmpty() || aName.isEmpty() || bName.isEmpty()) return null;
            String aKey = NameUtils.canonicalKey(aName);
            String bKey = NameUtils.canonicalKey(bName);
            if (self.equals(aKey) && !self.equals(bKey)) return minimalMember(bKey, bName);
            if (self.equals(bKey) && !self.equals(aKey)) return minimalMember(aKey, aName);
            return null;
        }
        if (!self.isEmpty())
        {
            boolean selfIsA = self.equals(NameUtils.canonicalKey(a));
            boolean selfIsB = self.equals(NameUtils.canonicalKey(b));
            if (selfIsA != selfIsB)
            {
                return selfIsA ? minimalMember(b, bName) : minimalMember(a, aName);
            }
        }
        return minimalMember(a, aName);
    }

    private static LobbyMember minimalMember(String playerId, String name)
    {
        return new LobbyMember(playerId, name,
            EnumSet.noneOf(Style.class), EnumSet.noneOf(BuildType.class),
            -1, "");
    }

    /** {@code queue/matched}: remembers the session's opponent for
     *  {@link #resolveOpponent}. */
    private void handleQueueMatched(JsonObject data)
    {
        String sid = optString(data, "fight_session_id");
        String name = optString(data, "opponent_name");
        String playerId = optString(data, "opponent_player_id");
        if (sid.isEmpty() || (name.isEmpty() && playerId.isEmpty())) return;
        if (playerId.isEmpty()) playerId = NameUtils.canonicalKey(name);
        if (name.isEmpty()) name = playerId;
        Style style = parseStyle(optString(data, "style"));
        BuildType build = parseBuild(optString(data, "opponent_build"));
        var opponent = new LobbyMember(playerId, name,
            style == null ? EnumSet.noneOf(Style.class) : EnumSet.of(style),
            build == null ? EnumSet.noneOf(BuildType.class) : EnumSet.of(build),
            -1, optString(data, "opponent_region"));
        if (queueOpps.size() >= QUEUE_MAX) queueOpps.clear();
        queueOpps.put(sid, opponent);
    }

    /** The longest confirm window a push may set, in seconds. */
    private static final double MAX_WINDOW_S = 900d;

    /** A push's {@code confirm_window_s} in milliseconds: a JSON number from 1 to
     *  {@link #MAX_WINDOW_S} seconds. Anything else (absent, not a number,
     *  under a second, above the maximum) is {@link FightSession#CONFIRM_MS}. */
    private static long confirmMs(JsonObject o)
    {
        JsonElement el = o == null ? null : o.get("confirm_window_s");
        if (el == null || !el.isJsonPrimitive() || !el.getAsJsonPrimitive().isNumber()) return FightSession.CONFIRM_MS;
        try
        {
            double seconds = el.getAsDouble();
            if (!(seconds >= 1d && seconds <= MAX_WINDOW_S)) return FightSession.CONFIRM_MS;
            return (long) (seconds * 1000d);
        }
        catch (RuntimeException e)
        {
            return FightSession.CONFIRM_MS;
        }
    }

    private static Set<String> parseStrings(JsonObject o, String key)
    {
        Set<String> out = new HashSet<>();
        if (o == null || !o.has(key) || !o.get(key).isJsonArray()) return out;
        for (JsonElement el : o.getAsJsonArray(key))
        {
            if (el == null || el.isJsonNull() || !el.isJsonPrimitive()) continue;
            String s = el.getAsString();
            if (!s.isEmpty()) out.add(s);
        }
        return out;
    }

    private static Style parseStyle(String s)
    {
        if (s == null || s.isEmpty()) return null;
        try { return Style.valueOf(s.toUpperCase()); }
        catch (IllegalArgumentException e) { return null; }
    }

    private static BuildType parseBuild(String s)
    {
        if (s == null || s.isEmpty()) return null;
        try { return BuildType.valueOf(s.toUpperCase()); }
        catch (IllegalArgumentException e) { return null; }
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.game.*;
import com.pvp.leaderboard.tournament.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import java.util.function.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.widgets.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.game.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.tooltip.*;
import net.runelite.client.util.*;
import net.runelite.api.Point;
import static com.pvp.leaderboard.game.ArenaWidgets.*;

@Singleton
public class ArenaGearOverlay extends Overlay
{
    static final int GREY_TEXT = 0x808080;
    static final Color GREY_COVER = new Color(0x96505050, true);
    static final Color OUTLINE = new Color(0xE6FFD700, true);
    static final int OUTLINE_PX = 2;
    static final String UNREAD_TOOLTIP = "The plugin hasn't read your kit yet — open your kit tab (see the PvP Leaderboard panel)";
    static final String STALE_TOOLTIP = "Your kit changed since the plugin last read it — open your kit tab (see the PvP Leaderboard panel)";

    private final Client client;
    private final TooltipManager tooltips;
    private final KitReader reader;
    private final GearSearch search;
    private final OppTracker sessions;
    private volatile Supplier<GearReporter.View> view = () -> GearReporter.View.EMPTY;

    private final Map<Widget, Integer> originalColors = new IdentityHashMap<>();
    private boolean greyed;

    @Inject
    public ArenaGearOverlay(Client client, TooltipManager tooltips, KitReader reader, GearSearch search, OppTracker sessions)
    {
        this.client = client;
        this.tooltips = tooltips;
        this.reader = reader;
        this.search = search;
        this.sessions = sessions;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGH);
    }

    public void setView(Supplier<GearReporter.View> supplier)
    {
        view = supplier == null ? () -> GearReporter.View.EMPTY : supplier;
    }

    boolean isGreyed()
    {
        return greyed;
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        try
        {
            renderInner(g);
        }
        catch (RuntimeException ignored)
        {
        }
        return null;
    }

    private void renderInner(Graphics2D g)
    {
        GearReporter.View v = view.get();
        boolean gearEvent = v != null && v.event != null && v.event.arena;
        if (!gearEvent)
        {
            if (greyed || !originalColors.isEmpty()) applyGrey(false);
            greyed = false;
            return;
        }
        DuelScreen s = reader.screen();
        boolean againstOpponent = s != null && isTourneyOpp(v, s.opponentName);
        boolean grey = againstOpponent && !v.verifiedOk();
        applyGrey(grey);
        greyed = grey;
        if (grey)
        {
            drawCovers(g);
            maybeTooltip(v);
        }
        if (v.event.set.spellbook != null)
        {
            String want = v.event.set.spellbook;
            if (againstOpponent && s.ownPanel >= 0 && s.ownKit != null && !want.equals(s.ownKit.spellbook))
            {
                outline(g, spellbookBox(DUEL_PANELS[s.ownPanel]));
            }
            int chest = reader.suppliesPanel();
            if (chest >= 0 && GearSet.BUILDS.get(chest).equals(v.event.set.build) && !want.equals(reader.suppliesBook()))
            {
                outline(g, spellbookBox(SUPPLIES_PANELS[chest]));
            }
        }
        GearSearch.Highlight h = search.highlight();
        if (h != null)
        {
            ArenaWidgets.KitPanel panel = s != null && s.ownPanel >= 0 ? DUEL_PANELS[s.ownPanel]
                : reader.suppliesPanel() >= 0 ? SUPPLIES_PANELS[reader.suppliesPanel()] : null;
            if (panel != null) outlineRows(g, panel, h);
        }
    }

    private boolean isTourneyOpp(GearReporter.View v, String name)
    {
        MatchSeries series = sessions.getActiveSeries();
        if (series == null || !series.hasNamedOpponent() || name == null) return false;
        if (series.tournamentId != null && !series.tournamentId.isEmpty() && !series.tournamentId.equals(v.event.tournamentId)) return false;
        String want = NameUtils.canonicalKey(series.opponentName);
        return !want.isEmpty() && want.equals(NameUtils.canonicalKey(name));
    }

    private void applyGrey(boolean grey)
    {
        for (int id : DUEL_CONFIRMS)
        {
            Widget w = client.getWidget(id);
            if (w != null) colourTexts(w, grey, 2);
        }
    }

    private void colourTexts(Widget w, boolean grey, int depth)
    {
        if (w == null) return;
        String text = w.getText();
        if (text != null && !text.trim().isEmpty())
        {
            if (grey)
            {
                if (!originalColors.containsKey(w)) originalColors.put(w, w.getTextColor());
                if (w.getTextColor() != GREY_TEXT) w.setTextColor(GREY_TEXT);
            }
            else
            {
                Integer original = originalColors.remove(w);
                if (original != null) w.setTextColor(original);
            }
        }
        if (depth <= 0) return;
        for (Widget[] kids : KitReader.kids(w))
        {
            if (kids == null) continue;
            for (Widget k : kids) colourTexts(k, grey, depth - 1);
        }
    }

    private void drawCovers(Graphics2D g)
    {
        g.setColor(GREY_COVER);
        for (int id : DUEL_CONFIRMS)
        {
            Widget w = client.getWidget(id);
            if (w == null || w.isHidden()) continue;
            Rectangle b = w.getBounds();
            if (b != null) g.fill(b);
        }
    }

    private void maybeTooltip(GearReporter.View v)
    {
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null) return;
        for (int id : DUEL_CONFIRMS)
        {
            Widget w = client.getWidget(id);
            if (w == null || w.isHidden()) continue;
            Rectangle b = w.getBounds();
            if (b != null && b.contains(mouse.getX(), mouse.getY()))
            {
                tooltips.add(new Tooltip(tooltipFor(v)));
                return;
            }
        }
    }

    static String tooltipFor(GearReporter.View v)
    {
        if (v.kit == null || v.diff == null) return UNREAD_TOOLTIP;
        if (v.stale()) return STALE_TOOLTIP;
        return "Your kit doesn't match the tournament set (" + v.diff.summary() + ") — see the PvP Leaderboard panel";
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded e)
    {
        if (!greyed) return;
        MenuEntry entry = e.getMenuEntry();
        if (entry == null || !GearWatcher.contains(DUEL_CONFIRMS, entry.getParam1())) return;
        String option = entry.getOption();
        if (option == null || !"confirm".equals(option.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT))) return;
        entry.setOption(ColorUtil.wrapWithColorTag("Confirm", Color.GRAY));
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed e)
    {
        if (e.getGroupId() == DUEL_GROUP)
        {
            originalColors.clear();
            greyed = false;
        }
    }

    /** The bounds of the panel's spellbook drop-down as shown: the first visible of its display, container and menu. */
    private Rectangle spellbookBox(ArenaWidgets.KitPanel panel)
    {
        for (int id : new int[]{panel.bookDisplay, panel.bookBox, panel.bookMenu})
        {
            Widget w = client.getWidget(id);
            if (w == null || w.isHidden()) continue;
            Rectangle b = w.getBounds();
            if (b != null && !b.isEmpty()) return b;
        }
        return null;
    }

    private void outlineRows(Graphics2D g, ArenaWidgets.KitPanel panel, GearSearch.Highlight h)
    {
        Widget list = client.getWidget(panel.itemsList);
        if (list == null || list.isHidden()) return;
        Rectangle visibleArea = list.getBounds();
        for (Widget row : KitReader.slotsOf(list))
        {
            if (!h.matches(row, ItemVariationMapping::map)) continue;
            Rectangle b = row.getBounds();
            if (b != null && (visibleArea == null || visibleArea.intersects(b))) outline(g, b);
        }
    }

    private static void outline(Graphics2D g, Rectangle r)
    {
        if (r == null) return;
        g.setColor(OUTLINE);
        g.fillRect(r.x, r.y, r.width, OUTLINE_PX);
        g.fillRect(r.x, r.y + r.height - OUTLINE_PX, r.width, OUTLINE_PX);
        g.fillRect(r.x, r.y, OUTLINE_PX, r.height);
        g.fillRect(r.x + r.width - OUTLINE_PX, r.y, OUTLINE_PX, r.height);
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.config.*;
import com.pvp.leaderboard.game.*;
import java.awt.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.client.ui.*;
import static java.awt.RenderingHints.*;

@Slf4j
@Singleton
public final class MatchFoundNotificationOverlay extends Popup
{
    /** Total on-screen window (includes fade in + fade out). Hardcoded
     *  per the product spec — no config slider exposed for this one. */
    static final long VISIBLE_MS = 5_000L;
    static final float PEAK_ALPHA = 0.8f;

    static final int POPUP_W = 155;
    static final int POPUP_H = 66;
    /** Title bar height (top section above the separator). */
    static final int TITLE_BAR_H = 19;
    /** Distance from the top of the viewport. */
    static final int TOP_OFFSET = 11;
    static final float TITLE_PT = 10f;
    private static final int SIDE_MARGIN = 6;

    private final PvPLeaderboardConfig config;
    private final FightMonitor fightMonitor;

    /** {@code fight_session_id} of the most-recently-shown match. Sticky
     *  for the lifetime of the singleton so a re-push of the same
     *  fight_proposed event (server replay, bus double-fire) does NOT
     *  pop the same popup twice. Cleared by {@link #clear()} on
     *  plugin shutdown. */
    private volatile String lastShownId;

    private volatile String activeOpp;
    private volatile String activeSubtext;
    /** Rank-tier colour for the opponent name in the caption. Null is
     *  coerced to {@link Color#WHITE} at intake. */
    private volatile Color activeColor;
    private volatile long shownSince;

    @Inject
    public MatchFoundNotificationOverlay(Client client, PvPLeaderboardConfig config, FightMonitor fightMonitor)
    {
        super(client, log, "MatchFoundNotificationOverlay", POPUP_W, POPUP_H, TITLE_BAR_H, TOP_OFFSET);
        this.config = config;
        this.fightMonitor = fightMonitor;
    }

    /**
     * Triggers a fresh popup for a locked-in match against
     * {@code opponentName}. {@code subtext} is a short summary
     * ({@code "NH (Main) at Arena"}) that becomes the body's second
     * line. Safe to call from any thread.
     *
     * <p><b>De-duplication:</b> if {@code fightId} matches the
     * last fight this overlay rendered, the call is silently dropped.
     * This is the source-of-truth dedupe; the panel side does not need
     * to guard.
     *
     * <p><b>Config gate:</b> when the popup is disabled in config we
     * still update {@link #lastShownId} so re-enabling the
     * popup later doesn't suddenly surface a stale match the user
     * "missed" while it was off.
     */
    public void showMatch(String fightId,
                          String opponentName,
                          String subtext,
                          Color opponentColor)
    {
        if (opponentName == null || opponentName.isEmpty()) return;
        if (fightId != null && fightId.equals(lastShownId))
        {
            return;
        }
        lastShownId = fightId;
        boolean enabled = config.enableMatchFoundNotification();
        if (!enabled)
        {
            // Stamped as seen so a later toggle-on doesn't replay it,
            // but no on-screen state mutated.
            return;
        }
        activeOpp = opponentName;
        activeSubtext = subtext == null ? "" : subtext;
        activeColor = (opponentColor != null) ? opponentColor : Color.WHITE;
        shownSince = System.currentTimeMillis();
    }

    /** Clears any pending popup AND the dedupe state. Called on
     *  plugin shutdown so the next plugin start can pop fresh matches
     *  without remembering ids from a prior session. Idempotent. */
    public void clear()
    {
        drop();
        lastShownId = null;
    }

    /** Drops the popup on screen; the dedupe key stays. */
    private void drop()
    {
        activeOpp = null;
        activeSubtext = null;
        activeColor = null;
        shownSince = 0L;
    }

    @Override
    Dimension draw(Graphics2D g)
    {
        if (!config.enableMatchFoundNotification())
        {
            // Disabled mid-popup: drop active state so re-enabling
            // doesn't resume a partially-faded render.
            if (shownSince != 0L) drop();
            return null;
        }
        // In-combat suppression — DEFER the popup instead of
        // dropping it. Active state is preserved + shownSince is
        // pinned forward each suppressed frame so the visible-window
        // timer freezes during combat (2026-05-25 user spec: "still show
        // the notification after the combat has ended"). The match-found
        // popup carries the meeting world + place — the user MUST
        // see it eventually, just not while taking hits.
        if (config.suppressNotificationsInCombat() && fightMonitor.isInCombat())
        {
            if (shownSince != 0L) this.shownSince = System.currentTimeMillis();
            return null;
        }
        String opponent = activeOpp;
        long start = shownSince;
        if (opponent == null || start == 0L) return null;
        long elapsed = System.currentTimeMillis() - start;
        if (elapsed >= VISIBLE_MS)
        {
            // End-of-life: drop active state but DO NOT clear
            // lastShownId — that's the dedupe key and
            // must outlive the visual window so a later re-push of
            // the same fight_proposed stays suppressed.
            drop();
            return null;
        }
        return paint(g, alphaAt(elapsed), opponent);
    }

    static float alphaAt(long elapsedMs)
    {
        return fade(elapsedMs, VISIBLE_MS) * PEAK_ALPHA;
    }

    @Override
    void paintBody(Graphics2D g, int x, int y, String opponent)
    {
        g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
        g.setRenderingHint(KEY_TEXT_ANTIALIASING, VALUE_TEXT_ANTIALIAS_ON);

        // Title — centred in the title bar.
        Font titleFont = FontManager.getRunescapeBoldFont().deriveFont(TITLE_PT);
        g.setFont(titleFont);
        FontMetrics tfm = g.getFontMetrics();
        String title = "Match found!";
        int titleX = x + (POPUP_W - tfm.stringWidth(title)) / 2;
        int titleCenterY = y + 1 + TITLE_BAR_H / 2;
        int titleY = titleCenterY + (tfm.getAscent() - tfm.getDescent()) / 2;
        g.setColor(TITLE_FG);
        g.drawString(title, titleX, titleY);

        g.setFont(FontManager.getRunescapeSmallFont());
        FontMetrics bodyFm = g.getFontMetrics();
        int maxBodyW = POPUP_W - 2 * SIDE_MARGIN;
        String name = fitText(opponent, bodyFm, maxBodyW);
        int opponentW = bodyFm.stringWidth(name);
        int captionX = x + (POPUP_W - opponentW) / 2;
        int bodyTop = y + TITLE_BAR_H + 2;
        int bodyBottom = y + POPUP_H;
        int lineH = bodyFm.getHeight();
        int blockTop = (bodyTop + bodyBottom - 2 * lineH) / 2;
        int captionY = blockTop + bodyFm.getAscent();
        Color opponentColor = activeColor;
        g.setColor(opponentColor != null ? opponentColor : BODY_FG);
        g.drawString(name, captionX, captionY);

        String sub = activeSubtext;
        if (sub == null) sub = "";
        String trimmed = fitText(sub, bodyFm, maxBodyW);
        int subX = x + (POPUP_W - bodyFm.stringWidth(trimmed)) / 2;
        int subY = captionY + lineH;
        g.setColor(BODY_FG);
        g.drawString(trimmed, subX, subY);
    }

    /** Truncates {@code text} with a trailing ellipsis so it fits in
     *  {@code maxWidth} pixels under {@code fm}. */
    private static String fitText(String text, FontMetrics fm, int maxWidth)
    {
        if (fm.stringWidth(text) <= maxWidth) return text;
        String ell = "…";
        int ellW = fm.stringWidth(ell);
        if (ellW >= maxWidth) return ell;
        int lo = 0;
        int hi = text.length();
        while (lo < hi)
        {
            int mid = (lo + hi + 1) >>> 1;
            int w = fm.stringWidth(text.substring(0, mid)) + ellW;
            if (w <= maxWidth) lo = mid;
            else hi = mid - 1;
        }
        return text.substring(0, lo) + ell;
    }
}

package com.pvp.leaderboard.overlay;

import lombok.*;
import java.awt.*;
import java.awt.event.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.client.ui.*;
import net.runelite.client.input.MouseAdapter;
import static java.awt.RenderingHints.*;

/**
 * In-game warning popup shown after the player disabled the plugin
 * mid-fight in an LMS arena (a {@code plugin_disabled} freeze-log).
 *
 * <p>Painted in the same OSRS Collection-Log palette as
 * {@link MatchFoundNotificationOverlay} so the two popups visually
 * rhyme, but with two deliberate differences dictated by the
 * ban-warning product spec:
 * <ul>
 *   <li>It carries an explicit <b>OK</b> button the user must click to
 *       acknowledge — it does not silently fade away like the
 *       match-found toast. (It still self-dismisses after the 10 s
 *       window as a safety net so it can never wedge on screen.)</li>
 *   <li>It is <b>not</b> config-gated or in-combat-suppressed — the
 *       whole point is that the user sees the ban warning.</li>
 * </ul>
 *
 * <p>The plugin calls {@link #showWarning()} on the next
 * {@code LOGGED_IN} after the pending-warning config marker is found,
 * registers {@link #mouse} with RuneLite's mouse manager so the OK click is
 * caught, and passes a {@link #setOnDismiss dismiss callback} that
 * clears the config marker. Dismissal (OK click OR 10 s elapse) fires
 * that callback exactly once.
 *
 * <p><b>Threading:</b> {@link #showWarning()} is callable from any
 * thread; render runs on the RuneLite game thread; the mouse callback
 * runs on the AWT thread. Active-state fields are {@code volatile}.
 */
@Slf4j
@Singleton
public final class PluginDisableWarningOverlay extends Popup
{
    /** Total on-screen window (safety self-dismiss). */
    static final long VISIBLE_MS = 10_000L;

    /** The exact warning copy required by the product spec. */
    static final String[] BODY_LINES = {
        "Turning off a plugin mid fight will",
        "result in you being banned from",
        "the plugin. Do not do it again.",
    };
    private static final String TITLE = "Warning";
    private static final String OK_LABEL = "OK";

    // ---- Collection-Log popup palette: Popup's, plus the OK button's fill ----
    private static final Color OK_FILL = new Color(0x3a342a);

    // ---- Geometry ----
    private static final int POPUP_W = 340;
    private static final int POPUP_H = 168;
    private static final int TITLE_BAR_H = 38;
    private static final int TOP_OFFSET = 22;
    private static final float BODY_FONT_PT = 15f;
    private static final int OK_W = 60;
    private static final int OK_H = 24;
    private static final int OK_MARGIN = 12;

    private volatile long shownSince;
    /** OK-button screen bounds from the last paint; consulted by the
     *  mouse handler. Null when not showing / not yet painted. */
    private volatile Rectangle okBounds;
    /** Fired once on dismissal (OK click or timeout) — clears the
     *  config marker. */
    @Setter private volatile Runnable onDismiss;

    @Inject
    public PluginDisableWarningOverlay(Client client)
    {
        super(client, log, "PluginDisableWarningOverlay", POPUP_W, POPUP_H, TITLE_BAR_H, TOP_OFFSET);
    }

    /** Show the warning. Safe from any thread; a re-show while one is
     *  already visible simply restarts the 10 s window. */
    public void showWarning()
    {
        okBounds = null;
        shownSince = System.currentTimeMillis();
    }

    /** Drop active state without firing the dismiss callback. Called on
     *  plugin shutdown. Idempotent. */
    public void clear()
    {
        shownSince = 0L;
        okBounds = null;
    }

    boolean isShowing()
    {
        return shownSince != 0L;
    }

    /** Dismiss (OK click or timeout): drop state + fire the callback
     *  exactly once. */
    void dismiss()
    {
        boolean wasShowing = isShowing();
        clear();
        Runnable cb = onDismiss;
        if (wasShowing && cb != null)
        {
            try
            {
                cb.run();
            }
            catch (Exception e)
            {
            }
        }
    }

    @Override
    Dimension draw(Graphics2D g)
    {
        long start = shownSince;
        if (start == 0L)
        {
            return null;
        }
        long elapsed = System.currentTimeMillis() - start;
        if (elapsed >= VISIBLE_MS)
        {
            // Safety self-dismiss so the popup can never wedge on screen.
            dismiss();
            return null;
        }
        return paint(g, fade(elapsed, VISIBLE_MS), null);
    }

    /** The title, the warning lines and the OK button. */
    @Override
    void paintBody(Graphics2D g, int x, int y, String text)
    {
        g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
        g.setRenderingHint(KEY_TEXT_ANTIALIASING,
            VALUE_TEXT_ANTIALIAS_ON);

        Font titleFont = FontManager.getRunescapeBoldFont();
        g.setFont(titleFont);
        FontMetrics tfm = g.getFontMetrics();
        int titleW = tfm.stringWidth(TITLE);
        int titleX = x + (POPUP_W - titleW) / 2;
        int titleY = y + (TITLE_BAR_H + tfm.getAscent()) / 2 - 2;
        g.setColor(TITLE_FG);
        g.drawString(TITLE, titleX, titleY);

        Font bodyFont = FontManager.getRunescapeBoldFont().deriveFont(BODY_FONT_PT);
        g.setFont(bodyFont);
        FontMetrics bfm = g.getFontMetrics();
        g.setColor(BODY_FG);
        int lineH = bfm.getHeight();
        int startY = y + TITLE_BAR_H + 8 + bfm.getAscent();
        for (int i = 0; i < BODY_LINES.length; i++)
        {
            String line = BODY_LINES[i];
            int lw = bfm.stringWidth(line);
            int lx = x + (POPUP_W - lw) / 2;
            g.drawString(line, lx, startY + i * lineH);
        }

        int okX = x + (POPUP_W - OK_W) / 2;
        int okY = y + POPUP_H - OK_H - OK_MARGIN;
        // Record the screen-space bounds so the mouse handler can hit-test.
        okBounds = new Rectangle(okX, okY, OK_W, OK_H);

        g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_OFF);
        g.setColor(OK_FILL);
        g.fillRect(okX, okY, OK_W, OK_H);
        g.setColor(FRAME_BEVEL);
        g.drawRect(okX, okY, OK_W - 1, OK_H - 1);
        g.setColor(OUTER_OUTLINE);
        g.drawRect(okX - 1, okY - 1, OK_W + 1, OK_H + 1);

        Font okFont = FontManager.getRunescapeBoldFont();
        g.setFont(okFont);
        FontMetrics fm = g.getFontMetrics();
        int lw = fm.stringWidth(OK_LABEL);
        int lx = okX + (OK_W - lw) / 2;
        int ly = okY + (OK_H + fm.getAscent()) / 2 - 2;
        g.setColor(TITLE_FG);
        g.drawString(OK_LABEL, lx, ly);
    }

    /** Registered with RuneLite's mouse manager: a press on the OK button
     *  (while showing) dismisses and is consumed; every other event passes
     *  through unchanged ({@link MouseAdapter} returns it). */
    public final MouseAdapter mouse = new MouseAdapter()
    {
        @Override
        public MouseEvent mousePressed(MouseEvent e)
        {
            Rectangle r;
            if (isShowing() && (r = okBounds) != null && r.contains(e.getX(), e.getY()))
            {
                dismiss();
                e.consume();
            }
            return e;
        }
    };
}

package com.pvp.leaderboard.overlay;

import java.awt.*;
import net.runelite.api.*;
import net.runelite.client.ui.overlay.*;
import org.slf4j.*;
import static java.awt.RenderingHints.*;

/**
 * The OSRS Collection-Log pop-up frame the Match found and plugin-disable
 * warning pop-ups share: the palette, the fade, the frame with its title
 * separator centred at the top of the canvas, and a render that never lets a
 * throwable reach RuneLite's overlay renderer. Each pop-up paints its own body.
 */
abstract class Popup extends Overlay
{
    /** Fade-in duration at the start of each popup. */
    static final long FADE_IN_MS = 200L;
    /** Fade-out duration at the end of each popup. */
    static final long FADE_OUT_MS = 400L;

    // ---- Collection-Log popup palette (eyedropper from the widget) ----
    /** Frame stone-brown fill — main interior + title bar share this
     *  colour, the title bar is differentiated by the separator line
     *  alone (matches the vanilla widget). */
    static final Color FRAME_FILL = new Color(0x4d4639);
    /** Outer 1-px hard outline that bounds the whole popup. */
    static final Color OUTER_OUTLINE = new Color(0x120f0a);
    /** Bevel highlight running just inside the outer outline. */
    static final Color FRAME_BEVEL = new Color(0x746952);
    /** Horizontal separator under the title. */
    static final Color TITLE_LINE = new Color(0x1c1810);
    /** Bevel highlight running just below the title separator. */
    static final Color LINE_HI = new Color(0x6e634d);
    /** Title text — RuneScape orange. */
    static final Color TITLE_FG = new Color(0xff981f);
    /** Body text. */
    static final Color BODY_FG = Color.WHITE;

    private final Client client;
    private final Logger log;
    private final String name;
    private final int width;
    private final int height;
    private final int titleBarHeight;
    private final int top;

    /** {@code log} and {@code name} are the pop-up's own, for its render warning. */
    Popup(Client client, Logger log, String name, int width, int height, int titleBarHeight, int top)
    {
        this.client = client;
        this.log = log;
        this.name = name;
        this.width = width;
        this.height = height;
        this.titleBarHeight = titleBarHeight;
        this.top = top;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        // Any throwable from the pop-up is logged once with the pop-up's
        // name + a real stack (the first allocation happens here, before
        // HotSpot's OmitStackTraceInFastThrow strips the trace from repeat
        // throws) and swallowed so OverlayRenderer doesn't WARN-spam every
        // frame.
        try
        {
            return draw(g);
        }
        catch (Throwable t)
        {
            log.warn("[{}] render threw - swallowing", name, t);
            return null;
        }
    }

    /** This frame of the pop-up, or {@code null} when it shows nothing. */
    abstract Dimension draw(Graphics2D g);

    /** The pop-up's title and body, inside the frame whose top-left is ({@code x}, {@code y}). */
    abstract void paintBody(Graphics2D g, int x, int y, String text);

    /** The share of full opacity {@code elapsedMs} into a {@code totalMs}
     *  pop-up: up over {@link #FADE_IN_MS}, down over the last
     *  {@link #FADE_OUT_MS}, clamped to 0..1. */
    static float fade(long elapsedMs, long totalMs)
    {
        float share;
        if (elapsedMs < FADE_IN_MS)
        {
            share = (float) elapsedMs / FADE_IN_MS;
        }
        else if (elapsedMs > totalMs - FADE_OUT_MS)
        {
            share = 1f - (float) (elapsedMs - (totalMs - FADE_OUT_MS)) / FADE_OUT_MS;
        }
        else
        {
            share = 1f;
        }
        return Math.max(0f, Math.min(1f, share));
    }

    /** Paints the frame at {@code alpha}, centred at the top of the canvas,
     *  then the body; restores the graphics state it changes. {@code null}
     *  without a canvas. */
    Dimension paint(Graphics2D g, float alpha, String text)
    {
        Dimension canvas = client.getRealDimensions();
        if (canvas == null) return null;
        int x = Math.max(0, (canvas.width - width) / 2);

        Composite prevComposite = g.getComposite();
        Stroke prevStroke = g.getStroke();
        Font prevFont = g.getFont();
        Object prevAA = g.getRenderingHint(KEY_ANTIALIASING);
        Object prevTAA = g.getRenderingHint(KEY_TEXT_ANTIALIASING);
        try
        {
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
            g.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_OFF);
            g.setColor(FRAME_FILL);
            g.fillRect(x, top, width, height);
            g.setStroke(new BasicStroke(1f));
            g.setColor(FRAME_BEVEL);
            g.drawRect(x + 1, top + 1, width - 3, height - 3);
            g.setColor(OUTER_OUTLINE);
            g.drawRect(x, top, width - 1, height - 1);

            int sepY = top + titleBarHeight;
            g.setColor(TITLE_LINE);
            g.drawLine(x + 2, sepY, x + width - 3, sepY);
            g.setColor(LINE_HI);
            g.drawLine(x + 2, sepY + 1, x + width - 3, sepY + 1);

            paintBody(g, x, top, text);
        }
        finally
        {
            g.setComposite(prevComposite);
            g.setStroke(prevStroke);
            g.setFont(prevFont);
            if (prevAA != null) g.setRenderingHint(KEY_ANTIALIASING, prevAA);
            if (prevTAA != null) g.setRenderingHint(KEY_TEXT_ANTIALIASING, prevTAA);
        }
        return new Dimension(width, height);
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.cache.*;
import com.pvp.leaderboard.config.*;
import com.pvp.leaderboard.config.PvPLeaderboardConfig.*;
import com.pvp.leaderboard.game.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.api.Point;
import static java.lang.System.*;

@Slf4j
public class RankOverlay extends Overlay
{
    private final Client client;
    private final ScenePlayers scene;
    private final PvPLeaderboardConfig config;
    private final PvpApi pvpApi;
    /** Opt-in membership set from the snapshot/delta feed (names only). The
     *  overlay gates rendering on this; rank itself comes from the name-keyed
     *  shards (see {@link #fetchSceneRankIfNeeded}). Replaces the
     *  whitelist.json membership blob (see PLAN_PRESENCE_FRESHNESS.md). */
    private final MemberCache memberCache;

    // Resolved rank labels keyed by canonical name — populated by the
    // API-set path (post-fight) and by scene/self shard lookups; read
    // every frame by the overlay render loop.
    private final ConcurrentHashMap<String, String> shownRanks = new ConcurrentHashMap<>();

    /** When each {@link #shownRanks} entry was last written or
     *  re-checked, in millis since epoch. Drives {@link #PEER_RANK_MS}.
     *  A missing timestamp means the label came from a path that didn't stamp
     *  it, so its age is unknown; it is treated as due so the map self-heals. */
    private final ConcurrentHashMap<String, Long> rankShownMs = new ConcurrentHashMap<>();

    /** How long a peer's rank label may go without a re-resolution
     *  attempt (exactly one interval old counts as due). Without this, a
     *  label resolved once was pinned for the whole session: the scene loop
     *  only looks a player up when it has NO label, so an existing entry
     *  short-circuited every later read and
     *  {@code PvpApi}'s 6h shard TTL was never reached for overhead
     *  ranks. Deliberately far below that TTL so a refresh lands on the next
     *  shard generation shortly after it expires; refreshes inside the TTL
     *  are served from the in-memory shard cache, so the added CDN cost is
     *  one read per player per 6h. Pinned by RankOverlayPeerRankRefreshTest. */
    static final long PEER_RANK_MS = 15L * 60L * 1000L;

    // API-set ranks that should persist until shard cache refreshes with matching data
    private final ConcurrentHashMap<String, String> apiSetRanks = new ConcurrentHashMap<>();

    // Combat tracking for "hide rank out of combat" feature
    // Tracks when self was last in combat (milliseconds)
    private volatile long selfCombatMs = 0L;

    // Config change tracking
    private String lastBucketKey = null;

    // Self-rank scheduling
    private volatile long selfRefresh = 0L;
    private volatile boolean selfTried = false;
    private volatile long selfRankDue = 0L;

    /** Scene shard lookup state for opted-in players visible in the
     *  world who don't yet have a rank label above their head. Retry
     *  throttle so render() (~60 fps) issues at most one shard
     *  resolution attempt per player per interval, and none while one is
     *  in flight (pinned by RankOverlaySceneShardTest). Uses the passive
     *  ({@code bypassCache=false}) lookup of
     *  {@link PvpApi#getShardRank(String, String, boolean)}
     *  so repeat attempts are served from the 6h positive cache (once
     *  resolved) or the missing-player negative cache (when unranked),
     *  keeping CDN cost bounded even in a crowded scene. Bounded by
     *  membership + in-scene visibility + this per-player backoff —
     *  never a whole-world shard poll. */
    private static final long SHARD_GAP_MS = 30_000L;
    private final ConcurrentHashMap<String, Long> shardTriedMs = new ConcurrentHashMap<>();
    private final Set<String> shardBusy = ConcurrentHashMap.newKeySet();

    /** Negative backoff for the profile-API fallback used when a scene
     *  player misses the CDN shard. The shard GET is cheap +
     *  CDN/negative-cached, but the {@code /user} profile fetch is a
     *  Lambda+DynamoDB call, so a player who resolves in NEITHER shard nor
     *  profile must not re-hit /user on every {@link #SHARD_GAP_MS}
     *  tick. Positive resolutions are cached permanently in
     *  {@link #shownRanks}, so this only rate limits
     *  genuinely-unresolvable players. */
    private static final long MISS_WAIT_MS = 10L * 60L * 1000L;
    private final ConcurrentHashMap<String, Long> missUntilMs = new ConcurrentHashMap<>();

    // MMR change notification queue (for multi-kill scenarios)
    private final ConcurrentLinkedQueue<MmrNotice> noticeQueue = new ConcurrentLinkedQueue<>();
    private volatile MmrNotice shownNotice = null;
    private volatile long noticeAtMs = 0L;
    private volatile int noticeTick = -1; // Track tick for 1-per-tick display

    // Legacy fields kept for backwards compatibility
    private volatile Double previousMmr = null;

    /**
     * Represents a single MMR change notification.
     */
    @AllArgsConstructor
    private static class MmrNotice {
        final double delta;
        final String bucketLabel;
        final boolean portalCapped;
    }

    @Inject
    public RankOverlay(Client client, PvPLeaderboardConfig config, PvpApi pvpApi,
                       MemberCache memberCache, ScenePlayers scene)
    {
        this.client = client;
        this.scene = scene;
        this.config = config;
        this.pvpApi = pvpApi;
        this.memberCache = memberCache;
        // Always use DYNAMIC for snap-to-player rendering
        // Use UNDER_WIDGETS layer (same as player indicators) so it appears above prayers
        // Use PRIORITY_LOW so it renders behind player indicator names
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPriority(Overlay.PRIORITY_LOW);
    }

    /** Drop-shadow behind every rank label. Hoisted out of the draw
     *  loop: this ran once per label per frame. */
    private static final Color OUTLINE_COLOR = new Color(0, 0, 0, 180);

    /** 3rd Age glow: concentric white layers, widest and faintest
     *  first (offsets 3, 2, 1 by index), drawn under the solid label. */
    private static final Color[] GLOW_COLORS = {
        new Color(255, 255, 255, 25),
        new Color(255, 255, 255, 50),
        new Color(255, 255, 255, 100),
    };

    /** Label font, rebuilt only when the configured text size changes —
     *  see {@link #rankFont(int)}. Touched only from the render thread. */
    private Font rankFont;

    /**
     * Schedule a self-rank refresh on the next frame.
     */
    public void scheduleSelf()
    {
        selfRankDue = currentTimeMillis();
        selfTried = false;
        selfRefresh = selfRankDue;
    }

    /**
     * Reset lookup state on world hop.
     */
    public void onWorldHop()
    {
        selfTried = false;
        selfRankDue = 0L;
        // Note: Don't clear whitelist cache on world hop - it's fetched from API and valid for 1 hour
    }

    /**
     * Get cached rank for a player.
     */
    public String getCachedRankFor(String playerName)
    {
        return shownRanks.get(NameUtils.canonicalKey(playerName));
    }

    /**
     * Set rank from API response.
     * This rank will persist until the shard cache refreshes with matching data.
     */
    public void setApiRank(String playerName, String rank)
    {
        if (playerName == null || playerName.trim().isEmpty() || rank == null || rank.trim().isEmpty())
        {
            return;
        }
        String key = NameUtils.canonicalKey(playerName);
        putShownRank(key, rank);
        // Track this as an API-set rank - persists until shard cache confirms with same rank
        apiSetRanks.put(key, rank);
        pvpApi.clearMisses(playerName);
    }

    /**
     * Write a resolved rank label and stamp it for the refresh cadence.
     * Every path that populates {@link #shownRanks} must go through
     * here, otherwise the entry looks ageless to the refresh check.
     */
    private void putShownRank(String nameKey, String rank)
    {
        shownRanks.put(nameKey, rank);
        rankShownMs.put(nameKey, currentTimeMillis());
    }

    /**
     * Show MMR delta notification with the actual delta from match history.
     * This is the preferred method as it uses the accurate server-calculated delta.
     * Notifications are queued for multi-kill scenarios.
     *
     * @param mmrDelta The actual MMR change (positive for gain, negative for loss)
     * @param bucketLabel Optional bucket label to display (e.g., "Multi") when different from config bucket
     */
    public void showMmrDelta(double mmrDelta, String bucketLabel)
    {
        queueNotice(new MmrNotice(mmrDelta, bucketLabel, false));
    }

    public void showCapped(String bucketLabel)
    {
        queueNotice(new MmrNotice(0.0, bucketLabel, true));
    }

    private void queueNotice(MmrNotice notification)
    {
        if (!config.showMmrChangeNotification())
        {
            return;
        }

        // Add to queue for sequential display
        noticeQueue.offer(notification);

        // If no notification is currently showing, start this one immediately
        if (shownNotice == null && noticeAtMs == 0L)
        {
            startNotice();
        }
    }

    /**
     * Start displaying the next notification from the queue.
     */
    private void startNotice()
    {
        MmrNotice next = noticeQueue.poll();
        if (next != null)
        {
            shownNotice = next;
            noticeAtMs = currentTimeMillis();
        }
        else
        {
            shownNotice = null;
            noticeAtMs = 0L;
        }
    }

    /**
     * Reset the visibility timer when in combat. Called by FightMonitor on
     * every hit. Universal: it keeps all ranks (self and other players)
     * visible for the configured duration.
     */
    public void updateSelfCombatTime()
    {
        selfCombatMs = currentTimeMillis();
    }

    /** Tracks the last time we logged a render-loop throwable, in
     *  millis since epoch. Used to rate-limit the swallow-warn so a
     *  pathological 60-fps NPE storm produces at most one WARN per
     *  minute instead of ~3,600 per minute. */
    private volatile long lastErrorLog = 0L;

    /** Minimum interval between {@code "render threw — swallowing"}
     *  WARN entries when the inner body is failing every frame. One
     *  minute is enough to keep the user's log readable while still
     *  giving prompt feedback if a new failure appears mid-session. */
    private static final long ERROR_LOG_MS = 60_000L;

    @Override
    public Dimension render(Graphics2D graphics)
    {
        // Catch-all guard: the rank overlay paints every frame at
        // ~60 FPS and reaches into client/Player APIs that can
        // transiently null out around login / world-hop / scene
        // transitions. Without this wrapper, a single null deref
        // would feed RuneLite's OverlayRenderer a same-bytecode-
        // location throw every frame; HotSpot then strips the
        // stack via OmitStackTraceInFastThrow and the user sees
        // 60 untraceable WARN lines/sec. Logging once with a real
        // stack here + swallowing downstream restores the diagnostic
        // signal. See {@code RankOverlayRenderSafetyTest} for the
        // contract.
        try
        {
            return renderInner(graphics);
        }
        catch (Throwable t)
        {
            // Rate-limit the WARN line so a pathological 60-fps NPE
            // cannot flood the log. The synthetic Throwable allocated
            // at the catch site always carries a real stack — even
            // when HotSpot has stack-stripped {@code t} via
            // {@code -XX:+OmitStackTraceInFastThrow} after thousands
            // of throws from the same bytecode location — so the user
            // can still locate the call path through {@code render()}.
            long now = currentTimeMillis();
            if (now - lastErrorLog >= ERROR_LOG_MS)
            {
                lastErrorLog = now;
                log.warn(
                    "[RankOverlay] render threw {} (msg={}) — swallowing. " +
                        "Diagnostic stack (HotSpot may have stripped the original):",
                    t.getClass().getName(), t.getMessage(),
                    new Throwable("RankOverlay render diagnostic capture"));
            }
            return new Dimension(0, 0);
        }
    }

    private Dimension renderInner(Graphics2D graphics)
    {
        if (config == null || client == null)
        {
            return new Dimension(0, 0);
        }

        // Handle bucket config changes
        String currentBucket = RankBucket.key(config.rankBucket());

        if (lastBucketKey == null || !lastBucketKey.equals(currentBucket))
        {
            shownRanks.clear();
            rankShownMs.clear();
            apiSetRanks.clear();
            shardTriedMs.clear();
            shardBusy.clear();
            missUntilMs.clear();
            lastBucketKey = currentBucket;
            selfTried = false;
            selfRankDue = 0L;
        }

        // Get local player
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
        {
            return new Dimension(0, 0);
        }

        String localName = localPlayer.getName();

        // Handle self-rank refresh scheduling
        if (config.showOwnRank() && localName != null && selfRefresh > 0L)
        {
            long now = currentTimeMillis();
            if (now >= selfRefresh && !selfTried && now >= selfRankDue)
            {
                selfTried = true;
                selfRefresh = 0L;
                fetchSelf(localName);
            }
        }

        // Show ranks unless "hide rank out of combat" is on and the
        // configured minutes have passed since the last hit. Universal:
        // applies to both the self rank and other players' ranks.
        boolean showRanks = !config.hideRankOutOfCombat()
            || config.hideRankAfterMinutes() * 60_000L >= currentTimeMillis() - selfCombatMs;

        // Fixed heights rather than player.getLogicalHeight(), so the rank
        // doesn't "jump" when players wear different helmets/hats: feet 0,
        // head level 220 (just above the player name), above head 268. A
        // corrupted/missing persisted setting can return null; that draws
        // above the head like the default instead of throwing every frame.
        RankPosition pos = config.rankPosition();
        int heightOffset = pos == RankPosition.FEET ? 0
            : pos == RankPosition.HEAD ? 220 : 268;

        // Render self rank if enabled. localName == null happens
        // transiently during world hops / login; the label is only placed
        // when there is a rank to show and ranks are shown.
        if (config.showOwnRank() && localName != null && showRanks)
        {
            String cachedRank = shownRanks.get(NameUtils.canonicalKey(localName));
            if (cachedRank != null)
            {
                label(graphics, localPlayer, cachedRank, heightOffset);
            }
        }

        // Render MMR change notification
        renderNotice(graphics, localPlayer);

        // Render opted-in player ranks (if enabled and the membership feed
        // has loaded). Membership now comes from the snapshot/delta feed
        // (MemberCache); rank is resolved per name via shards below.
        if (config.enableWhitelistRanks() && memberCache.size() > 0)
        {
            renderRanks(graphics, localPlayer, currentBucket, heightOffset);
        }

        return new Dimension(0, 0);
    }

    /**
     * Render ranks above opted-in players in the scene.
     *
     * <p>Membership (who is an opted-in plugin user) comes from the
     * snapshot/delta feed ({@link MemberCache}); the rank label
     * itself is resolved per name from the {@code rank_idx} shards and
     * stored in {@link #shownRanks} — either eagerly by a fight's
     * API result ({@link #setApiRank}) or lazily by the scene shard
     * lookup below. Uses the current bucket setting.
     */
    private void renderRanks(Graphics2D graphics, Player localPlayer, String bucket,
                                        int heightOffset)
    {
        String localName = localPlayer.getName();

        for (Player player : scene.all())
        {
            if (player == null || player == localPlayer) continue;

            String playerName = player.getName();
            if (playerName == null || playerName.equals(localName)) continue;

            // Only show ranks for opted-in players (membership feed).
            if (!memberCache.isMember(playerName)) continue;

            String nameKey = NameUtils.canonicalKey(playerName);
            // Rank resolved either from a prior fight (API-set) or a
            // previous scene shard lookup — both land in shownRanks.
            String displayRank = shownRanks.get(nameKey);

            // Opted-in + visible but no label yet — kick a cached shard
            // read to resolve it. Passive (cache-first) so a crowded
            // scene is served from the 6h positive cache / missing-player
            // negative cache instead of hammering the CDN each retry.
            // The profile fallback is allowed here: a blank head has
            // nothing to show, so the expensive path is worth it.
            if (displayRank == null)
            {
                fetchSceneRankIfNeeded(playerName, bucket, nameKey, true);
                continue;
            }

            // Label present but past its refresh interval (or of unknown
            // age) — re-resolve in the background while still rendering
            // the current value, so a peer who ranked up mid-session stops
            // showing a label frozen at whatever it was when we first saw
            // them. Shard only: we already have something to display, so a
            // miss must not escalate to the /user Lambda.
            Long setAt = rankShownMs.get(nameKey);
            if (setAt == null || currentTimeMillis() - setAt >= PEER_RANK_MS)
            {
                fetchSceneRankIfNeeded(playerName, bucket, nameKey, false);
            }

            label(graphics, player, displayRank, heightOffset);
        }
    }

    /** Draws {@code rank} above {@code player}'s head (offset by the
     *  configured position). The font metrics are read before
     *  {@link #renderRank} switches to the rank font, as before. */
    private void label(Graphics2D g, Player player, String rank, int heightOffset)
    {
        Point head = player.getCanvasTextLocation(g, "", heightOffset);
        if (head != null)
        {
            renderRank(g, rank, head.getX() + config.rankOffsetX(),
                head.getY() - g.getFontMetrics().getAscent() - 2 + config.rankOffsetY(), Math.max(10, config.rankTextSize()));
        }
    }

    /**
     * Async two-tier rank resolution for an opted-in, in-scene player who
     * still has no rank label (or whose label is due a refresh):
     * <ol>
     *   <li><b>Shard</b> (passive, cache-first): served from the 6h
     *       positive shard cache, or the missing-player negative cache,
     *       so a crowded scene doesn't re-hit the CDN every retry.</li>
     *   <li><b>Profile API fallback</b> on a shard miss: players the shard
     *       writer hasn't picked up for this bucket only resolve via the
     *       {@code /user} endpoint. Rate-limited by
     *       {@link #MISS_WAIT_MS} so an unresolvable
     *       player doesn't hammer the Lambda+DynamoDB path.</li>
     * </ol>
     * Throttled to one in-flight attempt per player and
     * {@link #SHARD_GAP_MS} between attempts so render() never
     * calls the service every frame. A resolved rank lands in
     * {@link #shownRanks} and renders on the next frame, and is
     * re-resolved every {@link #PEER_RANK_MS}; a peer's own
     * post-fight rank change still updates immediately via the API-set
     * path.
     *
     * @param useProfile whether a shard miss may escalate to
     *        the {@code /user} profile API. True for a player with no
     *        label at all, false for a periodic refresh of a label we can
     *        already render — the fallback is a Lambda+DynamoDB call and
     *        isn't worth paying to confirm a rank we're already showing.
     */
    private void fetchSceneRankIfNeeded(String playerName, String bucket, String nameKey,
                                        boolean useProfile)
    {
        long now = currentTimeMillis();
        // A player never attempted has no stamp. A null last-attempt
        // timestamp must never be unboxed into a primitive here: that NPE,
        // swallowed by the render() wrapper, once silently blocked EVERY
        // scene rank resolution.
        Long lastAttempt = shardTriedMs.get(nameKey);
        if (lastAttempt != null && now - lastAttempt < SHARD_GAP_MS || !shardBusy.add(nameKey))
        {
            return;
        }
        shardTriedMs.put(nameKey, now);
        // Re-arm the refresh cadence at ATTEMPT time, not on completion:
        // a lookup that fails or resolves nothing must still wait a full
        // interval, otherwise an unresolvable player would retry every
        // SHARD_GAP_MS forever.
        rankShownMs.put(nameKey, now);

        pvpApi.getShardRank(playerName, bucket, false)
            .whenComplete((sr, ex) ->
            {
                if (ex != null)
                {
                    shardBusy.remove(nameKey);
                    return;
                }
                if (sr != null && sr.tier != null && !sr.tier.trim().isEmpty())
                {
                    shardBusy.remove(nameKey);
                    applyShard(nameKey, sr.tier);
                    return;
                }
                // Nothing to gain from the profile API when we already
                // have a label to render — keep the /user path cold.
                if (!useProfile)
                {
                    shardBusy.remove(nameKey);
                    return;
                }
                // Shard miss — fall back to the profile API. Players the
                // shard writer hasn't picked up for this bucket (e.g. "RUN
                // PIGGY") only resolve via /user. Rate-limited by a negative
                // backoff so an unresolvable player doesn't re-hit the
                // Lambda+DynamoDB path on every scene-retry tick.
                Long missUntil = missUntilMs.get(nameKey);
                if (missUntil != null && currentTimeMillis() < missUntil)
                {
                    shardBusy.remove(nameKey);
                    return;
                }
                pvpApi.getLobbyRank(playerName, bucket)
                    .whenComplete((tier, pex) ->
                    {
                        shardBusy.remove(nameKey);
                        if (pex != null)
                        {
                            missUntilMs.put(nameKey,
                                currentTimeMillis() + MISS_WAIT_MS);
                            return;
                        }
                        if (tier != null && !tier.trim().isEmpty())
                        {
                            putShownRank(nameKey, tier);
                            return;
                        }
                        // Unresolved in both shard and profile — back off the
                        // profile retry to protect the /user endpoint.
                        missUntilMs.put(nameKey,
                            currentTimeMillis() + MISS_WAIT_MS);
                    });
            });
    }

    /**
     * Adopt a shard-resolved rank (for a scene player or, as the API
     * fallback, for self), deferring to a post-fight API rank that the
     * shard hasn't caught up to yet.
     *
     * <p>An API rank is newer than any shard generation, so a disagreeing
     * shard read is stale data and must not clobber it. Once the shard
     * agrees, the override has served its purpose and is dropped.
     */
    private void applyShard(String nameKey, String shardRank)
    {
        String apiRank = apiSetRanks.get(nameKey);
        if (apiRank != null && !apiRank.equals(shardRank))
        {
            return;
        }
        if (apiRank != null)
        {
            apiSetRanks.remove(nameKey);
        }
        putShownRank(nameKey, shardRank);
    }

    private void fetchSelf(String selfName)
    {
        String bucket = RankBucket.key(config.rankBucket());
        String key = NameUtils.canonicalKey(selfName);

        pvpApi.getTierFromProfile(selfName, bucket)
            .thenAccept(apiTier -> {
                long fetchedAt = currentTimeMillis();

                if (apiTier != null)
                {
                    putShownRank(key, apiTier);
                    apiSetRanks.put(key, apiTier);
                    selfRankDue = fetchedAt + 60_000L;
                }
                else
                {
                    fetchRankForSelfFromShard(selfName, bucket, key);
                }
            })
            .exceptionally(ex -> {
                fetchRankForSelfFromShard(selfName, bucket, key);
                return null;
            });
    }

    /**
     * Fallback method to fetch self rank from shard when API fails.
     */
    private void fetchRankForSelfFromShard(String selfName, String bucket, String key)
    {
        pvpApi.getShardRank(selfName, bucket, false)
            .thenAccept(sr -> {
                if (sr == null)
                {
                    return;
                }
                if (sr.tier != null)
                {
                    long fetchedAt = currentTimeMillis();
                    // An API-set rank persists until the shard has refreshed with matching data
                    applyShard(key, sr.tier);
                    selfRankDue = fetchedAt + 60_000L;
                }
            })
            .exceptionally(ex -> {
                selfRankDue = currentTimeMillis() + 60_000L;
                return null;
            });
    }

    private void renderRank(Graphics2D g, String fullRank, int x, int y, int size)
    {
        String text = rankLabelText(fullRank);
        if (text.isEmpty())
        {
            return;
        }

        g.setFont(rankFont(size));
        FontMetrics fm = g.getFontMetrics();
        int centerX = x - fm.stringWidth(text) / 2;
        int baseY = y + fm.getAscent();

        // 3rd Age: special glow (white layers widest first), then core
        // white text; every other rank: black outline + coloured text
        // (white in colour-blind mode and for a "Rank N" label).
        boolean glow = text.startsWith("3rd") && !config.colorblindMode();
        if (glow)
        {
            for (int i = 0; i < GLOW_COLORS.length; i++)
            {
                g.setColor(GLOW_COLORS[i]);
                ring(g, text, centerX, baseY, 3 - i);
            }
        }
        else
        {
            g.setColor(OUTLINE_COLOR);
            ring(g, text, centerX, baseY, 1);
        }
        g.setColor(glow || config.colorblindMode() || text.startsWith("Rank ") ? Color.WHITE : RankUtils.getRankColor(text));
        g.drawString(text, centerX, baseY);
    }

    /** Draws {@code text} at every offset within {@code r} of (x, y) except
     *  (x, y) itself, rows top to bottom: the outline / glow ring. */
    private static void ring(Graphics2D g, String text, int x, int y, int r)
    {
        for (int dy = -r; dy <= r; dy++)
        {
            for (int dx = -r; dx <= r; dx++)
            {
                if (dx != 0 || dy != 0)
                {
                    g.drawString(text, x + dx, y + dy);
                }
            }
        }
    }

    /**
     * The label to draw for {@code fullRank}: the rank and its division,
     * trimmed and single-spaced, or empty when there's nothing to show.
     *
     * <p>Normalised rather than used verbatim because the label is
     * centred on the player's head from its measured width — a stray
     * double space would draw wider than it measured and sit off-centre.
     */
    static String rankLabelText(String fullRank)
    {
        if (fullRank == null) return "";
        String trimmed = fullRank.trim();
        if (trimmed.isEmpty()) return "";
        int space = trimmed.indexOf(' ');
        if (space < 0) return trimmed;
        String rankName = trimmed.substring(0, space);
        String division = trimmed.substring(space + 1).trim();
        return division.isEmpty() ? rankName : (rankName + " " + division);
    }

    /**
     * The bold label font at {@code size}, cached across frames.
     *
     * <p>This is called once per visible opted-in player per frame, so
     * at 50 FPS in a crowded area it ran thousands of times a second —
     * each {@code new Font} also forced a fresh font-metrics lookup.
     * The size only changes when the user moves the rank-text-size
     * slider, so one cached instance serves ~every call.
     */
    private Font rankFont(int size)
    {
        Font cached = rankFont;
        if (cached == null || cached.getSize() != size)
        {
            cached = new Font(Font.DIALOG, Font.BOLD, size);
            rankFont = cached;
        }
        return cached;
    }

    private void renderNotice(Graphics2D g, Player localPlayer)
    {
        int currentTick = client.getTickCount();

        if (shownNotice == null || noticeAtMs == 0L)
        {
            // Try to start next notification if queue has items (rate limit: 1 per tick)
            if (!noticeQueue.isEmpty() && currentTick != noticeTick)
            {
                startNotice();
                noticeTick = currentTick;
            }
            return;
        }
        if (!config.showMmrChangeNotification())
        {
            return;
        }

        // Check if current notification duration has expired
        long durationMs = config.mmrDuration() * 1000L;
        long elapsed = currentTimeMillis() - noticeAtMs;

        if (elapsed > durationMs)
        {
            // Current notification finished - start next (rate limit: 1 per tick)
            if (currentTick != noticeTick)
            {
                startNotice();
                noticeTick = currentTick;
            }
            else
            {
                // Already started one this tick, clear current and wait for next tick
                shownNotice = null;
                noticeAtMs = 0L;
            }
            return;
        }

        // Get position above player
        Point headLoc = localPlayer.getCanvasTextLocation(g, "", localPlayer.getLogicalHeight() + 80);
        if (headLoc == null)
        {
            return;
        }

        MmrNotice notification = shownNotice;

        // Calculate fade progress
        float progress = (float) elapsed / durationMs;
        int alpha = (int) (255 * (1.0f - progress));
        int floatOffset = (int) (progress * 30); // Float up 30 pixels

        String text = noticeText(notification.delta, notification.bucketLabel, notification.portalCapped);
        Color baseColor = noticeColor(notification.delta, notification.portalCapped, config.colorblindMode());
        Color color = new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), alpha);

        // Render with black outline
        g.setFont(new Font(Font.DIALOG, Font.BOLD, Math.max(12, config.rankTextSize() + 2)));
        FontMetrics fm = g.getFontMetrics();
        int textW = fm.stringWidth(text);
        int centerX = headLoc.getX() - textW / 2 + config.mmrOffsetX();
        int drawY = headLoc.getY() - floatOffset + config.mmrOffsetY();

        // Black outline with alpha
        g.setColor(new Color(0, 0, 0, (int) (180 * (1.0f - progress))));
        ring(g, text, centerX, drawY, 1);

        // Main colored text
        g.setColor(color);
        g.drawString(text, centerX, drawY);
    }

    /** "+14.0 MMR" (a zero change reads as a gain), or the portal cap's
     *  label; " (label)" appended when a bucket label is given. */
    static String noticeText(double mmrDelta, String bucketLabel, boolean portalCapped)
    {
        return (portalCapped ? PortalCap.LABEL : String.format("%s%.1f MMR", mmrDelta >= 0 ? "+" : "", mmrDelta))
            + (bucketLabel != null && !bucketLabel.isEmpty() ? " (" + bucketLabel + ")" : "");
    }

    /** White in colour-blind mode; else green for a gain or a capped fight, red for a loss. */
    static Color noticeColor(double mmrDelta, boolean portalCapped, boolean colorblind)
    {
        return colorblind ? Color.WHITE : portalCapped || mmrDelta >= 0 ? new Color(0, 200, 0) : new Color(0xe53935);
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.game.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import java.util.function.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.outline.*;
import java.util.List;

@Singleton
public class TournamentOpponentOverlay extends Overlay
{
    /** The outline colour. */
    static final Color OUTLINE = new Color(0xffd700);
    private static final int OUTLINE_WIDTH = 2;
    private static final int OUTLINE_FEATHER = 0;

    private final Client client;
    private final ModelOutlineRenderer renderer;
    private final ScenePlayers scene;
    private volatile Supplier<Set<String>> oppsSupplier = () -> null;

    private Set<String> lookupKeys;
    private List<Player> lookupResult = Collections.emptyList();
    private int lookupTick;

    @Inject
    public TournamentOpponentOverlay(Client client, ModelOutlineRenderer renderer, ScenePlayers scene)
    {
        this.client = client;
        this.renderer = renderer;
        this.scene = scene;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(Overlay.PRIORITY_LOW);
    }

    /** The canonical keys of every name to outline; {@code null} or empty for none. Wired by the plugin to the session tracker. */
    public void setOpponentKeysSupplier(Supplier<Set<String>> supplier)
    {
        oppsSupplier = supplier;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        try
        {
            for (Player opponent : opponentsFor(oppsSupplier.get()))
            {
                renderer.drawOutline(opponent, OUTLINE_WIDTH, OUTLINE, OUTLINE_FEATHER);
            }
        }
        catch (Exception ignored)
        {
            // A transient scene state must never feed RuneLite's renderer an exception per frame.
        }
        return null;
    }

    private List<Player> opponentsFor(Set<String> keys)
    {
        if (keys == null || keys.isEmpty()) return Collections.emptyList();
        int tick = client.getTickCount();
        if (!keys.equals(lookupKeys) || tick != lookupTick)
        {
            lookupKeys = keys;
            lookupTick = tick;
            lookupResult = Collections.emptyList();
            lookupResult = findByKeys(keys);
        }
        return lookupResult;
    }

    /** Every scene player whose canonical name is one of {@code wanted}, never the local player. */
    private List<Player> findByKeys(Set<String> wanted)
    {
        Player local = client.getLocalPlayer();
        List<Player> found = new ArrayList<>(1);
        for (Player p : scene.all())
        {
            if (p == null || p == local) continue;
            String name = p.getName();
            if (name == null) continue;
            if (wanted.contains(NameUtils.canonicalKey(name))) found.add(p);
        }
        return found;
    }
}

package com.pvp.leaderboard.overlay;

import com.pvp.leaderboard.cache.*;
import com.pvp.leaderboard.config.*;
import com.pvp.leaderboard.game.*;
import com.pvp.leaderboard.service.*;
import java.awt.*;
import java.util.*;
import java.util.function.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;
import java.util.List;
import java.awt.Point;

@Singleton
public class WinStreakOverlay extends OverlayPanel
{
	/** Minimum gap between two cache peeks (a map lookup + a key
	 *  canonicalisation): the render loop runs ~50 times a second, the
	 *  profile changes a few times a session. */
	static final long PEEK_MS = 1_000L;
	static final int BORDER_PX = 2;
	static final int GAP_PX = 1;
	private static final int SHADOW_PX = 1;

	private final Client client;
	private final PvPLeaderboardConfig config;
	private final PvpApi pvpApi;
	private final WinStreakTracker tracker;
	/** Its auto-switch target is the style shown; its FFA portal flag gates the box. */
	private final FightMonitor fightMonitor;
	private final LongSupplier nowMs;

	// ---- profile-peek state: client thread only ----
	private String peekedSelf;
	private long nextPeekAtMs;
	private long peekedTs = Long.MIN_VALUE;
	private WinLossPeak winLossPeak;

	@Inject
	public WinStreakOverlay(Client client, PvPLeaderboardConfig config, PvpApi pvpApi,
		WinStreakTracker tracker, FightMonitor fightMonitor)
	{
		this(client, config, pvpApi, tracker, fightMonitor, System::currentTimeMillis);
	}

	WinStreakOverlay(Client client, PvPLeaderboardConfig config, PvpApi pvpApi,
		WinStreakTracker tracker, FightMonitor fightMonitor, LongSupplier nowMs)
	{
		this.client = client;
		this.config = config;
		this.pvpApi = pvpApi;
		this.tracker = tracker;
		this.fightMonitor = fightMonitor;
		this.nowMs = nowMs;
		// A positioned (non-DYNAMIC) overlay is movable + snappable through
		// RuneLite's standard Alt+drag; TOP_LEFT is only where it starts.
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(Overlay.PRIORITY_LOW);
		setResizable(false);
		panelComponent.setBorder(new Rectangle(BORDER_PX, BORDER_PX, BORDER_PX, BORDER_PX));
		panelComponent.setGap(new Point(0, GAP_PX));
	}

	public static boolean isShown(boolean alwaysShow, boolean showInFfa, boolean insideFfaPortal)
	{
		return alwaysShow || (showInFfa && insideFfaPortal);
	}

	@Override
	public Dimension getPreferredSize()
	{
		return null;
	}

	/** Forget the peeked profile and the last frame (plugin shutdown) so a
	 *  re-enable re-reads the cache at once. */
	public void clear()
	{
		peekedSelf = null;
		nextPeekAtMs = 0L;
		peekedTs = Long.MIN_VALUE;
		winLossPeak = null;
		panelComponent.getChildren().clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		try
		{
			panelComponent.getChildren().clear();
			if (!isShown(config.showKillStreakBox(), config.killStreakBoxInFfaPortal(), fightMonitor.isInsideFfaPortal())) return null;
			String self = localPlayerName();
			if (self == null) return null;
			WinLossPeak profile = profileFor(self);
			if (!tracker.isKnown()) return null;
			List<String> lines = linesFor(resolveBucket(), tracker, profile, config.killStreakBoxShowLongest(),
				config.killStreakBoxShowWinLoss(), config.killStreakBoxShowPeak());
			Font font = FontManager.getRunescapeSmallFont();
			FontMetrics fm = graphics.getFontMetrics(font);
			int widest = 0;
			for (String line : lines)
			{
				panelComponent.getChildren().add(LineComponent.builder().left(line).leftFont(font).rightFont(font).build());
				widest = Math.max(widest, fm.stringWidth(line));
			}
			panelComponent.setPreferredSize(new Dimension(widest + 2 * BORDER_PX + SHADOW_PX, 0));
			return super.render(graphics);
		}
		catch (Exception ignored)
		{
			// A transient client / config state must never feed RuneLite's renderer an exception per frame.
			panelComponent.getChildren().clear();
			return null;
		}
	}

	/** The style to show: the pinned one while auto-switch is off; else the
	 *  auto-switch target (Tournament reads Event), the leaderboard bucket the
	 *  config holds, then NH. */
	StreakBucket resolveBucket()
	{
		if (!config.killStreakBoxAutoSwitch())
		{
			StreakBucket pinned = config.killStreakBoxBucket();
			return pinned == null ? StreakBucket.NH : pinned;
		}
		StreakBucket live = StreakBucket.forRank(fightMonitor.getAutoSwitchTarget());
		if (live != null) return live;
		StreakBucket persisted = StreakBucket.forRank(config.rankBucket());
		return persisted == null ? StreakBucket.NH : persisted;
	}

	static List<String> linesFor(StreakBucket bucket, WinStreakTracker tracker, WinLossPeak profile,
		boolean showLongest, boolean showWinLoss, boolean showPeak)
	{
		String key = bucket.bucketKey;
		List<String> lines = new ArrayList<>(4);
		lines.add(bucket.label + " Current Kill Streak: " + tracker.text(key));
		if (showLongest) lines.add("Longest Kill Streak: " + tracker.longest(key));
		if (showWinLoss && profile != null) lines.add("W/L: " + profile.wins(key) + "-" + profile.losses(key));
		String peak = showPeak && profile != null ? profile.peak(key) : null;
		if (peak != null) lines.add("Peak: " + peak);
		return lines;
	}

	WinLossPeak profileFor(String self)
	{
		if (!self.equals(peekedSelf))
		{
			peekedSelf = self;
			nextPeekAtMs = 0L;
			peekedTs = Long.MIN_VALUE;
			winLossPeak = null;
		}
		long now = nowMs.getAsLong();
		if (now >= nextPeekAtMs)
		{
			nextPeekAtMs = now + PEEK_MS;
			UserStats cached = pvpApi.peekProfile(self);
			if (cached != null && cached.getTimestamp() != peekedTs)
			{
				peekedTs = cached.getTimestamp();
				tracker.observeProfile(cached);
				winLossPeak = WinLossPeak.fromProfile(cached.getStats());
			}
		}
		return winLossPeak;
	}

	private String localPlayerName()
	{
		Player local = client.getLocalPlayer();
		if (local == null) return null;
		String name = local.getName();
		return name == null || name.trim().isEmpty() ? null : name;
	}
}

