package com.pvp.leaderboard.queue;

import com.google.gson.*;
import java.util.*;

/**
 * Server-push callbacks for the matchmaking queue (Plan 10 Part B / F.1),
 * registered with a {@link QueueService}. Every callback is delivered on
 * the Swing EDT (the {@code WebSocketQueueService} marshals), so panels
 * may mutate Swing components directly. All methods are {@code default}
 * no-ops. A queue match ({@code queue/matched}) is the lobby service's:
 * its {@code lobby/fight_proposed} drives the Confirm Fight view.
 */
public interface QueueEventListener
{
    /** {@code queue/state} — after join / leave / expand / status and every
     *  tick while searching. {@code state == idle} with a {@code reason}
     *  means the worker tore a proposed fight down (expired / declined). */
    default void onQueueState(QueueState state) {}

    /** {@code queue/timeout} — the wait preference elapsed; the user is
     *  out of the queue. */
    default void onQueueTimeout(QueueState state) {}

    /** {@code queue/prefs} — echo of the shared preferences after
     *  {@code queue/set_prefs}. */
    default void onQueuePrefs(JsonObject prefs) {}

    /** {@code error/queue} — a stable error code + message. */
    default void onQueueError(String code, String message) {}

    /** {@code queue/recent_list}: the recent joins, newest first; empty when there are none. */
    default void onRecentQueued(List<RecentJoin> joins) {}
}

package com.pvp.leaderboard.queue;

import com.google.gson.*;
import com.pvp.leaderboard.util.*;

/**
 * The shared matchmaking preferences carried by a {@code queue/prefs}
 * push (WEBSOCKET_PROTOCOL.md § 6.2b) — the plugin's inbound half of
 * parity gap <b>G-2</b>. The same {@code OSRS-MatchmakingPrefs} row backs
 * the plugin's gate pickers and the Discord modal, so a wait time or rank
 * range set on either surface has to land on the other.
 *
 * <p><b>Tri-state on purpose.</b> The wire distinguishes three things and
 * so does this object: a key the server did not send states nothing and
 * must not overwrite a local pick; an explicit {@code null}
 * {@code rank_range} is the server saying "no range"; an object turns the
 * range on. {@link #waitPrefS} is {@link QueueState#UNKNOWN} when unstated
 * and {@link #rangeEnabled} is {@code null} when unstated.
 *
 * <p><b>Nothing here is required.</b> Plugin releases take days and cannot
 * be reverted (CLAUDE.md § 10), so the backend must keep serving the
 * previous client: every field is optional, wrong types degrade to
 * "unstated" and unknown fields are ignored rather than rejected. The
 * server's own keys that the plugin has no picker for ({@code region},
 * {@code style}, {@code build}, {@code location},
 * {@code auto_switch_bucket}, {@code discord_user_id}) are deliberately
 * not read here — the gate owns those locally.
 */
public final class QueuePrefs
{
    /** The shared wait preference in seconds, snapped onto
     *  {@link QueueService#WAIT_CHOICES}, or {@link QueueState#UNKNOWN}
     *  when the push stated none. */
    public final int waitPrefS;

    /** {@code TRUE} = the server carries a range, {@code FALSE} = the server
     *  cleared it, {@code null} = the push stated nothing. */
    public final Boolean rangeEnabled;

    /** Ordered bounds, both {@link QueueState#UNKNOWN} unless
     *  {@link #rangeEnabled} is {@code TRUE}. */
    public final int minRankIdx;
    public final int maxRankIdx;

    public QueuePrefs(int waitPrefS, Boolean rangeEnabled, int minRankIdx, int maxRankIdx)
    {
        this.waitPrefS = waitPrefS;
        this.rangeEnabled = rangeEnabled;
        this.minRankIdx = minRankIdx;
        this.maxRankIdx = maxRankIdx;
    }

    /** {@code true} when the push named a wait preference. */
    public boolean hasWaitPref()
    {
        return waitPrefS != QueueState.UNKNOWN;
    }

    /** Parses the {@code prefs} object of a {@code queue/prefs} push (or of
     *  an additive {@code prefs} on {@code queue/state}). Never throws;
     *  {@code null} / empty states nothing. */
    public static QueuePrefs fromJson(JsonObject prefs)
    {
        Integer wait = JsonLenient.optInteger(prefs, "wait_pref_s");
        Boolean rangeEnabled = null;
        int min = QueueState.UNKNOWN;
        int max = QueueState.UNKNOWN;
        JsonElement rrRaw = prefs == null ? null : prefs.get("rank_range");
        if (rrRaw != null && rrRaw.isJsonNull())
        {
            // The server explicitly cleared the shared range.
            rangeEnabled = false;
        }
        else if (rrRaw != null && rrRaw.isJsonObject())
        {
            JsonObject rr = rrRaw.getAsJsonObject();
            int lo = JsonLenient.optInt(rr, "min_rank_idx", QueueState.UNKNOWN);
            int hi = JsonLenient.optInt(rr, "max_rank_idx", QueueState.UNKNOWN);
            // A half-written range cannot drive a two-ended slider; treat
            // it as "no range" rather than guessing the missing bound.
            rangeEnabled = lo != QueueState.UNKNOWN && hi != QueueState.UNKNOWN;
            if (rangeEnabled)
            {
                min = Math.min(lo, hi);
                max = Math.max(lo, hi);
            }
        }
        // Any other type (array, string, number) states nothing — a future
        // server shape must never clear a user's local pick.
        return new QueuePrefs(wait == null ? QueueState.UNKNOWN : WebSocketQueueService.snapWait(wait), rangeEnabled, min, max);
    }

    @Override
    public String toString()
    {
        return "QueuePrefs{wait=" + waitPrefS + " range=" + rangeEnabled + " " + minRankIdx + "–" + maxRankIdx + "}";
    }
}

package com.pvp.leaderboard.queue;

import com.pvp.leaderboard.lobby.*;

/**
 * The seam between the matchmaking panel and the queue transport (Plan
 * 10 Part B / F.1). Fire-and-forget: outcomes arrive through the
 * registered {@link QueueEventListener}. The production implementation is
 * {@link WebSocketQueueService}; {@link NoOpQueue} is the inert
 * fallback (the gate then hides the queue button). Every call defaults to
 * doing nothing, which is the inert service.
 */
public interface QueueService
{
    /** Wait-time choices (seconds) shared with Discord — AS-64. */
    int[] WAIT_CHOICES = {30, 300, 600, 900};

    /** The index of the choice nearest {@code waitPrefS}; of two equally
     *  near, the first. */
    static int waitIndex(int waitPrefS)
    {
        int best = 0;
        for (int i = 1; i < WAIT_CHOICES.length; i++)
        {
            if (Math.abs((long) WAIT_CHOICES[i] - waitPrefS) < Math.abs((long) WAIT_CHOICES[best] - waitPrefS))
            {
                best = i;
            }
        }
        return best;
    }

    default void setListener(QueueEventListener listener) { }

    default void start() { }

    /** {@code queue/join}: one style, one build, the user's region, an
     *  optional rank range (pass {@link QueueState#UNKNOWN} for both to
     *  omit) and the wait preference in seconds. */
    default void join(String region, Style style, BuildType build, int minRankIdx, int maxRankIdx, int waitPrefS) { }

    /** {@code queue/leave}. */
    default void leave() { }

    /** {@code queue/expand_range}: search everyone in the style at once. */
    default void expandRange() { }

    /** {@code queue/status}: re-sync (panel opened / reconnect). */
    default void requestStatus() { }

    /** {@code queue/recent} now and every 5 minutes while {@code open}; {@code false} stops it. */
    default void watchRecent(boolean open) { }

    // ---- shared preferences (parity gap G-2) -------------------------
    // The wait time and the rank range live in ONE server-side row shared
    // with the Discord queue, so the plugin writes it on a local pick and
    // re-reads it when the socket comes up. Each is one job.

    /** {@code queue/set_prefs} with an <b>empty</b> {@code prefs} object:
     *  merges nothing server-side and answers {@code queue/prefs} with the
     *  stored row — the read-through that brings a Discord-side change to
     *  the plugin's pickers. */
    default void requestPrefs() { }

    /** {@code queue/set_prefs} with only {@code wait_pref_s}, so the shared
     *  rank range is left untouched. */
    default void sendWaitPref(int waitPrefS) { }

    /** {@code queue/set_prefs} with only {@code rank_range}; pass
     *  {@link QueueState#UNKNOWN} for both bounds to clear it. */
    default void sendRange(int minRankIdx, int maxRankIdx) { }

    /** {@code true} when this is a real transport (the gate shows the
     *  queue controls); the no-op service answers {@code false}. */
    default boolean isAvailable() { return true; }
}

package com.pvp.leaderboard.queue;

import com.google.gson.*;
import com.pvp.leaderboard.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

/**
 * Immutable snapshot of the local user's matchmaking-queue state, parsed
 * from a {@code queue/state} (or {@code queue/timeout}) push — Plan 10
 * Part B / F.1 (2026-09-21). The part of the backend's
 * {@code matchmaking_queue.public_state} the plugin shows:
 *
 * <pre>
 * state            searching | idle | timeout
 * window           ±rating window (100/200/400/800) or null = anyone in the style
 * expanded         true once the search is open to everyone
 * elapsed_s / wait_pref_s
 * reason           idle only: "expired" | "opponent_declined" (Part E, additive)
 * fight_session_id idle with a reason: the fight session the server ended
 * </pre>
 *
 * The server also sends the rank range, the remaining and next-expansion
 * times, the match counters, style, build and region; nothing reads them.
 * Missing keys degrade to neutral values so a partial push never throws
 * on the socket read thread. No UUIDs — the queue is keyed on
 * {@code player_id} server-side and the plugin only ever sees names.
 */
public final class QueueState
{
    public static final int UNKNOWN = -1;

    public final String state;
    /** {@code null} = the search is open to anyone in the style. */
    public final Integer window;
    public final boolean expanded;
    public final int elapsedS;
    public final int waitPrefS;
    public final String reason;
    /** The fight session an idle state's {@code reason} is about; {@code null} when the push names none. */
    public final String fightId;

    public QueueState(String state, Integer window, boolean expanded, int elapsedS, int waitPrefS, String reason,
                      String fightId)
    {
        this.state = state == null ? "idle" : state;
        this.window = window;
        this.expanded = expanded;
        this.elapsedS = elapsedS;
        this.waitPrefS = waitPrefS;
        this.reason = reason;
        this.fightId = fightId == null || fightId.isEmpty() ? null : fightId;
    }

    public static QueueState fromJson(JsonObject d)
    {
        if (d == null) d = new JsonObject();
        return new QueueState(
            optString(d, "state", "idle"),
            optInteger(d, "window"),
            optBool(d, "expanded", false),
            optInt(d, "elapsed_s", 0),
            optInt(d, "wait_pref_s", 0),
            optString(d, "reason", null),
            optString(d, "fight_session_id", null));
    }

    public boolean isSearching()
    {
        return "searching".equals(state);
    }

    /** {@code true} for an idle state whose {@code reason} says the server ended a match before both
     *  players confirmed: {@code "expired"} or {@code "opponent_declined"}. */
    public boolean endsMatch()
    {
        return "idle".equals(state) && ("expired".equals(reason) || "opponent_declined".equals(reason));
    }

    @Override
    public String toString()
    {
        return "QueueState{" + state + " window=" + window + " expanded=" + expanded + " elapsed=" + elapsedS + "/" + waitPrefS + "}";
    }
}

package com.pvp.leaderboard.queue;

import com.pvp.leaderboard.lobby.*;
import java.util.*;

/**
 * User-facing text for the matchmaking queue (Plan 10 F.1, 2026-09-21):
 * the wait-time labels shared by the gate picker and the timeout banner,
 * the banners for the server's idle {@code reason}s (Part E), the
 * {@code error/queue} table, and the style / build labels the searching
 * card prints. Pure functions — {@code MatchmakingLobbyPanel} decides
 * <i>when</i> to show them. Wording is the operator's (mockup v4 / plan
 * § Part F); lobby codes defer to {@link LobbyErrors} so one code
 * never has two translations, except {@code MATCHMAKING_SUSPENDED} ({@link #BANNED}).
 */
public final class QueueText
{
    /** The same sentence as the lobby's {@code FIGHT_SESSION_EXPIRED}. */
    public static final String EXPIRED = LobbyErrors.MATCH_EXPIRED;
    public static final String OPPONENT_DECLINED = "Your opponent can't make it — the match was cancelled.";
    public static final String LEFT_ON_DISCORD = "You left the queue on Discord.";
    /** A queue join refused with {@code MATCHMAKING_SUSPENDED}, and a tournament
     *  registration refused with {@code TOURNAMENT_BANNED}. */
    public static final String BANNED = "Your account is banned from matchmaking and tournaments. DM Toyco if this is a mistake.";
    public static final String RECENT = "Recently Queued";

    /** {@code error/queue} codes and their sentences; read before the lobby table. */
    private static final Map<String, String> QUEUE_ERRORS = Map.of(
        "MATCHMAKING_SUSPENDED", BANNED,
        "QUEUE_ALREADY_IN", "You are already in the queue.",
        "QUEUE_NOT_IN", "You are not in the queue.",
        "QUEUE_IN_OPEN_SESSION", "You already have a match to confirm.",
        "QUEUE_COOLDOWN", "You're on a matchmaking cooldown.",
        "QUEUE_INVALID_PREF", "That queue preference is not valid. Pick a wait time from the list and try again.",
        "QUEUE_STYLE_UNAVAILABLE", "The queue is NH only.");

    /** {@code "30 s"} / {@code "5 min"} / {@code "10 min"} / {@code "15 min"};
     *  any other value prints the same way ({@code "1 min 30 s"}). */
    public static String waitLabel(int waitPrefS)
    {
        int s = Math.max(0, waitPrefS);
        if (s < 60) return s + " s";
        if (s % 60 == 0) return (s / 60) + " min";
        return (s / 60) + " min " + (s % 60) + " s";
    }

    /** The banner for an idle {@code queue/state}'s {@code reason}, or
     *  {@code null} when there is nothing to tell the user. */
    public static String forIdleReason(String reason)
    {
        if (reason == null) return null;
        switch (reason)
        {
            case "expired": return EXPIRED;
            case "opponent_declined": return OPPONENT_DECLINED;
            case "left_on_discord": return LEFT_ON_DISCORD;
            default: return null;
        }
    }

    /** The {@code queue/timeout} banner. */
    public static String forTimeout(int waitPrefS)
    {
        return "No opponent found within " + waitLabel(waitPrefS) + " — you left the queue.";
    }

    /** Queue codes and {@code MATCHMAKING_SUSPENDED} → the table above; other
     *  lobby codes → {@link LobbyErrors}; anything newer → the server's
     *  message, then the generic fallback. Never the raw code. */
    public static String forError(String code, String message)
    {
        String queue = code == null ? null : QUEUE_ERRORS.get(code);
        if (queue != null) return queue;
        if (LobbyErrors.isKnown(code)) return LobbyErrors.forCode(code);
        if (message != null && !message.trim().isEmpty()) return message.trim();
        return LobbyErrors.UNKNOWN_FALLBACK;
    }

    /** {@code "NH"} for the wire's {@code "nh"}; the fallback's label when
     *  the wire value is absent / unknown; {@code "?"} without either. */
    public static String styleLabel(String wireStyle, Style fallback)
    {
        Style s = parseStyle(wireStyle);
        if (s == null) s = fallback;
        return s == null ? "?" : s.label;
    }

    /** {@code "Main"} for the wire's {@code "main"}, same fallbacks as {@link #styleLabel}. */
    public static String buildLabel(String wireBuild, BuildType fallback)
    {
        BuildType b = parseBuild(wireBuild);
        if (b == null) b = fallback;
        return b == null ? "?" : b.label;
    }

    /** The wire style ({@code nh} / {@code veng} / {@code multi} / {@code dmm}, any case), or {@code null}. */
    public static Style parseStyle(String wire)
    {
        if (wire == null || wire.trim().isEmpty()) return null;
        try
        {
            return Style.valueOf(wire.trim().toUpperCase(Locale.ROOT));
        }
        catch (IllegalArgumentException e)
        {
            return null;
        }
    }

    /** The wire build ({@code main} / {@code zerker} / {@code pure}, any case), or {@code null}. */
    public static BuildType parseBuild(String wire)
    {
        if (wire == null || wire.trim().isEmpty()) return null;
        try
        {
            return BuildType.valueOf(wire.trim().toUpperCase(Locale.ROOT));
        }
        catch (IllegalArgumentException e)
        {
            return null;
        }
    }
}

