package com.pvp.leaderboard.queue;

import com.google.gson.*;
import com.pvp.leaderboard.lobby.*;
import com.pvp.leaderboard.service.socket.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import javax.inject.*;
import javax.swing.*;

/**
 * {@link QueueService} over the plugin's WebSocket (Plan 10 Part B / F.1,
 * 2026-09-21). Encodes the {@code queue/*} cmds and turns the server
 * pushes + {@code error/queue} into EDT-delivered
 * {@link QueueEventListener} callbacks.
 *
 * <p>Reconnect: after a socket re-open the server's row may or may not
 * still exist (queue rows expire with the wait preference), so the
 * service re-asks with {@code queue/status} instead of replaying the
 * join — the panel re-renders from the answer.
 *
 * <p>No UUIDs: {@code queue/join} carries region / style / build / range
 * / wait only; the server keys the row on the trusted connection.
 */
@Singleton
public class WebSocketQueueService implements QueueService
{
    private final SocketMgr socket;
    private final SocketBus bus;
    private final ScheduledExecutorService scheduler;
    private volatile QueueEventListener listener;
    private volatile boolean started = false;
    /** The 5-minute {@code queue/recent} repeat; {@code null} while the Matchmaking tab is closed. */
    private volatile ScheduledFuture<?> recentJob;

    @Inject
    public WebSocketQueueService(SocketMgr socket, SocketBus bus, ScheduledExecutorService scheduler)
    {
        this.socket = socket;
        this.bus = bus;
        this.scheduler = scheduler;
    }

    @Override
    public void setListener(QueueEventListener listener)
    {
        this.listener = listener;
    }

    @Override
    public synchronized void start()
    {
        if (started) return;
        started = true;
        bus.register("queue/state", this::handleState);
        bus.register("queue/timeout", this::handleTimeout);
        bus.register("queue/prefs", this::handlePrefs);
        bus.register("error/queue", this::handleError);
        bus.register("queue/recent_list", this::handleRecent);
        // ONE re-sync listener: on a socket (re-)open, ask for the live queue
        // row and re-read the shared prefs row (G-2) in the same hook, and the
        // recent joins while the Matchmaking tab is open.
        socket.addResyncListener(() ->
        {
            requestStatus();
            requestPrefs();
            if (recentJob != null) requestRecent();
        });
    }

    @Override
    public void join(String region, Style style, BuildType build, int minRankIdx, int maxRankIdx, int waitPrefS)
    {
        if (style == null || build == null) return;
        var d = new JsonObject();
        d.addProperty("region", region == null ? "" : region);
        d.addProperty("style", style.name().toLowerCase());
        d.addProperty("build", build.name().toLowerCase());
        if (minRankIdx != QueueState.UNKNOWN && maxRankIdx != QueueState.UNKNOWN)
        {
            d.add("rank_range", range(minRankIdx, maxRankIdx));
        }
        d.addProperty("wait_pref_s", snapWait(waitPrefS));
        socket.send("queue/join", d);
    }

    /** The {@code rank_range} object: the two bounds, lowest first. */
    private static JsonObject range(int a, int b)
    {
        var rr = new JsonObject();
        rr.addProperty("min_rank_idx", Math.min(a, b));
        rr.addProperty("max_rank_idx", Math.max(a, b));
        return rr;
    }

    /** Snaps any value onto the shared choice list (AS-64). */
    static int snapWait(int waitPrefS)
    {
        return WAIT_CHOICES[QueueService.waitIndex(waitPrefS)];
    }

    @Override
    public void leave()
    {
        socket.send("queue/leave", new JsonObject());
    }

    @Override
    public void expandRange()
    {
        socket.send("queue/expand_range", new JsonObject());
    }

    @Override
    public void requestStatus()
    {
        socket.send("queue/status", new JsonObject());
    }

    @Override
    public synchronized void watchRecent(boolean open)
    {
        if (open == (recentJob != null)) return;
        if (open)
        {
            requestRecent();
            recentJob = scheduler.scheduleWithFixedDelay(this::requestRecent, 5, 5, TimeUnit.MINUTES);
            return;
        }
        recentJob.cancel(false);
        recentJob = null;
    }

    /** {@code queue/recent}: the recent joins, answered with {@code queue/recent_list}. */
    void requestRecent()
    {
        socket.send("queue/recent", new JsonObject());
    }

    // ---- shared preferences (G-2) ----

    @Override
    public void requestPrefs()
    {
        // An EMPTY prefs object: matchmaking_queue.save_prefs validates it
        // to {}, merges nothing, and answers queue/prefs with the stored
        // row. A read without a backend change — and without the risk of
        // pushing a stale local value over one set from Discord.
        sendPrefs(new JsonObject());
    }

    @Override
    public void sendWaitPref(int waitPrefS)
    {
        var prefs = new JsonObject();
        prefs.addProperty("wait_pref_s", snapWait(waitPrefS));
        sendPrefs(prefs);
    }

    @Override
    public void sendRange(int minRankIdx, int maxRankIdx)
    {
        var prefs = new JsonObject();
        // An explicit null clears the shared range; an absent key would
        // leave whatever Discord last wrote in place.
        prefs.add("rank_range", minRankIdx == QueueState.UNKNOWN || maxRankIdx == QueueState.UNKNOWN
            ? JsonNull.INSTANCE : range(minRankIdx, maxRankIdx));
        sendPrefs(prefs);
    }

    /** One {@code queue/set_prefs} frame carrying exactly {@code prefs};
     *  the server merges the named keys and leaves the rest alone. */
    private void sendPrefs(JsonObject prefs)
    {
        var d = new JsonObject();
        d.add("prefs", prefs);
        socket.send("queue/set_prefs", d);
    }

    // ---- inbound ----
    private void handleState(JsonObject d)
    {
        QueueState state = QueueState.fromJson(d);
        onEdt(l -> l.onQueueState(state));
        // Forward compatibility with the G-2 backend half: when
        // matchmaking_queue.status_snapshot starts carrying an additive
        // `prefs` object, this client already applies it — no second
        // plugin release needed (CLAUDE.md § 10).
        JsonObject prefs = JsonLenient.optObject(d, "prefs");
        if (prefs != null) onEdt(l -> l.onQueuePrefs(prefs));
    }

    private void handleTimeout(JsonObject d)
    {
        QueueState state = QueueState.fromJson(d);
        onEdt(l -> l.onQueueTimeout(state));
    }

    private void handlePrefs(JsonObject d)
    {
        JsonObject sent = JsonLenient.optObject(d, "prefs");
        JsonObject prefs = sent == null ? new JsonObject() : sent;
        onEdt(l -> l.onQueuePrefs(prefs));
    }

    /** The joins with a name and a whole positive time, in the order sent, at most 20. */
    private void handleRecent(JsonObject d)
    {
        var joins = new ArrayList<RecentJoin>();
        for (JsonElement e : JsonLenient.optArray(d, "entries"))
        {
            JsonObject o = e.isJsonObject() ? e.getAsJsonObject() : null;
            String name = o == null ? null : JsonLenient.str(o.get("name"));
            long at = JsonLenient.optWhole(o, "at");
            if (name != null && !name.isBlank() && at > 0 && joins.size() < 20) joins.add(new RecentJoin(name, at));
        }
        onEdt(l -> l.onRecentQueued(joins));
    }

    private void handleError(JsonObject d)
    {
        if ("queue/recent".equals(JsonLenient.optString(d, "cmd"))) return;
        String code = JsonLenient.optString(d, "code", "UNKNOWN");
        String message = JsonLenient.optString(d, "message");
        onEdt(l -> l.onQueueError(code, message));
    }

    private void onEdt(Consumer<QueueEventListener> fn)
    {
        SwingUtilities.invokeLater(() ->
        {
            QueueEventListener l = listener;
            if (l == null) return;
            try
            {
                fn.accept(l);
            }
            catch (Exception e)
            {
            }
        });
    }
}

package com.pvp.leaderboard.service;

import java.util.*;

/**
 * In-memory blocked-player registry for the Player Lookup tab's
 * per-row Block button. This is a UI-side block list scoped to the
 * lookup view, kept in step with the server-backed block set (the
 * {@code lobby/block} pushes and snapshot).
 *
 * <p>Names are normalised (lowercase, trimmed, single-spaced) before
 * storage so display-time casing differences don't lead to duplicate
 * entries. The set lives in process memory only; closing RuneLite
 * drops it.
 */
public final class BlockList
{
    private static final Set<String> BLOCKED =
        Collections.synchronizedSet(new LinkedHashSet<>());

    public static boolean isBlocked(String name)
    {
        // A blank name normalises to null, which is never stored
        return BLOCKED.contains(normalize(name));
    }

    /** Adds {@code name} to the block list. */
    public static void block(String name)
    {
        String n = normalize(name);
        if (n != null) BLOCKED.add(n);
    }

    /** Removes {@code name} from the block list. */
    public static void unblock(String name)
    {
        BLOCKED.remove(normalize(name));
    }

    /** Convenience flip — block if currently unblocked, unblock otherwise.
     *  Returns the new state ({@code true} = now blocked). */
    public static boolean toggle(String name)
    {
        if (isBlocked(name))
        {
            unblock(name);
            return false;
        }
        block(name);
        return true;
    }

    /** Replaces the entire set with {@code names} (each normalised).
     *  Used by the {@code MatchmakingLobbyPanel.onBlockListSnapshot}
     *  mirror so a reconnect or cross-device rehydrate keeps the UI-side
     *  block registry in lockstep with the canonical server state.
     *  Null input is treated as "empty set" — the registry is cleared. */
    public static void replaceAll(Set<String> names)
    {
        Set<String> normalised = new LinkedHashSet<>();
        if (names != null)
        {
            for (String n : names)
            {
                String norm = normalize(n);
                if (norm != null) normalised.add(norm);
            }
        }
        synchronized (BLOCKED)
        {
            BLOCKED.clear();
            BLOCKED.addAll(normalised);
        }
    }

    private static String normalize(String n)
    {
        if (n == null) return null;
        String t = n.trim().replaceAll("\\s+", " ").toLowerCase();
        return t.isEmpty() ? null : t;
    }
}

package com.pvp.leaderboard.service;

import com.google.gson.*;
import com.pvp.leaderboard.*;
import com.pvp.leaderboard.util.*;
import java.io.*;
import java.net.*;
import java.nio.charset.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.util.*;
import okhttp3.*;

/**
 * "Login with Discord" service — loopback-free, server-brokered handshake.
 *
 * <p>Discord is a <b>confidential</b> OAuth client, so the plugin cannot
 * exchange the authorization {@code code} itself (the token endpoint needs the
 * {@code client_secret}). The old flow ran a {@code http://127.0.0.1:49215}
 * loopback HTTP server and surfaced a raw localhost page in the browser. This
 * flow removes the loopback entirely:
 *
 * <ol>
 *   <li>{@code GET /auth/discord/plugin-init} — the backend mints a
 *       {@code login_id} (== OAuth {@code state}) + PKCE (verifier held
 *       server-side) and returns {@code {login_id, authorize_url}}.</li>
 *   <li>Open {@code authorize_url} in the browser. The OAuth redirect lands on
 *       a <b>hosted</b> page on {@code pvp-leaderboard.com} (NOT
 *       {@code 127.0.0.1}); that page relays {@code {code, state}} to the
 *       backend, which performs the secret-bearing exchange and stores a
 *       minimal session.</li>
 *   <li>The plugin polls {@code GET /auth/discord/plugin-poll?login_id=} until
 *       {@code status=complete} and adopts the returned minimal session.</li>
 * </ol>
 *
 * <p>The plugin never sees the Discord access token or the client secret —
 * only the minimal session (Discord id + display name). {@link #isLoggedIn()}
 * reflects "a Discord identity was linked this session".
 */
public class DiscordLogin
{
    /** Overall wall-clock budget for a login (browser auth + polling). */
    private static final long TIMEOUT_MS = 120_000L;
    /** Poll cadence while waiting for the browser side to complete. */
    private static final long POLL_MS = 2_000L;

    /** Fallback session lifetime when the session omits {@code expires_at}. */
    private static final long LOGIN_TTL_MS = 7L * 24L * 60L * 60L * 1000L;

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final ScheduledExecutorService scheduler;
    private final Client client;

    // Minimal session (no tokens, no secrets): the linked identity's name
    // (its Discord id when it has none) and when the session ends.
    private volatile String displayName;
    private volatile long sessionExpiry;

    // In-flight handshake state (one login at a time).
    private final AtomicBoolean loginActive = new AtomicBoolean(false);
    private volatile ScheduledFuture<?> pollFuture;
    private volatile Call inFlightCall;

    @Inject
    public DiscordLogin(OkHttpClient httpClient, Gson gson,
                              ScheduledExecutorService scheduler, Client client)
    {
        this.httpClient = httpClient;
        this.gson = gson;
        this.scheduler = scheduler;
        this.client = client;
    }

    /**
     * Start a loopback-free Discord login. Resolves {@code true} once a minimal
     * session has been adopted, {@code false} on cancel/timeout/error.
     */
    public CompletableFuture<Boolean> login()
    {
        CompletableFuture<Boolean> result = new CompletableFuture<>();
        if (!loginActive.compareAndSet(false, true))
        {
            // A login is already in progress; don't start a second handshake.
            result.complete(false);
            return result;
        }

        try
        {
            get(buildInitUrl(PvpConsts.INIT_URL, currentRsn()), res ->
            {
                try
                {
                    String body = body(res);
                    String loginId = parseString(gson, body, "login_id");
                    String authorizeUrl = parseString(gson, body, "authorize_url");
                    if (!res.isSuccessful() || loginId == null || authorizeUrl == null)
                    {
                        finish(result, false);
                        return;
                    }
                    LinkBrowser.browse(authorizeUrl);
                    startPolling(loginId, result, System.currentTimeMillis() + TIMEOUT_MS);
                }
                catch (Exception e)
                {
                    finish(result, false);
                }
            }, () -> finish(result, false));
        }
        catch (Exception e)
        {
            finish(result, false);
        }
        return result;
    }

    /** Cancel an in-flight login (user pressed Cancel / closed the panel). */
    public void cancelLogin()
    {
        if (loginActive.get())
        {
            stopLogin();
        }
    }

    private void startPolling(String loginId, CompletableFuture<Boolean> result, long deadlineMs)
    {
        if (scheduler == null)
        {
            // No scheduler (degenerate/test wiring) — can't poll.
            finish(result, false);
            return;
        }
        pollFuture = scheduler.scheduleWithFixedDelay(() -> {
            if (!loginActive.get() || result.isDone())
            {
                return;
            }
            if (System.currentTimeMillis() > deadlineMs)
            {
                finish(result, false);
                return;
            }
            pollOnce(loginId, result);
        }, POLL_MS, POLL_MS, TimeUnit.MILLISECONDS);
    }

    private void pollOnce(String loginId, CompletableFuture<Boolean> result)
    {
        try
        {
            get(buildPollUrl(PvpConsts.POLL_URL, loginId), res ->
            {
                try
                {
                    if (result.isDone() || !loginActive.get())
                    {
                        return;
                    }
                    String body = body(res);
                    String status = parseString(gson, body, "status");
                    if ("complete".equals(status))
                    {
                        JsonObject session = parsePollSession(gson, body);
                        finish(result, session != null && adoptSession(session));
                    }
                    else if ("error".equals(status) || "expired".equals(status))
                    {
                        finish(result, false);
                    }
                    // "pending" (or unknown) -> keep polling.
                }
                catch (Exception ignore)
                {
                    // Keep polling; the deadline guard ends it eventually.
                }
            }, () -> {
                // Transient network blip — keep polling until the deadline.
            });
        }
        catch (Exception ignore)
        {
            // Keep polling; the deadline guard ends it eventually.
        }
    }

    /** GETs {@code url} as the in-flight call: {@code ok} gets the response
     *  (closed afterwards), {@code failed} runs on a network failure. */
    private void get(String url, Consumer<Response> ok, Runnable failed)
    {
        Call call = httpClient.newCall(new Request.Builder().url(url).addHeader("Accept", "application/json").build());
        inFlightCall = call;
        call.enqueue(new Callback()
        {
            @Override public void onFailure(Call c, IOException e)
            {
                failed.run();
            }

            @Override public void onResponse(Call c, Response response)
            {
                try (Response res = response)
                {
                    ok.accept(res);
                }
            }
        });
    }

    private static String body(Response res) throws IOException
    {
        ResponseBody rb = res.body();
        return rb != null ? rb.string() : "";
    }

    /** Adopt the minimal-session JSON object into local state. */
    boolean adoptSession(JsonObject session)
    {
        String id = JsonLenient.optString(session, "discord_user_id");
        if (id.isEmpty()) return false;
        // expires_at is the Discord token expiry (epoch seconds).
        long expiresAt = JsonLenient.optLong(session, "expires_at", -1);
        displayName = JsonLenient.optString(session, "display_name", id);
        sessionExpiry = expiresAt >= 0 ? expiresAt * 1000L : System.currentTimeMillis() + LOGIN_TTL_MS;
        return true;
    }

    public boolean isLoggedIn()
    {
        return displayName != null && System.currentTimeMillis() < sessionExpiry;
    }

    public void logout()
    {
        displayName = null;
        sessionExpiry = 0L;
    }

    /** Stop polling + cancel any in-flight call and mark the handshake done. */
    private void stopLogin()
    {
        loginActive.set(false);
        ScheduledFuture<?> poll = pollFuture;
        if (poll != null) poll.cancel(false);
        pollFuture = null;
        Call call = inFlightCall;
        if (call != null) call.cancel();
        inFlightCall = null;
    }

    /** Resolve the login future exactly once and tear down the handshake. */
    private void finish(CompletableFuture<Boolean> result, boolean success)
    {
        stopLogin();
        if (!result.isDone())
        {
            result.complete(success);
        }
    }

    // ---- Pure helpers (package-private for unit tests) ----

    /** Build the plugin-init URL, appending the current RSN when known. */
    static String buildInitUrl(String base, String playerName)
    {
        if (playerName == null || playerName.trim().isEmpty())
        {
            return base;
        }
        return base + "?player_name=" + URLEncoder.encode(playerName.trim(), StandardCharsets.UTF_8);
    }

    /** Build the plugin-poll URL for a given handshake id. */
    static String buildPollUrl(String base, String loginId)
    {
        return base + "?login_id=" + URLEncoder.encode(loginId, StandardCharsets.UTF_8);
    }

    /**
     * Extract the nested {@code session} object from a {@code complete}
     * plugin-poll response, or {@code null} when absent / not complete.
     */
    static JsonObject parsePollSession(Gson gson, String body)
    {
        try
        {
            return JsonLenient.optObject(gson.fromJson(body, JsonObject.class), "session");
        }
        catch (Exception e)
        {
            return null;
        }
    }

    /** The response's non-empty text at {@code key} ({@code login_id},
     *  {@code authorize_url}, {@code status}), or {@code null}. */
    static String parseString(Gson gson, String body, String key)
    {
        try
        {
            String v = gson.fromJson(body, JsonObject.class).get(key).getAsString();
            return v.isEmpty() ? null : v;
        }
        catch (Exception e)
        {
            return null;
        }
    }

    /** Current in-game RSN, or {@code null} if not logged into the game. */
    private String currentRsn()
    {
        try
        {
            if (client == null) return null;
            Player local = client.getLocalPlayer();
            return local != null ? local.getName() : null;
        }
        catch (Exception e)
        {
            return null;
        }
    }
}

package com.pvp.leaderboard.service;

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.client.config.*;
import net.runelite.client.util.*;

@Slf4j
@Singleton
public class IdentitySvc
{
    private static final String GROUP = "PvPLeaderboard";
    private static final String KEY = "clientUniqueId";
    /** A blank id file younger than this may be another client's new file still being written. */
    private static final int FRESH_SECS = 10;

    private final ConfigManager configManager;
    private volatile String clientUniqueId;

    @Inject
    public IdentitySvc(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    /**
     * Loads the id once, at start-up: the id file, else the profile copy, else a new UUID; after a read error, the
     * profile copy or none. The profile copy is kept equal to the id.
     */
    public synchronized void load(Callable<Filepath> dataPath)
    {
        if (clientUniqueId != null) return;
        String profile = configManager.getConfiguration(GROUP, KEY);
        String id;
        try
        {
            id = readOrCreate(idFile(dataPath), profile);
        }
        catch (Exception e)
        {
            log.warn("PvP Leaderboard could not read its id file: {}", e.toString());
            id = blank(profile) ? null : profile;
        }
        if (id != null && !id.equals(profile)) configManager.setConfiguration(GROUP, KEY, id);
        clientUniqueId = id;
    }

    public String getClientUniqueId()
    {
        return clientUniqueId;
    }

    /** The plugin's data path (the old id file, renamed there by RuneLite), or {@code id} inside it if it is a folder.
     *  Asked twice: another client may have renamed the old file at the same moment. */
    private static Filepath idFile(Callable<Filepath> dataPath) throws Exception
    {
        Filepath p;
        try
        {
            p = dataPath.call();
        }
        catch (IOException e)
        {
            p = dataPath.call();
        }
        return p.isDirectory() ? p.joinSegment("id") : p;
    }

    private static String readOrCreate(Filepath file, String profile) throws IOException
    {
        if (file.exists())
        {
            String id = read(file);
            if (!id.isEmpty())
            {
                return id;
            }
            if (blank(profile) && Duration.between(file.getLastModifiedTime().toInstant(), Instant.now()).getSeconds() < FRESH_SECS)
            {
                throw new IOException("blank id file, possibly still being written");
            }
            String fresh = fresh(profile);
            file.write(fresh);
            return fresh;
        }
        String fresh = fresh(profile);
        try
        {
            file.write(fresh, StandardOpenOption.CREATE_NEW);
            return fresh;
        }
        catch (FileAlreadyExistsException e)
        {
            String id = read(file);
            if (id.isEmpty()) throw new IOException("blank id file, still being written");
            return id;
        }
    }

    private static String read(Filepath file) throws IOException
    {
        try (InputStream in = file.openInputStream())
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
        }
    }

    private static String fresh(String profile)
    {
        return blank(profile) ? UUID.randomUUID().toString() : profile;
    }

    private static boolean blank(String s)
    {
        return s == null || s.isEmpty();
    }
}

