package com.pvp.leaderboard.service;

import com.pvp.leaderboard.*;
import com.pvp.leaderboard.config.*;
import java.io.*;
import java.util.concurrent.*;
import javax.inject.*;
import okhttp3.*;

/**
 * Sends presence heartbeats to the backend.
 *
 * <h2>Scope (p15-membership-feed)</h2>
 * This service used to ALSO fetch {@code whitelist.json} to drive the rank
 * overlay. That responsibility moved to {@link MemberFeed}, which
 * consumes the names-only snapshot/delta feed ({@code plugin-users/snapshot.json}
 * + {@code delta.json}) — see PLAN_PRESENCE_FRESHNESS.md. The plugin no longer
 * downloads {@code whitelist.json}; the backend keeps generating it only as a
 * server-side fallback. This class is now heartbeat-only.
 *
 * <h2>Heartbeat behaviour</h2>
 * <ul>
 *   <li>Sends a POST on login, then every 5 minutes (each 5 minutes after
 *       the previous one ran) until logout.</li>
 *   <li>Only sends when a username is available AND "Show your rank to others"
 *       is enabled.</li>
 *   <li>Auth: {@code X-Client-Unique-Id} (UUID) + {@code User-Agent} headers.</li>
 * </ul>
 */
@Singleton
public class WhitelistService
{
    private static final String HEARTBEAT_URL = PvpConsts.API_BASE_URL + "/heartbeat";

    private static final long HEARTBEAT_MS = 5L * 60L * 1000L; // 5 minutes

    private final OkHttpClient okHttpClient;
    private final PvPLeaderboardConfig config;
    private final ScheduledExecutorService scheduler;
    private final IdentitySvc identitySvc;

    // Heartbeat state
    private volatile String currentUsername = null;
    private volatile ScheduledFuture<?> scheduledHeartbeat = null;

    @Inject
    public WhitelistService(OkHttpClient okHttpClient, PvPLeaderboardConfig config,
                            ScheduledExecutorService scheduler,
                            IdentitySvc identitySvc)
    {
        this.okHttpClient = okHttpClient;
        this.config = config;
        this.scheduler = scheduler;
        this.identitySvc = identitySvc;
    }

    /**
     * Called when player logs in. Starts the heartbeat cycle.
     *
     * @param username The player's username (required for heartbeat)
     */
    public void onLogin(String username)
    {
        if (username == null || username.trim().isEmpty())
        {
            return;
        }

        this.currentUsername = username.trim();

        // Cancel any existing heartbeat schedule to prevent chain accumulation
        cancelScheduledHeartbeat();

        // Send immediate heartbeat on login
        sendHeartbeat();

        // Then one every 5 minutes, each 5 minutes after the previous one
        // ran; a throw ends the chain, logout cancels it.
        scheduledHeartbeat = scheduler.scheduleWithFixedDelay(this::sendHeartbeat,
            HEARTBEAT_MS, HEARTBEAT_MS, TimeUnit.MILLISECONDS);
    }

    /**
     * Called when player logs out.
     */
    public void onLogout()
    {
        currentUsername = null;
        cancelScheduledHeartbeat();
    }

    /**
     * Whether a heartbeat schedule is currently active.
     */
    public boolean isHeartbeatActive()
    {
        ScheduledFuture<?> scheduled = scheduledHeartbeat;
        return scheduled != null && !scheduled.isDone() && currentUsername != null;
    }

    /**
     * Cancel any scheduled heartbeat to prevent chain accumulation.
     */
    private void cancelScheduledHeartbeat()
    {
        ScheduledFuture<?> scheduled = scheduledHeartbeat;
        // cancel() is false for a future that already finished.
        if (scheduled != null && scheduled.cancel(false))
        {
        }
        scheduledHeartbeat = null;
    }

    /**
     * Send a heartbeat to the server.
     * Only sends if "Show your rank to others" is enabled.
     */
    private void sendHeartbeat()
    {
        if (!config.showRankToOthers())
        {
            return;
        }

        String username = currentUsername;
        if (username == null || username.isEmpty())
        {
            return;
        }

        String clientUuid = identitySvc.getClientUniqueId();
        if (clientUuid == null || clientUuid.isEmpty())
        {
            return;
        }

        // Build JSON body with username
        String jsonBody = "{\"username\":\"" + username.replace("\"", "\\\"") + "\"}";

        RequestBody body = RequestBody.create(MediaType.parse("application/json"), jsonBody);

        Request request = new Request.Builder()
            .url(HEARTBEAT_URL)
            .header("X-Client-Unique-Id", clientUuid)
            .header("User-Agent", PvpConsts.USER_AGENT)
            .post(body)
            .build();

        okHttpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
            }

            /** The body is not read: closing discards it and keeps the connection. */
            @Override
            public void onResponse(Call call, Response response)
            {
                response.close();
            }
        });
    }
}

package com.pvp.leaderboard.service;

import com.google.gson.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

public final class WinLossPeak
{
	public static final WinLossPeak EMPTY = new WinLossPeak(Collections.emptyMap(), Collections.emptyMap());

	private final Map<String, int[]> records;
	private final Map<String, String> peaks;

	private WinLossPeak(Map<String, int[]> records, Map<String, String> peaks)
	{
		this.records = records;
		this.peaks = peaks;
	}

	public static WinLossPeak fromProfile(JsonObject profile)
	{
		if (profile == null) return EMPTY;
		Map<String, int[]> records = new HashMap<>();
		JsonObject cum = optObject(profile, "cumulative_stats");
		if (cum != null)
		{
			for (Map.Entry<String, JsonElement> e : cum.entrySet())
			{
				JsonObject b = optObject(cum, e.getKey());
				if (b == null) continue;
				records.put(e.getKey(), new int[]{
					Math.max(0, optInt(b, "wins", 0)),
					Math.max(0, optInt(b, "losses", 0))});
			}
		}
		Map<String, String> peaks = new HashMap<>();
		JsonObject peakMap = optObject(profile, "peaks");
		if (peakMap != null)
		{
			for (Map.Entry<String, JsonElement> e : peakMap.entrySet())
			{
				String text = peakText(optObject(peakMap, e.getKey()));
				if (text != null) peaks.put(e.getKey(), text);
			}
		}
		return records.isEmpty() && peaks.isEmpty() ? EMPTY : new WinLossPeak(records, peaks);
	}

	private static String peakText(JsonObject peak)
	{
		String rank = optString(peak, "rank").trim();
		if (rank.isEmpty()) return null;
		int division = optInt(peak, "division", 0);
		return division > 0 ? rank + " " + division : rank;
	}

	public int wins(String bucketKey)
	{
		return count(bucketKey, 0);
	}

	public int losses(String bucketKey)
	{
		return count(bucketKey, 1);
	}

	/** Both maps are a HashMap or an empty map: either answers a null key with null. */
	public String peak(String bucketKey)
	{
		return peaks.get(bucketKey);
	}

	private int count(String bucketKey, int i)
	{
		int[] v = records.get(bucketKey);
		return v == null ? 0 : v[i];
	}
}

package com.pvp.leaderboard.service;

import com.google.gson.*;
import com.pvp.leaderboard.cache.*;
import com.pvp.leaderboard.config.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import java.util.function.*;
import javax.inject.*;
import net.runelite.client.config.*;

@Singleton
public class WinStreakTracker
{
	static final String CONFIG_GROUP = "PvPLeaderboard";
	static final String KEY_PREFIX = "winStreak.";
	static final long GRACE_MS = 30_000L;
	static final int GRACE_TRIES = 2;

	private static final String WIN = "win";
	private static final String LOSS = "loss";

	private final ConfigManager configManager;
	private final LongSupplier nowMs;

	private String loadedProfile;
	private final Map<StreakBucket, Streak> streaks = new EnumMap<>(StreakBucket.class);
	private boolean known;
	private long profileTs = Long.MIN_VALUE;

	private static final class Streak
	{
		int current;
		boolean plus;
		int serverBest;
		int localBest;
		int graceSeen;
		long graceStartMs;
	}

	@Inject
	public WinStreakTracker(ConfigManager configManager)
	{
		this(configManager, System::currentTimeMillis);
	}

	public WinStreakTracker(ConfigManager configManager, LongSupplier nowMs)
	{
		this.configManager = configManager;
		this.nowMs = nowMs;
	}

	public synchronized void seedHistory(JsonArray newestFirst)
	{
		if (newestFirst == null || !ensureLoaded()) return;
		known = true;
		Map<StreakBucket, int[]> tally = new EnumMap<>(StreakBucket.class);
		for (JsonElement e : newestFirst)
		{
			if (!e.isJsonObject()) continue;
			JsonObject row = e.getAsJsonObject();
			StreakBucket bucket = StreakBucket.forKey(JsonLenient.optString(row, "bucket", null));
			if (bucket == null) continue;
			int[] t = tally.computeIfAbsent(bucket, k -> new int[2]);
			if (t[1] == 1) continue;
			String result = normalise(JsonLenient.optString(row, "result", null));
			if (WIN.equals(result)) t[0]++;
			else if (LOSS.equals(result)) t[1] = 1;
		}
		for (Map.Entry<StreakBucket, int[]> en : tally.entrySet())
		{
			int wins = en.getValue()[0];
			boolean exact = en.getValue()[1] == 1;
			Streak s = streaks.get(en.getKey());
			if (exact)
			{
				set(en.getKey(), s, wins, false);
				s.graceSeen = 0;
			}
			else if (wins > s.current)
			{
				set(en.getKey(), s, wins, true);
				s.graceSeen = 0;
			}
		}
	}

	public synchronized void onFight(String bucketKey, String result)
	{
		StreakBucket bucket = StreakBucket.forKey(bucketKey);
		if (bucket == null || !ensureLoaded()) return;
		Streak s = streaks.get(bucket);
		String r = normalise(result);
		if (WIN.equals(r))
		{
			set(bucket, s, s.current == Integer.MAX_VALUE ? s.current : s.current + 1, s.plus);
		}
		else if (LOSS.equals(r))
		{
			set(bucket, s, 0, false);
		}
	}

	public synchronized void reconcile(String bucketKey, int serverStreak, int serverBest)
	{
		StreakBucket bucket = StreakBucket.forKey(bucketKey);
		if (bucket == null || !ensureLoaded()) return;
		known = true;
		Streak s = streaks.get(bucket);
		if (serverBest >= 0) s.serverBest = serverBest;
		if (serverStreak < 0) return;
		if (serverStreak >= s.current)
		{
			set(bucket, s, serverStreak, false);
			s.graceSeen = 0;
			return;
		}
		long now = nowMs.getAsLong();
		if (s.graceSeen == 0) s.graceStartMs = now;
		s.graceSeen++;
		if (s.graceSeen >= GRACE_TRIES && now - s.graceStartMs >= GRACE_MS)
		{
			set(bucket, s, serverStreak, false);
			s.localBest = serverStreak;
			s.graceSeen = 0;
		}
	}

	public synchronized void observeProfile(UserStats cached)
	{
		if (cached == null || !ensureLoaded()) return;
		if (cached.getTimestamp() == profileTs) return;
		profileTs = cached.getTimestamp();
		known = true;
		JsonObject buckets = JsonLenient.optObject(cached.getStats(), "buckets");
		for (StreakBucket b : StreakBucket.values())
		{
			JsonObject bucket = JsonLenient.optObject(buckets, b.bucketKey);
			reconcile(b.bucketKey, sent(bucket, "streak"), sent(bucket, "best_streak"));
		}
	}

	/** {@code buckets.<key>.<field>} as the server sent it, or -1 when it sent
	 *  none: absent, not a number, or negative (a streak is never below zero). */
	private static int sent(JsonObject bucket, String field)
	{
		Integer v = JsonLenient.optInteger(bucket, field);
		return v == null || v < 0 ? -1 : v;
	}

	public synchronized void clear()
	{
		loadedProfile = null;
		streaks.clear();
		known = false;
		profileTs = Long.MIN_VALUE;
	}

	public synchronized boolean isKnown()
	{
		return ensureLoaded() && known;
	}

	public synchronized int current(String bucketKey)
	{
		Streak s = find(bucketKey);
		return s == null ? 0 : s.current;
	}

	public synchronized boolean plus(String bucketKey)
	{
		Streak s = find(bucketKey);
		return s != null && s.plus;
	}

	public synchronized int longest(String bucketKey)
	{
		Streak s = find(bucketKey);
		return s == null ? 0 : Math.max(s.serverBest, Math.max(s.localBest, s.current));
	}

	public synchronized String text(String bucketKey)
	{
		Streak s = find(bucketKey);
		return s == null ? "0" : encode(s.current, s.plus);
	}

	private Streak find(String bucketKey)
	{
		StreakBucket bucket = StreakBucket.forKey(bucketKey);
		return bucket == null || !ensureLoaded() ? null : streaks.get(bucket);
	}

	private boolean ensureLoaded()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null) return false;
		if (!profile.equals(loadedProfile))
		{
			loadedProfile = profile;
			known = false;
			profileTs = Long.MIN_VALUE;
			streaks.clear();
			for (StreakBucket b : StreakBucket.values())
			{
				Streak s = new Streak();
				int[] saved = decode(configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_PREFIX + b.bucketKey));
				s.current = saved[0];
				s.plus = saved[1] == 1;
				s.localBest = s.current;
				streaks.put(b, s);
			}
		}
		return true;
	}

	private void set(StreakBucket bucket, Streak s, int value, boolean plus)
	{
		int v = Math.max(0, value);
		boolean p = plus && v > 0;
		String before = encode(s.current, s.plus);
		s.current = v;
		s.plus = p;
		s.localBest = Math.max(s.localBest, v);
		String after = encode(v, p);
		if (after.equals(before)) return;
		try
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PREFIX + bucket.bucketKey, after);
		}
		catch (RuntimeException e)
		{
		}
	}

	static String encode(int current, boolean plus)
	{
		return plus ? current + "+" : String.valueOf(current);
	}

	static int[] decode(String saved)
	{
		if (saved == null) return new int[]{0, 0};
		String t = saved.trim();
		boolean plus = t.endsWith("+");
		if (plus) t = t.substring(0, t.length() - 1);
		try
		{
			int v = Integer.parseInt(t);
			return v < 0 ? new int[]{0, 0} : new int[]{v, plus && v > 0 ? 1 : 0};
		}
		catch (NumberFormatException e)
		{
			return new int[]{0, 0};
		}
	}

	private static String normalise(String result)
	{
		return result == null ? null : result.trim().toLowerCase(Locale.ROOT);
	}
}

package com.pvp.leaderboard.service.socket;

import com.google.gson.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import javax.inject.*;

/**
 * Cmd-keyed listener registry for server-pushed socket events.
 * Owns the dispatch fanout from {@link SocketMgr}'s
 * single read-loop thread to whatever subscriber wants the payload.
 *
 * <p>Subscribers are {@code Consumer<JsonObject>} so they receive the
 * payload {@code data} object directly (the outer {@code cmd} envelope
 * is already routed by name to the right consumer list). Subscribers
 * are called <b>synchronously on the socket's read-loop thread</b> —
 * they MUST be cheap or marshal to another thread themselves. The
 * existing pattern in the plugin uses {@code SwingUtilities.invokeLater}
 * to bounce to the EDT for any UI mutation; the lobby panel's
 * {@link com.pvp.leaderboard.lobby.LobbyService}/
 * {@link com.pvp.leaderboard.lobby.LobbyEventListener} contract requires
 * EDT delivery — the {@code WebSocketLobbyService} adapter does that
 * marshalling so individual UI consumers don't have to.
 *
 * <p>Registrations are append-only for the life of the registered
 * service (typically the {@code @Singleton} {@code WebSocketLobbyService}).
 * No unregister API yet — singleton services don't need one and
 * exposing one invites lifecycle bugs where stale callbacks live past
 * their owner.
 *
 * <p>{@link CopyOnWriteArrayList} per-cmd lets fire iteration not
 * block registration and vice versa, so a subscriber registering a
 * new listener from inside its callback (rare but legal) doesn't
 * trip {@link java.util.ConcurrentModificationException}.
 */
@Singleton
public final class SocketBus
{
    /** Cmd → list of subscribers. Initialised lazily on first register;
     *  never holds a null or empty cmd. */
    private final Map<String, CopyOnWriteArrayList<Consumer<JsonObject>>> listeners = new HashMap<>();

    /**
     * Subscribes {@code handler} to be invoked every time a server frame
     * with the given {@code cmd} arrives. Multiple subscribers per cmd
     * are allowed and called in registration order; the typical pattern
     * is one subscriber per cmd (the {@code WebSocketLobbyService}).
     */
    public synchronized void register(String cmd, Consumer<JsonObject> handler)
    {
        if (cmd == null || cmd.isEmpty() || handler == null) return;
        listeners.computeIfAbsent(cmd, k -> new CopyOnWriteArrayList<>()).add(handler);
    }

    /**
     * Fires {@code data} to every registered subscriber of {@code cmd}.
     * No-op if there are no subscribers. Exceptions thrown by any
     * subscriber are caught + logged so a single buggy listener can't
     * starve the rest.
     */
    public void fire(String cmd, JsonObject data)
    {
        CopyOnWriteArrayList<Consumer<JsonObject>> subs;
        synchronized (this)
        {
            subs = listeners.get(cmd);
        }
        if (subs == null) return;
        for (Consumer<JsonObject> s : subs)
        {
            try
            {
                s.accept(data);
            }
            catch (Exception e)
            {
                // Best-effort isolation: don't let a UI bug in one
                // listener take down the dispatch loop.
            }
        }
    }

    /** Test/debug accessor: true if {@link #register} has been called for
     *  the given cmd at least once. Used by {@link SocketMgr}
     *  diagnostics. */
    public synchronized boolean hasSubscribers(String cmd)
    {
        return listeners.containsKey(cmd);
    }
}

package com.pvp.leaderboard.service.socket;

import com.google.gson.*;

/**
 * Immutable wire-envelope value object for socket-lobby traffic. Both
 * directions (client→server cmds and server→client pushes) share the
 * same shape per the locked decision in
 * {@code OSRS-MMR/lambda_code/docs/WEBSOCKET_PROTOCOL.md §0.2}
 * ("symmetric envelope"):
 *
 * <pre>{ "cmd": "&lt;namespace&gt;/&lt;verb&gt;", "data": { ... } }</pre>
 *
 * <p>Serialised via {@link com.google.gson.Gson} — the field names match
 * the wire keys directly so no {@code @SerializedName} annotations are
 * needed.
 *
 * <p>Fields are package-private finals; the type is constructed via
 * factory methods in {@link SocketProtocol} (encode side) or parsed
 * straight off the wire by {@link com.google.gson.Gson#fromJson} (decode
 * side). The {@link #data} object is never null — empty payloads use
 * {@code new JsonObject()} per the protocol's
 * {@code "data": {}} rule (§2 "always an object, never null or omitted").
 */
public final class SocketCommand
{
    public final String cmd;
    public final JsonObject data;

    /** {@code cmd} is non-empty: both callers ({@link SocketProtocol#encode}
     *  after its allowlist test, {@link SocketProtocol#decode} after its own
     *  test) never pass anything else. */
    public SocketCommand(String cmd, JsonObject data)
    {
        this.cmd = cmd;
        // Defensive: tolerate callers passing null by substituting an
        // empty object. The wire spec disallows null data but a
        // misbehaving listener shouldn't trip a NullPointerException
        // downstream — fail soft, log nothing, render an empty payload.
        this.data = data == null ? new JsonObject() : data;
    }
}

package com.pvp.leaderboard.service.socket;

import com.google.gson.*;
import com.pvp.leaderboard.*;
import com.pvp.leaderboard.config.*;
import com.pvp.leaderboard.util.*;
import java.net.*;
import java.nio.charset.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.regex.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import okhttp3.*;

/**
 * Single-connection socket lifecycle owner. Maintains exactly one
 * {@code okhttp3.WebSocket} to {@link PvpConsts#SOCKET_URL}
 * keyed by the local user's OSRS client UUID.
 *
 * <p><b>Lifecycle contract</b> (enforced by
 * {@code PvPLeaderboardPlugin.onGameStateChanged}):
 * <ul>
 *   <li>{@link #connect(String, String)} on {@code GameState.LOGGED_IN}
 *   (post-10-tick player-ready delay).</li>
 *   <li>{@link #disconnect()} on {@code GameState.LOGIN_SCREEN}
 *   (close code 1001 GOING_AWAY).</li>
 *   <li>{@link #shutdown()} on plugin {@code shutDown()}.</li>
 * </ul>
 * Re-{@link #connect(String, String)} with the same UUID and name while
 * already connected is a no-op. With a different UUID or name it tears down
 * the current connection (close 1000) and connects fresh.
 *
 * <p><b>Reconnect policy</b>: a jittered exponential backoff, see
 * {@link #retryDelayMs(int, double)}. The attempt count grows with
 * every connection that fails or closes before
 * {@link #STABLE_MS} and resets once one stays open that long.
 * Triggered by any close of the current socket that the plugin did not
 * request, whatever its code (the server's 2-hour close included), AND by
 * network-level {@code onFailure}. A logout or a plugin stop never
 * reconnects: {@link #disconnect()} forgets the UUID, and every retry needs
 * one; the closes the plugin requests itself (logout, name change, config
 * change) forget the socket first, so its callbacks are stale. A
 * {@link #connect} while a retry is scheduled leaves that retry in place,
 * and more than {@link #OPEN_BURST} opens within a minute wait for a
 * scheduled retry.
 *
 * <p>HTTP 401 retries after {@link #authDelayMs(double)}. The
 * panel surfaces a "Attempting to reconnect" banner with the countdown
 * (see {@link #getRetryAtMs()}).
 *
 * <p>{@code error/rate_limited} with {@code retry_at_epoch_ms} holds
 * outgoing frames until that time, at most
 * {@link #MAX_HOLD_MS}: the named {@code cmd}, or every frame
 * when none is named.
 *
 * <p><b>Keepalive</b>: RFC 6455 native ping every 8 min
 * ({@link OkHttpClient.Builder#pingInterval}). API Gateway's idle
 * timeout is 10 min; 8 min leaves a comfortable buffer. No
 * application-layer {@code system/ping} cmd exists per the protocol
 * doc's locked decision §0.1.
 *
 * <p><b>Send model</b>: fire-and-forget. {@link #send(String, JsonObject)}
 * routes through {@link SocketProtocol#encode} (allowlist guard) and
 * then {@code WebSocket.send(String)} — which itself buffers up to
 * 16 MB on the wire. If the socket is closed at send time the call
 * silently no-ops (returns {@code false}). The panel's contract is
 * "user action → fire-and-forget cmd; outcomes arrive asynchronously
 * via push events" so a dropped-while-offline send is acceptable.
 *
 * <p><b>Threading</b>: all connection state is guarded by {@code this}
 * monitor since {@link #connect} / {@link #disconnect} / WebSocket listener
 * callbacks race. OkHttp calls the listener on its own threads (never from
 * inside {@code close()}), and every callback takes the monitor first.
 */
@Slf4j
@Singleton
public final class SocketMgr
{
    /** RFC 6455 close code for clean disconnect by either party. */
    public static final int CLOSE_NORMAL = 1000;
    /** RFC 6455 close code for "endpoint going away" (logout). */
    public static final int CLOSE_GOING_AWAY = 1001;

    /** Lowercase UUID-v4 format check — same regex the backend uses
     *  in {@code backend.core.validation.is_valid_uuid_format}. Pre-flight
     *  rejection prevents accidentally getting the IP WAF-banned by
     *  a malformed-UUID $connect attempt (architecture Phase 1
     *  validation step 2). */
    private static final Pattern UUID_V4 = Pattern.compile(
        "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$");

    static final long STABLE_MS = 30_000L;
    static final long RESYNC_MS = 5_000L;
    static final int OPEN_BURST = 5;
    static final long MAX_HOLD_MS = 60_000L;

    private final OkHttpClient sharedHttp;
    private final SocketBus eventBus;
    private final ScheduledExecutorService scheduler;
    private final Gson gson;
    private final PvPLeaderboardConfig config;
    private final LongSupplier clock;
    private final DoubleSupplier random;

    /** Lazily-built pinging client; reuses the shared client's connection
     *  pool / dispatcher via {@code newBuilder()} so we don't double up
     *  on threads / cache. */
    private OkHttpClient pingingClient;

    /** Active connection state — all access guarded by {@code this}
     *  monitor. The OkHttp dispatcher uses its own thread pool for
     *  listener callbacks, so without the lock a {@code onClosed} →
     *  reconnect-schedule could race with a user-driven
     *  {@link #disconnect}. A socket is only ever open with a UUID. */
    private WebSocket activeSocket;
    /** The UUID to (re)connect with; {@code null} before the first connect
     *  and after {@link #disconnect()} / {@link #shutdown()}, which is what
     *  stops every scheduled retry. */
    private String activeUuid;
    /** Display-cased name of the in-game character the user is currently
     *  logged in as (e.g. {@code "Toyco"}). Sent to the server on
     *  $connect as a {@code &name=<urlencoded>} query parameter so the
     *  conn row + lobby member row are pinned to the active session
     *  rather than {@code sorted(player_names)[0]}. {@code null} when
     *  not yet known (called before {@code client.getLocalPlayer()}
     *  resolves). Backend treats null/missing as "fall back to alphabet
     *  default" and validates non-null names against the MMR row's
     *  {@code player_names} set (anti-spoof). */
    private String activeName;
    /** Consecutive scheduled reconnects since a socket last stayed open
     *  {@link #STABLE_MS}. */
    private int retryAttempt;
    /** Clock reading at the current socket's open; {@code 0} when none is open. */
    private long openedAtMs;
    /** Clock readings of the recent opens, oldest first. */
    private final ArrayDeque<Long> openTimes = new ArrayDeque<>();
    private ScheduledFuture<?> retryJob;
    private ScheduledFuture<?> resyncJob;
    /** Epoch ms when {@link #retryJob} is scheduled to fire,
     *  or {@code 0} when no retry is queued. Exposed via
     *  {@link #getRetryAtMs()} so the lobby panel
     *  can render a countdown banner. Set on every
     *  {@link #scheduleRetry(boolean)} and cleared on
     *  {@link #retryTick()} entry / a successful
     *  {@link Listener#onOpen}. {@code volatile} since the panel's
     *  Swing-EDT ticker reads it from a different thread than the
     *  scheduler thread that writes it. */
    private volatile long retryAtMs = 0L;

    /** Listeners called every time the socket transitions from
     *  not-connected to connected (i.e. {@code onOpen} fires). Invoked on
     *  the OkHttp dispatcher thread — listeners must marshal to their
     *  target thread themselves. {@link CopyOnWriteArrayList} so
     *  addConnectListener during an open-callback doesn't trip CME. */
    private final CopyOnWriteArrayList<Runnable> connectHooks = new CopyOnWriteArrayList<>();

    private final CopyOnWriteArrayList<Runnable> resyncHooks = new CopyOnWriteArrayList<>();

    /** Clock reading until which every outgoing frame is held; {@code 0} when none is. */
    private volatile long holdAllUntil;
    /** Per-cmd hold, clock reading until which that cmd is held. */
    private final Map<String, Long> holdCmdUntil = new ConcurrentHashMap<>();

    @Inject
    public SocketMgr(OkHttpClient sharedHttp,
                            SocketBus eventBus,
                            ScheduledExecutorService scheduler,
                            Gson gson,
                            PvPLeaderboardConfig config)
    {
        this(sharedHttp, eventBus, scheduler, gson, config,
            System::currentTimeMillis, () -> ThreadLocalRandom.current().nextDouble());
    }

    SocketMgr(OkHttpClient sharedHttp,
                     SocketBus eventBus,
                     ScheduledExecutorService scheduler,
                     Gson gson,
                     PvPLeaderboardConfig config,
                     LongSupplier clock,
                     DoubleSupplier random)
    {
        this.sharedHttp = sharedHttp;
        this.eventBus = eventBus;
        this.scheduler = scheduler;
        this.gson = gson;
        this.config = config;
        this.clock = clock;
        this.random = random;
        if (eventBus != null) eventBus.register("error/rate_limited", this::onLimited);
    }

    /**
     * Opens (or resumes) the socket for {@code (uuid, displayName)}. A
     * second call with the same UUID and name while already connected is a
     * no-op; a call with the same UUID but a different name (e.g. user
     * switched characters on the same client) or a different UUID tears down
     * and reconnects so the server's OSRS-Connections row matches the active
     * in-game session. After a {@link #shutdown()} (RuneLite keeps this
     * {@code @Singleton} across plugin off / on) it simply opens again.
     *
     * <p>The {@code displayName} is sent to the server as a
     * {@code &name=<urlencoded>} query parameter on the WebSocket URL.
     * The server validates it against the MMR row's {@code player_names}
     * set (anti-spoof — a modified plugin can't claim a name that isn't
     * linked to the trusted UUID) and uses it for the conn row's
     * {@code name} + canonical {@code player_id} attributes. Pass
     * {@code null} when the name isn't known yet (e.g. plugin re-toggle
     * before {@code client.getLocalPlayer()} has resolved); the server
     * falls back to {@code sorted(player_names)[0]}.
     *
     * @param uuid        OSRS client UUID, lowercase v4. Invalid UUIDs
     *                    are refused without a connect attempt to avoid
     *                    the WAF auto-ban that would follow.
     * @param displayName Active in-game display name (e.g. "Toyco"), or
     *                    {@code null} if not yet known.
     */
    public synchronized void connect(String uuid, String displayName)
    {
        if (uuid == null || !UUID_V4.matcher(uuid).matches())
        {
            log.warn("WebSocketManager: refusing connect with invalid UUID format (would trip WAF auto-ban)");
            return;
        }
        String normName = (displayName == null || displayName.trim().isEmpty())
            ? null : displayName.trim();
        if (activeSocket != null)
        {
            // Same (uuid, name) tuple already wired — no-op resume.
            if (uuid.equals(activeUuid) && Objects.equals(normName, activeName)) return;
            // Switching UUID *or* display name: close existing cleanly
            // so the server can free its OSRS-Connections row before we
            // open a new one. The server also force-closes duplicates
            // server-side (force_close_duplicate keys on player_id, and
            // a name change with the same UUID could yield a different
            // player_id — explicit teardown avoids racing the
            // server-side eviction with a fresh open).
            closeLocked(CLOSE_NORMAL, uuid.equals(activeUuid) ? "name_change" : "uuid_change");
        }
        activeUuid = uuid;
        activeName = normName;
        if (retryPending()) return;
        cancelRetry();
        openNowOrDeferLocked();
    }

    /**
     * Tears down and re-opens the socket with the SAME {@code (uuid, name)}
     * so $connect-captured query flags (currently {@code show_rank}) are
     * re-sent. Used when the "Show your rank to others" config toggles — the
     * opt-out is snapshotted server-side at $connect (like {@code is_mod}), so
     * a live reconnect is the way to apply it promptly instead of waiting for
     * the next natural reconnect. No-op when not currently connected (the next
     * {@link #connect} will pick up the flag anyway).
     */
    public synchronized void reconnectNow()
    {
        if (activeSocket == null) return;
        closeLocked(CLOSE_NORMAL, "config_change");
        cancelRetry();
        openNowOrDeferLocked();
    }

    /**
     * Closes the socket with {@link #CLOSE_GOING_AWAY}. Disables
     * reconnect until the next {@link #connect(String, String)} call. Idempotent.
     */
    public synchronized void disconnect()
    {
        cancelRetry();
        if (resyncJob != null)
        {
            resyncJob.cancel(false);
            resyncJob = null;
        }
        if (activeSocket != null) closeLocked(CLOSE_GOING_AWAY, "client_logout");
        activeUuid = null;
    }

    /**
     * Final teardown — called from the plugin's {@code shutDown()}. The
     * same as {@link #disconnect()}: closes the socket and cancels any
     * scheduled retry; nothing reconnects until the next connect.
     */
    public void shutdown()
    {
        disconnect();
    }

    /**
     * Encodes + sends a cmd. Returns {@code true} if the frame was
     * handed off to OkHttp's send queue, {@code false} if the socket is
     * closed, the cmd isn't allowlisted or the cmd is held.
     *
     * <p>NOTE: this is the only way to send anything. The encode helper
     * enforces the {@link SocketProtocol#ALLOWED_OUTGOING} guard.
     */
    public boolean send(String cmd, JsonObject data)
    {
        if (isHeld(cmd, clock.getAsLong()))
        {
            return false;
        }
        WebSocket snapshot;
        synchronized (this) { snapshot = activeSocket; }
        if (snapshot == null)
        {
            // The socket can be null transiently between disconnect
            // and the next reconnect. Surface this at DEBUG so a
            // dropped frame (e.g. a confirm racing an open) is
            // diagnosable from logs without spamming WARN noise
            // every time the user types during a backoff.
            return false;
        }
        final String wire;
        try
        {
            wire = SocketProtocol.encode(gson, cmd, data);
        }
        catch (IllegalArgumentException e)
        {
            log.warn("WebSocketManager: refusing to send disallowed cmd={}", cmd);
            return false;
        }
        return snapshot.send(wire);
    }

    /** True while {@link #activeSocket} != null. */
    public synchronized boolean isConnected()
    {
        return activeSocket != null;
    }

    /** The display name the socket was last connected with; {@code null}
     *  before a connect with a name. */
    public synchronized String getActiveName()
    {
        return activeName;
    }

    /** Epoch ms at which the next reconnect attempt is scheduled to
     *  fire, or {@code 0} when no retry is pending (either because
     *  the socket is connected, or because no UUID has been set yet).
     *
     *  <p>Read on the Swing EDT by the lobby panel's 1Hz banner
     *  ticker; written on the scheduler/OkHttp threads. The field is
     *  {@code volatile} so the read sees the latest write without
     *  taking the manager's monitor (the ticker fires every second —
     *  contending on the monitor would serialize it behind in-flight
     *  sends). Stale-by-up-to-one-second is fine for a countdown
     *  display. */
    public long getRetryAtMs()
    {
        return retryAtMs;
    }

    /**
     * Registers {@code l} to be called every time the socket completes
     * an {@code $connect} handshake ({@code onOpen}). Invoked on
     * OkHttp's dispatcher thread — listeners must marshal as needed.
     *
     * <p>No unregister API: the callers are {@code @Singleton} services;
     * exposing one invites lifecycle bugs.
     */
    public void addConnectListener(Runnable l)
    {
        if (l != null) connectHooks.add(l);
    }

    /**
     * Registers {@code l} to run once per opened socket, a random
     * 0–{@link #RESYNC_MS} after the open, while that socket is
     * still the open one. Every re-sync listener runs in the same task.
     */
    public void addResyncListener(Runnable l)
    {
        if (l != null) resyncHooks.add(l);
    }

    /** Retry delay for the {@code attempt}-th consecutive reconnect:
     *  between 1 s and {@code min(60 s, 2^attempt s)} (attempts below 1
     *  count as 1). */
    static long retryDelayMs(int attempt, double r)
    {
        return between(1_000L, Math.min(60_000L, 1_000L << Math.min(Math.max(1, attempt), 6)), r);
    }

    /** Retry delay after an HTTP 401 on $connect: 30 to 90 s. */
    static long authDelayMs(double r)
    {
        return between(30_000L, 90_000L, r);
    }

    static long resyncMs(double r)
    {
        return between(0L, RESYNC_MS, r);
    }

    private static long between(long lo, long hi, double r)
    {
        if (hi <= lo) return lo;
        double c = Double.isNaN(r) ? 0.0 : Math.max(0.0, Math.min(1.0, r));
        return lo + Math.round(c * (hi - lo));
    }

    // ---------------------------------------------------------------
    // Internal — connection wire-up
    // ---------------------------------------------------------------

    /** Lazily builds (and caches) the OkHttpClient used specifically for
     *  the WebSocket. Derived from the injected shared client so we
     *  keep its connection pool / SSL config but tack on the 8-min
     *  RFC 6455 ping interval. */
    private OkHttpClient pingingClient()
    {
        if (pingingClient == null)
        {
            pingingClient = sharedHttp.newBuilder()
                .pingInterval(8, TimeUnit.MINUTES)
                .build();
        }
        return pingingClient;
    }

    /** Must be called under {@code synchronized (this)}. */
    private void openLocked()
    {
        if (activeUuid == null) return;
        // The name: RFC 3986 reserved chars are stripped by the in-game name
        // validator (RuneScape names are [A-Za-z0-9 _-]) so a single
        // urlencode pass is sufficient — no double-encode risk.
        // show_rank (p15-membership-feed): when the user turns "Show your
        // rank to others" OFF we append show_rank=0 so the backend marks this
        // profile opted-out in OSRS-PluginUsers (drops it from the membership
        // feed). Default (opted-in) omits the param — the server treats
        // absence as opted-in. Captured at $connect like is_mod, so a
        // mid-session toggle applies on reconnect (see reconnectNow).
        String url = PvpConsts.SOCKET_URL + "?uuid=" + activeUuid
            + (activeName == null ? "" : "&name=" + URLEncoder.encode(activeName, StandardCharsets.UTF_8))
            + (config.showRankToOthers() ? "" : "&show_rank=0")
            + "&v=" + PvpConsts.VERSION;
        Request req = new Request.Builder()
            .url(url)
            .header("User-Agent", PvpConsts.USER_AGENT)
            .build();
        openTimes.addLast(clock.getAsLong());
        while (openTimes.size() > OPEN_BURST) openTimes.removeFirst();
        activeSocket = pingingClient().newWebSocket(req, new Listener());
    }

    /** Opens now, or, after {@link #OPEN_BURST} opens within a minute,
     *  schedules the open as a retry. Must be called under
     *  {@code synchronized (this)}. */
    private void openNowOrDeferLocked()
    {
        long now = clock.getAsLong();
        while (!openTimes.isEmpty() && now - openTimes.peekFirst() >= 60_000L)
        {
            openTimes.removeFirst();
        }
        if (openTimes.size() >= OPEN_BURST)
        {
            scheduleRetry(false);
            return;
        }
        openLocked();
    }

    /** Asks the current socket to close and forgets it (its callbacks are
     *  stale from here on). Must be called under {@code synchronized (this)}
     *  with a socket open. */
    private void closeLocked(int code, String reason)
    {
        try { activeSocket.close(code, reason); }
        catch (Exception ignored) { /* best-effort */ }
        endLocked(activeSocket);
    }

    /** Bookkeeping for {@code ws} going away: when it is the current socket,
     *  forgets it and resets the backoff if it stayed open
     *  {@link #STABLE_MS}. Returns whether it was current — a
     *  callback from a socket the plugin already replaced or closed is stale.
     *  Must be called under {@code synchronized (this)}. */
    private boolean endLocked(WebSocket ws)
    {
        if (activeSocket != ws) return false;
        activeSocket = null;
        if (openedAtMs > 0L && clock.getAsLong() - openedAtMs >= STABLE_MS)
        {
            retryAttempt = 0;
        }
        openedAtMs = 0L;
        return true;
    }

    /** Runs every listener, each isolated from the others' exceptions. */
    private void runAll(List<Runnable> listeners)
    {
        for (Runnable l : listeners)
        {
            try { l.run(); }
            catch (Exception e)
            {
            }
        }
    }

    private boolean isHeld(String cmd, long now)
    {
        if (now < holdAllUntil) return true;
        if (cmd == null) return false;
        Long until = holdCmdUntil.get(cmd);
        if (until == null) return false;
        if (now < until) return true;
        holdCmdUntil.remove(cmd, until);
        return false;
    }

    private void onLimited(JsonObject data)
    {
        if (data == null) return;
        long now = clock.getAsLong();
        long retryAt = JsonLenient.optLong(data, "retry_at_epoch_ms", 0L);
        if (retryAt <= now) return;
        long until = Math.min(retryAt, now + MAX_HOLD_MS);
        String cmd = JsonLenient.optString(data, "cmd");
        if (cmd.isEmpty())
        {
            holdAllUntil = Math.max(holdAllUntil, until);
        }
        else
        {
            holdCmdUntil.merge(cmd, until, Math::max);
        }
    }

    private void scheduleResync(WebSocket opened)
    {
        if (resyncHooks.isEmpty()) return;
        long delay = resyncMs(random.getAsDouble());
        synchronized (this)
        {
            resyncJob = scheduler.schedule(() -> runResync(opened), delay, TimeUnit.MILLISECONDS);
        }
    }

    private void runResync(WebSocket opened)
    {
        synchronized (this)
        {
            if (activeSocket != opened) return;
        }
        runAll(resyncHooks);
    }

    private synchronized void cancelRetry()
    {
        if (retryJob != null)
        {
            retryJob.cancel(false);
            retryJob = null;
        }
        retryAtMs = 0L;
    }

    /** A scheduled retry that has not run yet. Must be called under
     *  {@code synchronized (this)}. */
    private boolean retryPending()
    {
        return retryJob != null && !retryJob.isDone();
    }

    /** Schedules the next open: after an HTTP 401, after
     *  {@link #authDelayMs(double)}; otherwise after
     *  {@link #retryDelayMs(int, double)} for the next attempt. Nothing
     *  without a UUID or while a retry is already scheduled. The panel
     *  surfaces a reconnect banner with a countdown driven by
     *  {@link #getRetryAtMs()}. */
    private synchronized void scheduleRetry(boolean authRefused)
    {
        if (activeUuid == null || retryPending()) return;
        long delay = authRefused ? authDelayMs(random.getAsDouble()) : retryDelayMs(++retryAttempt, random.getAsDouble());
        retryAtMs = System.currentTimeMillis() + delay;
        retryJob = scheduler.schedule(this::retryTick, delay, TimeUnit.MILLISECONDS);
    }

    private synchronized void retryTick()
    {
        retryJob = null;
        retryAtMs = 0L;
        if (activeUuid == null || activeSocket != null) return;
        openLocked();
    }

    /** WebSocket listener — runs on OkHttp's dispatcher thread. */
    private final class Listener extends WebSocketListener
    {
        @Override
        public void onOpen(WebSocket webSocket, Response response)
        {
            boolean isCurrent;
            synchronized (SocketMgr.this)
            {
                isCurrent = (activeSocket == webSocket);
                if (isCurrent) openedAtMs = clock.getAsLong();
                retryAtMs = 0L;
            }
            runAll(connectHooks);
            if (isCurrent) scheduleResync(webSocket);
        }

        @Override
        public void onMessage(WebSocket webSocket, String text)
        {
            SocketCommand cmd = SocketProtocol.decode(gson, text);
            if (cmd == null)
            {
                return;
            }
            eventBus.fire(cmd.cmd, cmd.data);
        }

        @Override
        public void onClosing(WebSocket webSocket, int code, String reason)
        {
            // Acknowledge server-initiated close cleanly.
            webSocket.close(code, reason);
        }

        /** Any close of the current socket reconnects with backoff, whatever
         *  its code (the server's 2-hour close is 1001). A callback from a
         *  socket the plugin already replaced (the {@code name_change}
         *  reconnect in {@link #connect}) or closed (logout, plugin stop) is
         *  stale: it must neither clobber the live socket — {@link #send} would
         *  then drop every frame as "no active socket" — nor schedule a
         *  spurious reconnect. */
        @Override
        public void onClosed(WebSocket webSocket, int code, String reason)
        {
            boolean isCurrent;
            synchronized (SocketMgr.this) { isCurrent = endLocked(webSocket); }
            if (isCurrent) scheduleRetry(false);
        }

        /** Same stale-callback guard as {@link #onClosed} (e.g. the previous
         *  socket's TCP RST arriving after the name-change replacement). An
         *  HTTP 401 on $connect retries after the auth-refused delay, any
         *  other failure on the backoff. */
        @Override
        public void onFailure(WebSocket webSocket, Throwable t, @Nullable Response response)
        {
            int status = response == null ? -1 : response.code();
            boolean isCurrent;
            synchronized (SocketMgr.this) { isCurrent = endLocked(webSocket); }
            if (response != null) response.close();
            if (isCurrent) scheduleRetry(status == 401);
        }
    }
}

package com.pvp.leaderboard.service.socket;

import com.google.gson.*;
import java.util.*;

/**
 * Pure helper for socket-lobby wire encoding/decoding + the
 * client-side outgoing-cmd allowlist.
 *
 * <p>Mirrors backend's {@code backend.core.socket_protocol} module —
 * {@link #ALLOWED_OUTGOING} is the plugin-side counterpart of the
 * Python {@code ALLOWED_COMMANDS} env-var-driven allowlist. Any client
 * code that wants to send a cmd MUST route through
 * {@link #encode(Gson, String, JsonObject)} so the allowlist guard fires
 * before bytes leave the process. The server has the same allowlist
 * server-side (defense in depth) but failing fast on the client makes
 * the bug obvious to plugin contributors instead of hidden behind a
 * silent {@code error/invalid_message} push.
 *
 * <p>Max wire size is enforced server-side (4 KB per
 * {@code WEBSOCKET_PROTOCOL.md} §1). The plugin doesn't pre-check size —
 * we'd just be guessing what the JSON serialises to. Server's
 * {@code error/invalid_message MESSAGE_TOO_LARGE} push is the
 * authoritative signal.
 *
 * <p>Keepalive is RFC 6455 native ping/pong (handled by
 * {@code OkHttpClient.Builder.pingInterval(8 min)} in
 * {@link SocketMgr}) — there is no {@code system/ping} cmd in
 * this release per the protocol doc's locked decision §0.1.
 */
public final class SocketProtocol
{
    /**
     * The cmds the plugin is allowed to send (the lobby's confirm, block and
     * unblock). Anything outside this set throws from
     * {@link #encode(Gson, String, JsonObject)}.
     *
     * <p>Plan 10 (2026-09-21) appended the five {@code queue/*} cmds and
     * the nine {@code tournament/*} cmds (WEBSOCKET_PROTOCOL.md 6.2b / 6.3);
     * {@code WebSocketQueueService} / {@code TourneySvc}
     * are the only senders.
     *
     * <p>Server-only outbound cmds ({@code lobby/roster},
     * {@code lobby/invite_received}, etc.) are NEVER in this set —
     * they're inbound-only on the client. Listening for them is via
     * {@link SocketBus#register(String, java.util.function.Consumer)}.
     */
    public static final Set<String> ALLOWED_OUTGOING = Set.of(
        "lobby/confirm", "lobby/block", "lobby/unblock",
        // Plan 10 (2026-09-21): the matchmaking queue (Part B, WebSocketQueueService)
        // and the Swiss tournaments (Part C, TourneySvc). Mirrors the
        // backend additive ALLOWED_COMMANDS_EXTRA / ALLOWED_COMMANDS_TOURNAMENT env lines.
        "queue/join", "queue/leave", "queue/expand_range", "queue/set_prefs", "queue/status", "queue/recent",
        "tournament/list", "tournament/register", "tournament/withdraw", "tournament/status",
        "tournament/subscribe", "tournament/unsubscribe", "tournament/in_combat",
        "tournament/round_end_reply", "tournament/report_problem", "tournament/gear_status", "tournament/world",
        "tournament/no_show");

    /**
     * Encodes a cmd + payload pair into the wire envelope string.
     * Throws if {@code cmd} is not in {@link #ALLOWED_OUTGOING}.
     *
     * @param gson the injected client {@link Gson}
     * @param cmd  the cmd name (e.g. {@code "lobby/invite"})
     * @param data the payload object; {@code null} renders as
     *             {@code "data": {}} per the protocol's "never null"
     *             rule (§2)
     * @return JSON text ready for {@code WebSocket.send(String)}
     * @throws IllegalArgumentException if {@code cmd} is not allowlisted
     */
    public static String encode(Gson gson, String cmd, JsonObject data)
    {
        if (cmd == null || !ALLOWED_OUTGOING.contains(cmd))
        {
            throw new IllegalArgumentException(
                "cmd not in ALLOWED_OUTGOING: " + cmd);
        }
        return gson.toJson(new SocketCommand(cmd, data));
    }

    /**
     * Decodes a server-pushed wire frame into a {@link SocketCommand}.
     * Returns {@code null} for any malformed input (empty string,
     * non-JSON, JSON that isn't an object, missing/empty/non-string
     * {@code cmd}); a missing or non-object {@code data} reads as
     * {@code {}}. Callers treat {@code null} as "drop this frame silently".
     */
    public static SocketCommand decode(Gson gson, String wire)
    {
        try
        {
            // Gson reads null, empty and blank input as null. isJsonPrimitive()
            // is true for numbers + booleans too; the wire spec says cmd is a
            // string. Per protocol §2 data must always be an object; anything
            // else is a server bug and SocketCommand renders it as empty.
            JsonObject root = gson.fromJson(wire, JsonObject.class);
            JsonElement c = root == null ? null : root.get("cmd");
            if (c == null || !c.isJsonPrimitive() || !c.getAsJsonPrimitive().isString() || c.getAsString().isEmpty()) return null;
            JsonElement d = root.get("data");
            return new SocketCommand(c.getAsString(), d != null && d.isJsonObject() ? d.getAsJsonObject() : null);
        }
        catch (JsonParseException | IllegalStateException | ClassCastException e)
        {
            return null;
        }
    }
}

package com.pvp.leaderboard.tournament;

import java.util.function.*;

/**
 * Plan 10 F.2 (2026-09-21): the listener that flips the side panel +
 * overlay to the <b>Tournament</b> bucket the moment a round opens with an
 * opponent ({@code tournament/match_assigned}), while the
 * {@code autoSwitchTournamentBucket} config allows it. Nothing else
 * switches: the way back is the next ordinary fight, through
 * {@code FightMonitor}'s auto-switch like every other bucket (AS-72), and
 * the {@link OppTracker} pin keeps tournament games from
 * flipping the panel to NH in between. The plugin supplies the config
 * read and the config write.
 */
public final class BucketSwitch implements TournamentEventListener
{
    private final BooleanSupplier enabled;
    private final Runnable toTourney;

    public BucketSwitch(BooleanSupplier enabled, Runnable toTourney)
    {
        this.enabled = enabled == null ? () -> false : enabled;
        this.toTourney = toTourney == null ? () -> {} : toTourney;
    }

    @Override
    public void onMatchAssigned(MatchSeries series)
    {
        if (series == null) return;
        if (!enabled.getAsBoolean()) return;
        toTourney.run();
    }
}

