package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import lombok.*;

public final class GearCapture
{

    private static final String NAME_CHARS = "[^A-Za-z0-9 .,!'()+\\-/&]";

    @RequiredArgsConstructor
    private static final class Row
    {
        final int id;
        final String name;
        long qty;
        String slot;
        boolean stackable;
        boolean alsoCarried;
    }

    public static String toCatalog(GearKit kit)
    {
        if (kit == null) return null;
        Map<Integer, Row> rows = new LinkedHashMap<>();
        for (GearItem i : kit.worn) add(rows, i, true);
        for (GearItem i : kit.carried) add(rows, i, false);
        if (kit.pouchKnown) for (GearItem i : kit.pouch) add(rows, i, false);
        if (rows.isEmpty()) return null;

        String build = GearSet.BUILDS.contains(kit.build) ? kit.build : "main";
        var sb = new StringBuilder("{\n");
        field(sb, "set_id", quote("capture-" + build));
        field(sb, "name", quote("Captured " + GearSet.buildLabel(build).replace('/', '-') + " kit"));
        field(sb, "version", "1");
        field(sb, "placeholder", "false");
        field(sb, "build", quote(build));
        field(sb, "spellbook", kit.spellbook == null ? "null" : quote(kit.spellbook));
        field(sb, "match", quote("exact"));
        field(sb, "variants", quote("any"));
        sb.append("  \"items\": [\n");
        List<String> lines = new ArrayList<>();
        for (Row r : rows.values())
        {
            var line = new StringBuilder("    {\"id\": ").append(r.id)
                .append(", \"name\": ").append(quote(r.name))
                .append(", \"qty\": ").append(r.qty);
            boolean keepSlot = r.slot != null && (r.stackable || (!r.alsoCarried && r.qty == 1));
            if (keepSlot) line.append(", \"slot\": ").append(quote(r.slot));
            if (r.stackable) line.append(", \"stackable\": true");
            lines.add(line.append('}').toString());
        }
        sb.append(String.join(",\n", lines)).append("\n  ]\n}");
        return sb.toString();
    }

    private static void add(Map<Integer, Row> rows, GearItem i, boolean worn)
    {
        if (i == null || i.noted || i.id <= 0 || i.qty <= 0) return;
        Row r = rows.computeIfAbsent(i.id, k -> new Row(i.id, cleanName(i.name, i.id)));
        r.qty += i.qty;
        r.stackable |= i.stackable;
        if (worn && i.slot != null && r.slot == null) r.slot = i.slot;
        if (!worn) r.alsoCarried = true;
    }

    static String cleanName(String name, int id)
    {
        String n = name == null ? "" : name.replaceAll("<[^>]*>", "").replace(' ', ' ').replaceAll(NAME_CHARS, "").replaceAll(" +", " ").trim();
        if (n.length() > 60) n = n.substring(0, 60).trim();
        return n.isEmpty() ? "Item " + id : n;
    }

    private static void field(StringBuilder sb, String key, String jsonValue)
    {
        sb.append("  ").append(quote(key)).append(": ").append(jsonValue).append(",\n");
    }

    private static String quote(String s)
    {
        return new JsonPrimitive(s).toString();
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;

public final class GearDiff
{
    public static final int DIFF_MAX = 12;

    public static final class Row
    {
        public final int itemId;
        public final String name;
        public final int need;
        public final int have;
        public final boolean stackable;
        public final boolean noted;
        public final List<Integer> altIds;

        public Row(int itemId, String name, int need, int have, boolean stackable, boolean noted, List<Integer> altIds)
        {
            this.itemId = itemId;
            this.name = name;
            this.need = need;
            this.have = have;
            this.stackable = stackable;
            this.noted = noted;
            this.altIds = altIds == null ? Collections.<Integer>emptyList() : altIds;
        }

        public boolean isMissing()
        {
            return have < need;
        }

        public boolean isExtra()
        {
            return have > need;
        }

        public int shortBy()
        {
            return Math.max(0, need - have);
        }

        public int overBy()
        {
            return Math.max(0, have - need);
        }

        @Override
        public String toString()
        {
            return itemId + " " + have + "/" + need;
        }
    }

    public final String setBuild;
    public final String kitBuild;
    public final boolean buildOk;
    public final String setSpellbook;
    public final String kitSpellbook;
    public final boolean spellbookOk;
    public final List<Row> missing;
    public final List<Row> extra;
    public final boolean pouchUnknown;
    public final boolean ok;

    public GearDiff(String setBuild, String kitBuild, boolean buildOk, String setSpellbook, String kitSpellbook, boolean spellbookOk,
                    List<Row> missing, List<Row> extra, boolean pouchUnknown)
    {
        this.setBuild = setBuild;
        this.kitBuild = kitBuild;
        this.buildOk = buildOk;
        this.setSpellbook = setSpellbook;
        this.kitSpellbook = kitSpellbook;
        this.spellbookOk = spellbookOk;
        this.missing = missing;
        this.extra = extra;
        this.pouchUnknown = pouchUnknown;
        ok = buildOk && spellbookOk && missing.isEmpty() && extra.isEmpty();
    }

    public JsonArray wireDiff()
    {
        var out = new JsonArray();
        for (List<Row> rows : Arrays.asList(missing, extra))
        {
            for (Row r : rows)
            {
                if (out.size() >= DIFF_MAX) return out;
                var t = new JsonArray();
                t.add(r.itemId);
                t.add(r.need);
                t.add(r.have);
                out.add(t);
            }
        }
        return out;
    }

    public String summary()
    {
        List<String> parts = new ArrayList<>();
        if (!missing.isEmpty()) parts.add(missing.size() + " missing");
        if (!extra.isEmpty()) parts.add(extra.size() + " extra");
        if (!buildOk) parts.add("wrong build");
        if (!spellbookOk) parts.add("wrong spellbook");
        return String.join(", ", parts);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import com.pvp.leaderboard.game.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import lombok.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

/** One item: a row of a gear set, or an item read from a kit ({@code noted} only there; {@code variants} and
 *  {@code altIds} only on set rows). */
@EqualsAndHashCode
public final class GearItem
{
    public final int id;
    public final int qty;
    public final String name;
    public final String slot;
    public final boolean stackable;
    public final boolean noted;
    public final String variants;
    public final List<Integer> altIds;

    public GearItem(int id, int qty, String name, String slot, boolean stackable, boolean noted, String variants, Collection<Integer> altIds)
    {
        this.id = id;
        this.qty = qty;
        this.name = name;
        this.slot = slot;
        this.stackable = stackable;
        this.noted = noted;
        this.variants = variants;
        this.altIds = alternatives(id, altIds);
    }

    public static GearItem fromJson(JsonElement e)
    {
        if (e == null || !e.isJsonObject()) return null;
        JsonObject o = e.getAsJsonObject();
        Integer id = optInteger(o, "id");
        Integer qty = optInteger(o, "qty");
        if (id == null || id < 1 || qty == null || qty < 1) return null;
        String name = optString(o, "name").trim();
        return new GearItem(id, qty, name.isEmpty() ? "Item " + id : name, wornSlot(optString(o, "slot", null)),
            optBool(o, "stackable", false), false, variantsMode(optString(o, "variants", null)), altIdsOf(o));
    }

    public List<Integer> ids()
    {
        List<Integer> out = new ArrayList<>(1 + altIds.size());
        out.add(id);
        out.addAll(altIds);
        return out;
    }

    public boolean isWorn()
    {
        return slot != null;
    }

    static List<Integer> altIdsOf(JsonObject o)
    {
        List<Integer> out = new ArrayList<>();
        for (JsonElement a : optArray(o, "alt_ids"))
        {
            Integer v = wholeNumber(a);
            if (v != null) out.add(v);
        }
        return out;
    }

    private static Integer wholeNumber(JsonElement e)
    {
        if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber()) return null;
        try
        {
            double d = e.getAsDouble();
            if (d != Math.rint(d) || d < Integer.MIN_VALUE || d > Integer.MAX_VALUE) return null;
            return (int) d;
        }
        catch (RuntimeException ex)
        {
            return null;
        }
    }

    static List<Integer> alternatives(int id, Collection<Integer> raw)
    {
        if (raw == null || raw.isEmpty()) return Collections.emptyList();
        Set<Integer> out = new LinkedHashSet<>();
        for (Integer alt : raw)
        {
            if (alt != null && alt > 0 && alt != id) out.add(alt);
        }
        return out.isEmpty() ? Collections.<Integer>emptyList() : Collections.unmodifiableList(new ArrayList<>(out));
    }

    static String wornSlot(String s)
    {
        if (s == null) return null;
        for (String slot : ArenaWidgets.SLOT_NAMES) if (slot.equals(s)) return slot;
        return null;
    }

    static String variantsMode(String s)
    {
        return GearSet.VARIANTS_ANY.equals(s) || GearSet.VARIANTS_EXACT.equals(s) ? s : null;
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import java.util.function.*;
import net.runelite.api.gameval.ItemID;
import static com.pvp.leaderboard.util.JsonLenient.*;

public final class GearKit
{
    public static final String SOURCE_DUEL = "duel_kit";
    public static final String SOURCE_SUPPLIES = "supplies";
    public static final String SOURCE_CONTAINERS = "containers";
    public static final String SOURCE_SAVED = "saved_kit";
    public static final Set<Integer> POUCH_IDS = Set.of(ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH,
        ItemID.DIVINE_RUNE_POUCH_TROUVER);

    public final String source;
    public final String build;
    public final String spellbook;
    public final List<GearItem> worn;
    public final List<GearItem> carried;
    public final List<GearItem> pouch;
    public final boolean pouchKnown;
    public final long readAtMs;
    public final long loadoutSig;
    public final long pouchSig;
    public final boolean stale;

    /** A null {@code source} reads as {@link #SOURCE_CONTAINERS}; the lists are copied without their null entries. */
    public GearKit(String source, String build, String spellbook, List<GearItem> worn, List<GearItem> carried, List<GearItem> pouch,
                   boolean pouchKnown, long readAtMs, long loadoutSig, long pouchSig, boolean stale)
    {
        this.source = source == null ? SOURCE_CONTAINERS : source;
        this.build = build;
        this.spellbook = spellbook;
        this.worn = immutable(worn);
        this.carried = immutable(carried);
        this.pouch = immutable(pouch);
        this.pouchKnown = pouchKnown;
        this.readAtMs = readAtMs;
        this.loadoutSig = loadoutSig;
        this.pouchSig = pouchSig;
        this.stale = stale;
    }

    private static List<GearItem> immutable(List<GearItem> items)
    {
        if (items == null || items.isEmpty()) return Collections.emptyList();
        List<GearItem> out = new ArrayList<>(items.size());
        for (GearItem i : items) if (i != null) out.add(i);
        return Collections.unmodifiableList(out);
    }

    /** {@code s}'s answer; false when it throws. */
    public static boolean safe(BooleanSupplier s)
    {
        try
        {
            return s.getAsBoolean();
        }
        catch (RuntimeException e)
        {
            return false;
        }
    }

    public boolean hasRunePouch()
    {
        for (GearItem i : carried) if (POUCH_IDS.contains(i.id)) return true;
        for (GearItem i : worn) if (POUCH_IDS.contains(i.id)) return true;
        return false;
    }

    public GearKit asStale()
    {
        return new GearKit(source, build, spellbook, worn, carried, pouch, pouchKnown, readAtMs, loadoutSig, pouchSig, true);
    }

    public GearKit withSource(String newSource)
    {
        return new GearKit(newSource, build, spellbook, worn, carried, pouch, pouchKnown, readAtMs, loadoutSig, pouchSig, stale);
    }

    public GearKit withPouch(List<GearItem> runes, boolean known, long newPouchSig)
    {
        return new GearKit(source, build, spellbook, worn, carried, runes, known, readAtMs, loadoutSig, newPouchSig, stale);
    }

    public boolean sameContent(GearKit o)
    {
        return o != null && Objects.equals(build, o.build) && Objects.equals(spellbook, o.spellbook) && worn.equals(o.worn)
            && carried.equals(o.carried) && pouch.equals(o.pouch) && pouchKnown == o.pouchKnown && loadoutSig == o.loadoutSig
            && pouchSig == o.pouchSig;
    }

    public boolean isEmpty()
    {
        return worn.isEmpty() && carried.isEmpty() && pouch.isEmpty();
    }

    public String toJson()
    {
        var o = new JsonObject();
        o.addProperty("build", build);
        o.addProperty("spellbook", spellbook);
        o.add("worn", itemsJson(worn));
        o.add("carried", itemsJson(carried));
        o.add("pouch", itemsJson(pouch));
        o.addProperty("pouch_known", pouchKnown);
        o.addProperty("read_at", readAtMs);
        o.addProperty("loadout_sig", loadoutSig);
        o.addProperty("pouch_sig", pouchSig);
        return o.toString();
    }

    public static GearKit fromJson(String text)
    {
        if (text == null || text.trim().isEmpty()) return null;
        JsonElement e;
        try
        {
            e = new JsonParser().parse(text);
        }
        catch (RuntimeException ex)
        {
            return null;
        }
        if (e == null || !e.isJsonObject()) return null;
        JsonObject o = e.getAsJsonObject();
        return new GearKit(SOURCE_SAVED, optString(o, "build", null), optString(o, "spellbook", null),
            itemsFrom(optArray(o, "worn")), itemsFrom(optArray(o, "carried")), itemsFrom(optArray(o, "pouch")),
            optBool(o, "pouch_known", false), optLong(o, "read_at", 0L), longOf(o, "loadout_sig"), longOf(o, "pouch_sig"), false);
    }

    private static long longOf(JsonObject o, String key)
    {
        JsonElement e = o.get(key);
        if (e == null || !e.isJsonPrimitive()) return 0L;
        try
        {
            return e.getAsLong();
        }
        catch (RuntimeException ex)
        {
            return 0L;
        }
    }

    private static JsonArray itemsJson(List<GearItem> items)
    {
        var a = new JsonArray();
        for (GearItem i : items)
        {
            var o = new JsonObject();
            o.addProperty("id", i.id);
            o.addProperty("qty", i.qty);
            o.addProperty("name", i.name);
            if (i.slot != null) o.addProperty("slot", i.slot);
            if (i.stackable) o.addProperty("stackable", true);
            if (i.noted) o.addProperty("noted", true);
            a.add(o);
        }
        return a;
    }

    private static List<GearItem> itemsFrom(JsonArray a)
    {
        List<GearItem> out = new ArrayList<>();
        for (JsonElement e : a)
        {
            if (e == null || !e.isJsonObject()) continue;
            JsonObject o = e.getAsJsonObject();
            Integer id = optInteger(o, "id");
            Integer qty = optInteger(o, "qty");
            if (id == null || id < 1 || qty == null || qty < 1) continue;
            out.add(new GearItem(id, qty, optString(o, "name", "Item " + id), optString(o, "slot", null),
                optBool(o, "stackable", false), optBool(o, "noted", false), null, null));
        }
        return out;
    }
}

package com.pvp.leaderboard.tournament;

import java.util.*;
import java.util.function.*;
import lombok.*;

@RequiredArgsConstructor
public final class GearMatcher
{
    private final IntUnaryOperator variations;
    private final IntPredicate isRune;

    @RequiredArgsConstructor
    private static final class Units
    {
        final String name;
        final boolean stackable;
        long qty;
    }

    @RequiredArgsConstructor
    private static final class Group
    {
        final boolean exact;
        final Set<Integer> keys;
        final GearItem first;
        long need;
        long have;
    }

    public GearDiff match(GearSet set, GearKit kit, String buildInUse)
    {
        if (set == null || kit == null) return null;
        String kitBuild = buildInUse != null ? buildInUse : kit.build;
        boolean buildOk = kitBuild == null || set.build.equals(kitBuild);
        boolean spellbookOk = set.spellbook == null || set.spellbook.equals(kit.spellbook);

        boolean pouchChecked = listsRunes(set);
        Map<Integer, Units> units = new LinkedHashMap<>();
        Map<Integer, Units> noted = new LinkedHashMap<>();
        collect(kit.worn, units, noted);
        collect(kit.carried, units, noted);
        if (pouchChecked && kit.pouchKnown) collect(kit.pouch, units, noted);

        Map<String, Group> groups = new LinkedHashMap<>();
        for (GearItem item : set.items)
        {
            boolean exact = GearSet.VARIANTS_EXACT.equals(set.variantsFor(item));
            Set<Integer> keys = new TreeSet<>();
            for (int id : item.ids()) keys.add(exact ? id : variations.applyAsInt(id));
            Group g = groups.computeIfAbsent((exact ? "x" : "a") + keys, k -> new Group(exact, keys, item));
            g.need += item.qty;
        }

        Map<Integer, Long> remaining = new LinkedHashMap<>();
        for (Map.Entry<Integer, Units> e : units.entrySet()) remaining.put(e.getKey(), e.getValue().qty);
        for (boolean exact : new boolean[]{true, false})
        {
            for (Group g : groups.values()) if (g.exact == exact) take(g, remaining);
        }

        List<GearDiff.Row> standalone = new ArrayList<>();
        for (Map.Entry<Integer, Long> e : remaining.entrySet())
        {
            long left = e.getValue();
            if (left <= 0) continue;
            Group owner = ownerOf(groups.values(), e.getKey());
            if (owner != null)
            {
                owner.have += left;
                continue;
            }
            Units u = units.get(e.getKey());
            standalone.add(new GearDiff.Row(e.getKey(), u.name, 0, clamp(left), u.stackable, false, null));
        }

        List<GearDiff.Row> missing = new ArrayList<>();
        List<GearDiff.Row> extra = new ArrayList<>();
        for (Group g : groups.values())
        {
            var row = new GearDiff.Row(g.first.id, g.first.name, clamp(g.need), clamp(g.have), g.first.stackable, false,
                g.first.altIds);
            if (row.isMissing()) missing.add(row);
            else if (row.isExtra()) extra.add(row);
        }
        extra.addAll(standalone);
        for (Map.Entry<Integer, Units> e : noted.entrySet())
        {
            extra.add(new GearDiff.Row(e.getKey(), e.getValue().name, 0, clamp(e.getValue().qty), e.getValue().stackable, true, null));
        }
        boolean pouchUnknown = pouchChecked && kit.hasRunePouch() && !kit.pouchKnown;
        return new GearDiff(set.build, kitBuild, buildOk, set.spellbook, kit.spellbook, spellbookOk, missing, extra, pouchUnknown);
    }

    private boolean listsRunes(GearSet set)
    {
        for (GearItem item : set.items)
        {
            for (int id : item.ids())
            {
                if (isRune.test(id) || isRune.test(variations.applyAsInt(id))) return true;
            }
        }
        return false;
    }

    private void take(Group g, Map<Integer, Long> remaining)
    {
        for (Map.Entry<Integer, Long> e : remaining.entrySet())
        {
            if (g.have >= g.need) return;
            if (e.getValue() <= 0 || !holds(g, e.getKey())) continue;
            long taken = Math.min(e.getValue(), g.need - g.have);
            g.have += taken;
            e.setValue(e.getValue() - taken);
        }
    }

    private Group ownerOf(Collection<Group> groups, int id)
    {
        for (boolean exact : new boolean[]{true, false})
        {
            for (Group g : groups) if (g.exact == exact && holds(g, id)) return g;
        }
        return null;
    }

    private boolean holds(Group g, int kitId)
    {
        return g.keys.contains(g.exact ? kitId : variations.applyAsInt(kitId));
    }

    private static void collect(List<GearItem> items, Map<Integer, Units> units, Map<Integer, Units> noted)
    {
        for (GearItem i : items)
        {
            if (i == null || i.id <= 0 || i.qty <= 0) continue;
            Map<Integer, Units> into = i.noted ? noted : units;
            into.computeIfAbsent(i.id, k -> new Units(i.name, i.stackable)).qty += i.qty;
        }
    }

    private static int clamp(long v)
    {
        return (int) Math.min(v, Integer.MAX_VALUE);
    }
}

package com.pvp.leaderboard.tournament;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import lombok.*;

@RequiredArgsConstructor
public final class GearReporter implements TournamentEventListener
{
    public static final long SEND_MS = 1_000L;
    public static final long RESEND_MS = 10_000L;
    static final long RATE_MIN_MS = 1_000L;
    static final long RATE_MAX_MS = 10_000L;
    static final long JITTER_MS = 1_000L;
    static final long ERROR_RETRY_MS = 10_000L;
    static final long ERROR_MAX_MS = 300_000L;
    static final long STALE_MIN_MS = 1_000L;
    static final long STALE_MAX_MS = 30_000L;
    static final String STATUS_CMD = "tournament/gear_status";

    @AllArgsConstructor
    public static final class View
    {
        public static final View EMPTY = new View(null, null, null, false, false, 0L);

        public final GearTracker.GearEvent event;
        public final GearKit kit;
        public final GearDiff diff;
        public final boolean inCombat;
        public final boolean atArena;
        public final long nowMs;

        public boolean hasEvent()
        {
            return event != null;
        }

        public boolean neverRead()
        {
            return event != null && kit == null;
        }

        public boolean stale()
        {
            return kit != null && kit.stale;
        }

        public boolean verifiedOk()
        {
            return diff != null && diff.ok && !stale();
        }

        public List<Integer> missingIds()
        {
            if (diff == null) return Collections.emptyList();
            List<Integer> out = new ArrayList<>();
            for (GearDiff.Row r : diff.missing)
            {
                out.add(r.itemId);
                out.addAll(r.altIds);
            }
            return out;
        }
    }

    private final TourneySvc service;
    private final GearTracker events;
    private final KitSource source;
    private final GearMatcher matcher;
    private final BooleanSupplier inCombat;
    private final LongSupplier nowMs;
    /** 0 to 1: scales the up-to-{@link #JITTER_MS} added to each {@code RATE_LIMITED} retry. */
    private final DoubleSupplier jitter;
    private final List<Consumer<View>> listeners = new CopyOnWriteArrayList<>();
    private volatile View view = View.EMPTY;

    private String sentKey;
    private String sentSig;
    private boolean sentOk;
    private boolean awaitingAck;
    private long lastSentAtMs;
    private long forceAtMs;
    private long changeAtMs;
    private long staleBackoff = STALE_MIN_MS;
    private long errorBackoff = ERROR_RETRY_MS;
    private long rateBackoff = RATE_MIN_MS;

    /** Without jitter. */
    public GearReporter(TourneySvc service, GearTracker events, KitSource source, GearMatcher matcher,
                              BooleanSupplier inCombat, LongSupplier nowMs)
    {
        this(service, events, source, matcher, inCombat, nowMs, () -> 0.0);
    }

    public View view()
    {
        return view;
    }

    public void addViewListener(Consumer<View> listener)
    {
        listeners.add(listener);
    }

    public void tick()
    {
        long now = nowMs.getAsLong();
        GearTracker.GearEvent ev = events.current();
        View v;
        try
        {
            v = evaluate(ev, now);
        }
        catch (RuntimeException e)
        {
            v = new View(ev, null, null, false, false, now);
        }
        view = v;
        if (ev == null)
        {
            resetSend();
        }
        else if (v.kit != null && v.diff != null)
        {
            sendIfDue(ev, v, now);
        }
        for (Consumer<View> l : listeners)
        {
            try
            {
                l.accept(v);
            }
            catch (RuntimeException e)
            {
            }
        }
    }

    private View evaluate(GearTracker.GearEvent ev, long now)
    {
        boolean fighting = GearKit.safe(inCombat);
        if (ev == null) return new View(null, null, null, fighting, source.atArena(), now);
        GearKit kit = source.kit(ev.set, ev.arena);
        GearDiff diff = matcher.match(ev.set, kit, source.buildInUse(ev.arena));
        return new View(ev, kit, diff, fighting, source.atArena(), now);
    }

    private void sendIfDue(GearTracker.GearEvent ev, View v, long now)
    {
        String key = ev.tournamentId + "|" + ev.set.digest;
        boolean ok = v.verifiedOk();
        String signature = key + "|" + ok + "|" + v.diff.buildOk + "|" + v.diff.spellbookOk + "|" + v.diff.missing.size() + "|"
            + v.diff.extra.size() + "|" + v.kit.source + "|" + v.diff.wireDiff();
        if (!key.equals(sentKey))
        {
            if (forceAtMs == 0 || forceAtMs > now) forceAtMs = now;
        }
        if (signature.equals(sentSig)) changeAtMs = 0;
        else if (changeAtMs == 0) changeAtMs = now + SEND_MS;
        boolean due = (forceAtMs > 0 && now >= forceAtMs) || (changeAtMs > 0 && now >= changeAtMs)
            || (awaitingAck && now - lastSentAtMs >= RESEND_MS);
        if (!due) return;
        if (!ev.arena && source.frozen(false)) return;
        service.gearStatus(ev.tournamentId, ev.set.digest, v.diff, v.kit.source, ok);
        sentKey = key;
        sentSig = signature;
        sentOk = ok;
        awaitingAck = true;
        lastSentAtMs = now;
        forceAtMs = 0;
        changeAtMs = 0;
    }

    private void resetSend()
    {
        sentKey = null;
        sentSig = null;
        awaitingAck = false;
        forceAtMs = 0;
        changeAtMs = 0;
    }

    private long jitterMs()
    {
        return Math.round(jitter.getAsDouble() * JITTER_MS);
    }

    // ---------------------------------------------------------------- listener (EDT)

    @Override
    public void onGearCheck(String tournamentId, int round, long untilEpochS)
    {
        forceAtMs = nowMs.getAsLong();
    }

    @Override
    public void onGearAck(String tournamentId, boolean ok)
    {
        if (!awaitingAck || sentKey == null || tournamentId == null) return;
        if (!sentKey.startsWith(tournamentId + "|") || (!ok && sentOk)) return;
        awaitingAck = false;
        staleBackoff = STALE_MIN_MS;
        errorBackoff = ERROR_RETRY_MS;
        rateBackoff = RATE_MIN_MS;
    }

    @Override
    public void onConnected()
    {
        forceAtMs = nowMs.getAsLong();
    }

    @Override
    public void onTournamentError(String code, String message, String cmd)
    {
        if (!STATUS_CMD.equals(cmd)) return;
        long now = nowMs.getAsLong();
        awaitingAck = false;
        switch (code == null ? "" : code)
        {
            case "RATE_LIMITED":
                forceAtMs = now + rateBackoff + jitterMs();
                rateBackoff = Math.min(rateBackoff * 2, RATE_MAX_MS);
                break;
            case "TOURNAMENT_GEAR_STALE":
                service.status();
                forceAtMs = now + staleBackoff;
                staleBackoff = Math.min(staleBackoff * 2, STALE_MAX_MS);
                break;
            case "TOURNAMENT_NOT_REGISTERED":
                forceAtMs = 0;
                changeAtMs = 0;
                break;
            default:
                forceAtMs = now + errorBackoff;
                errorBackoff = Math.min(errorBackoff * 2, ERROR_MAX_MS);
        }
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import lombok.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

@AllArgsConstructor
public final class GearSet
{
    public static final String VARIANTS_ANY = "any";
    public static final String VARIANTS_EXACT = "exact";
    public static final List<String> BUILDS = Collections.unmodifiableList(Arrays.asList("main", "zerker", "pure"));
    static final List<String> SPELLBOOKS = Collections.unmodifiableList(Arrays.asList("standard", "ancient", "lunar", "arceuus"));

    public final String setId;
    public final String name;
    public final int version;
    public final boolean placeholder;
    /** main / zerker / pure. */
    public final String build;
    public final String buildLabel;
    public final String spellbook;
    public final String bookLabel;
    public final String match;
    public final String variants;
    public final String digest;
    public final String imageUrl;
    public final List<GearItem> items;

    public static GearSet fromJson(JsonElement e)
    {
        if (e == null || !e.isJsonObject()) return null;
        JsonObject o = e.getAsJsonObject();
        String setId = optString(o, "set_id").trim();
        String digest = optString(o, "digest").trim();
        String build = optString(o, "build");
        if (setId.isEmpty() || digest.isEmpty() || !BUILDS.contains(build)) return null;
        List<GearItem> items = new ArrayList<>();
        for (JsonElement item : optArray(o, "items"))
        {
            GearItem parsed = GearItem.fromJson(item);
            if (parsed != null) items.add(parsed);
        }
        if (items.isEmpty()) return null;
        String spellbook = optString(o, "spellbook", null);
        if (!SPELLBOOKS.contains(spellbook)) spellbook = null;
        String buildLabel = optString(o, "build_label").trim();
        String bookLabel = optString(o, "spellbook_label").trim();
        String variants = optString(o, "variants", VARIANTS_ANY);
        Integer version = optInteger(o, "version");
        String name = optString(o, "name").trim();
        return new GearSet(
            setId,
            name.isEmpty() ? setId : name,
            version == null || version < 1 ? 1 : version,
            optBool(o, "placeholder", false),
            build,
            buildLabel.isEmpty() ? buildLabel(build) : buildLabel,
            spellbook,
            spellbook == null ? null : bookLabel.isEmpty() ? bookLabel(spellbook) : bookLabel,
            "exact",
            VARIANTS_EXACT.equals(variants) ? VARIANTS_EXACT : VARIANTS_ANY,
            digest,
            optString(o, "image_url", null),
            Collections.unmodifiableList(items));
    }

    public String variantsFor(GearItem item)
    {
        return item != null && item.variants != null ? item.variants : variants;
    }

    public static String buildLabel(String build)
    {
        if ("main".equals(build)) return "Max/Med";
        if ("zerker".equals(build)) return "Zerker";
        if ("pure".equals(build)) return "1 Def Pure";
        return build;
    }

    public static String buildFromText(String text)
    {
        String t = plain(text);
        if (t.contains("max/med") || t.contains("max-med")) return "main";
        if (t.contains("zerker")) return "zerker";
        if (t.contains("1 def pure") || t.contains("1 def")) return "pure";
        return null;
    }

    public static String bookLabel(String key)
    {
        if (key == null) return null;
        switch (key)
        {
            case "standard": return "Standard";
            case "ancient": return "Ancient Magicks";
            case "lunar": return "Lunar";
            case "arceuus": return "Arceuus";
            default: return key;
        }
    }

    public static String bookOfText(String text)
    {
        String t = plain(text);
        if (t.contains("ancient")) return "ancient";
        if (t.contains("lunar")) return "lunar";
        if (t.contains("arceuus")) return "arceuus";
        if (t.contains("standard") || t.contains("normal") || t.contains("modern")) return "standard";
        return null;
    }

    public static String bookOfVarbit(int value)
    {
        return value >= 0 && value < SPELLBOOKS.size() ? SPELLBOOKS.get(value) : null;
    }

    public static String plain(String text)
    {
        if (text == null) return "";
        return text.replaceAll("<[^>]*>", "").replace(' ', ' ').trim().toLowerCase(Locale.ROOT);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import lombok.*;

@RequiredArgsConstructor
public final class GearTracker implements TournamentEventListener
{
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class GearEvent
    {
        public final String tournamentId;
        public final GearSet set;
        public final boolean arena;
        public final boolean running;
        public final long checkUntilS;
        public final int checkRound;

        public boolean prepOpen(long nowEpochS)
        {
            return checkUntilS > nowEpochS;
        }

        boolean sameAs(GearEvent o)
        {
            return o != null && tournamentId.equals(o.tournamentId) && set == o.set && arena == o.arena && running == o.running
                && checkUntilS == o.checkUntilS && checkRound == o.checkRound;
        }
    }

    @RequiredArgsConstructor
    private static final class Entry
    {
        final String id;
        GearSet set;
        String location;
        long startsAt;
        boolean registered;
        boolean running;
        long checkUntil;
        int checkRound;
    }

    private final Runnable requestStatus;
    private final Map<String, Entry> entries = new LinkedHashMap<>();
    private volatile GearEvent current;

    public GearEvent current()
    {
        return current;
    }

    // ---------------------------------------------------------------- listener (EDT)

    @Override
    public void onTournamentList(List<Tourney> tournaments)
    {
        if (tournaments == null) return;
        for (Tourney t : tournaments)
        {
            if (t == null) continue;
            Entry e = entries.get(t.tournamentId);
            if (t.gearSet == null)
            {
                if (e != null && e.set != null) entries.remove(t.tournamentId);
                continue;
            }
            e = learn(t);
            if (t.myStatus != null) e.registered = t.amRegistered();
        }
        publish();
    }

    @Override
    public void onRegistered(Tourney tournament, String regStatus)
    {
        if (tournament == null) return;
        Entry e = tournament.gearSet != null ? learn(tournament) : entries.get(tournament.tournamentId);
        if (e != null) e.registered = "registered".equals(regStatus);
        publish();
    }

    @Override
    public void onWithdrawn(String tournamentId)
    {
        Entry e = tournamentId == null ? null : entries.get(tournamentId);
        if (e != null) e.registered = false;
        publish();
    }

    @Override
    public void onTournamentState(List<Tourney> registrations, LiveTourney active)
    {
        Set<String> mine = new HashSet<>();
        if (registrations != null)
        {
            for (Tourney r : registrations)
            {
                if (r == null) continue;
                if (r.gearSet != null) learn(r);
                if (r.amRegistered()) mine.add(r.tournamentId);
            }
        }
        boolean activeRunning = active != null && active.isRunning();
        if (activeRunning) mine.add(active.tournamentId);
        for (Entry e : entries.values())
        {
            e.registered = mine.contains(e.id);
            e.running = false;
        }
        if (activeRunning)
        {
            Entry e = entries.get(active.tournamentId);
            if (e == null && active.gearSet != null)
            {
                e = new Entry(active.tournamentId);
                entries.put(e.id, e);
            }
            if (e != null)
            {
                e.running = true;
                e.registered = true;
                if (active.gearSet != null) e.set = active.gearSet;
                if (active.location != null) e.location = active.location;
                if (active.gearDeadline > 0) e.checkUntil = active.gearDeadline;
            }
        }
        publish();
    }

    @Override
    public void onStandings(TourneyBoard standings)
    {
        if (standings == null) return;
        Entry e = entries.get(standings.tournamentId);
        if (e != null && standings.gearDeadline > 0)
        {
            e.checkUntil = standings.gearDeadline;
            publish();
        }
    }

    @Override
    public void onMatchAssigned(MatchSeries series)
    {
        if (series == null) return;
        Entry e = entries.get(series.tournamentId);
        if (e == null) return;
        e.checkUntil = 0L;
        e.running = true;
        publish();
    }

    @Override
    public void onGearCheck(String tournamentId, int round, long untilEpochS)
    {
        if (tournamentId == null || tournamentId.isEmpty()) return;
        Entry e = entries.get(tournamentId);
        if (e == null)
        {
            e = new Entry(tournamentId);
            entries.put(tournamentId, e);
        }
        e.checkUntil = untilEpochS;
        e.checkRound = round;
        if (e.set == null) requestStatus.run();
        publish();
    }

    @Override
    public void onRemoved(String tournamentId, String status, String reason, int round)
    {
        forget(tournamentId);
    }

    @Override
    public void onCancelled(String tournamentId, String reason)
    {
        forget(tournamentId);
    }

    @Override
    public void onFinished(String tournamentId, JsonObject winners, List<StandingsRow> standings)
    {
        forget(tournamentId);
    }

    private Entry learn(Tourney t)
    {
        Entry e = entries.computeIfAbsent(t.tournamentId, Entry::new);
        if (t.gearSet != null) e.set = t.gearSet;
        if (t.location != null) e.location = t.location;
        if (t.startsAt > 0) e.startsAt = t.startsAt;
        return e;
    }

    private void forget(String tournamentId)
    {
        if (tournamentId == null || tournamentId.isEmpty()) return;
        if (entries.remove(tournamentId) != null) publish();
    }

    private void publish()
    {
        Entry best = null;
        for (Entry e : entries.values())
        {
            if (e.set == null || !e.registered) continue;
            if (best == null || better(e, best)) best = e;
        }
        GearEvent next = best == null ? null : new GearEvent(best.id, best.set, isArena(best.location), best.running, best.checkUntil,
            best.checkRound);
        GearEvent now = current;
        if (next == null ? now != null : !next.sameAs(now)) current = next;
    }

    private static boolean better(Entry a, Entry b)
    {
        if (a.running != b.running) return a.running;
        long sa = a.startsAt > 0 ? a.startsAt : Long.MAX_VALUE;
        long sb = b.startsAt > 0 ? b.startsAt : Long.MAX_VALUE;
        if (sa != sb) return sa < sb;
        return a.id.compareTo(b.id) < 0;
    }

    static boolean isArena(String location)
    {
        return location == null || location.trim().isEmpty() || location.toLowerCase(Locale.ROOT).contains("arena");
    }
}

package com.pvp.leaderboard.tournament;

public interface KitSource
{
    GearKit kit(GearSet set, boolean arena);

    String buildInUse(boolean arena);

    boolean frozen(boolean arena);

    boolean atArena();
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

public final class LiveTourney
{
    public final String tournamentId;
    public final String name;
    public final String status;
    public final int round;
    public final int rounds;
    public final int etaS;
    public final long breakUntil;
    /** {@code null} on a bye or between rounds. */
    public final MatchSeries series;
    public final boolean bye;
    public final List<StandingsRow> standings;
    /** -1 when unknown. */
    public final int myRank;
    public final GearSet gearSet;
    public final int gearPrepSec;
    public final long gearDeadline;
    public final String location;

    private LiveTourney(JsonObject o, String id)
    {
        tournamentId = id;
        name = optString(o, "name", id);
        status = optString(o, "status", "running");
        round = optInt(o, "round", 0);
        rounds = optInt(o, "rounds", 0);
        etaS = optInt(o, "eta_s", -1);
        breakUntil = optLong(o, "break_until", 0L);
        series = MatchSeries.fromJson(optObject(o, "series"), id, optLong(o, "deadline_at", 0L));
        bye = optBool(o, "bye", false);
        standings = StandingsRow.fromArray(optArray(o, "standings"), StandingsRow.tierLabels(o));
        myRank = optInt(o, "my_rank", -1);
        gearSet = GearSet.fromJson(o.get("gear_set"));
        gearPrepSec = Math.max(0, optInt(o, "gear_prep_sec", 0));
        gearDeadline = Math.max(0L, optLong(o, "gear_check_until", 0L));
        location = Tourney.textOf(o, "location");
    }

    /** {@code null} for a null / non-object / id-less payload (= not in a running tournament). */
    public static LiveTourney fromJson(JsonObject o)
    {
        if (o == null) return null;
        String id = optString(o, "tournament_id");
        return id.isEmpty() ? null : new LiveTourney(o, id);
    }

    public boolean isRunning()
    {
        return "running".equals(status);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

/**
 * The local player's series in the current round (Plan 10 Part C):
 * {@code tournament/match_assigned} and {@code tournament/state.active.series}
 * both parse into this. The opponent is identified by name / acct_sha /
 * player_id only.
 */
public final class MatchSeries
{
    public static final String UNKNOWN_OPPONENT = "your opponent";

    public final String tournamentId;
    public final String seriesId;
    public final int round;
    /** open | decided | dnf | void | bye. */
    public final String status;
    public final String opponentName;
    public final String world;
    public final String meetingPlace;
    /** Round deadline (epoch seconds), 0 when unknown. */
    public final long deadlineAt;
    public final String category;
    public final String style;
    /** Every name the opponent is logged in with ({@code opponent_names}); empty when the push carries none. */
    public final List<String> opponentNames;
    /** The opponent's region ({@code opponent_region}, "na-e"); {@code null} when the push carries none. */
    public final String opponentRegion;

    private MatchSeries(JsonObject o, String sid, String tid, long deadline)
    {
        tournamentId = optString(o, "tournament_id", tid);
        seriesId = sid;
        round = optInt(o, "round", 0);
        status = optString(o, "status", "open");
        opponentName = optString(o, "opponent_name", UNKNOWN_OPPONENT);
        world = optString(o, "world", null);
        meetingPlace = optString(o, "meeting_place", null);
        deadlineAt = optLong(o, "deadline_at", deadline);
        category = optString(o, "category", null);
        style = optString(o, "style", null);
        opponentNames = namesOf(o, "opponent_names");
        opponentRegion = Tourney.textOf(o, "opponent_region");
    }

    /** The names the outline matches: {@link #opponentNames}, else the one {@link #opponentName} when named. */
    public List<String> outlineNames()
    {
        if (!opponentNames.isEmpty()) return opponentNames;
        return hasNamedOpponent() ? Collections.singletonList(opponentName) : Collections.<String>emptyList();
    }

    /** The string entries of {@code key}'s array, trimmed, blanks and non-strings skipped; empty when it is not an array. */
    public static List<String> namesOf(JsonObject o, String key)
    {
        List<String> out = new ArrayList<>();
        for (JsonElement e : optArray(o, key))
        {
            String s = str(e);
            if (s != null && !s.trim().isEmpty()) out.add(s.trim());
        }
        return out;
    }

    /** {@code "W370"} for {@code 370} / {@code "370"} / {@code " w370 "}; {@code null} for nothing. */
    public static String worldLabelOf(String world)
    {
        if (world == null) return null;
        String w = world.trim();
        if (w.isEmpty()) return null;
        return w.toUpperCase().startsWith("W") ? "W" + w.substring(1) : "W" + w;
    }

    /** {@code null} without a {@code series_id}. {@code tournamentId} /
     *  {@code deadlineAt} come from the object itself when present
     *  ({@code match_assigned}) or from the enclosing state otherwise. */
    public static MatchSeries fromJson(JsonObject o, String tournamentId, long deadlineAt)
    {
        if (o == null) return null;
        String sid = optString(o, "series_id");
        return sid.isEmpty() ? null : new MatchSeries(o, sid, tournamentId, deadlineAt);
    }

    public boolean isOpen()
    {
        return "open".equals(status);
    }

    /** {@code "W370"} for {@code 370} / {@code "370"} / {@code "W370"}; {@code "?"} when unknown. */
    public String worldLabel()
    {
        String label = worldLabelOf(world);
        return label == null ? "?" : label;
    }

    public boolean hasNamedOpponent()
    {
        return !opponentName.trim().isEmpty() && !UNKNOWN_OPPONENT.equals(opponentName);
    }

    public int worldNumber()
    {
        if (world == null) return 0;
        String w = world.trim();
        if (w.startsWith("W") || w.startsWith("w")) w = w.substring(1).trim();
        try
        {
            int n = Integer.parseInt(w);
            return n > 0 ? n : 0;
        }
        catch (NumberFormatException e)
        {
            return 0;
        }
    }
}

package com.pvp.leaderboard.tournament;

import lombok.*;
import com.google.gson.*;
import com.pvp.leaderboard.util.*;
import java.util.*;
import javax.inject.*;

@Singleton
public class OppTracker implements TournamentEventListener
{
    private volatile String activeTournamentId;
    @Getter private volatile MatchSeries activeSeries;
    /** The canonical keys of every name the outline matches; {@code null} while nothing is highlighted. The outline
     *  ends on the first hit on the opponent, the match's clear, the next round's assignment or bye, the end of the
     *  event, a state that is not running and a logout - never by time: a push's {@code until} / {@code deadline_at}
     *  is not applied. */
    private volatile Set<String> oppKeys;
    private volatile String foughtKey;
    private volatile String foughtId;

    @Inject
    public OppTracker()
    {
    }

    /** {@code true} while the player is in a RUNNING tournament (not merely registered for an upcoming one). */
    public boolean isPlaying()
    {
        return activeTournamentId != null;
    }

    /** The canonical keys of every name the outline matches, or {@code null} while there is nothing to outline. */
    public Set<String> getHighlightedOpponentKeys()
    {
        Set<String> keys = oppKeys;
        return keys == null || fought(keys) ? null : keys;
    }

    public boolean isAwaiting()
    {
        Set<String> wanted = oppKeys;
        return wanted != null && !fought(wanted);
    }

    private boolean fought(Set<String> keys)
    {
        String fought = foughtKey;
        return fought != null && keys != null && keys.contains(fought);
    }

    public void onCombatWith(String playerName, int localWorld)
    {
        Set<String> wanted = oppKeys;
        if (wanted == null || fought(wanted)) return;
        String key = NameUtils.canonicalKey(playerName);
        if (!wanted.contains(key)) return;
        MatchSeries s = activeSeries;
        if (!onAssignedWorld(s, localWorld)) return;
        foughtId = s == null ? null : s.seriesId;
        foughtKey = key;
    }

    private static boolean onAssignedWorld(MatchSeries s, int localWorld)
    {
        int assigned = s == null ? 0 : s.worldNumber();
        return assigned == 0 || assigned == localWorld;
    }

    public void clear()
    {
        activeTournamentId = null;
        activeSeries = null;
        oppKeys = null;
    }

    private void endSession()
    {
        clear();
        forgetCombat();
    }

    private void clearIf(String tournamentId)
    {
        String active = activeTournamentId;
        if (active == null) return;
        if (tournamentId.isEmpty() || tournamentId.equals(active)) endSession();
    }

    private static Set<String> keysOf(List<String> names)
    {
        Set<String> keys = new LinkedHashSet<>();
        for (String n : names)
        {
            String key = NameUtils.canonicalKey(n);
            if (!key.isEmpty()) keys.add(key);
        }
        return keys;
    }

    private void assign(String seriesId, Set<String> keys)
    {
        boolean otherPairing = isOtherPairing(seriesId, keys);
        oppKeys = keys.isEmpty() ? null : keys;
        if (otherPairing) forgetCombat();
        else if (foughtKey != null && foughtId == null && seriesId != null) foughtId = seriesId;
    }

    private boolean isOtherPairing(String seriesId, Set<String> opponentKeys)
    {
        String fought = foughtKey;
        if (fought == null) return false;
        String foughtSeries = foughtId;
        boolean otherSeries = foughtSeries != null && seriesId != null && !foughtSeries.equals(seriesId);
        boolean otherOpponent = !opponentKeys.isEmpty() && !opponentKeys.contains(fought);
        return otherSeries || otherOpponent;
    }

    private void forgetCombat()
    {
        foughtKey = null;
        foughtId = null;
    }

    // ---- listener ----
    @Override
    public void onTournamentState(List<Tourney> registrations, LiveTourney active)
    {
        if (active == null || !active.isRunning())
        {
            endSession();
            return;
        }
        activeTournamentId = active.tournamentId;
        MatchSeries s = active.series != null && active.series.isOpen() ? active.series : null;
        activeSeries = s;
        if (s == null) oppKeys = null;
        else assign(s.seriesId, keysOf(s.outlineNames()));
        if (active.bye) forgetCombat();
    }

    @Override
    public void onMatchAssigned(MatchSeries series)
    {
        activeTournamentId = series.tournamentId;
        activeSeries = series;
        assign(series.seriesId, keysOf(series.outlineNames()));
    }

    /** The push's {@code until} is not applied: the outline ends on the match's events, not by time. */
    @Override
    public void onOpponentHighlight(String tournamentId, String opponentName, List<String> opponentNames)
    {
        Set<String> keys = keysOf(opponentNames);
        if (keys.isEmpty()) keys = keysOf(Collections.singletonList(opponentName));
        if (keys.isEmpty()) return;
        if (!tournamentId.isEmpty()) activeTournamentId = tournamentId;
        assign(null, keys);
    }

    @Override
    public void onOpponentHighlightClear(String tournamentId, String seriesId)
    {
        oppKeys = null;
        MatchSeries s = activeSeries;
        if (s != null && (seriesId == null || seriesId.isEmpty() || seriesId.equals(s.seriesId))) activeSeries = null;
    }

    @Override
    public void onBye(String tournamentId, int round)
    {
        if (!tournamentId.isEmpty()) activeTournamentId = tournamentId;
        activeSeries = null;
        oppKeys = null;
        forgetCombat();
    }

    @Override
    public void onRemoved(String tournamentId, String status, String reason, int round)
    {
        clearIf(tournamentId);
    }

    @Override
    public void onCancelled(String tournamentId, String reason)
    {
        clearIf(tournamentId);
    }

    @Override
    public void onFinished(String tournamentId, JsonObject winners, List<StandingsRow> standings)
    {
        clearIf(tournamentId);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

public final class StandingsRow
{
    public final int rank;
    public final String displayName;
    public final double points;
    public final int wins, losses, draws, byes;
    public final String status;
    /** The tier's label from the payload's {@code tier_labels} ("Adamant 3"), {@code null} when none applies. */
    public final String rankLabel;
    /** The prize in whole gp ({@code prize_gp}), -1 when the row has none. */
    public final long prizeGp;
    /** The prize came from the random draw: {@code prize_random} is a JSON {@code true}. */
    public final boolean prizeRandom;
    /** {@code round_done} is {@code true}: the player has a result in the current round. */
    public final boolean roundDone;

    private StandingsRow(JsonObject o, int fallbackRank, List<String> tierLabels)
    {
        String acct = optString(o, "acct_sha");
        int tier = optInt(o, "tier", -1);
        String label = tier >= 0 && tier < tierLabels.size() ? tierLabels.get(tier) : null;
        rank = optInt(o, "rank", fallbackRank);
        displayName = optString(o, "display_name", acct.length() >= 8 ? acct.substring(0, 8) : acct);
        points = optDouble(o, "points", 0.0);
        wins = Math.max(0, optInt(o, "wins", 0));
        losses = Math.max(0, optInt(o, "losses", 0));
        draws = Math.max(0, optInt(o, "draws", 0));
        byes = Math.max(0, optInt(o, "byes", 0));
        status = optString(o, "status", "active");
        rankLabel = label == null || label.trim().isEmpty() ? null : label.trim();
        prizeGp = optWhole(o, "prize_gp");
        prizeRandom = new JsonPrimitive(true).equals(o.get("prize_random"));
        roundDone = optBool(o, "round_done", false);
    }

    /** The payload's {@code tier_labels} in order, a non-string entry as {@code null}; empty when absent. */
    public static List<String> tierLabels(JsonObject payload)
    {
        List<String> out = new ArrayList<>();
        for (JsonElement e : optArray(payload, "tier_labels"))
        {
            out.add(str(e));
        }
        return out;
    }

    /** Rows in wire order with their labels from the payload's {@code tier_labels}; non-object entries are skipped. Never null. */
    public static List<StandingsRow> fromArray(JsonArray arr, List<String> tierLabels)
    {
        List<StandingsRow> out = new ArrayList<>(arr.size());
        int i = 0;
        for (JsonElement e : arr)
        {
            i++;
            if (e == null || !e.isJsonObject()) continue;
            out.add(new StandingsRow(e.getAsJsonObject(), i, tierLabels));
        }
        return out;
    }

    /** Any status but {@code active}. */
    public boolean removed()
    {
        return !"active".equals(status);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;

/**
 * Server-push callbacks for the Swiss tournaments (Plan 10 Part C / F.3),
 * registered with the {@link TourneySvc}. Every callback is delivered
 * on the Swing EDT (the {@code TourneySvc} marshals), so
 * panels may touch Swing directly and the session tracker / overlay
 * supplier read plain volatile fields. All methods are {@code default}
 * no-ops. Mirrors WEBSOCKET_PROTOCOL.md § 6.3 (server → client).
 */
public interface TournamentEventListener
{
    /** {@code tournament/list_response}. */
    default void onTournamentList(List<Tourney> tournaments) {}

    /** {@code tournament/registered} — the event + the caller's registration status. */
    default void onRegistered(Tourney tournament, String regStatus) {}

    /** {@code tournament/withdrawn}. */
    default void onWithdrawn(String tournamentId) {}

    /** {@code tournament/state} — the caller's registrations + the running
     *  tournament they are part of ({@code null} when none). */
    default void onTournamentState(List<Tourney> registrations, LiveTourney active) {}

    /** {@code tournament/standings} — after subscribe and on every change. */
    default void onStandings(TourneyBoard standings) {}

    /** {@code tournament/match_assigned} — a round opened with an opponent. */
    default void onMatchAssigned(MatchSeries series) {}

    /** {@code tournament/opponent_highlight} with every name the opponent is logged in with
     *  ({@code opponent_names}; the one name when the push carries no list). */
    default void onOpponentHighlight(String tournamentId, String opponentName, List<String> opponentNames) {}

    /** {@code tournament/opponent_highlight_clear}. */
    default void onOpponentHighlightClear(String tournamentId, String seriesId) {}

    /** {@code tournament/bye}. */
    default void onBye(String tournamentId, int round) {}

    default void onRoundEndCheck(String tournamentId, int round, String opponentName, long respondByS, String message) {}

    /** {@code tournament/removed} — dnf / dq / kicked / withdrawn / dropped_unpaid. */
    default void onRemoved(String tournamentId, String status, String reason, int round) {}

    /** {@code tournament/cancelled}. */
    default void onCancelled(String tournamentId, String reason) {}

    /** {@code tournament/finished} — winners {@code {top[], random[], seed}} + the final standings rows. */
    default void onFinished(String tournamentId, JsonObject winners, List<StandingsRow> standings) {}

    /** {@code tournament/problem_ack}. */
    default void onProblemAck() {}

    /** {@code error/tournament} — stable code + message; {@code cmd} echoes the rejected cmd. */
    default void onTournamentError(String code, String message, String cmd) {}

    /** Not a push: the socket (re)opened (set 7). The transport tells its
     *  listeners from the manager's connect hook, on the EDT, so a panel
     *  that asked for the list while the socket was down asks again. */
    default void onConnected() {}

    default void onGearCheck(String tournamentId, int round, long untilEpochS) {}

    default void onGearAck(String tournamentId, boolean ok) {}

    /** {@code tournament/no_show_recorded}: the no-show report counts at {@code effective_at}. */
    default void onNoShowRecorded(String tournamentId, String seriesId, long effectiveAtS) {}
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

public final class Tourney
{
    public final String tournamentId;
    public final String name;
    /** registration | running | finished | cancelled. */
    public final String status;
    public final String format;
    /** nh / veng / multi / dmm. */
    public final String category;
    /** main / zerker / pure. */
    public final String style;
    public final int maxPlayers;
    public final long regClosesAt;
    public final long startsAt;
    public final int rounds;
    public final int currentRound;
    public final int regCount;
    /** registered | withdrawn | dnf | dq | kicked | dropped_unpaid, or {@code null} when not registered. */
    public final String myStatus;
    public final String rulesUrl;
    public final long buyInGp;
    public final String prizeMode;
    public final int prizeTopX;
    public final int prizeRandomY;
    public final long prizePoolGp;
    public final boolean pluginRequired;
    public final boolean lateJoins;
    public final int minGames;
    /** The host ({@code creator_name}); {@code null} when the row does not carry it. */
    public final String creatorName;
    /** {@code rank_limits} in bucket order (the order Discord prints them); empty when the event has none. */
    public final List<RankLimit> rankLimits;
    /** The optional {@code rules} block; {@code null} = absent or junk, so the plugin uses {@link #rulesUrl}. */
    public final TourneyRules rules;
    public final GearSet gearSet;
    public final int gearPrepSec;
    public final String location;
    public final boolean roundsAuto;
    /** Where a registered player meets when round 1 opens ({@code meeting.world}, "W578"); {@code null} when the entry has none. */
    public final String meetingWorld;
    /** {@code meeting.place}; {@code null} when the entry has none. */
    public final String meetingPlace;
    /** {@code ended_at} of a finished event (the history route), 0 when absent. */
    public final long endedAt;

    /** One bucket's entry of {@code rank_limits}: rank indices (0 = Bronze 3 … 24 = 3rd Age), {@code -1} = that bound is not set. */
    public static final class RankLimit
    {
        public final String bucket;
        public final int minIdx;
        public final int maxIdx;

        public RankLimit(String bucket, int minIdx, int maxIdx)
        {
            this.bucket = bucket;
            this.minIdx = minIdx;
            this.maxIdx = maxIdx;
        }
    }

    private Tourney(JsonObject o, String id)
    {
        tournamentId = id;
        name = optString(o, "name", id);
        status = optString(o, "status");
        format = optString(o, "format", "swiss");
        category = optString(o, "category");
        style = optString(o, "style", "main");
        maxPlayers = optInt(o, "max_players", 0);
        regClosesAt = optLong(o, "registration_closes_at", 0L);
        startsAt = optLong(o, "starts_at", 0L);
        rounds = optInt(o, "rounds", 0);
        currentRound = optInt(o, "current_round", 0);
        regCount = optInt(o, "registered_count", 0);
        myStatus = optString(o, "my_status", null);
        rulesUrl = optString(o, "rules_url", null);
        buyInGp = optLong(o, "buy_in_gp", 0L);
        prizeMode = optString(o, "prize_mode", "top_x");
        prizeTopX = optInt(o, "prize_top_x", 1);
        prizeRandomY = optInt(o, "prize_random_y", 0);
        prizePoolGp = optLong(o, "prize_pool_gp", 0L);
        pluginRequired = optBool(o, "plugin_required", true);
        lateJoins = optBool(o, "mid_event_joins", false);
        minGames = optInt(o, "min_games", 0);
        creatorName = optString(o, "creator_name", null);
        rankLimits = limitsFrom(o);
        rules = TourneyRules.fromJson(o.get("rules"));
        gearSet = GearSet.fromJson(o.get("gear_set"));
        gearPrepSec = Math.max(0, optInt(o, "gear_prep_sec", 0));
        location = textOf(o, "location");
        roundsAuto = optBool(o, "rounds_auto", false);
        meetingWorld = meetingWorld(o);
        meetingPlace = meetingPlace(o);
        endedAt = optLong(o, "ended_at", 0L);
    }

    /** {@code meeting.world} of an object, as "W578"; {@code null} without one. */
    static String meetingWorld(JsonObject o)
    {
        JsonObject meeting = optObject(o, "meeting");
        return meeting == null ? null : MatchSeries.worldLabelOf(optString(meeting, "world", null));
    }

    /** {@code meeting.place} of an object; {@code null} without one. */
    static String meetingPlace(JsonObject o)
    {
        JsonObject meeting = optObject(o, "meeting");
        return meeting == null ? null : textOf(meeting, "place");
    }

    /** {@code null} when the object has no {@code tournament_id}. */
    public static Tourney fromJson(JsonObject o)
    {
        if (o == null) return null;
        String id = optString(o, "tournament_id");
        return id.isEmpty() ? null : new Tourney(o, id);
    }

    static String textOf(JsonObject o, String key)
    {
        String s = str(o == null ? null : o.get(key));
        return s == null || s.trim().isEmpty() ? null : s.trim();
    }

    /** {@code rank_limits: {<bucket>: {min_idx?, max_idx?}}} → one
     *  {@link RankLimit} per bucket that carries at least one numeric bound,
     *  in bucket order (what {@code discord_tournament_messages._rank_limit_parts}
     *  prints). Junk — not an object, a non-object bucket, a non-numeric
     *  bound — is skipped, never thrown on. */
    static List<RankLimit> limitsFrom(JsonObject o)
    {
        JsonObject limits = optObject(o, "rank_limits");
        if (limits == null) return Collections.emptyList();
        List<String> buckets = new ArrayList<>(limits.keySet());
        Collections.sort(buckets);
        List<RankLimit> out = new ArrayList<>();
        for (String bucket : buckets)
        {
            JsonObject entry = optObject(limits, bucket);
            if (entry == null) continue;
            Integer lo = optInteger(entry, "min_idx");
            Integer hi = optInteger(entry, "max_idx");
            if (lo == null && hi == null) continue;
            out.add(new RankLimit(bucket.trim().toLowerCase(Locale.ROOT), lo == null ? -1 : lo, hi == null ? -1 : hi));
        }
        return Collections.unmodifiableList(out);
    }

    /** The events of a list in its order; non-objects and entries without an id are skipped. */
    public static List<Tourney> listOf(JsonArray arr)
    {
        List<Tourney> out = new ArrayList<>();
        for (JsonElement e : arr)
        {
            if (e == null || !e.isJsonObject()) continue;
            Tourney t = fromJson(e.getAsJsonObject());
            if (t != null) out.add(t);
        }
        return out;
    }

    public boolean isRegOpen()
    {
        return "registration".equals(status);
    }

    public boolean isRunning()
    {
        return "running".equals(status);
    }

    public boolean amRegistered()
    {
        return "registered".equals(myStatus);
    }

    /** {@code "NH Main"} — the category + build the way the lobby chips spell them. */
    public String styleLabel()
    {
        return categoryLabel() + " " + buildLabel();
    }

    /** {@code "NH"} / {@code "Veng"} / {@code "Multi"} / {@code "DMM"}, {@code "?"} when unknown. */
    public String categoryLabel()
    {
        return categoryLabel(category);
    }

    /** {@code "Main"} / {@code "Zerker"} / {@code "Pure"} ({@code "Main"} when unset). */
    public String buildLabel()
    {
        return style.isEmpty() ? "Main" : Character.toUpperCase(style.charAt(0)) + style.substring(1);
    }

    /** The bucket label the Discord messages use ({@code STYLE_LABELS}): nh → NH, dmm → DMM, else capitalised; {@code "?"} for none. */
    public static String categoryLabel(String category)
    {
        return "nh".equals(category) ? "NH" : "dmm".equals(category) ? "DMM" : category.isEmpty() ? "?" : Character.toUpperCase(category.charAt(0)) + category.substring(1);
    }

    @Override
    public String toString()
    {
        return "TournamentSummary{" + tournamentId + " " + name + " " + status + " my=" + myStatus + "}";
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

/**
 * A {@code tournament/standings} push (Plan 10 Part C / C.8): the live
 * leaderboard of one tournament plus the round clock. Pushed at once
 * after {@code tournament/subscribe} and on every score change while
 * subscribed; the same payload feeds the website (IoT) and Discord.
 */
public final class TourneyBoard
{
    public final String tournamentId;
    public final String status;
    public final int round;
    public final int rounds;
    /** Seconds left in the round, -1 when no round is open. */
    public final int etaS;
    /** Epoch seconds, 0 when not on a break. */
    public final long breakUntil;
    public final int extended;
    public final List<StandingsRow> rows;
    public final long gearDeadline;

    private TourneyBoard(JsonObject o, String id)
    {
        tournamentId = id;
        status = optString(o, "status");
        round = optInt(o, "round", 0);
        rounds = optInt(o, "rounds", 0);
        etaS = optInt(o, "eta_s", -1);
        breakUntil = optLong(o, "break_until", 0L);
        extended = optInt(o, "extended", 0);
        rows = StandingsRow.fromArray(optArray(o, "standings"), StandingsRow.tierLabels(o));
        gearDeadline = Math.max(0L, optLong(o, "gear_check_until", 0L));
    }

    /** {@code null} without a {@code tournament_id}. */
    public static TourneyBoard fromJson(JsonObject o)
    {
        if (o == null) return null;
        String id = optString(o, "tournament_id");
        return id.isEmpty() ? null : new TourneyBoard(o, id);
    }

    public boolean isFinished()
    {
        return "finished".equals(status);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import java.util.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

/**
 * The optional {@code rules} block of a {@code tournament/list_response}
 * entry (plugin set 6, operator request 2026-09-22):
 * <pre>{"version": 1, "sections": [{"heading": "...", "lines": ["...", "..."]}, ...]}</pre>
 * rendered by the in-panel Rules dialog as headings + wrapped plain lines.
 * The field is additive — an older backend sends none and the plugin falls
 * back to the entry's {@code rules_url} — so it is parsed defensively:
 * anything that is not an object with at least one usable section reads as
 * <b>absent</b> ({@code null}); a section needs a string heading or at
 * least one string line; non-string lines are skipped, never printed.
 */
public final class TourneyRules
{
    public final int version;
    /** In wire order, never empty. */
    public final List<Section> sections;

    public static final class Section
    {
        /** {@code ""} when the section has no heading. */
        public final String heading;
        public final List<String> lines;

        public Section(String heading, List<String> lines)
        {
            this.heading = heading;
            this.lines = lines;
        }
    }

    public TourneyRules(int version, List<Section> sections)
    {
        this.version = version;
        this.sections = sections;
    }

    /** {@code null} when {@code e} is missing, not an object, has no
     *  {@code sections} array, or no section survives the checks above. */
    public static TourneyRules fromJson(JsonElement e)
    {
        if (e == null || !e.isJsonObject()) return null;
        JsonObject o = e.getAsJsonObject();
        List<Section> out = new ArrayList<>();
        for (JsonElement s : optArray(o, "sections"))
        {
            if (s == null || !s.isJsonObject()) continue;
            JsonObject so = s.getAsJsonObject();
            String heading = str(so.get("heading"));
            heading = heading == null ? "" : heading.trim();
            List<String> lines = new ArrayList<>();
            for (JsonElement l : optArray(so, "lines"))
            {
                String line = str(l);
                if (line != null && !line.isEmpty()) lines.add(line);
            }
            if (heading.isEmpty() && lines.isEmpty()) continue;
            out.add(new Section(heading, lines));
        }
        if (out.isEmpty()) return null;
        return new TourneyRules(optInt(o, "version", 1), out);
    }
}

package com.pvp.leaderboard.tournament;

import com.google.gson.*;
import com.pvp.leaderboard.service.socket.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import javax.inject.*;
import javax.swing.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

@Singleton
public class TourneySvc
{
    private final SocketMgr socket;
    private final SocketBus bus;
    private final CopyOnWriteArrayList<TournamentEventListener> listeners = new CopyOnWriteArrayList<>();
    private volatile boolean started = false;
    /** The tournament whose standings the sub-tab is watching (re-subscribed on reconnect). */
    private volatile String subscribedTo;

    @Inject
    public TourneySvc(SocketMgr socket, SocketBus bus)
    {
        this.socket = socket;
        this.bus = bus;
    }

    public void addListener(TournamentEventListener listener)
    {
        listeners.addIfAbsent(listener);
    }

    public void removeListener(TournamentEventListener listener)
    {
        listeners.remove(listener);
    }

    public synchronized void start()
    {
        if (started) return;
        started = true;
        bus.register("tournament/list_response", this::handleList);
        bus.register("tournament/registered", this::handleRegistered);
        bus.register("tournament/withdrawn", this::handleWithdrawn);
        bus.register("tournament/state", this::handleState);
        bus.register("tournament/standings", this::handleStandings);
        bus.register("tournament/match_assigned", this::handleMatchAssigned);
        bus.register("tournament/opponent_highlight", this::handleHighlight);
        bus.register("tournament/opponent_highlight_clear", this::handleHighlightClear);
        bus.register("tournament/bye", this::handleBye);
        bus.register("tournament/round_end_check", this::handleRoundEndCheck);
        bus.register("tournament/removed", this::handleRemoved);
        bus.register("tournament/cancelled", this::handleCancelled);
        bus.register("tournament/finished", this::handleFinished);
        bus.register("tournament/problem_ack", d -> fire(TournamentEventListener::onProblemAck));
        bus.register("tournament/gear_check", this::handleGearCheck);
        bus.register("tournament/gear_ack", this::handleGearAck);
        bus.register("tournament/no_show_recorded", this::handleNoShow);
        bus.register("error/tournament", this::handleError);
        socket.addResyncListener(this::onReconnect);
    }

    private void onReconnect()
    {
        status();
        String sub = subscribedTo;
        if (sub != null) subscribe(sub);
        // Set 7: the sub-tab re-asks for the list it could not send while
        // the socket was down (SocketMgr.send drops without a socket).
        fire(TournamentEventListener::onConnected);
    }

    /** {@code true} while the socket is open (set 7): the sub-tab waits
     *  with "Connecting…" instead of sending frames the manager would drop,
     *  and re-asks from {@link TournamentEventListener#onConnected()}. */
    public boolean isConnected()
    {
        return socket.isConnected();
    }

    // ---- outbound ----
    private static JsonObject withId(String tournamentId)
    {
        var d = new JsonObject();
        d.addProperty("tournament_id", tournamentId);
        return d;
    }

    private static String tid(JsonObject d)
    {
        return optString(d, "tournament_id");
    }

    private static boolean blank(String s)
    {
        return s == null || s.trim().isEmpty();
    }

    public void list()
    {
        socket.send("tournament/list", new JsonObject());
    }

    private static JsonArray caps()
    {
        var a = new JsonArray();
        a.add("gear1");
        return a;
    }

    public void register(String tournamentId, String region)
    {
        JsonObject d = withId(tournamentId);
        if (!blank(region)) d.addProperty("region", region);
        d.add("caps", caps());
        socket.send("tournament/register", d);
    }

    public void withdraw(String tournamentId)
    {
        socket.send("tournament/withdraw", withId(tournamentId));
    }

    public void status()
    {
        var d = new JsonObject();
        d.add("caps", caps());
        socket.send("tournament/status", d);
    }

    public void subscribe(String tournamentId)
    {
        subscribedTo = tournamentId;
        socket.send("tournament/subscribe", withId(tournamentId));
    }

    public void unsubscribe(String tournamentId)
    {
        if (tournamentId.equals(subscribedTo)) subscribedTo = null;
        socket.send("tournament/unsubscribe", withId(tournamentId));
    }

    private static JsonObject inSeries(String tournamentId, String seriesId)
    {
        JsonObject d = withId(tournamentId);
        d.addProperty("series_id", seriesId);
        return d;
    }

    public void inCombat(String tournamentId, String seriesId)
    {
        socket.send("tournament/in_combat", inSeries(tournamentId, seriesId));
    }

    public void noShow(String tournamentId, String seriesId)
    {
        socket.send("tournament/no_show", inSeries(tournamentId, seriesId));
    }

    /** {@code tournament/world}: the world the player is in while the series is open. */
    public void world(String tournamentId, String seriesId, int world)
    {
        JsonObject d = inSeries(tournamentId, seriesId);
        d.addProperty("world", world);
        socket.send("tournament/world", d);
    }

    /** {@code tournament/report_problem}: the text trimmed and cut to the 280 characters the server accepts
     *  (socket_protocol.PROBLEM_TEXT_MAX); blank text sends nothing. */
    public void reportProblem(String tournamentId, String text)
    {
        if (blank(text)) return;
        String trimmed = text.trim();
        if (trimmed.length() > 280) trimmed = trimmed.substring(0, 280);
        JsonObject d = withId(tournamentId);
        d.addProperty("text", trimmed);
        socket.send("tournament/report_problem", d);
    }

    private static void putVerdict(JsonObject d, GearDiff diff, boolean ok)
    {
        d.addProperty("ok", ok);
        d.addProperty("build_ok", diff.buildOk);
        d.addProperty("missing", diff.missing.size());
        d.addProperty("extra", diff.extra.size());
        d.addProperty("spellbook_ok", diff.spellbookOk);
        JsonArray triples = diff.wireDiff();
        if (triples.size() > 0) d.add("diff", triples);
    }

    public void gearStatus(String tournamentId, String digest, GearDiff diff, String source, boolean ok)
    {
        if (blank(tournamentId) || blank(digest) || diff == null) return;
        JsonObject d = withId(tournamentId);
        d.addProperty("digest", digest);
        putVerdict(d, diff, ok);
        d.addProperty("source", blank(source) ? GearKit.SOURCE_CONTAINERS : source);
        socket.send("tournament/gear_status", d);
    }

    // ---- inbound ----
    private void handleList(JsonObject d)
    {
        List<Tourney> rows = Tourney.listOf(optArray(d, "tournaments"));
        fire(l -> l.onTournamentList(rows));
    }

    private void handleRegistered(JsonObject d)
    {
        // the meeting rides beside the event on this push
        JsonObject o = optObject(d, "tournament");
        JsonObject meeting = optObject(d, "meeting");
        if (o != null && meeting != null && Tourney.meetingWorld(o) == null) o.add("meeting", meeting);
        Tourney t = Tourney.fromJson(o);
        if (t == null) return;
        String status = optString(optObject(d, "registration"), "status", "registered");
        fire(l -> l.onRegistered(t, status));
    }

    private void handleWithdrawn(JsonObject d)
    {
        String tid = tid(d);
        if (tid.isEmpty()) return;
        fire(l -> l.onWithdrawn(tid));
    }

    private void handleState(JsonObject d)
    {
        List<Tourney> regs = Tourney.listOf(optArray(d, "registrations"));
        JsonObject a = optObject(d, "active");
        LiveTourney active = LiveTourney.fromJson(a);
        fire(l -> l.onTournamentState(regs, active));
        JsonObject end = optObject(a, "round_end");
        if (active != null && end != null) roundEnd(active.tournamentId, end);
    }

    private void handleStandings(JsonObject d)
    {
        TourneyBoard s = TourneyBoard.fromJson(d);
        if (s == null) return;
        fire(l -> l.onStandings(s));
    }

    private void handleMatchAssigned(JsonObject d)
    {
        String tid = tid(d);
        MatchSeries s = MatchSeries.fromJson(d, tid, optLong(d, "deadline_at", 0L));
        if (s == null || tid.isEmpty())
        {
            return;
        }
        fire(l -> l.onMatchAssigned(s));
    }

    private void handleHighlight(JsonObject d)
    {
        String name = optString(d, "opponent_name");
        if (name.isEmpty()) return;
        String tid = tid(d);
        List<String> listed = MatchSeries.namesOf(d, "opponent_names");
        List<String> names = listed.isEmpty() ? Collections.singletonList(name) : listed;
        fire(l -> l.onOpponentHighlight(tid, name, names));
    }

    private void handleHighlightClear(JsonObject d)
    {
        String tid = tid(d);
        String sid = optString(d, "series_id", null);
        fire(l -> l.onOpponentHighlightClear(tid, sid));
    }

    private void handleBye(JsonObject d)
    {
        String tid = tid(d);
        int round = optInt(d, "round", 0);
        fire(l -> l.onBye(tid, round));
    }

    private void handleRoundEndCheck(JsonObject d)
    {
        String tid = tid(d);
        if (!tid.isEmpty() && !optString(d, "series_id").isEmpty()) roundEnd(tid, d);
    }

    /** {@code onRoundEndCheck} from a {@code round_end_check} push or a state's {@code active.round_end}. */
    private void roundEnd(String tid, JsonObject d)
    {
        int round = optInt(d, "round", 0);
        String opp = optString(d, "opponent_name", "your opponent");
        long respondBy = optLong(d, "respond_by", 0L);
        String message = Tourney.textOf(d, "message");
        fire(l -> l.onRoundEndCheck(tid, round, opp, respondBy, message));
    }

    private void handleRemoved(JsonObject d)
    {
        String tid = tid(d);
        String status = optString(d, "status", "removed");
        String reason = optString(d, "reason");
        int round = optInt(d, "round", 0);
        fire(l -> l.onRemoved(tid, status, reason, round));
    }

    private void handleCancelled(JsonObject d)
    {
        String tid = tid(d);
        String reason = optString(d, "reason");
        fire(l -> l.onCancelled(tid, reason));
    }

    private void handleFinished(JsonObject d)
    {
        String tid = tid(d);
        JsonObject winners = optObject(d, "winners");
        List<StandingsRow> rows = StandingsRow.fromArray(optArray(d, "standings"), StandingsRow.tierLabels(d));
        fire(l -> l.onFinished(tid, winners, rows));
    }

    private void handleGearCheck(JsonObject d)
    {
        String tid = tid(d);
        if (tid.isEmpty()) return;
        int round = optInt(d, "round", 0);
        long until = optLong(d, "until", 0L);
        fire(l -> l.onGearCheck(tid, round, until));
    }

    private void handleGearAck(JsonObject d)
    {
        String tid = tid(d);
        if (tid.isEmpty()) return;
        boolean ok = optBool(d, "ok", false);
        fire(l -> l.onGearAck(tid, ok));
    }

    private void handleNoShow(JsonObject d)
    {
        String tid = tid(d);
        String sid = optString(d, "series_id");
        long at = optLong(d, "effective_at", 0L);
        if (!tid.isEmpty() && !sid.isEmpty()) fire(l -> l.onNoShowRecorded(tid, sid, at));
    }

    private void handleError(JsonObject d)
    {
        String code = optString(d, "code", "UNKNOWN");
        String message = optString(d, "message");
        String cmd = optString(d, "cmd");
        fire(l -> l.onTournamentError(code, message, cmd));
    }

    private void fire(Consumer<TournamentEventListener> fn)
    {
        SwingUtilities.invokeLater(() ->
        {
            for (TournamentEventListener l : listeners)
            {
                try
                {
                    fn.accept(l);
                }
                catch (Exception e)
                {
                }
            }
        });
    }
}

package com.pvp.leaderboard.tournament;

import java.util.*;
import javax.inject.*;

/** Sends {@code tournament/world} for the open match ({@link OppTracker}'s, which hears each push first): at the
 *  assignment, for each new world and after a reconnect's re-sync; never a 0 world or the same series and world twice
 *  in a row. EDT only. */
@Singleton
public final class WorldReport implements TournamentEventListener
{
    private final TourneySvc svc;
    private final OppTracker opp;
    private int world;
    private String sent;

    @Inject
    WorldReport(TourneySvc svc, OppTracker opp)
    {
        this.svc = svc;
        this.opp = opp;
    }

    /** The world the player is in, 0 when not in one. */
    public void onWorld(int world)
    {
        this.world = world;
        send();
    }

    @Override
    public void onMatchAssigned(MatchSeries series)
    {
        send();
    }

    @Override
    public void onTournamentState(List<Tourney> registrations, LiveTourney active)
    {
        send();
    }

    @Override
    public void onConnected()
    {
        sent = null;
    }

    private void send()
    {
        MatchSeries s = opp.getActiveSeries();
        String key = s == null || world <= 0 ? null : s.seriesId + ":" + world;
        if (key == null || key.equals(sent)) return;
        sent = key;
        svc.world(s.tournamentId, s.seriesId, world);
    }
}

