    /** Forwards a {@code GameStateChanged} signal from the plugin to
     *  the matchmaking panel so the lobby-gate notice can flip
     *  between "Please log into the game" and "Loading…" without
     *  waiting for the 10-tick {@link JoinGate#onLogin()}
     *  delay. */
    public void syncLogins()
    {
        lobbyCard.refreshGate();
        if (tourneyPanel != null)
        {
            tourneyPanel.refreshLogin();
        }
    }

    /** Forwards the match-found popup notifier from the plugin lifecycle
     *  layer to the matchmaking panel. */
    public void setMatchFoundNotifier(MatchmakingLobbyPanel.MatchAlert notifier)
    {
        lobbyCard.setMatchFoundNotifier(notifier);
    }

    /**
     * Loads match history only if NO player is currently being viewed.
     * This prevents game events from overwriting a user's active search.
     * Called on login/world hop - will not switch away from user's search.
     */
    public void loadIfIdle(String playerId)
    {
        // If user is already viewing someone (searched for a player), don't overwrite
        if (lookupId != null && !lookupId.isEmpty()) {
            return;
        }

        // No one currently viewed - load the requested player (usually self)
        loadMatches(playerId);
    }

    /**
     * Public entry point for the right-click "PvP lookup" menu (and any future
     * caller that wants to surface a specific player). Forces the Player Lookup
     * tab to the foreground BEFORE kicking off the match-history load so the
     * user actually sees the data they asked for.
     *
     * <p>Kept separate from {@link #loadMatches(String)} on purpose:
     * loadMatches is also invoked by auto-paths (login, game events,
     * refresh) where forcibly switching tabs would yank focus away from the
     * Matchmaking Lobby unexpectedly. Right-click menu = explicit intent =
     * tab switch is desired; everything else = silent background load.
     */
    public void openLookup(String playerId)
    {
        Runnable open = () ->
        {
            setActiveTab(CARD_LOOKUP);
            loadMatches(playerId);
        };
        if (isEventDispatchThread())
        {
            open.run();
        }
        else
        {
            invokeLater(open);
        }
    }

    /**
     * Forces a full refresh of match history. Called from explicit user actions (search, refresh button).
     */
    public void loadMatches(String playerId)
    {
        final int gen = ++loadGen;
        lookupId = normalizeId(playerId);

        Runnable uiReset = () -> {
            playerLabel.setText(playerId);
            loginPanel.setPluginSearchText(playerId);
            refreshButton.setVisible(true);
            streaksBtn.setVisible(true);
            historyBtn.setVisible(false);
            advancedToggle.setVisible(false);
            extraStats.setPlayerName(lookupId);
            updateBlock(lookupId);
            resetUi();
        };
        if (isEventDispatchThread()) {
            uiReset.run();
        } else {
            invokeLater(uiReset);
        }

        try {
            String normalizedId = lookupId;
            loadStats(normalizedId, gen);

            // Your own history is read by account (the hash of the stored
            // client id) when there is one, everyone else's by name.
            boolean isSelf = isSelf(normalizedId);
            String sha = isSelf ? pvpApi.getSelfSha() : null;
            extraStats.setAcctSha(sha);
            pvpApi.getMatches(sha, normalizedId, null, PAGE_SIZE, false).thenAccept(jsonResponse -> {
                if (gen != loadGen || jsonResponse == null)
                {
                    return;
                }

                JsonArray matches = optArray(jsonResponse, "matches");

                invokeLater(() -> {
                    if (gen != loadGen) return;
                    if (isSelf) seedStreaks(matches);
                    updateUi(matches);
                });
            });
        } catch (Exception ex) {
            // ignored
        }
    }

    private void updateUi(JsonArray matches) {
        chartPanel.setMatches(matches);
        extraStats.setMatches(matches);
        allMatches = matches;

        boolean hasData = matches != null && matches.size() > 0;
        historyBtn.setVisible(hasData);
        advancedToggle.setVisible(hasData);

        refreshBars();
    }

    private void resetUi()
    {
        rankProgress.reset();
        perfStats.reset();
        chartPanel.setMatches(new JsonArray());
        extraStats.setMatches(new JsonArray());
        allMatches = null;
    }

    private void loadStats(String playerId, int gen)
    {
        try {
            pvpApi.getProfile(playerId, false).thenAccept(stats -> {
                if (gen != loadGen || stats == null)
                {
                    return;
                }
                invokeLater(() -> {
                    if (gen != loadGen) return;
                    updateBars(stats, gen);
                    if (isShowingSelf()) syncStreaks(playerId);
                });
            });
        } catch (Exception ex) {
            // ignored
        }
    }

    @Setter private volatile WinStreakTracker winStreakTracker;

    private void seedStreaks(JsonArray matches)
    {
        WinStreakTracker tracker = winStreakTracker;
        if (tracker == null) return;
        tracker.seedHistory(matches);
        refreshLines();
    }

    private void syncStreaks(String playerId)
    {
        WinStreakTracker tracker = winStreakTracker;
        if (tracker == null) return;
        tracker.observeProfile(pvpApi.peekProfile(playerId));
        refreshLines();
    }

    private void refreshLines()
    {
        for (StreakBucket b : StreakBucket.values()) refreshLine(b.bucketKey);
    }

    /** The local player's own profile was refreshed after a fight: redraws the rating rows from the cached profile while it is shown. */
    public void refreshOwn(String playerName)
    {
        String normalized = normalizeId(playerName);
        if (normalized == null || normalized.isEmpty()) return;
        invokeLater(() ->
        {
            if (!isShowingSelf() || !normalized.equalsIgnoreCase(lookupId)) return;
            UserStats cached = pvpApi.peekProfile(playerName);
            JsonObject stats = cached == null ? null : cached.getStats();
            if (stats == null) return;
            String name = optString(stats, "player_name", playerName);
            applyAll(stats, name, loadGen);
        });
    }

    public void refreshLine(String bucketKey)
    {
        WinStreakTracker tracker = winStreakTracker;
        StreakBucket bucket = StreakBucket.forKey(bucketKey);
        if (tracker == null || bucket == null || !isShowingSelf() || !tracker.isKnown()) return;
        String key = bucket.bucketKey;
        rankProgress.updateStreak(key, tracker.current(key), tracker.plus(key), tracker.longest(key));
    }

    /** Whether the normalised {@code id} is the logged-in player's own name. */
    private boolean isSelf(String id)
    {
        String self = normalizeId(plugin.getLocalName());
        return self != null && !self.isEmpty() && self.equalsIgnoreCase(id);
    }

    private boolean isShowingSelf()
    {
        return isSelf(lookupId);
    }

    private void updateBars(JsonObject stats, int gen)
    {
        String playerName = optString(stats, "player_name", optString(stats, "player_id", null));
        if (playerName != null)
        {
            applyAll(stats, playerName, gen);
        }

        JsonObject cumulative = optObject(stats, "cumulative_stats");
        if (cumulative != null) perfStats.setTotals(cumulative);
        JsonObject opponents = optObject(stats, "opponent_rank_stats_by_bucket");
        if (opponents != null) perfStats.setOppRanks(opponents);
    }

    /** Every rating row in screen order: Overall reads the profile's root
     *  (its streak pair from {@code buckets.overall}), each other bucket its
     *  object under {@code buckets}. The tournament bucket is null until the
     *  player's first tournament game; optObject keeps that JSON null from
     *  throwing and the row stays hidden ("—"). */
    private void applyAll(JsonObject stats, String playerName, int gen)
    {
        for (String bucketKey : RankProgress.BUCKET_KEYS)
        {
            applyBucket(playerName, bucketKey, "overall".equals(bucketKey) ? stats
                : optObject(optObject(stats, "buckets"), bucketKey), gen);
        }
    }

    private void applyBucket(String playerName, String bucketKey, JsonObject bucketObj, int gen)
    {
        if (bucketObj == null) {
            // Unplayed bucket: no rank, no streak line (hides the tournament row).
            rankProgress.updateBucket(bucketKey, "—", 0, 0, -1, null, 0, 0);
            return;
        }

        String rankLabel = "—";
        int division = 0;
        double pct = 0.0;
        double mmr = Double.NaN;

        if (bucketObj.has("mmr")) {
            mmr = bucketObj.get("mmr").getAsDouble();
            RankInfo ri = RankUtils.toRankInfo(mmr);
            rankLabel = ri.rank;
            division = ri.division;
            pct = ri.progress;
        }
        pct = optDouble(optObject(bucketObj, "rank_progress"), "progress_to_next_rank_pct", pct);
        String r = optString(bucketObj, "rank");
        if (!r.isEmpty()) rankLabel = r;
        division = optInt(bucketObj, "division", division);

        // The streak lines under the bar: every row's pair is in its bucket
        // object, the overall one in buckets.overall. The later rank-number /
        // Top % refresh uses the 6-arg form so it leaves the lines alone.
        JsonObject streaks = "overall".equals(bucketKey) ? optObject(optObject(bucketObj, "buckets"), "overall") : bucketObj;
        int streak = optInt(streaks, "streak", 0);
        int bestStreak = optInt(streaks, "best_streak", 0);
        rankProgress.updateBucket(bucketKey, rankLabel, division, pct, -1, null, streak, bestStreak);

        if (!"—".equals(rankLabel)) refreshRankLine(playerName, bucketKey, rankLabel, division, pct, mmr, gen);
    }

    /** Adds the rank number and the "Top X.XX%" to a bucket's rank line: both
     *  computed on a background thread so the row updates once with both, and
     *  dropped when another lookup has started meanwhile. */
    private void refreshRankLine(String playerName, String bucket, String rank, int division, double pct, double mmr, int gen)
    {
        new SwingWorker<Integer, Void>()
        {
            String top;

            @Override protected Integer doInBackground() {
                top = computeTop(bucket, mmr);
                return getBoardRank(playerName, bucket);
            }

            @Override protected void done() {
                try {
                    if (gen == loadGen) rankProgress.updateBucket(bucket, rank, division, pct, get(), top);
                } catch (Exception ignore) {
                }
            }
        }.execute();
    }

    private void refreshBars() {
        if (allMatches == null || allMatches.size() == 0) return;
        String playerName = playerLabel.getText();
        if ("Player Name".equals(playerName)) return;

        final int gen = loadGen;
        for (String bucket : RankProgress.BUCKET_KEYS)
        {
            // The bucket's latest match: the first one, replaced only by a strictly later "when".
            JsonObject latest = null;
            for (JsonElement e : allMatches)
            {
                JsonObject match = e.getAsJsonObject();
                if (bucket.equals(optString(match, "bucket").toLowerCase())
                    && (latest == null || (match.has("when") && latest.has("when")
                        && match.get("when").getAsLong() > latest.get("when").getAsLong())))
                {
                    latest = match;
                }
            }

            if (latest != null && latest.has("player_mmr"))
            {
                double mmr = latest.get("player_mmr").getAsDouble();
                RankInfo est = RankUtils.toRankInfo(mmr);
                refreshRankLine(playerName, bucket,
                    optString(latest, "player_rank", est.rank),
                    optInt(latest, "player_division", est.division),
                    est.progress, mmr, gen);
            }
        }
    }

    // --- Helpers ---

    /**
     * The player's "Top X.XX%" for a bucket, derived from the cached rank
     * histogram ({@code rank_hist/<bucket>.json}). Runs on a background
     * thread (it blocks briefly on the cached future), so it must NOT be
     * called from the EDT. Reuses {@link PvpApi#getHistogram}
     * which is backed by the shared 60-minute shard cache — so the histogram
     * for each bucket is fetched at most once per hour and shared with the
     * "What are the ranks" view, never re-fetched per lookup. Returns
     * {@code null} when it can't be determined (a missing histogram counts
     * nobody) so the caller omits the suffix.
     */
    private String computeTop(String bucket, double mmr)
    {
        if (!Double.isFinite(mmr)) return null;
        try {
            JsonObject hist = pvpApi.getHistogram(bucket).get(5, TimeUnit.SECONDS);
            return RankUtils.formatTopPercentPrecise(RankUtils.totalAbove(hist, mmr), RankUtils.histTotal(hist));
        } catch (Exception ignore) {
            return null;
        }
    }

    /** {@code bucket} is one of {@link RankProgress#BUCKET_KEYS}. */
    public int getBoardRank(String playerName, String bucket)
    {
        try {
            // bypassCache=true: this method runs on a SwingWorker
            // background thread spawned from openLookup —
            // i.e. a user gesture. The 2026-05-24 backend handoff
            // moved shard writes to a DynamoDB-stream-driven path
            // with ≈30 s propagation, so an explicit "look this
            // player up" should pick up post-match rank changes
            // instead of serving the cached payload (which could
            // be up to 60 min stale).
            ShardRank sr = pvpApi.getShardRank(playerName, bucket, true)
                .get(5, TimeUnit.SECONDS);
            return sr != null && sr.rank > 0 ? sr.rank : -1;
        } catch (Exception ex) {
            return -1;
        }
    }

    private static String normalizeId(String name) {
        return name != null ? name.trim().replaceAll("\\s+", " ").toLowerCase() : null;
    }

    /** Nested scroll panes hand the mouse wheel on: each scrolls itself while
     *  it can move that way and passes the wheel to its parent at its top
     *  (turning up) or bottom (turning down), or always without a visible
     *  bar. Covers every pane in {@code c} now and any added later. */
    private static void wire(Component c)
    {
        if (c instanceof JScrollPane)
        {
            var sp = (JScrollPane) c;
            sp.setWheelScrollingEnabled(false);
            sp.addMouseWheelListener(e -> {
                JScrollBar vbar = sp.getVerticalScrollBar();
                int turn = e.getWheelRotation();
                if (!vbar.isVisible() || turn < 0 && vbar.getValue() <= vbar.getMinimum()
                    || turn > 0 && vbar.getValue() >= vbar.getMaximum() - vbar.getVisibleAmount())
                {
                    sp.getParent().dispatchEvent(convertMouseEvent(sp, e, sp.getParent()));
                }
                else
                {
                    vbar.setValue(vbar.getValue() + e.getUnitsToScroll() * vbar.getUnitIncrement());
                }
            });
        }
        if (c instanceof Container)
        {
            var container = (Container) c;
            for (Component child : container.getComponents())
            {
                wire(child);
            }
            container.addContainerListener(new ContainerAdapter()
            {
                @Override
                public void componentAdded(ContainerEvent e)
                {
                    wire(e.getChild());
                }
            });
        }
    }
}

package com.pvp.leaderboard.ui;

import lombok.*;
import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.text.*;
import java.time.*;
import java.util.*;
import java.util.stream.*;
import javax.swing.*;
import lombok.extern.slf4j.*;
import java.util.List;
import static com.pvp.leaderboard.ui.Ui.*;
import static com.pvp.leaderboard.util.JsonLenient.*;
import static java.awt.RenderingHints.*;
import static java.lang.Math.*;
import static com.pvp.leaderboard.util.RankUtils.*;

/**
 * The "Additional Stats" box (Overall): the highest rank defeated, the lowest
 * rank lost to, and the Tier Graph button.
 *
 * <p>Its height is capped at its content's ({@link CapPanel}): the content is
 * pinned to {@link BorderLayout#NORTH}, and {@code BorderLayout} otherwise
 * reports an unbounded maximum height, so the dashboard's vertical
 * {@code BoxLayout} would hand it all of the leftover vertical slack —
 * stretching the box far below its content (most visible right after login,
 * when the rank/advanced sections below are short). Width stays flexible.
 */
@Slf4j
public class ExtraStats extends CapPanel {
    private final JLabel highestRankLabel = new JLabel("-");
    private final JLabel highestTimeLabel = new JLabel("-");
    private final JLabel lowestRankLabel = new JLabel("-");
    private final JLabel lowestTimeLabel = new JLabel("-");

    private final SimpleDateFormat fmt = new SimpleDateFormat("M/d/yyyy, h:mm:ss a");
    private JsonArray matches = new JsonArray();

    private final PvpApi pvpApi;
    @Setter private String playerName;
    @Setter private String acctSha;

    private static final int DAILY_LIMIT = 3;
    private static final int FETCH_PAGE = 15;
    private static final int MAX_FETCHED = 200;
    private static final long LOOKBACK_MS = 24L * 60 * 60 * 1000;

    private final Map<String, CachedMatches> matchCache = new HashMap<>();

    private final Set<String> dailyLookups = new HashSet<>();
    private LocalDate lookupDate = LocalDate.now();

    private static class CachedMatches {
        final JsonArray matches;
        final long cachedAtMs;
        final double latestWhen;

        CachedMatches(JsonArray matches, long cachedAtMs) {
            this.matches = matches;
            this.cachedAtMs = cachedAtMs;
            double max = 0;
            for (int i = 0; i < matches.size(); i++) {
                max = Math.max(max, optDouble(matches.get(i).getAsJsonObject(), "when", 0));
            }
            latestWhen = max;
        }
    }

    private final JButton tierGraphBtn;
    private final JLabel graphInfo;

    public ExtraStats(PvpApi pvpApi) {
        this.pvpApi = pvpApi;
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createTitledBorder("Additional Stats"));

        var content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));

        var statsCol = new JPanel();
        statsCol.setLayout(new BoxLayout(statsCol, BoxLayout.Y_AXIS));
        left(statsCol);
        statsCol.add(makeStat("Highest Rank Defeated", highestRankLabel, highestTimeLabel));
        statsCol.add(vgap(6));
        statsCol.add(makeStat("Lowest Rank Lost To", lowestRankLabel, lowestTimeLabel));
        content.add(statsCol);
        content.add(vgap(8));

        tierGraphBtn = new JButton(getGraphText());
        tierGraphBtn.addActionListener(e -> onGraphClick());
        content.add(tierGraphBtn);
        content.add(vgap(4));

        graphInfo = new JLabel(
                "<html>Free tier allows 3 unique player searches per day due to "
                + "backend cost, reach out to Toyco on discord to get more access</html>");
        graphInfo.setForeground(Color.GRAY);
        plain(graphInfo, 14f);
        content.add(graphInfo);

        add(content, BorderLayout.NORTH);
    }

    public void setMatches(JsonArray newMatches) {
        matches = (newMatches != null) ? newMatches : new JsonArray();
        updateExtra();
    }

    /**
     * The tier-graph bucket selector's wire keys, in display order. G-11
     * appended {@code tournament} so the selector matches the website's
     * Performance Overview; the "Overall" series is unchanged (the backend
     * adds Tournament to Overall at 10% ON TOP of the existing 100% —
     * {@code backend/core/buckets.with_tournament} — so the local
     * approximation in {@link TierGraphPanel#set} is untouched here).
     */
    static String[] bucketKeys() {
        return new String[]{"overall", "nh", "veng", "multi", "dmm", "tournament"};
    }

    /** Display labels for {@link #bucketKeys()}, same order. */
    static String[] bucketLabels() {
        return BUCKETS;
    }

    private String getGraphText() {
        resetDay();
        return "Tier Graph " + (DAILY_LIMIT - dailyLookups.size()) + "/" + DAILY_LIMIT + " remaining";
    }

    private void resetDay() {
        LocalDate today = LocalDate.now();
        if (!today.equals(lookupDate)) {
            lookupDate = today;
            dailyLookups.clear();
        }
    }

    private void onGraphClick() {
        resetDay();
        if (pvpApi == null || playerName == null || playerName.isEmpty()) {
            JOptionPane.showMessageDialog(this,
                    "No player loaded. Please search for a player first.",
                    "No Player", JOptionPane.INFORMATION_MESSAGE);
            return;
        }
        String key = playerName.toLowerCase(Locale.ROOT);
        boolean alreadyCached = matchCache.containsKey(key);
        if (!alreadyCached && dailyLookups.size() >= DAILY_LIMIT
                && !dailyLookups.contains(key)) {
            JOptionPane.showMessageDialog(this,
                    "You have used all 3 unique new player tier graph lookups for today.\n"
                    + "Previously cached players can still be reopened.\n"
                    + "This limit resets daily.",
                    "Daily Limit Reached", JOptionPane.WARNING_MESSAGE);
            return;
        }

        openGraph(key, alreadyCached);
    }

    private void openGraph(String cacheKey, boolean alreadyCached) {
        JDialog dialog = dialog(this, "Tier Graph Over Time - " + playerName, 700, 500);

        var mainPanel = new JPanel(new BorderLayout(0, 4));

        String[] bucketKeys = bucketKeys();
        String[] bucketLabels = bucketLabels();
        var bucketBar = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        var bucketBtns = new JButton[bucketKeys.length];
        var graph = new TierGraphPanel();
        // The dialog paints only after this method returns, so the status is
        // chosen up front; the card layout already shows its first card.
        var statusLabel = new JLabel(alreadyCached ? "Updating with latest matches..." : "Loading all matches...");
        statusLabel.setHorizontalAlignment(SwingConstants.CENTER);

        final String[] dialogBucket = { "overall" };
        final JsonArray[] dialogMatches = { new JsonArray() };

        for (int i = 0; i < bucketKeys.length; i++) {
            final String key = bucketKeys[i];
            bucketBtns[i] = new JButton(bucketLabels[i]);
            bucketBtns[i].setEnabled(alreadyCached);
            bucketBtns[i].addActionListener(e -> {
                dialogBucket[0] = key;
                styleBtns(bucketBtns, bucketKeys, key);
                graph.set(dialogMatches[0], key);
            });
            bucketBar.add(bucketBtns[i]);
        }
        styleBtns(bucketBtns, bucketKeys, dialogBucket[0]);

        mainPanel.add(bucketBar, BorderLayout.NORTH);

        var centerWrapper = new JPanel(new CardLayout());
        centerWrapper.add(statusLabel, "loading");
        centerWrapper.add(graph, "graph");

        mainPanel.add(centerWrapper, BorderLayout.CENTER);
        dialog.add(mainPanel);
        dialog.setVisible(true);

        Runnable showGraph = () -> SwingUtilities.invokeLater(() -> {
            JsonArray current = matchCache.containsKey(cacheKey)
                    ? matchCache.get(cacheKey).matches : new JsonArray();
            dialogMatches[0] = current;
            for (JButton btn : bucketBtns) btn.setEnabled(true);
            graph.set(current, dialogBucket[0]);
            ((CardLayout) centerWrapper.getLayout()).show(centerWrapper, "graph");
            tierGraphBtn.setText(getGraphText());
        });

        if (alreadyCached) {
            CachedMatches cached = matchCache.get(cacheKey);
            long now = System.currentTimeMillis();
            double cutoffSec = Math.max(cached.cachedAtMs / 1000.0, (now - LOOKBACK_MS) / 1000.0);
            var newMatches = new JsonArray();
            fetchPage(null, newMatches, cached.latestWhen, cutoffSec, 0, () -> {
                newMatches.addAll(cached.matches);
                matchCache.put(cacheKey, new CachedMatches(newMatches, System.currentTimeMillis()));
                showGraph.run();
            });
        } else {
            pvpApi.getAllMatches(acctSha, playerName).thenAccept(allMatches -> {
                matchCache.put(cacheKey, new CachedMatches(allMatches, System.currentTimeMillis()));
                dailyLookups.add(cacheKey);
                showGraph.run();
            }).exceptionally(ex -> {
                log.warn("Failed to fetch all matches for tier graph", ex);
                SwingUtilities.invokeLater(() -> {
                    statusLabel.setText("Failed to load matches.");
                    for (JButton btn : bucketBtns) btn.setEnabled(true);
                });
                return null;
            });
        }
    }

    /**
     * Pages newest-first through the player's matches newer than the cache
     * ({@code cachedWhen}) and the lookback ({@code cutoffSec}), up to
     * {@link #MAX_FETCHED} in all; a recursion only starts below
     * that cap. An empty page (or no {@code matches} array) ends it.
     */
    private void fetchPage(String nextToken, JsonArray accumulator,
                                      double cachedWhen, double cutoffSec,
                                      int totalFetched, Runnable onDone) {
        pvpApi.getMatches(acctSha, playerName, nextToken, FETCH_PAGE, true)
                .thenAccept(response -> {
                    JsonArray page = optArray(response, "matches");
                    boolean caughtUp = false;
                    int added = 0;
                    for (JsonElement e : page) {
                        JsonObject m = e.getAsJsonObject();
                        double when = optDouble(m, "when", 0);
                        if (when <= cachedWhen || when < cutoffSec) {
                            caughtUp = true;
                            break;
                        }
                        accumulator.add(m);
                        if (totalFetched + ++added >= MAX_FETCHED) {
                            caughtUp = true;
                            break;
                        }
                    }
                    if (caughtUp) {
                        onDone.run();
                        return;
                    }
                    String next = added > 0 ? optString(response, "next_token", null) : null;
                    if (next != null && !next.isEmpty()) {
                        fetchPage(next, accumulator, cachedWhen, cutoffSec,
                                totalFetched + added, onDone);
                    } else {
                        onDone.run();
                    }
                }).exceptionally(ex -> {
                    log.warn("Incremental match fetch failed", ex);
                    onDone.run();
                    return null;
                });
    }

    private void styleBtns(JButton[] btns, String[] keys, String selected) {
        Color selBg = SELECTED_BG;
        Color selFg = Color.WHITE;
        Color unselFg = Color.GRAY;
        for (int i = 0; i < btns.length; i++) {
            if (keys[i].equals(selected)) {
                btns[i].setBackground(selBg);
                btns[i].setForeground(selFg);
            } else {
                btns[i].setBackground(null);
                btns[i].setForeground(unselFg);
            }
        }
    }

    /** A match whose mu moves more than this from the bucket's previous
     *  point is treated as bad data and skipped (the point is still
     *  plotted at the previous value). */
    private static final int MAX_DELTA = 250;

    /**
     * The "Overall" history for the tier graph — one Overall mu per match,
     * in the given (already sorted) order. G-16 (operator decision
     * 2026-09-22): the formula is the backend's, mirrored in
     * {@link OverallMmr} — the four standard buckets weighted
     * {@code 0.55 / 0.30 / 0.05 / 0.10} (1000 until a bucket has a game)
     * plus {@code 0.10 × tournament} on top, where the tournament term
     * exists only once a tournament match with a rating has been seen; a
     * history without one plots exactly the legacy Overall. A point that
     * carries no usable mu (or jumps more than {@link #MAX_DELTA})
     * leaves its bucket where it was. Package-private for the tests.
     */
    static List<Double> muSeries(List<JsonObject> sortedItems) {
        var acc = new OverallMmr();
        List<Double> out = new ArrayList<>();
        for (JsonObject m : sortedItems) {
            String b = optString(m, "bucket").toLowerCase(Locale.ROOT);
            if (OverallMmr.isRated(b)) {
                Double prev = acc.lastMu(b);
                // A standard bucket starts from the 1000 default exactly as
                // before (a delta-only first point resolves against it and
                // the outlier guard measures from it). The tournament bucket
                // has no local seed: its first point must carry a rating of
                // its own, or the term stays absent.
                Double baseline = prev != null ? prev
                        : (OverallMmr.TOURNEY_KEY.equals(b) ? null : OverallMmr.DEFAULT_MU);
                double mu = resolveMu(m, baseline);
                if (Double.isFinite(mu) && (baseline == null || abs(mu - baseline) <= MAX_DELTA)) {
                    acc.record(b, mu);
                }
            }
            out.add(acc.overall());
        }
        return out;
    }

    private JPanel makeStat(String title, JLabel value, JLabel time) {
        var p = new JPanel();
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        var t = new JLabel(title);
        bold(t, 16f);
        bold(value, 18f);
        time.setForeground(new Color(230, 200, 80));
        p.add(t);
        p.add(vgap(4));
        p.add(value);
        p.add(time);
        return p;
    }

    private void updateExtra() {
        String bestRank = null; Long bestTs = null;
        String worstRank = null; Long worstTs = null;

        for (int i = 0; i < matches.size(); i++) {
            JsonObject m = matches.get(i).getAsJsonObject();
            String result = optString(m, "result").toLowerCase(Locale.ROOT);
            long ts = (long) floor(optDouble(m, "when", 0));

            String oppRank = rankLabel(optString(m, "opponent_rank"), optInt(m, "opponent_division", 0));
            if (oppRank.isEmpty()) continue;

            if ("win".equals(result)) {
                if (bestRank == null || getRankOrder(oppRank) > getRankOrder(bestRank)) {
                    bestRank = oppRank; bestTs = ts;
                }
            } else if ("loss".equals(result)) {
                if (worstRank == null || getRankOrder(oppRank) < getRankOrder(worstRank)) {
                    worstRank = oppRank; worstTs = ts;
                }
            }
        }

        highestRankLabel.setText(bestRank != null ? bestRank : "-");
        highestTimeLabel.setText(bestTs != null ? fmt.format(new Date(bestTs * 1000)) : "-");
        lowestRankLabel.setText(worstRank != null ? worstRank : "-");
        lowestTimeLabel.setText(worstTs != null ? fmt.format(new Date(worstTs * 1000)) : "-");
    }

    /** The first of the match's absolute mu keys that is present, else
     *  {@code prevMu} plus the rating change's delta, else NaN. */
    private static double resolveMu(JsonObject m, Double prevMu) {
        for (String k : new String[]{"player_mmr_after", "player_new_mmr", "player_mmr"}) {
            double mu = optDouble(m, k, Double.NaN);
            if (!Double.isNaN(mu)) return mu;
        }
        double delta = optDouble(optObject(m, "rating_change"), "mmr_delta", Double.NaN);
        return Double.isNaN(delta) || prevMu == null ? Double.NaN : prevMu + delta;
    }

    private static String rankLabel(String rank, int division) {
        if (rank == null || rank.isEmpty()) return "";
        return division > 0 ? (rank + " " + division) : rank;
    }

    /**
     * The Tier Graph: the rank labels drawn in the left 80 px and the plot in
     * the rest, each through its own clipped graphics exactly as two side-by-side
     * panels would be. The dialog is a fixed size and never packed, so the
     * panel needs no preferred size.
     */
    static class TierGraphPanel extends JPanel {
        double lo = 0.0, hi = 24.0;
        List<Double> series = new ArrayList<>();

        /**
         * Plots {@code bucket}'s history from {@code allMatches}: the visible
         * range is whole rank families (multiples of 3) around the points, and
         * each point is a match's 0-100 height in it. A bucket's point holds
         * the previous rating on a match with no usable rating or a jump over
         * {@link #MAX_DELTA}, and is 1000 before the first one.
         */
        void set(JsonArray allMatches, String bucket) {
            List<JsonObject> items = new ArrayList<>();
            for (int i = 0; i < allMatches.size(); i++) items.add(allMatches.get(i).getAsJsonObject());
            items = items.stream()
                    .filter(m -> bucket.equals("overall") || bucket.equalsIgnoreCase(optString(m, "bucket")))
                    .sorted(Comparator.comparingDouble(m -> optDouble(m, "when", 0)))
                    .collect(Collectors.toList());

            List<Double> rawY = new ArrayList<>();
            if ("overall".equals(bucket)) {
                for (double overallMu : muSeries(items)) {
                    rawY.add(tierValueOf(overallMu));
                }
            } else {
                Double prevMu = null;
                for (JsonObject m : items) {
                    double mu = resolveMu(m, prevMu);
                    if (Double.isFinite(mu) && (prevMu == null || abs(mu - prevMu) <= MAX_DELTA)) prevMu = mu;
                    rawY.add(tierValueOf(prevMu != null ? prevMu : 1000.0));
                }
            }

            // Every point is finite: OverallMmr records only finite mu, and the tier maths clamps.
            double minY = 24.0, maxY = 0.0;
            for (double y : rawY) {
                minY = min(minY, y);
                maxY = Math.max(maxY, y);
            }
            double low = Math.max(0, (int) floor(minY / 3.0) * 3);
            double high = min(24, (int) ceil(maxY / 3.0) * 3);
            if (high <= low) high = min(24, low + 3);

            List<Double> points = new ArrayList<>();
            double span = Math.max(1e-6, high - low);
            for (double y : rawY) {
                points.add(Math.max(0.0, min(100.0, ((y - low) / span) * 100.0)));
            }
            lo = low;
            hi = high;
            series = points;
            repaint();
        }

        @Override protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            int w = getWidth(), h = getHeight();
            paintLabels((Graphics2D) g.create(0, 0, 80, h), h);
            paintPlot((Graphics2D) g.create(80, 0, w - 80, h), w - 80, h);
        }

        private void paintLabels(Graphics2D g2, int h) {
            g2.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
            int innerH = Math.max(1, h - 40);
            int end = (int) ceil(hi);
            for (int gi = (int) floor(lo); gi <= end; gi++) {
                double frac = (gi - lo) / Math.max(1e-6, (hi - lo));
                int y = 20 + innerH - (int) round(frac * innerH);
                g2.setColor(new Color(0x787878));
                g2.drawLine(0, y, 80, y);
                String baseRank = THRESHOLDS[min(gi / 3 * 3, THRESHOLDS.length - 1)][0];
                if (gi % 3 == 0) {
                    g2.setColor(getRankColor(baseRank));
                    g2.drawString(baseRank.equals("3rd Age") ? baseRank : baseRank + " 3", 2, y + 5);
                }
            }
            g2.dispose();
        }

        private void paintPlot(Graphics2D g2, int w, int h) {
            g2.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
            int innerW = Math.max(1, w - 20);
            int innerH = Math.max(1, h - 40);

            g2.setColor(new Color(0x787878));
            int end = (int) ceil(hi);
            for (int gi = (int) floor(lo); gi <= end; gi++) {
                if (gi % 3 != 0) continue;
                double frac = (gi - lo) / Math.max(1e-6, (hi - lo));
                int y = 20 + innerH - (int) round(frac * innerH);
                g2.drawLine(0, y, innerW, y);
            }

            if (series.size() > 1) {
                g2.setColor(Color.WHITE);
                g2.setStroke(new BasicStroke(2f));
                for (int i = 0; i < series.size() - 1; i++) {
                    int x1 = i * innerW / (series.size() - 1);
                    int x2 = (i + 1) * innerW / (series.size() - 1);
                    int y1 = 20 + innerH - (int) round((series.get(i) / 100.0) * innerH);
                    int y2 = 20 + innerH - (int) round((series.get(i + 1) / 100.0) * innerH);
                    g2.drawLine(x1, y1, x2, y2);
                }
            } else {
                g2.setColor(Color.GRAY);
                g2.drawString("No tier data available", w / 2 - 60, h / 2);
            }
            g2.dispose();
        }
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.tournament.*;
import java.awt.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import java.util.List;
import static com.pvp.leaderboard.ui.Ui.*;

public class GearCard extends CapPanel
{
    public static final String NAME = "tournament-gear-card";
    static final String NEVER_READ = "Open your kit tab on the duel screen or the Supplies chest so the plugin can read your kit.";
    static final String STALE_HINT = "Your kit changed since the plugin last read it (a Load-outs copy?) — open your kit tab so it can re-read it.";
    static final String POUCH_HINT = "Open your kit's rune pouch once so the plugin can read its runes.";
    static final String AWAY_HINT = "Fights are PvP Arena Unranked Duels — head to the PvP Arena.";
    static final String STUB_BANNER = "Placeholder kit — the host's final kit may differ";
    static final String COPIED = "Copied — paste it into gear_sets_catalog.json";

    private static final float LINE_PT = TourneyPanel.BODY_PT;
    private static final float ITEM_PT = 14f;
    /** An item icon's width plus its gap to the text. */
    private static final int ICON_ROOM_PX = 40;
    static final Color RED = new Color(0xff6b6b);

    public interface Actions
    {
        void findItem(int itemId, List<Integer> altIds, String name);

        void copySetup(GearKit kit);

        void showMissing(List<Integer> itemIds);

        void openPanel();
    }

    public interface Icons
    {
        void apply(JLabel label, int itemId, int qty, boolean stackable);
    }

    private final Icons icons;
    private final Actions actions;
    private final BooleanSupplier autoOpenEnabled;
    private String shape;
    private JLabel countdown;
    private JLabel okLine;
    private String lastAutoOpen;
    private GearReporter.View current = GearReporter.View.EMPTY;

    public GearCard(Icons icons, Actions actions, BooleanSupplier autoOpenEnabled)
    {
        this.icons = icons;
        this.actions = actions;
        this.autoOpenEnabled = autoOpenEnabled;
        setName(NAME);
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        cardStyle(this);
        setVisible(false);
    }

    public void render(GearReporter.View v)
    {
        current = v == null ? GearReporter.View.EMPTY : v;
        maybeOpen(current);
        if (current.event == null || current.inCombat)
        {
            setVisible(false);
            return;
        }
        String nextShape = shapeOf(current);
        if (!nextShape.equals(shape))
        {
            shape = nextShape;
            rebuild(current);
        }
        refreshClock(current);
        setVisible(true);
    }

    private void maybeOpen(GearReporter.View v)
    {
        String key = autoOpenKey(v);
        if (key == null || key.equals(lastAutoOpen) || !GearKit.safe(autoOpenEnabled)) return;
        lastAutoOpen = key;
        actions.openPanel();
    }

    static String autoOpenKey(GearReporter.View v)
    {
        if (v == null || v.event == null || v.inCombat || v.verifiedOk()) return null;
        if (v.event.prepOpen(v.nowMs / 1000L)) return "prep|" + v.event.tournamentId + "|" + v.event.checkUntilS;
        if (v.event.running) return "start|" + v.event.tournamentId;
        return null;
    }

    private static String shapeOf(GearReporter.View v)
    {
        var sb = new StringBuilder(v.event.tournamentId).append('|').append(v.event.set.digest).append('|').append(v.event.arena)
            .append('|').append(v.atArena).append('|').append(v.verifiedOk()).append('|').append(v.stale()).append('|').append(v.kit == null);
        GearDiff d = v.diff;
        if (d != null)
        {
            sb.append('|').append(d.buildOk).append(d.spellbookOk).append(d.pouchUnknown).append(d.missing).append(d.extra);
        }
        return sb.toString();
    }

    private void rebuild(GearReporter.View v)
    {
        removeAll();
        countdown = null;
        okLine = null;
        GearSet set = v.event.set;
        if (v.verifiedOk())
        {
            okLine = label("gear-card-ok", "", GREEN, Font.BOLD, LINE_PT);
            add(okLine);
            revalidate();
            repaint();
            return;
        }
        add(label("gear-card-title", "Required kit: " + set.name, Color.WHITE, Font.BOLD, TourneyPanel.HEADER_PT));
        if (set.placeholder) add(label("gear-card-placeholder", STUB_BANNER, AMBER));
        countdown = label("gear-card-countdown", " ", AMBER, Font.BOLD, LINE_PT);
        add(countdown);
        if (v.event.arena && !v.atArena) add(label("gear-card-where", AWAY_HINT, MUTED));
        if (v.kit == null)
        {
            add(label("gear-card-hint", NEVER_READ, AMBER));
            for (GearItem item : set.items)
            {
                JLabel row = itemLabel("gear-card-need-" + item.id, item.qty + " × " + escape(item.name), "", INFO);
                icons.apply(row, item.id, item.qty, item.stackable);
                add(row);
            }
            finish();
            return;
        }
        if (v.stale()) add(label("gear-card-hint", STALE_HINT, AMBER));
        GearDiff d = v.diff;
        add(d.buildOk
            ? label("gear-card-build", "Build: " + set.buildLabel, GREEN)
            : label("gear-card-build", "Pick " + set.buildLabel + " on the duel screen's Stats tab", RED, Font.BOLD, LINE_PT));
        for (GearDiff.Row r : d.missing) add(missingRow(r));
        for (GearDiff.Row r : d.extra)
        {
            JLabel row = itemLabel("gear-card-extra-" + r.itemId, "remove: " + (r.need == 0 ? r.have : r.overBy()) + " × " + escape(r.name), "", AMBER);
            icons.apply(row, r.itemId, Math.max(1, r.need == 0 ? r.have : r.overBy()), r.stackable);
            add(row);
        }
        if (set.spellbook != null)
        {
            String book = set.bookLabel == null ? set.spellbook : set.bookLabel;
            add(d.spellbookOk
                ? label("gear-card-spellbook", "Spellbook: " + book, GREEN)
                : label("gear-card-spellbook", "Spellbook: " + book + " — switch it in the kit tab's drop-down", RED, Font.BOLD, LINE_PT));
        }
        if (d.pouchUnknown) add(label("gear-card-pouch", POUCH_HINT, AMBER));
        finish();
    }

    private JLabel missingRow(GearDiff.Row r)
    {
        JLabel row = itemLabel("gear-card-missing-" + r.itemId, escape(r.name), " <font color='#ff6b6b'>" + r.have + " / " + r.need + "</font>", INFO);
        icons.apply(row, r.itemId, r.need, r.stackable);
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        row.setToolTipText("Find it in the kit's supplies list (or the bank)");
        onClick(row, () -> actions.findItem(r.itemId, r.altIds, r.name));
        return row;
    }

    private void finish()
    {
        GearReporter.View v = current;
        var buttons = new JPanel();
        buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
        buttons.setOpaque(false);
        left(buttons);
        if (v.kit != null)
        {
            JButton copy = TourneyPanel.tabButton("Copy my setup", "gear-card-copy", this::onCopy);
            copy.setToolTipText("Copy the kit the plugin read as a gear-set catalog entry");
            buttons.add(copy);
            buttons.add(vgap(4));
        }
        if (!v.event.arena && v.diff != null && !v.diff.missing.isEmpty())
        {
            buttons.add(TourneyPanel.tabButton("Show missing in bank", "gear-card-bank", () -> actions.showMissing(current.missingIds())));
        }
        if (buttons.getComponentCount() > 0)
        {
            add(vgap(4));
            add(buttons);
        }
        revalidate();
        repaint();
    }

    private void onCopy()
    {
        GearKit kit = current.kit;
        if (kit == null) return;
        actions.copySetup(kit);
        JLabel done = label("gear-card-copied", COPIED, GREEN);
        for (Component c : getComponents())
        {
            if ("gear-card-copied".equals(c.getName())) remove(c);
        }
        add(done);
        revalidate();
        repaint();
    }

    private void refreshClock(GearReporter.View v)
    {
        GearTracker.GearEvent e = v.event;
        long nowS = v.nowMs / 1000L;
        boolean prep = e.prepOpen(nowS);
        String left = prep ? mmss(e.checkUntilS - nowS) : null;
        if (countdown != null)
        {
            String text = prep ? TournamentInfoCard.wrapEscaped(countdown.getFont(), TournamentInfoCard.TEXT_WIDTH,
                (e.checkRound > 0 ? "Round " + e.checkRound : "The round") + " starts in " + left + " — your kit must match") : " ";
            if (!text.equals(countdown.getText())) countdown.setText(text);
            countdown.setVisible(prep);
        }
        if (okLine != null)
        {
            String clock = prep ? " · " + (e.checkRound > 0 ? "round " + e.checkRound : "the round") + " starts in " + left : "";
            String text = TournamentInfoCard.wrapEscaped(okLine.getFont(), TournamentInfoCard.TEXT_WIDTH, "Kit matches " + escape(e.set.name) + clock);
            if (!text.equals(okLine.getText())) okLine.setText(text);
        }
    }

    /** A plain line of text, wrapped to the card's width. */
    private static JLabel label(String name, String text, Color fg)
    {
        return label(name, text, fg, Font.PLAIN, LINE_PT);
    }

    /** A line of text, wrapped to the card's width. */
    private static JLabel label(String name, String text, Color fg, int style, float pt)
    {
        var l = new JLabel();
        l.setName(name);
        l.setForeground(fg);
        wrap(font(l, style, pt), text);
        return l;
    }

    /** An item row: escaped text wrapped to the width left beside its item
     *  icon, then {@code suffix} markup (may be empty) on the last line. */
    private static JLabel itemLabel(String name, String escaped, String suffix, Color fg)
    {
        var l = new JLabel();
        l.setName(name);
        l.setForeground(fg);
        plain(l, ITEM_PT);
        l.setText("<html>" + TournamentInfoCard.wrapInner(l.getFont(), TournamentInfoCard.TEXT_WIDTH - ICON_ROOM_PX, escaped) + suffix + "</html>");
        return l;
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.text.*;
import java.util.*;
import javax.swing.*;
import javax.swing.table.*;
import static com.pvp.leaderboard.util.JsonLenient.*;

/** The "Popout Match History" table; its dialog has a fixed size and is never packed. */
public class HistoryPanel extends JPanel
{
    private final DefaultTableModel tableModel = new DefaultTableModel(new String[]{"Res", "Opponent", "Type", "Match", "Change", "Time"}, 0);

    public HistoryPanel()
    {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createTitledBorder("Match History"));

        var table = new JTable(tableModel);
        table.setFillsViewportHeight(true);
        table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
        int[] widths = {40, 140, 60, 220, 180, 160};
        for (int i = 0; i < widths.length; i++)
        {
            table.getColumnModel().getColumn(i).setPreferredWidth(widths[i]);
        }
        add(new JScrollPane(table), BorderLayout.CENTER);
    }

    public void setMatches(JsonArray matches)
    {
        SwingUtilities.invokeLater(() -> {
            tableModel.setRowCount(0);
            if (matches == null) return;

            for (JsonElement e : matches)
            {
                JsonObject match = e.getAsJsonObject();
                tableModel.addRow(new Object[]{
                    optString(match, "result"),
                    optString(match, "opponent_id"),
                    match.has("bucket") ? match.get("bucket").getAsString().toUpperCase() : "Unknown",
                    computeRank(match, "player_") + " vs " + computeRank(match, "opponent_"),
                    computeRatingChangePlain(match),
                    match.has("when") ? new SimpleDateFormat("MM/dd/yyyy HH:mm").format(new Date(match.get("when").getAsLong() * 1000)) : ""});
            }
        });
    }

    private static String computeRank(JsonObject match, String prefix)
    {
        String rank = optString(match, prefix + "rank", null);
        if (rank == null) return "Unknown";
        int division = optInt(match, prefix + "division", 0);
        return rank + (division > 0 ? " " + division : "");
    }

    /** The capped label, else the backend's MMR delta, else "-". The backend's
     *  one {@code rating_change} builder ({@code backend/core/match_rating_change.py})
     *  always writes {@code mmr_delta} and omits the object otherwise. */
    private static String computeRatingChangePlain(JsonObject match)
    {
        if (PortalCap.isCapped(match))
        {
            return PortalCap.LABEL;
        }
        double delta = optDouble(optObject(match, "rating_change"), "mmr_delta", Double.NaN);
        return Double.isNaN(delta) ? "-" : String.format("%+.2f MMR", delta);
    }
}

package com.pvp.leaderboard.ui;

import lombok.*;
import com.pvp.leaderboard.*;
import com.pvp.leaderboard.service.*;
import java.awt.*;
import java.awt.event.*;
import java.net.*;
import java.nio.charset.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import net.runelite.client.util.*;
import javax.swing.Timer;
import static com.pvp.leaderboard.ui.Ui.*;

public class LoginPanel extends JPanel
{
    private static final int MAX_SEARCHES = 10;

    /** Discord brand "blurple" (#5865F2) — matches flipping-copilot's button. */
    private static final Color BLURPLE = new Color(88, 101, 242);

    private final DiscordLogin discordLogin;
    private final Consumer<String> onSearch;
    private final Runnable onLoginState;

    private JTextField searchField;
    private JButton searchBtn;
    @Getter private JButton loginButton;

    private boolean loggingIn = false;
    private boolean isLoggedIn = false;

    // Rate limiting for plugin search (10 per minute)
    private final Deque<Long> searchTimes = new ArrayDeque<>();

    /** Both callbacks are always wired (the dashboard passes them). */
    public LoginPanel(DiscordLogin discordLogin, Consumer<String> onSearch, Runnable onLoginState)
    {
        this.discordLogin = discordLogin;
        this.onSearch = onSearch;
        this.onLoginState = onLoginState;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(pad(4, 4, 4, 4));
        setMaximumSize(new Dimension(220, 85));
        setPreferredSize(new Dimension(220, 85));

        initUI();
    }

    private static final String PLACEHOLDER = "Player to search";

    private void initUI()
    {
        searchField = new JTextField(PLACEHOLDER);
        searchField.setHorizontalAlignment(JTextField.CENTER);
        searchField.setForeground(Color.GRAY);
        maxH(searchField, 25);
        left(searchField);
        searchField.addFocusListener(new FocusAdapter() {
            @Override
            public void focusGained(FocusEvent e) {
                if (searchField.getText().equals(PLACEHOLDER)) {
                    searchField.setText("");
                    searchField.setForeground(null);
                }
            }
            @Override
            public void focusLost(FocusEvent e) {
                if (searchField.getText().isEmpty()) {
                    searchField.setText(PLACEHOLDER);
                    searchField.setForeground(Color.GRAY);
                }
            }
        });
        searchField.addActionListener(e -> searchHere());
        add(searchField);

        add(vgap(4));

        var btnPanel = new JPanel(new GridLayout(1, 2, 4, 0));
        left(btnPanel);
        maxH(btnPanel, 40);

        var siteBtn = new JButton("<html><center>Website<br>Search</center></html>");
        siteBtn.addActionListener(e -> searchSite());

        searchBtn = new JButton("<html><center>Plugin<br>Search</center></html>");
        searchBtn.addActionListener(e -> searchHere());

        btnPanel.add(siteBtn);
        btnPanel.add(searchBtn);
        add(btnPanel);

        // Hoisted into the dashboard's community box, which sizes it.
        // Discord blurple (#5865F2), matching flipping-copilot's login button.
        loginButton = new JButton("Login with Discord");
        loginButton.setBackground(BLURPLE);
        loginButton.setForeground(Color.WHITE);
        loginButton.setOpaque(true);
        loginButton.setFocusPainted(false);
        loginButton.addActionListener(e -> handleLogin());
    }

    /** RuneScape name format: 1-12 letters, digits, spaces, underscores or
     *  hyphens. Rejects null, blank and the 16-character placeholder. */
    private boolean isValidUsername(String username)
    {
        if (username == null) return false;
        String trimmed = username.trim();
        if (trimmed.isEmpty() || trimmed.length() > 12) return false;
        // Allow alphanumeric, spaces, underscores, and hyphens (RuneScape username format)
        return trimmed.matches("^[a-zA-Z0-9 _-]+$");
    }

    private String normalizeUsername(String username)
    {
        if (username == null) return null;
        // Normalize: trim, lowercase, collapse multiple spaces to single space
        return username.trim().toLowerCase().replaceAll("\\s+", " ");
    }

    private void searchSite()
    {
        String username = searchField.getText();
        if (username.trim().isEmpty() || PLACEHOLDER.equals(username))
        {
            LinkBrowser.browse(PvpConsts.SITE_URL);
            return;
        }
        if (!isValidUsername(username)) return;
        // A valid name encodes to URL-safe text, so the https link always opens.
        LinkBrowser.browse(PvpConsts.SITE_URL + "/profile.html?player="
            + URLEncoder.encode(normalizeUsername(username), StandardCharsets.UTF_8));
    }

    private void searchHere()
    {
        String username = searchField.getText();
        if (!isValidUsername(username))
        {
            return;
        }

        // Rate limit: 10 searches per minute
        if (!checkLimit())
        {
            // Show rate limit feedback briefly
            searchBtn.setText("Wait...");
            Timer timer = new Timer(1000, e -> searchBtn.setText("Search"));
            timer.setRepeats(false);
            timer.start();
            return;
        }

        onSearch.accept(normalizeUsername(username));

        searchField.setText(PLACEHOLDER);
        searchField.setForeground(Color.GRAY);
        searchField.transferFocus();
    }

    private boolean checkLimit()
    {
        long now = System.currentTimeMillis();
        long oneMinuteAgo = now - 60_000;

        // Remove timestamps older than 1 minute
        while (!searchTimes.isEmpty() && searchTimes.peekFirst() < oneMinuteAgo)
        {
            searchTimes.pollFirst();
        }

        // Check if we've exceeded the limit
        if (searchTimes.size() >= MAX_SEARCHES)
        {
            return false; // Rate limited
        }

        // Record this search
        searchTimes.addLast(now);
        return true;
    }

    private void handleLogin()
    {
        if (loggingIn)
        {
            // The button doubles as "Cancel login" while a handshake is in
            // flight (the OAuth redirect now lands on a hosted page, so login
            // takes a browser round-trip + polling).
            discordLogin.cancelLogin();
            setLoginBusy(false);
            return;
        }
        if (isLoggedIn)
        {
            setLoggedIn(false);
            discordLogin.logout();
            onLoginState.run();
            return;
        }

        // Use Discord OAuth flow. The login state is read on the Swing
        // thread; no logout can happen meanwhile, the button reads Cancel.
        setLoginBusy(true);
        discordLogin.login().whenComplete((success, ex) -> SwingUtilities.invokeLater(() -> {
            setLoginBusy(false);
            if (Boolean.TRUE.equals(success) && discordLogin.isLoggedIn())
            {
                setLoggedIn(true);
                onLoginState.run();
            }
        }));
    }

    /** The button stays enabled while busy so the user can cancel the handshake. */
    private void setLoginBusy(boolean busy)
    {
        loggingIn = busy;
        loginButton.setText(busy ? "Cancel login" : (isLoggedIn ? "Logout" : "Login with Discord"));
        searchField.setEnabled(!busy);
    }

    public void setLoggedIn(boolean loggedIn)
    {
        isLoggedIn = loggedIn;
        loginButton.setText(loggedIn ? "Logout" : "Login with Discord");
    }

    public void setPluginSearchText(String text)
    {
        searchField.setText(text);
    }

    public String getPluginSearchText()
    {
        String text = searchField.getText();
        return PLACEHOLDER.equals(text) ? "" : text;
    }
}

