/**
 * Matchmaking Lobby UI — pure presentational panel that reads through a
 * {@link LobbyService} seam. The production implementation is
 * {@code WebSocketLobbyService} (wire adapter).
 *
 * <p>The panel owns <b>presentation</b> only — every roster member,
 * incoming invite, fight-session transition, and match-found event
 * comes from the service via the {@link LobbyEventListener} callbacks
 * defined on this class. The panel never seeds its own data or runs
 * its own timers.
 *
 * <p>Outgoing-invite tracking is the one piece of state the panel still
 * keeps locally — {@link #outgoingInvitesByOpponent} mirrors what the
 * user has sent so the per-row {@code [Invited M:SS]} chip + countdown
 * can render without round-tripping the service for every paint. Keyed
 * by the opponent's canonical {@code player_id} (the lowercased display
 * name). The display-cased {@code name} is also pushed alongside
 * {@code player_id} on every roster row + invite-received push so the
 * panel can render the proper-cased label without losing the canonical
 * lookup key.
 */
@Slf4j
public class MatchmakingLobbyPanel extends JPanel implements LobbyEventListener
{
    /** Human-readable rank labels derived once from {@link RankUtils#THRESHOLDS}. */
    private static final String[] RANK_LABELS = PlayerCard.RANK_LABELS;

    /** Root card keys: the gate — the <b>queue view</b> every player
     *  rests on: region / style / build picks and the
     *  {@link QueueGateSection} with the one <b>Queue for Matchmaking</b>
     *  button —, the roster (built, never attached to the card host),
     *  and the full-screen fight-setup view (Pick Style → optional
     *  sub-location → Meet At) that takes over the panel between [Fight] /
     *  a queue match and "Back to queue". The card-key strings double
     *  as {@link Component#getName()} on each card's root panel so tests
     *  (and any future "which card am I on?" diagnostic) can find the
     *  currently-visible card by name. Every switch goes through
     *  {@link #showCard(String)}. */
    public static final String CARD_GATE = "gate";
    public static final String CARD_FIGHT = "fight";
    /** Plan 10 F.1: the matchmaking queue's "Searching…" card
     *  ({@link QueueSearchingPanel}), shown while {@code queue/state} says
     *  searching and never over a fight being set up. */
    public static final String CARD_QUEUE = "queue";

    /** Stable {@link Component#getName()} on {@code rootCardHost} so
     *  tests can locate it without walking layout indices. */
    public static final String ROOT_NAME = "matchmaking-root-cards";

    /** Shared font size for every header in the pre-lobby gate
     *  ("Set up matchmaking", "Your region", "Pick your styles") and for the
     *  region dropdown's text — so the whole gate reads as one block.
     *
     *  <p>Was 18pt; matched down to 16pt to align with
     *  {@code Dashboard.NAV_FONT_PT} (which dropped from 18→16 to keep
     *  "Player Lookup" from clipping). At 18pt + bold the wider gate
     *  headers ("Pick your styles") were also clipping on the right edge
     *  of the 215px sidepanel. */
    private static final float GATE_PT = 16f;

    /** Region short codes used both as the dropdown values and as
     *  {@link LobbyMember#region}. Keep order stable — gate / lobby dropdowns
     *  share the same indexing. */
    private static final String[] REGION_CODES =
        {"NA-E", "NA-W", "EU", "BR", "OCE", "Other"};

    /** Human-readable labels paired with {@link #REGION_CODES} (same order). */
    private static final String[] REGION_LABELS =
        {"NA East", "NA West", "EU", "Brazil", "OCE", "Other"};

    /** Default region used when the user hasn't explicitly picked one yet. */
    private static final String DEFAULT_REGION = "NA-E";
    /** The user's own region — picked once at the gate. Surfaced as the
     *  region chip on incoming-invite cards' Meet At view (so the receiver
     *  knows where the sender's coming from); never used to filter the
     *  roster. Players see everyone in the lobby regardless of region. */
    private String selfRegion = DEFAULT_REGION;

    private CardLayout rootCards;
    /** Container that owns {@link #rootCards}. Held as a field because
     *  the panel's top-level is now {@link BorderLayout} (with the error
     *  banner in NORTH); {@code rootCards.show(...)} calls must pass
     *  this host, not {@code this}. */
    private JPanel rootCardHost;

    /** Held as a field so {@link #resetGateOptions()} can put the region
     *  back to the default. */
    private JComboBox<String> regionCombo;

    // -------------------- Plan 10 F.1: matchmaking queue --------------------
    /** Queue transport. Inert until {@link #setQueue} wires the real
     *  one (the plugin does, config-gated); the gate hides the queue block
     *  while it is inert. */
    private QueueService queueService = new NoOpQueue();
    /** The gate's queue block (wait picker, queue button); visibility
     *  follows {@link QueueService#isAvailable()}. */
    private QueueGateSection queueSection;
    /** Holds the queue section's rank-range slider above the gate title;
     *  shown with the queue block while logged in. */
    private JPanel rangeHolder;
    /** The {@link #CARD_QUEUE} card; ticked at 1 Hz by
     *  {@link #onFightTick()} while it is the visible card. */
    private QueueSearchingPanel queueCard;
    /** The zone and "now" of the recent-joins lines. */
    @Setter(AccessLevel.PACKAGE) private Clock recentClock = Clock.systemDefaultZone();
    /** The Matchmaking tab is open: the side panel shown with this tab selected. */
    private boolean recentOpen;

    /** Container for the fight-setup card (rebuilt every time the user enters
     *  or transitions through the Pick Style → sub-loc → Meet At flow). Held
     *  as a field so {@link #showSetup} can swap its contents and
     *  {@link #rootCards} can switch to it. */
    private JPanel setupBox;

    /** Active fight session occupying the FIGHT card. One at a time — set
     *  on opponent-accept (sender side) or on receiver Accept Fight click;
     *  cleared on Back to queue, confirm-window expiry, or fight
     *  completion. Null while in the lobby. */
    private LocalFightState currentFight;

    /** 1Hz ticker that drives all live countdowns: row [Invited M:SS] chips,
     *  the FIGHT card's confirm-window label, and the two TTL expiry
     *  paths (10-min invite + confirm window). Started in the constructor;
     *  stopped by {@link #shutdown()}. */
    private Timer fightTicker;

    /** How long the Confirm Fight card ignores clicks on its buttons after it appears. */
    static final long CLICK_DELAY = 1_000L;

    /** The Confirm Fight card's two buttons for a queue match. */
    static final String CONFIRM_TEXT = "Confirm";
    static final String DECLINE_TEXT = "Decline";

    /** The exit button of every fight card except a queue match's Confirm card. */
    static final String BACK_TEXT = "Back to queue";

    /** Monotonic milliseconds read by the Confirm Fight card's click delay. */
    private LongSupplier clickClockMs = MatchmakingLobbyPanel::monotonicMs;

    /** Replaces the clock the Confirm Fight card's click delay reads. */
    void setClickClock(LongSupplier clockMs)
    {
        clickClockMs = clockMs == null ? MatchmakingLobbyPanel::monotonicMs : clockMs;
    }

    /** Monotonic milliseconds read by the Confirm Fight card's confirm window. */
    private LongSupplier confirmClock = MatchmakingLobbyPanel::monotonicMs;

    /** Replaces the clock the Confirm Fight card's confirm window reads. */
    void setConfirmWindowClock(LongSupplier clockMs)
    {
        confirmClock = clockMs == null ? MatchmakingLobbyPanel::monotonicMs : clockMs;
    }

    private static long monotonicMs()
    {
        return System.nanoTime() / 1_000_000L;
    }

    /** {@code true} once {@link #CLICK_DELAY} has passed since {@code shownAtMs}. */
    private boolean clickReady(long shownAtMs)
    {
        return clickClockMs.getAsLong() - shownAtMs >= CLICK_DELAY;
    }

    /** Panel-local UI state for the active mutual-confirm session. Wraps
     *  the immutable {@link FightSession} pushed by the service with two
     *  mutable flags the panel toggles in response to the local user
     *  clicking Confirm + the service's {@code onFightConfirmedByPeer} push.
     *
     *  <p><b>Clock-independent countdown.</b> The confirm window is
     *  driven by the session's {@link FightSession#confirmMs}
     *  measured from {@link #startMs} (a monotonic clock reading
     *  captured the instant the fight was proposed) — NOT by comparing
     *  {@link System#currentTimeMillis()} against the server's absolute
     *  {@code confirmByMs}. The monotonic clock
     *  ({@link System#nanoTime()} unless a test replaces it) is immune
     *  to the wall clock being set wrong, to NTP step corrections, to
     *  manual clock edits, and to DST jumps. This fixes the QA report
     *  where a player whose computer clock was wrong saw the
     *  Confirm-Fight card flash and return to the lobby immediately
     *  instead of waiting the full window — with the old wall-clock
     *  comparison a clock running ahead of the server (or a
     *  seconds-as-ms units bug on the wire) produced an already-elapsed
     *  deadline, so {@code onFightTick} called {@code exitSetup()}
     *  on its very first tick.
     *
     *  <p>{@link #confirmBy} is retained as the server's advisory
     *  deadline (for logging / diagnostics) but is deliberately NOT used
     *  to time the local countdown. The server stays authoritative via
     *  its {@code lobby/match_found} and {@code lobby/session_expired}
     *  pushes, which can end the window early regardless of this timer.
     *
     *  <p>Fields {@link #opponent}, {@link #style}, {@link #build},
     *  {@link #location} are aliased directly from the immutable session
     *  bundle so existing rendering code that reads e.g.
     *  {@code s.opponent.name} keeps working without churn. */
    private static final class LocalFightState
    {
        final FightSession session;
        final LobbyMember opponent;
        final Style style;
        final BuildType build;
        final String location;
        /** Server's advisory absolute confirm deadline (epoch ms).
         *  Diagnostics only — see class doc; the countdown uses the
         *  monotonic {@link #startMs} + {@link #windowMs} instead. */
        final long confirmBy;
        /** Monotonic milliseconds the window is counted on. */
        final LongSupplier clockMs;
        /** Monotonic anchor captured at construction (fight-proposed
         *  time). Immune to wall-clock changes — the basis for all
         *  elapsed-time math below. */
        final long startMs;
        /** Confirm-window length: the session's
         *  {@link FightSession#confirmMs}. Package-private + mutable
         *  ONLY so unit tests can force the window to zero to
         *  deterministically simulate "window elapsed" without sleeping
         *  (mirrors the existing mutable
         *  {@link #iConfirmed}/{@link #peerConfirmed} test seam). */
        long windowMs;
        boolean iConfirmed;
        boolean peerConfirmed;
        /** Both players confirmed: the Fight ready view is showing. */
        boolean fightReady;

        LocalFightState(FightSession session)
        {
            this(session, MatchmakingLobbyPanel::monotonicMs);
        }

        LocalFightState(FightSession session, LongSupplier clockMs)
        {
            this.session = session;
            opponent = session.opponent;
            style = session.style;
            build = session.build;
            location = session.location;
            confirmBy = session.confirmByMs;
            this.clockMs = clockMs;
            startMs = clockMs.getAsLong();
            windowMs = session.confirmMs;
        }

        /** Real milliseconds elapsed since the fight was proposed,
         *  measured monotonically. Never negative; never affected by
         *  wall-clock changes. */
        long getElapsedMs()
        {
            return Math.max(0L, clockMs.getAsLong() - startMs);
        }

        /** Milliseconds left in the confirm window, clamped at 0. */
        long remainingMs()
        {
            return Math.max(0L, windowMs - getElapsedMs());
        }

        /** True once the full confirm window has elapsed in real time. */
        boolean confirmOver()
        {
            return getElapsedMs() >= windowMs;
        }
    }

    /** Backing {@link LobbyService} — {@code WebSocketLobbyService} in
     *  production. */
    private final LobbyService service;

    /** Per-style match-count gate (anti-smurf: need
     *  {@link JoinGate#THRESHOLD} kills + deaths in a style before
     *  the user can advertise it). Drives the locked-style rendering on
     *  the gate's style toggles + the [Refresh count] / "Updated X min
     *  ago" status row. The server enforces the same rule at
     *  {@code lobby/join} (returning {@code SMURF_GUARD}); this client
     *  gate is UX-only.
     *
     *  <p>Default to {@link NoOpGate} so the panel is
     *  constructible in tests that don't need the anti-smurf UX — the
     *  no-op reports every style unlocked, so the server-side check is
     *  the safety net. */
    private final JoinGate joinGate;

    private final Runnable gateListener = this::onGateChange;

    /** Notice shown <i>in lieu of</i> the gate when the user isn't
     *  logged into OSRS. Driven by {@link JoinGate#isLoggedIn()}
     *  via {@link #applyGate()}; flips on/off whenever the
     *  gate listener fires. */
    private JLabel loginNotice;

    /** Sub-panel that holds every gate widget below the title (region
     *  picker, queue block).
     *  Hidden as one unit when
     *  {@link JoinGate#isLoggedIn()} is {@code false} so the user
     *  sees a clean "Please log into the game" notice instead of a
     *  half-greyed-out gate they can't interact with. */
    private JPanel gateContent;

    /** Eager game-state signal — returns true the moment
     *  {@code GameState.LOGGED_IN} fires, before the 10-tick
     *  name-resolve delay that gates {@link JoinGate#isLoggedIn()}.
     *  Used by {@link #applyGate()} to distinguish "truly
     *  logged out" (show "Please log into the game") from "logged in
     *  but waiting for player name + match counts to resolve" (show
     *  "Loading\u2026") so the brief startup window doesn't flash a
     *  stale logged-out prompt to a user who's already in-game.
     *
     *  <p>Optional — when null, the panel falls back to the legacy
     *  two-phase view (gate-or-please-login) so test fixtures that
     *  don't wire it still render the same as before. */
    private BooleanSupplier inGame;

    /** In-game popup hook for the "fight locked in" wire moment (the
     *  inviter-side or invitee-side equivalent of receiving an invite
     *  popup, but at the next step in the flow — invite accepted, both
     *  parties about to confirm). Wired by the plugin from
     *  {@link com.pvp.leaderboard.overlay.MatchFoundNotificationOverlay}.
     *  Null in unit tests / during the brief startup window before the
     *  plugin wires the overlay; the notification simply doesn't fire
     *  in those cases (the panel's in-card transition to the
     *  Confirm-Fight view is still authoritative). */
    @Setter private MatchAlert matchFoundNotifier;

    /** Persistence backend for gate selections (region / styles / builds /
     *  rank-slider bounds). Always non-null —
     *  ctor overloads that don't supply one fall back to
     *  {@link LobbyPrefs#inMemory()}. */
    private final LobbyPrefs prefs;

    /** Top-of-panel inline error banner. Persists across the gate / lobby /
     *  fight cards (lives above the {@link CardLayout}) so a SMURF_GUARD
     *  triggered from the gate doesn't vanish when the user navigates
     *  away. {@link #errorTimer} auto-dismisses after
     *  {@link #DISMISS_MS}. Driven by
     *  {@link #onError(String, String)} via the localized message table
     *  in {@link LobbyErrors}. */
    private JPanel errorBanner;
    private JLabel errorLabel;
    private Timer errorTimer;

    /** Auto-dismiss for the error banner. Six seconds is a tradeoff:
     *  long enough that a user with their eyes off the panel still
     *  catches the message; short enough that stale errors don't
     *  permanently clutter the UI. User can dismiss manually via the
     *  banner's [×] button anytime. */
    private static final int DISMISS_MS = 6_000;

    /** Reconnect-status banner pinned above the error banner. Shown
     *  whenever {@link LobbyService#isConnected()} returns
     *  {@code false} and {@link LobbyService#getRetryAtMs()}
     *  returns a non-zero scheduled retry. Displays the localized
     *  reconnect copy + a live countdown of seconds remaining until
     *  the next attempt. Driven by {@link #retryTicker} at
     *  1 Hz; we deliberately use polling instead of a callback from
     *  {@link com.pvp.leaderboard.service.socket.SocketMgr}
     *  because the countdown needs a 1Hz redraw anyway — a callback
     *  would only add complexity. */
    private JPanel retryBanner;
    private JLabel retryLabel;
    private Timer retryTicker;

    public MatchmakingLobbyPanel(LobbyService service, JoinGate joinGate)
    {
        this(service, joinGate, LobbyPrefs.inMemory());
    }

    public MatchmakingLobbyPanel(LobbyService service, JoinGate joinGate,
                                 LobbyPrefs prefs)
    {
        if (service == null) throw new IllegalArgumentException("LobbyService is required");
        this.service = service;
        // NoOpGate is the safe fallback — reports every style
        // unlocked so a wiring bug doesn't lock the user out (server
        // still has the final word via the v2 SMURF_GUARD check).
        this.joinGate = joinGate != null ? joinGate : new NoOpGate();
        // In-memory fallback so test call sites + the existing
        // NoOpLobby production placeholder continue to build
        // without a real ConfigManager. Real persistence kicks in once
        // PvPLeaderboardPlugin wires the Guice-provided variant.
        this.prefs = prefs != null ? prefs : LobbyPrefs.inMemory();
        // Restore previously-persisted gate state into the in-memory
        // fields BEFORE buildGate() initialises the widgets — the
        // gate's region combo, style toggles and build toggles read from
        // these fields.
        loadPrefs();
        // Outer = BorderLayout so the error banner can pin to NORTH
        // above the cards. The card-switching subpanel goes in CENTER
        // and owns the gate/lobby/fight subviews via {@link #rootCards}.
        // Was a top-level CardLayout pre-banner; that meant any pinned
        // chrome had to be duplicated into every card.
        setLayout(new BorderLayout());
        setBorder(pad(4, 4, 4, 4));

        errorBanner = buildError();
        errorBanner.setVisible(false);
        retryBanner = buildBanner();
        retryBanner.setVisible(false);
        // Stack the two banners (reconnect on top, error below) in a
        // single NORTH slot. BorderLayout allows only one component
        // per region, so the vertical box is the cheapest way to keep
        // both pinned without rebuilding the outer layout. Reconnect
        // sits above the error banner because it represents a more
        // urgent, ongoing condition — a transient validation error
        // shouldn't visually hide the persistent "we're disconnected"
        // state.
        var northStack = new JPanel();
        northStack.setLayout(new BoxLayout(northStack, Y_AXIS));
        northStack.setOpaque(false);
        northStack.add(retryBanner);
        northStack.add(errorBanner);
        add(northStack, NORTH);

        rootCards = new CardLayout();
        rootCardHost = new JPanel(rootCards);
        rootCardHost.setName(ROOT_NAME);
        JPanel gateCard = buildGate();
        gateCard.setName(CARD_GATE);
        rootCardHost.add(gateCard, CARD_GATE);
        setupBox = new JPanel(new BorderLayout());
        setupBox.setName(CARD_FIGHT);
        rootCardHost.add(setupBox, CARD_FIGHT);
        // Plan 10 F.1: the queue's Searching card. The two buttons route
        // straight to the transport; the card itself only renders.
        queueCard = new QueueSearchingPanel(() -> queueService.expandRange(), () -> queueService.leave());
        queueCard.setName(CARD_QUEUE);
        rootCardHost.add(queueCard, CARD_QUEUE);
        add(rootCardHost, CENTER);
        showCard(CARD_GATE);

        fightTicker = new Timer(1000, e -> onFightTick());
        fightTicker.setRepeats(true);
        fightTicker.start();

        retryTicker = new Timer(1000, e -> refreshRetry());
        retryTicker.setRepeats(true);
        retryTicker.start();

        // Register for server pushes.
        this.service.setListener(this);
        this.service.start();

        // Re-render the gate's match-count status row + style-toggle
        // lock states whenever the gate refreshes. EDT marshalling lives
        // inside the gate impl (see ProfileGate#fireOnEdt).
        this.joinGate.addListener(gateListener);
    }

    // -------------------- UI construction --------------------

    /**
     * The queue view: the rank-range slider on top, then "Set up
     * matchmaking" with the user's region, the wait time and the one queue
     * button. The queue goes out as {@link QueueGateSection#QUEUE_STYLE} +
     * {@link QueueGateSection#QUEUE_BUILD}; there is nothing else to pick.
     */
    private JPanel buildGate()
    {
        var gate = new JPanel();
        gate.setLayout(new BoxLayout(gate, Y_AXIS));
        gate.setBorder(pad(18, 8, 18, 8));

        // Built first: its rank-range slider sits above the title.
        queueSection = new QueueGateSection(prefs, GATE_PT, this::onQueueClicked);
        rangeHolder = new JPanel(new BorderLayout());
        rangeHolder.setOpaque(false);
        left(rangeHolder);
        rangeHolder.setBorder(pad(0, 0, 12, 0));
        rangeHolder.add(queueSection.rangeSlider(), CENTER);
        pin(rangeHolder);
        gate.add(rangeHolder);

        var title = new JLabel("Set up matchmaking");
        bold(title, GATE_PT);
        gate.add(title);
        gate.add(lgap(8));

        // ---- Logged-out notice (shown in lieu of the rest of the gate) ----
        // Lives next to {@link #gateContent} as a sibling; exactly one
        // of the two is visible at a time. Pre-construction default is
        // "logged out" since the lobby gate is built during the
        // dashboard ctor — well before any GameState event fires.
        // applyGate() at the bottom of this method picks the
        // right initial visibility from the gate.
        //
        // Explicit {@code <br>} rather than {@code <div style='width:'>}
        // — the latter under Substance L&F miscomputes wrap and clipped
        // the word "up" out of the rendered text. With a hand-broken
        // line we get deterministic layout matching the sidepanel's
        // ~209px usable width (225 sidepanel - 16 horizontal padding).
        loginNotice = new JLabel(
            "<html>Please log into the game<br>to set up matchmaking.</html>");
        bold(loginNotice, 15f);
        loginNotice.setForeground(new Color(0xcccccc));
        // Cap height to the rendered preferred height so BoxLayout
        // doesn't stretch the label vertically into the space freed up
        // by the hidden gateContent. Was Integer.MAX_VALUE which made
        // BoxLayout give the entire empty cell to the label — text
        // visually pinned to the bottom of the gate.
        Dimension noticePref = loginNotice.getPreferredSize();
        loginNotice.setMaximumSize(new Dimension(noticePref.width, noticePref.height));
        gate.add(loginNotice);

        // Wrap everything else in a sub-panel so we can hide/show as
        // one unit without playing whack-a-mole with individual
        // setVisible() calls every time a new gate widget is added.
        gateContent = new JPanel();
        gateContent.setLayout(new BoxLayout(gateContent, Y_AXIS));
        left(gateContent);
        gateContent.setOpaque(false);

        // ---- Region picker ----
        // Header + dropdown both share the title's 18pt BOLD treatment so the
        // gate reads as one consistent typographic block (per spec: match the
        // "Set up matchmaking" title).
        var regionTitle = new JLabel("Your region");
        bold(regionTitle, GATE_PT);
        gateContent.add(regionTitle);
        gateContent.add(lgap(4));

        regionCombo = new JComboBox<>(REGION_LABELS);
        regionCombo.setSelectedIndex(regionIndex(selfRegion));
        plain(regionCombo, GATE_PT);
        // Bumped from 32 to 40 to fit the larger 18pt font without clipping descenders.
        maxH(regionCombo, 40);
        left(regionCombo);
        regionCombo.addActionListener(e ->
        {
            int idx = regionCombo.getSelectedIndex();
            if (idx >= 0)
            {
                selfRegion = REGION_CODES[idx];
                prefs.setRegion(selfRegion);
            }
        });
        gateContent.add(regionCombo);
        gateContent.add(lgap(14));

        // ---- Matchmaking queue: wait time + the queue button ----
        // Hidden until the plugin wires a real QueueService (config-gated).
        queueSection.setVisible(queueService.isAvailable());
        gateContent.add(queueSection);

        // Mount the wrapper so all gate widgets show up under the
        // title. applyGate() then flips visibility based on
        // the current JoinGate.isLoggedIn() snapshot — the panel
        // is built during the dashboard ctor (well before any GameState
        // event fires) so the initial render is correct.
        gate.add(gateContent);
        applyGate();

        return gate;
    }

    /** The rank-range slider shows with the queue block: logged in, queue on. */
    private void refreshRange()
    {
        if (rangeHolder == null || gateContent == null) return;
        rangeHolder.setVisible(gateContent.isVisible() && queueService.isAvailable());
    }

    /** Toggles the gate between "logged in" and "logged out" views by
     *  swapping visibility of {@link #loginNotice} and
     *  {@link #gateContent}. Called from the gate-listener every time
     *  the {@link JoinGate} fires (which includes onLogin /
     *  onLogout transitions). EDT-only — the listener already
     *  marshals.
     *
     *  <p>On logout a fight view with a session keeps its card; otherwise
     *  a search is left and the root card goes back to {@link #CARD_GATE}.
     *  {@link #selectedStyles}/{@link #selectedBuildTypes}/{@link #selfRegion}
     *  are kept. A login changes no card. */
    private void applyGate()
    {
        if (gateContent == null || loginNotice == null) return;
        boolean gateReady = joinGate.isLoggedIn();
        // Eager game-state probe — true the instant
        // GameState.LOGGED_IN fires, before the 10-tick name-resolve
        // delay that gates JoinGate.onLogin(). We use this to
        // pick which logged-out copy to show: a true logged-out user
        // (game state != LOGGED_IN) sees the "Please log into the
        // game" prompt, while a freshly-logged-in user inside the
        // 10-tick startup window sees "Loading…" instead — the gate
        // listener fires again once name + counts resolve and flips
        // gateReady to true, hiding the notice entirely.
        // Defaults to true when the supplier is unwired (test
        // fixtures, gateless construction paths) so the legacy
        // two-phase notice still works for those callers.
        boolean gameLoggedIn = inGame == null
            || inGame.getAsBoolean();

        if (gateReady)
        {
            loginNotice.setVisible(false);
            gateContent.setVisible(true);
        }
        else if (gameLoggedIn)
        {
            // Logged into OSRS but plugin still resolving identity +
            // smurf-guard counts. Show a low-key "Loading…" so the
            // user knows the panel saw their login and isn't broken.
            // Same hand-broken <br> markup as the logged-out copy
            // (see field doc) to dodge Substance's HTML-wrap clip bug.
            loginNotice.setText("<html>Loading\u2026</html>");
            loginNotice.setVisible(true);
            gateContent.setVisible(false);
        }
        else
        {
            loginNotice.setText(
                "<html>Please log into the game<br>to set up matchmaking.</html>");
            loginNotice.setVisible(true);
            gateContent.setVisible(false);
        }
        refreshRange();
        // BoxLayout doesn't auto-revalidate on child visibility changes
        // — force the parent gate panel to recompute its layout so the
        // viewport collapses around whichever child is visible.
        Container parent = gateContent.getParent();
        if (parent != null)
        {
            parent.revalidate();
            parent.repaint();
        }

        if (!gateReady)
        {
            // Active fight session pinning: the user is mid-confirm
            // (CARD_FIGHT) or already in MeetAt. World hops can briefly
            // pass through LOGIN_SCREEN, and an intentional logout
            // mid-confirm shouldn't yank the dialog out from under
            // the user. Keep CARD_FIGHT visible — the local
            // confirm-window ticker still drives exitSetup() if
            // the window elapses AND the peer hasn't confirmed
            // (onFightTick), and "Back to queue" is the user's manual
            // escape hatch. MeetAt has no auto-expiry; the user clicks
            // "Back to queue" when ready.
            // Backend rules: a logged-out user's fight session is
            // expired server-side on $disconnect, so a re-login won't
            // resume a real session — but the panel staying on
            // CARD_FIGHT gives the user visual continuity so they can
            // hop to the meeting world without losing their place.
            if (currentFight != null) return;
            // Plan 10 F.1: a logged-out player cannot fight — leave the
            // queue so the server stops searching for them.
            if (isOnCard(CARD_QUEUE)) queueService.leave();
            showCard(CARD_GATE);
        }
    }

    // -------------------- Plan 10 F.1: matchmaking queue --------------------

    /** Wires the queue transport. The plugin passes
     *  {@code WebSocketQueueService} while the {@code enableQuickMatch}
     *  config is on and {@link NoOpQueue} otherwise; either way the
     *  panel becomes the listener, starts the service and shows / hides the
     *  gate's queue block. Safe to call again on a config flip — a user
     *  left on the Searching card by an inert service is returned to the
     *  gate. */
    public void setQueue(QueueService svc)
    {
        QueueService previous = queueService;
        if (previous != null && previous != svc)
        {
            previous.setListener(null);
            previous.watchRecent(false);
        }
        queueService = svc == null ? new NoOpQueue() : svc;
        queueService.setListener(new QueueEvents());
        queueService.start();
        queueService.watchRecent(recentOpen);
        boolean available = queueService.isAvailable();
        if (queueSection != null)
        {
            queueSection.setVisible(available);
            // G-2: the wait time / rank range live in one row shared with
            // Discord — write the touched key on a local pick, read the row
            // back on wire-up. One key per frame: pushing both would let a
            // wait change overwrite a rank range set on Discord.
            queueSection.setOnWaitChanged(this::pushWait);
            queueSection.setOnRangeChanged(this::pushRange);
        }
        refreshRange();
        if (available) queueService.requestPrefs();
        if (!available) exitQueue(null);
    }

    /** The Matchmaking tab opened or closed: the queue asks for the recent joins while it is open; closing clears them. */
    public void watchRecent(boolean open)
    {
        recentOpen = open;
        queueService.watchRecent(open);
        if (!open) showRecent(List.of());
    }

    /** The recent joins in both views. */
    private void showRecent(List<RecentJoin> joins)
    {
        queueSection.recent.show(joins, recentClock);
        queueCard.recent.show(joins, recentClock);
    }

    /** Local wait pick → the shared prefs row, so the Discord modal prefills with it. */
    private void pushWait()
    {
        if (queueSection != null) queueService.sendWaitPref(queueSection.waitPrefS());
    }

    /** Local rank-range pick → the shared prefs row. The full span sends an
     *  explicit null so the row is cleared rather than left at Discord's value. */
    private void pushRange()
    {
        if (queueSection == null) return;
        boolean rangeOn = queueSection.rangeEnabled();
        queueService.sendRange(rangeOn ? queueSection.rangeMinIdx() : QueueState.UNKNOWN,
            rangeOn ? queueSection.rangeMaxIdx() : QueueState.UNKNOWN);
    }

    /** "Queue for Matchmaking": NH + Main, the user's region, the slider's
     *  bounds when it is narrower than every rank, and the wait preference. */
    private void onQueueClicked()
    {
        if (queueSection == null) return;
        boolean rangeOn = queueSection.rangeEnabled();
        int minIdx = rangeOn ? queueSection.rangeMinIdx() : QueueState.UNKNOWN;
        int maxIdx = rangeOn ? queueSection.rangeMaxIdx() : QueueState.UNKNOWN;
        queueService.join(selfRegion, QueueGateSection.QUEUE_STYLE, QueueGateSection.QUEUE_BUILD,
            minIdx, maxIdx, queueSection.waitPrefS());
    }

    /** Every rank label, lowest first — the queue's rank-range slider reads them. */
    static String[] rankLabels()
    {
        return RANK_LABELS.clone();
    }

    /** Walks {@link #rootCardHost}'s children for the visible card and asks
     *  whether its name is {@code cardName}. CardLayout updates visibility
     *  synchronously on the EDT, so this read sees the live state. */
    private boolean isOnCard(String cardName)
    {
        if (rootCardHost == null) return false;
        for (Component c : rootCardHost.getComponents())
        {
            if (c.isVisible() && cardName.equals(c.getName())) return true;
        }
        return false;
    }

    // -------------------- cards --------------------

    /** The one way to switch root cards. A request for the roster lands
     *  on the queue view, and the incoming-invite strip above the cards
     *  is re-evaluated (hidden over the fight views). */
    private void showCard(String card)
    {
        if (rootCards == null || rootCardHost == null) return;
        rootCards.show(rootCardHost, card);
    }

    /** Stops the panel's timers and invite countdowns and unregisters it
     *  from the gate and the services. Idempotent. */
    public void shutdown()
    {
        joinGate.removeListener(gateListener);
        stopTimer(fightTicker);
        stopTimer(retryTicker);
        stopTimer(errorTimer);
        service.setListener(null);
        queueService.setListener(null);
    }

    private static void stopTimer(Timer t)
    {
        if (t != null) t.stop();
    }

    /** {@code queue/state searching}: render the card and show it — unless
     *  a fight is being set up (Confirm / Meet-At), which always outranks
     *  the queue card. */
    private void showSearch(QueueState state)
    {
        if (queueCard == null) return;
        queueCard.render(state);
        if (currentFight != null) return;
        showCard(CARD_QUEUE);
    }

    /** Leaves the Searching card (idle / timeout / inert service) for the
     *  gate; an optional banner explains why (expired, opponent declined,
     *  timeout). */
    private void exitQueue(String banner)
    {
        if (isOnCard(CARD_QUEUE)) showCard(CARD_GATE);
        if (banner != null) showError(banner);
    }

    /** The queue's server pushes (EDT — the service marshals). A match
     *  needs no handling here: the lobby's own {@code lobby/fight_proposed}
     *  arrives alongside {@code queue/matched} and {@link #onFightProposed}
     *  swaps to the Confirm Fight view as for any invite. An idle state that
     *  ends a queue match ({@link QueueState#endsMatch()}) closes its card. */
    private final class QueueEvents implements QueueEventListener
    {
        @Override
        public void onQueueState(QueueState state)
        {
            if (state == null) return;
            if (state.isSearching())
            {
                showSearch(state);
                return;
            }
            if (state.endsMatch()) closeMatch(state.fightId);
            exitQueue(QueueText.forIdleReason(state.reason));
        }

        @Override
        public void onQueueTimeout(QueueState state)
        {
            exitQueue(QueueText.forTimeout(state == null ? 0 : state.waitPrefS));
        }

        @Override
        public void onQueuePrefs(JsonObject prefs)
        {
            // G-2: the shared row, possibly last written from Discord.
            if (queueSection != null) queueSection.applyPrefs(QueuePrefs.fromJson(prefs));
        }

        @Override
        public void onQueueError(String code, String message)
        {
            showError(QueueText.forError(code, message));
        }

        @Override
        public void onRecentQueued(List<RecentJoin> joins)
        {
            if (recentOpen) showRecent(joins);
        }
    }

    /** EDT callback fired by {@link JoinGate#addListener}. Swaps the
     *  gate between "logged in" and "Please log into the game" views via
     *  {@link #applyGate()} — onLogin / onLogout transitions both
     *  fire through this listener. */
    private void onGateChange()
    {
        applyGate();
    }

    /** Pulls the last persisted gate selections (region / styles / builds /
     *  rank-slider bounds) into the in-memory fields.
     *  Called once from the ctor BEFORE {@link #buildGate()} so the
     *  widgets read the restored values when they construct.
     *
     *  <p>The field initialisers above remain the "first launch / no
     *  persistence" defaults; this method overrides them when the user
     *  has previously completed the gate. An invalid persisted set
     *  (zero styles or zero builds — possible if an older plugin version
     *  stored those) falls back to the field defaults so the gate stays
     *  usable. Out-of-range rank indices are clamped against
     *  {@link #RANK_LABELS}.length so a future RANK_LABELS shrink can't
     *  leave the slider pointing past the end. */
    private void loadPrefs()
    {
        selfRegion = prefs.getRegion(DEFAULT_REGION);
    }

    /** The lobby's form of a region code ({@code "na-w"} → {@code "NA-W"}); an unknown one upper-cased as sent, a blank one {@code null}. */
    static String regionCode(String code)
    {
        if (code == null || code.trim().isEmpty()) return null;
        String wanted = code.trim();
        for (String known : REGION_CODES)
        {
            if (known.equalsIgnoreCase(wanted)) return known;
        }
        return wanted.toUpperCase(Locale.ROOT);
    }

    /** Returns the index in {@link #REGION_CODES} matching {@code code}, or 0 if missing. */
    private static int regionIndex(String code)
    {
        for (int i = 0; i < REGION_CODES.length; i++)
        {
            if (REGION_CODES[i].equals(code)) return i;
        }
        return 0;
    }

    /** Wires the eager "is the local player in {@code GameState.LOGGED_IN}
     *  right now" signal — see {@link #inGame} doc for
     *  why this is separate from {@link JoinGate#isLoggedIn()}.
     *  Triggers an immediate {@link #applyGate()} so the
     *  notice flips to "Loading\u2026" the instant the supplier
     *  reports true (which it might already, if the user opened the
     *  panel post-login). */
    public void setInGame(BooleanSupplier supplier)
    {
        inGame = supplier;
        applyGate();
    }

    /** Run on the EDT after a queue match's Confirm Fight card is shown. */
    private Runnable shownHook = () -> { };

    /** Registers the callback run after a queue match's Confirm Fight card is shown. */
    void setShownHook(Runnable listener)
    {
        shownHook = listener == null ? () -> { } : listener;
    }

    private void notifyShown()
    {
        try
        {
            shownHook.run();
        }
        catch (RuntimeException e)
        {
        }
    }

    /** Strategy hook for the match-found popup. Mirror of
     *  {@link LobbyInviteNotifier} for the next step in the lobby
     *  flow. The production implementation is
     *  {@link com.pvp.leaderboard.overlay.MatchFoundNotificationOverlay}
     *  via a lambda wired from the plugin.
     *
     *  <p>{@code isInviter} carries the perspective: {@code true} when
     *  the local user originated the invite ({@link #outgoingInvitesByOpponent}
     *  contained this opponent at the moment {@code lobby/fight_proposed}
     *  arrived), {@code false} when the local user clicked Accept on
     *  an incoming card. The overlay flips its caption tail
     *  accordingly ({@code "<opp> accepted your invite"} vs just
     *  {@code "<opp>"}).
     *
     *  <p>{@code opponentNameColor} follows the same rank-tint rule
     *  as {@link LobbyInviteNotifier#showInvite}'s
     *  {@code senderNameColor} so the popup feels of-a-piece with the
     *  rest of the matchmaking UI.
     */
    @FunctionalInterface
    public interface MatchAlert
    {
        void showMatch(String fightId,
                       String opponentName,
                       String subtext,
                       Color opponentNameColor);
    }

    /** Public re-entry point for {@link #applyGate()} so the
     *  hosting plugin / dashboard can re-render the gate notice the
     *  instant a {@code GameStateChanged} event fires — the gate
     *  listener wired in this panel only fires after
     *  {@link JoinGate#onLogin()}, which is delayed 10 ticks for
     *  player-name resolve, so without an external poke from
     *  {@code GameState.LOGGED_IN} the "Loading\u2026" copy would
     *  never paint (the listener-driven re-render would already see
     *  {@code gateReady=true} and skip past it). EDT-only. Safe to
     *  call before {@link #setInGame} has wired the
     *  supplier. */
    public void refreshGate()
    {
        applyGate();
    }

    /** User-facing display name for a roster row / invite card.
     *  Prefers the display-cased {@link LobbyMember#name}, falls back
     *  to the canonical {@link LobbyMember#playerId} (lowercased
     *  form) if the display name is empty, and finally {@code
     *  "Unknown"} only if both are empty. */
    private static String nameOf(LobbyMember m)
    {
        return PlayerCard.nameOf(m);
    };;

    /** Common card-swap path. {@link #wrapInScroll(JPanel)} always returns
     *  a fresh JScrollPane so the default scrollbar value is 0, but we
     *  also snap the viewport explicitly after the layout pass — defensive
     *  cover against any PLAF that initialises the viewport to a non-zero
     *  position based on the previous card's geometry. */
    private void showSetup(JComponent view)
    {
        setupBox.removeAll();
        setupBox.add(view, CENTER);
        setupBox.revalidate();
        setupBox.repaint();
        showCard(CARD_FIGHT);
        if (view instanceof JScrollPane)
        {
            final var sp = (JScrollPane) view;
            SwingUtilities.invokeLater(() ->
            {
                JViewport vp = sp.getViewport();
                if (vp != null) vp.setViewPosition(new Point(0, 0));
            });
        }
    }

    /** Cleans up any in-flight FIGHT session + outgoing invite for the same
     *  opponent (Back to queue exit, window expiry, both-confirmed exit, etc.)
     *  and returns the user to the queue view. The server's session TTL keeps
     *  running server-side; the panel just drops its local state and
     *  ignores the late {@link #onFightConfirmedByPeer onFightConfirmedByPeer}
     *  / {@link #onMatchFound onMatchFound} push since
     *  {@code currentFight} is already null. */
    private void exitSetup()
    {
        currentFight = null;
        showCard(CARD_GATE);
    }

    /** User clicked Confirm Fight in the ConfirmFight view. Marks local
     *  state {@code iConfirmed=true}, fires the service confirm, and
     *  optimistically renders the Waiting view. If the peer had already
     *  confirmed, {@link #onMatchFound} fires shortly after, at which
     *  point the listener swaps the view to MeetAt — the
     *  {@code if (currentFight != null)} guard below
     *  avoids double-rendering the Waiting view in that case. */
    /** Confirm-Fight click handler.
     *
     *  <p>Takes an optional {@link JButton} so the in-card button can be
     *  instantly disabled + relabeled as visible evidence the click
     *  registered. Two-mode UX:
     *  <ul>
     *    <li>Normal path: button flips to "Confirming\u2026", disabled;
     *        the view immediately swaps to the Waiting card so the
     *        relabel only flashes for a frame. The relabel still
     *        matters because if the swap is delayed (Swing repaint
     *        scheduling under load), the user sees the click took.</li>
     *    <li>Stale-session path ({@code currentFight == null}):
     *        the button flips to "(expired)", disabled, and the view
     *        DOES NOT swap — the user is left on the Confirm Fight
     *        card with the dead button so they can read the label and
     *        click Back to queue. Pre-debounce, this code path was
     *        a silent no-op (matches the "I clicked Confirm and
     *        nothing happened" QA report when a race clears the
     *        session between view-build and click).</li>
     *  </ul>
     *
     *  <p>Also emits a {@code DEBUG} log on every click so the receiver
     *  side's debug log proves whether their click ever fired —
     *  critical for diagnosing "did they click or not" in
     *  asymmetric-visibility reports where only one side's log is
     *  available. */
    private void onConfirm(JButton confirmBtn)
    {
        LocalFightState s = currentFight;
        if (s == null)
        {
            log.warn("MatchmakingLobbyPanel: Confirm Fight clicked but currentFightSession=null -"
                + " session was cleared between view-build and click (most likely cause: late"
                + " match_found / session_expired). Click is a no-op; user must click Back to queue.");
            if (confirmBtn != null)
            {
                confirmBtn.setEnabled(false);
                confirmBtn.setText("(expired)");
            }
            return;
        }
        if (confirmBtn != null)
        {
            confirmBtn.setEnabled(false);
            confirmBtn.setText("Confirming\u2026");
        }
        s.iConfirmed = true;
        service.confirmFight();
        // Always swap to the Waiting view after the local confirm fires.
        // Pre-fix, this was guarded by !bothConfirmed() under the
        // assumption that match_found would land before the user notices
        // — but a peer who confirmed FIRST already set peerConfirmed=true,
        // so the second-to-confirm hits bothConfirmed=true at click time
        // and the guard skipped the swap. Result: stuck-on-Confirm-Fight
        // with a disabled "Confirming\u2026" button until the local timer
        // (now unconditional) kicks them out when the window ends. Swapping every
        // time keeps the visual transition consistent for both confirm
        // orderings; if match_found lands milliseconds later,
        // {@link #onMatchFound} immediately swaps Waiting \u2192 MeetAt.
        if (currentFight != null)
        {
            showSetup(buildWaiting());
        }
    }

    /** Live label on the FIGHT card that the ticker rewrites every second. */
    private JLabel clockLabel;

    /** Confirm Fight view — shown to the INVITER and for a queue match while
     *  they decide to lock in (the acceptor auto-confirms in
     *  {@link #onFightProposed} and skips straight to the Waiting view).
     *  Shows a big [Get Match Location] button
     *  and the live countdown; clicking it confirms the fight and, once
     *  both sides are in, the server reveals the world + meeting place — hence
     *  the label describes that outcome rather than the mechanical "Confirm".
     *  If the opponent has already confirmed, an extra subheader makes that
     *  visible. Both buttons ignore clicks for the card's first
     *  {@link #CLICK_DELAY}. For a queue match the buttons read
     *  {@link #CONFIRM_TEXT} and {@link #DECLINE_TEXT}. */
    private JComponent buildConfirm()
    {
        LocalFightState s = currentFight;
        final long shownAtMs = clickClockMs.getAsLong();
        JPanel card = newGateCard();
        card.add(makeHeader("Confirm fight"));
        card.add(lgap(8));
        addOpponentLines(card, s);
        if (s != null && s.peerConfirmed)
        {
            card.add(lgap(6));
            card.add(makeSubhead("Confirmed by other player"));
        }
        card.add(lgap(14));

        JButton confirm = makeAction(CONFIRM_TEXT, true);
        // Primary CTA — green (the colour the exit button used to be) so
        // it reads as the prominent positive action; the secondary
        // "Back to queue" exit below now uses the neutral default
        // button colour (2026-05-29 request). Label is "Get Match Location"
        // (2026-05-30 request) since confirming reveals the match world +
        // meeting place.
        confirm.setBackground(ACCENT);
        confirm.setForeground(Color.WHITE);
        confirm.setOpaque(true);
        confirm.setBorderPainted(false);
        confirm.addActionListener(e ->
        {
            if (clickReady(shownAtMs)) onConfirm(confirm);
        });
        card.add(confirm);
        card.add(lgap(8));

        clockLabel = makeSubhead(formatLeft(s));
        card.add(clockLabel);
        card.add(lgap(12));

        card.add(makeCancel(DECLINE_TEXT, () ->
        {
            if (clickReady(shownAtMs)) exitSetup();
        }));
        return wrapInScroll(card);
    }

    /** Waiting view — user has confirmed; shown until the opponent does
     *  too (header "Waiting on other player to confirm") or both have
     *  confirmed (header "Finalizing match details\u2026") or the confirm
     *  window expires. The two headers describe the same wait but
     *  attribute it correctly: in the first case we're waiting on the
     *  peer's wire confirm, in the second we're waiting on the server's
     *  {@code lobby/match_found} push. Without the second header the
     *  second-to-confirm player saw "Waiting on other player to
     *  confirm" even though the peer had already confirmed (the same
     *  scenario the QA test surfaced when match_found never landed). */
    private JComponent buildWaiting()
    {
        LocalFightState s = currentFight;
        JPanel card = newGateCard();
        String header = (s != null && s.peerConfirmed)
            ? "Finalizing match details\u2026"
            : "Waiting on other player to confirm";
        card.add(makeHeader(header));
        card.add(lgap(8));
        addOpponentLines(card, s);
        card.add(lgap(14));

        clockLabel = makeSubhead(formatLeft(s));
        card.add(clockLabel);
        card.add(lgap(12));

        card.add(makeCancel(BACK_TEXT, this::exitSetup));
        return wrapInScroll(card);
    }

    /** Terminal MeetAt view — shown after both confirmed. The server
     *  resolves the world + meeting place authoritatively via
     *  {@code resolve_match_world} / {@code resolve_meeting_place} in
     *  {@code backend/core/lobby.py}: NH Arena → W370 (AUS) / W558 (EU)
     *  / W578 (NA) with random-pick-of-the-two on mixed regions
     *  defaulting to W578; NH Wildy/FFA + Multi → world + Ferox Enclave;
     *  Veng → random PvP world from the member list + Grand Exchange;
     *  DMM → W345 + Grand Exchange. The plugin renders the values
     *  verbatim from {@link MatchInfo#world} / {@link MatchInfo#meetingPlace}
     *  per the handoff "render verbatim, no client-side world picking"
     *  rule — keeping the resolution logic server-side means the
     *  world tables can be updated (e.g. when Jagex retires a PvP
     *  world) without a plugin release.
     *
     *  <p>{@code match} is null only when the view is being re-rendered
     *  outside an {@link #onMatchFound} flow (currently unreachable —
     *  the view's only entry point is from {@link #onMatchFound}).
     *  Falls back to "TBD" defensively so a future refactor that
     *  invokes the view from another path doesn't NPE. */
    private JComponent buildMeetAt(MatchInfo match)
    {
        LocalFightState s = currentFight;
        JPanel card = newGateCard();
        card.add(makeHeader("Fight ready"));
        card.add(lgap(8));
        addOpponentLines(card, s);
        card.add(lgap(14));

        String worldText = match != null && match.world != null && !match.world.isEmpty()
            ? match.world : "TBD";
        String meetText = match != null && match.meetingPlace != null && !match.meetingPlace.isEmpty()
            ? match.meetingPlace
            : (s == null ? "TBD" : meetAtPlace(s.style, s.location));

        card.add(makeMeetRow("World:", worldText));
        card.add(lgap(6));
        card.add(makeMeetRow("Meet at:", meetText));
        card.add(lgap(14));

        // Per spec: this screen also has a Back to queue exit; auto-return
        // on real fight submission is a future hook tied to the in-game match
        // submission pipeline ().
        card.add(makeCancel(BACK_TEXT, this::exitSetup));
        return wrapInScroll(card);
    }

    /** Appends the opponent block used by Confirm/Waiting/MeetAt: the player
     *  name as a full-size header plus a same-sized but de-emphasized
     *  subheader carrying "Style - Build @ Place" for context (matches the
     *  incoming invite card's info-row format). Per spec, every text line
     *  on these screens must read at button size. */
    private static void addOpponentLines(JPanel card, LocalFightState s)
    {
        if (s == null) return;
        card.add(makeHeader(s.opponent.name));
        card.add(lgap(2));
        card.add(makeSubhead(formatSetup(s.style, s.build, s.location)));
    }

    /** "Style - Build @ Place" shared formatter. Used by the FightSession
     *  views (Confirm / Waiting / MeetAt opponent line) and the incoming
     *  invite card's info row, so both surfaces read identically. Falls
     *  back through {@link #inviteLabel(Style, String)} for
     *  Veng / DMM (no sub-loc picker, so the location reads as a generic
     *  "PvP World" / "DMM World" instead of being blank). */
    private static String formatSetup(Style style, BuildType build, String location)
    {
        var sb = new StringBuilder(style.label);
        if (build != null) sb.append(" - ").append(build.label);
        String loc = inviteLabel(style, location);
        if (!loc.isEmpty()) sb.append(" @ ").append(loc);
        return sb.toString();
    }

    /** Display name for the @-place portion of an invite info row.
     *  Returns the sub-location verbatim when one was picked (NH / Multi),
     *  otherwise the per-style default — "PvP World" for Veng, "DMM World"
     *  for DMM. Empty string for unknown style+null-location combos so the
     *  caller can omit the "@ ..." segment. */
    private static String inviteLabel(Style style, String location)
    {
        if (location != null && !location.isEmpty()) return location;
        if (style == Style.VENG) return "PvP World";
        if (style == Style.DMM) return "DMM World";
        return "";
    }

    /** The Confirm Fight card's countdown: {@code "M:SS remaining"}, whole seconds rounded up. */
    private static String formatLeft(LocalFightState s)
    {
        if (s == null) return "";
        // Monotonic remaining time — independent of the wall clock so the
        // displayed countdown always counts the full window down to zero.
        // See LocalFightState doc.
        long secs = (s.remainingMs() + 999L) / 1000L;
        return mmss((int) secs) + " remaining";
    }

    /** 1Hz tick: expires INVITED outgoing invites whose 10-min TTL has run out
     *  (refreshes affected rows), updates the FIGHT card's countdown
     *  label, and force-exits the FIGHT card when the confirm window
     *  elapses <em>and the peer has not confirmed</em>.
     *
     *  <p><b>Expiry policy (2026-05-29 user request).</b> On window
     *  elapse the panel returns to the lobby ONLY when
     *  {@code !peerConfirmed}. Once the other player has confirmed the
     *  screen stays put — the user explicitly does not want to be bounced
     *  back to the lobby while a match is being finalized. In that state
     *  the panel waits for the server's authoritative
     *  {@code lobby/match_found} (\u2192 MeetAt) or
     *  {@code lobby/session_expired} (\u2192 lobby) push, or the user's
     *  manual "Back to queue" click. When {@code match_found} lands in
     *  time, {@link #handleMatchFound} clears {@code currentFight}
     *  so this branch is moot — the outer {@code if (s != null)} guard
     *  skips.
     *
     *  <p>Trade-off: if the backend ever loses BOTH confirms (the old
     *  {@code confirmed_by} overwrite bug) and never pushes
     *  match_found/session_expired, a both-confirmed user is no longer
     *  auto-evicted when the window ends — the manual "Back to queue" button is
     *  the intended escape hatch in that (server-bug) scenario. */
    private void onFightTick()
    {
        LocalFightState s = currentFight;
        if (s != null)
        {
            // Monotonic, clock-independent window — see LocalFightState
            // doc. The window only elapses after windowMs of
            // REAL time, so a wrong / skewed wall clock (or a
            // seconds-as-ms deadline on the wire) can no longer pop the
            // card on the first tick. If match_found landed in time,
            // handleMatchFound already nulled currentFight and we
            // never reach here.
            if (s.confirmOver())
            {
                // A queue match the player never confirmed also returns to the queue view.
                if (!s.peerConfirmed || !s.iConfirmed)
                {
                    // Peer never confirmed within the window — return to
                    // the lobby so a one-sided confirm doesn't strand the
                    // user. serverDeadlineMs is logged next to the
                    // monotonic elapsedMs so client clock skew is obvious
                    // in a bug report (e.g. a serverDeadlineMs already in
                    // the past when elapsedMs reaches windowMs).
                    exitSetup();
                }
                // else: the peer HAS confirmed — per the 2026-05-29 user
                // request the screen must stay put (a match is being
                // finalized; don't bounce the user back to the lobby).
                // The server stays authoritative: lobby/match_found swaps
                // to MeetAt and lobby/session_expired returns to the
                // lobby. The user's manual "Back to queue" button is
                // always available as the escape hatch. We stop updating
                // the countdown label here so it freezes instead of
                // showing a stale "0:00 remaining".
            }
            else if (clockLabel != null)
            {
                clockLabel.setText(formatLeft(s));
            }
        }

        // Plan 10 F.1: the Searching card's elapsed clock between server pushes.
        if (queueCard != null && isOnCard(CARD_QUEUE)) queueCard.tick();
    }

    /** Resolves the sender's name colour for the in-game popup using
     *  the same rule the lobby row applies (see {@code addLobbyRow}'s
     *  {@code rankColor} branch): if {@code peakRankIdx} is a known
     *  index, tint by {@link RankUtils#getRankColor(String)} keyed on
     *  the rank label; otherwise default to {@link Color#WHITE} so a
     *  freshly-joined player whose shard hasn't published yet still
     *  reads cleanly. Package-private + static for testability.
     *
     *  <p>Note: {@code blocked} doesn't apply here — by the time an
     *  invite from a blocked sender reaches us, server-side filtering
     *  has already dropped it. The lobby row's grey-blocked path is
     *  intentionally NOT mirrored. */
    static Color senderColor(LobbyMember sender)
    {
        if (sender == null) return Color.WHITE;
        boolean rankKnown = sender.peakRankIdx >= 0 && sender.peakRankIdx < RANK_LABELS.length;
        if (!rankKnown) return Color.WHITE;
        return RankUtils.getRankColor(RANK_LABELS[sender.peakRankIdx]);
    }

    /** {@inheritDoc}
     *
     *  <p>Fired for both flows: (a) sender — opponent accepted our invite,
     *  drop the [Invited M:SS] chip and swap to ConfirmFight; (b) receiver
     *  — we just clicked Accept on an incoming card, server promoted us
     *  to mutual-confirm. Either way the lobby is hidden until the user
     *  exits via Back to queue, the confirm window expires
     *  ({@link #onFightSessionExpired}), or both sides confirm
     *  ({@link #onMatchFound}). (c) Neither: a queue match gets the same
     *  Confirm Fight card, labelled Confirm / Decline, and nothing is
     *  confirmed until Confirm is clicked. */
    @Override
    public void onFightProposed(FightSession session)
    {
        if (session == null || session.opponent == null)
        {
            log.warn("MatchmakingLobbyPanel.onFightProposed: dropped - session or opponent null"
                + " (session={}, opponent={})",
                session, session == null ? "n/a" : session.opponent);
            return;
        }
        // Diagnostic: prove from the user's debug log that their UI
        // transitioned to the Confirm Fight card. Critical for triaging
        // "the other player couldn't click Confirm" reports — if this
        // line is missing from the receiver's log, the panel never got
        // the swap, meaning the issue is upstream (no fight_proposed
        // arrived, or service-level filtering dropped it). If the line
        // IS present but no subsequent "Confirm Fight clicked" line
        // shows up, the user never clicked / the click didn't fire.
        currentFight = new LocalFightState(session, confirmClock);
        showSetup(buildConfirm());
        notifyShown();

        // In-game popup so users not actively looking at the sidepanel
        // still notice the match locking in. Config-gated inside the
        // overlay itself so a user who finds it noisy can disable it
        // without unregistering anything. No-op when no notifier wired.
        MatchAlert mfn = matchFoundNotifier;
        if (mfn != null)
        {
            String opponentDisplay = nameOf(session.opponent);
            String sub = buildSubtext(session);
            Color opponentColor = senderColor(session.opponent);
            mfn.showMatch(session.fightId, opponentDisplay, sub, opponentColor);
        }
    }

    /** Builds the second-line summary for the match-found popup —
     *  "{style} ({build}) at {location}" with sensible omissions when
     *  fields are absent (e.g. Veng has no sub-location). Keyed off the
     *  {@link FightSession} carrier. Package-private + static for
     *  testability. */
    static String buildSubtext(FightSession session)
    {
        if (session == null) return "";
        var sb = new StringBuilder();
        if (session.style != null) sb.append(session.style.label);
        if (session.build != null)
        {
            if (sb.length() > 0) sb.append(' ');
            sb.append('(').append(session.build.label).append(')');
        }
        if (session.location != null && !session.location.isEmpty())
        {
            if (sb.length() > 0) sb.append(" at ");
            sb.append(session.location);
        }
        return sb.toString();
    }

    @Override
    public void onFightConfirmedByPeer(String fightId)
    {
        LocalFightState s = currentFight;
        if (s == null) return;
        if (s.session.fightId != null
            && !s.session.fightId.equals(fightId)) return;
        s.peerConfirmed = true;
        // Two paths:
        //   (a) user hasn't confirmed yet  -> rebuild Confirm Fight view
        //       so the new "Confirmed by other player" subheader paints
        //       above the Confirm Fight button.
        //   (b) user already confirmed     -> we're on the Waiting view;
        //       rebuild it so the header flips from "Waiting on other
        //       player to confirm" to "Finalizing match details\u2026"
        //       (peer just confirmed; we're now waiting on the server's
        //       match_found, not on the peer's wire).
        if (!s.iConfirmed)
        {
            showSetup(buildConfirm());
        }
        else
        {
            showSetup(buildWaiting());
        }
    }

    @Override
    public void onMatchFound(MatchInfo match)
    {
        if (match == null) return;
        LocalFightState s = currentFight;
        if (s == null) return;
        if (s.session.fightId != null
            && !s.session.fightId.equals(match.fightId)) return;
        // Both sides confirmed — MeetAt is terminal until Back to queue.
        // Server-resolved world + meeting_place travel through `match`
        // so the view can render them verbatim (see buildMeetAt).
        s.fightReady = true;
        showSetup(buildMeetAt(match));
    }

    @Override
    public void onFightSessionExpired(String fightId)
    {
        LocalFightState s = currentFight;
        if (s == null) return;
        if (s.session.fightId != null
            && !s.session.fightId.equals(fightId)) return;
        // Mirror exitSetup() but without the cancelInvite — the
        // session is already torn down server-side.
        currentFight = null;
        showCard(CARD_GATE);
    }

    /** Closes a queue match's Confirm or Waiting card whose session the server ended, as
     *  {@link #onFightSessionExpired} does. {@code fightId} is the ended session, or
     *  {@code null} when the frame names none. An invite's card, Fight ready and another
     *  session's card stay. */
    private void closeMatch(String fightId)
    {
        LocalFightState s = currentFight;
        if (s == null || s.fightReady) return;
        if (fightId != null && !fightId.equals(s.session.fightId)) return;
        onFightSessionExpired(s.session.fightId);
    }

    @Override
    public void onError(String code, String message)
    {
        // Localized via LobbyErrors — never display the raw
        // server message; it's English-only debug text that may change
        // without notice. Unknown codes get a generic fallback so a
        // server that adds a new code without a plugin release degrades
        // gracefully.
        showError(LobbyErrors.forCode(code));

        // FIGHT_SESSION_EXPIRED answers a confirm whose session already ended.
        if ("FIGHT_SESSION_EXPIRED".equals(code)) closeMatch(null);
    }

    /**
     * Builds the top-of-panel error banner. Red-tinted strip with the
     * localized message + a [×] dismiss button on the right. Hidden by
     * default; {@link #showError} flips visibility + starts the
     * auto-dismiss timer.
     */
    private JPanel buildError()
    {
        var banner = new JPanel();
        banner.setLayout(new BoxLayout(banner, X_AXIS));
        banner.setBackground(new Color(0x6e1f1f));
        banner.setBorder(createCompoundBorder(
            createMatteBorder(0, 0, 1, 0, new Color(0x401010)),
            pad(6, 8, 6, 8)));
        maxH(banner, 80);

        errorLabel = new JLabel(" ");
        errorLabel.setForeground(new Color(0xffeeee));
        plain(errorLabel, 12f);
        // Wrap long messages inside the sidepanel width — SMURF_GUARD's
        // "Play casual PvP to build…" doesn't fit on one line at 225px.
        banner.add(errorLabel);
        banner.add(Box.createHorizontalGlue());

        var dismiss = new JLabel("\u00d7");
        dismiss.setForeground(new Color(0xffcccc));
        bold(dismiss, 14f);
        dismiss.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        dismiss.setToolTipText("Dismiss");
        dismiss.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e) { hideError(); }
        });
        banner.add(dismiss);

        return banner;
    }

    /** Show the localized message in the banner, restart the
     *  auto-dismiss timer, and force a re-layout so the banner becomes
     *  visible (BorderLayout doesn't auto-fire revalidate on
     *  setVisible). Safe to call from the EDT only. */
    private void showError(String localizedMessage)
    {
        if (errorBanner == null || errorLabel == null) return;
        // 200px hard cap matches the gate status label — keeps long
        // strings wrapping inside the sidepanel rather than punching
        // out the right edge.
        errorLabel.setText("<html><div style='width:200px'>"
            + escape(localizedMessage).replace("\"", "&quot;") + "</div></html>");
        errorBanner.setVisible(true);
        revalidate();
        repaint();

        if (errorTimer != null && errorTimer.isRunning())
        {
            errorTimer.stop();
        }
        errorTimer = new Timer(DISMISS_MS, e -> hideError());
        errorTimer.setRepeats(false);
        errorTimer.start();
    }

    private void hideError()
    {
        if (errorBanner == null) return;
        errorBanner.setVisible(false);
        revalidate();
        repaint();
        if (errorTimer != null) errorTimer.stop();
    }

    /**
     * Builds the reconnect-status banner pinned above {@link #errorBanner}.
     * Amber-tinted strip with a wrapped two-line message + a live
     * countdown to the next reconnect attempt. Hidden by default;
     * {@link #refreshRetry} flips visibility based on the
     * {@link LobbyService#isConnected()} / {@link
     * LobbyService#getRetryAtMs()} pair.
     *
     * <p>No dismiss button: the banner is informational and self-clears
     * when the socket reconnects. A manual dismiss would let users
     * hide a real ongoing problem and then wonder why nothing works.
     */
    private JPanel buildBanner()
    {
        var banner = new JPanel();
        banner.setLayout(new BoxLayout(banner, X_AXIS));
        // Amber, distinct from the red error banner — error = "your
        // last action failed", reconnect = "we're trying to get back
        // online". Different colors so a user who has both visible
        // doesn't conflate the two.
        banner.setBackground(new Color(0x6e551f));
        banner.setBorder(createCompoundBorder(
            createMatteBorder(0, 0, 1, 0, new Color(0x403010)),
            pad(6, 8, 6, 8)));

        retryLabel = new JLabel(" ");
        retryLabel.setForeground(new Color(0xfff2dd));
        plain(retryLabel, 12f);
        banner.add(retryLabel);
        banner.add(Box.createHorizontalGlue());
        return banner;
    }

    /**
     * 1Hz tick that polls the underlying service for connection state
     * and either shows the reconnect banner (with the live countdown)
     * or hides it. Called from {@link #retryTicker}; safe to
     * call from the EDT only.
     *
     * <p>We poll rather than wire a callback from
     * {@link com.pvp.leaderboard.service.socket.SocketMgr}
     * because the countdown needs a 1Hz redraw regardless — adding a
     * callback would only mean two notification paths for the same
     * state. The {@link LobbyService} interface deliberately exposes
     * the raw "is connected" + "next attempt epoch ms" pair instead of
     * a derived "seconds remaining" so the panel owns the
     * presentation logic (countdown formatting, edge cases when the
     * scheduled time is in the past while a reconnect is mid-flight).
     *
     * <p>{@link com.pvp.leaderboard.lobby.NoOpLobby} inherits the
     * interface defaults — {@code isConnected()=true} +
     * {@code getRetryAtMs()=0} — so the banner stays
     * hidden in unit-test runs without any extra stubbing.
     */
    private void refreshRetry()
    {
        if (retryBanner == null || retryLabel == null) return;
        boolean connected = true;
        long nextRetryMs = 0L;
        try
        {
            connected = service.isConnected();
            nextRetryMs = service.getRetryAtMs();
        }
        catch (Exception ignored)
        {
            // Defensive: a service impl that throws here should not
            // take down the panel's UI thread. Treat as "no banner".
        }

        // Two suppression cases:
        //   1. Connected — nothing to reconnect to.
        //   2. Disconnected but no retry scheduled — pre-login, or the
        //      manager is in the middle of a tick. Showing a banner
        //      with "0 seconds" would flicker; hide instead.
        if (connected || nextRetryMs <= 0L)
        {
            if (retryBanner.isVisible())
            {
                retryBanner.setVisible(false);
                revalidate();
                repaint();
            }
            return;
        }

        long remainingMs = nextRetryMs - System.currentTimeMillis();
        // Floor at 0 so a tick that lands after the scheduled time
        // (e.g. JVM pause, reconnect mid-flight) doesn't render a
        // negative countdown. Once the attempt fires the manager
        // zeroes retryAtMs and the next tick hides the
        // banner.
        long remainingSec = Math.max(0L, (remainingMs + 999L) / 1000L);

        // Two-line copy: instruction first, countdown second. Using
        // an HTML <div style='width:...'> caps wrap inside the
        // sidepanel — same trick as the gate's match-count status
        // label. 170px matches that label so both pieces of chrome
        // wrap at the same column.
        String html = "<html><div style='width:170px'>"
            + "Attempting to reconnect, if this doesn't disappear contact Toyco in discord."
            + "<br>"
            + remainingSec + " seconds remaining until next reconnect attempt."
            + "</div></html>";
        retryLabel.setText(html);
        if (!retryBanner.isVisible())
        {
            retryBanner.setVisible(true);
            revalidate();
            repaint();
        }
    }

    @Override
    public void onBlockListSnapshot(Set<String> playerIds)
    {
        if (playerIds == null) return;
        // Mirror to the static UI-side BlockList so the
        // Player-Lookup-tab Block/Unblock button on Dashboard
        // reflects the canonical server state (e.g. block from
        // another device, or rehydrate after a socket reconnect).
        // Both sets normalise on the same lowercased display-name
        // key, so they round-trip cleanly.
        BlockList.replaceAll(playerIds);
    }

    @Override
    public void onBlockAdded(String playerId)
    {
        if (playerId == null || playerId.isEmpty()) return;
        // Idempotent mirror to the dashboard-tab block list. Always
        // call regardless of the {@code .add()} return value: an
        // optimistic local Dashboard click already added it
        // here, so this push is a redundant set-mutation, but the
        // BlockList side may have missed the optimistic
        // path (e.g. when the click came from a different device).
        BlockList.block(playerId);
    }

    @Override
    public void onBlockRemoved(String playerId)
    {
        if (playerId == null || playerId.isEmpty()) return;
        BlockList.unblock(playerId);
    }

    /** Meeting place per (style, sub-location). Per spec:
     *  NH Arena → Arena; NH Wildy / FFA Portal → Ferox Enclave;
     *  Veng → Grand Exchange; Multi → Ferox Enclave; DMM → Grand Exchange. */
    private static String meetAtPlace(Style style, String location)
    {
        if (style == Style.NH)
        {
            if ("Arena".equalsIgnoreCase(location)) return "Arena";
            return "Ferox Enclave";
        }
        if (style == Style.VENG) return "Grand Exchange";
        if (style == Style.MULTI) return "Ferox Enclave";
        if (style == Style.DMM) return "Grand Exchange";
        return "TBD";
    }

    // -------------------- Fight setup widget helpers (gate-like styling) --------------------

    private JPanel newGateCard()
    {
        var card = new JPanel();
        card.setLayout(new BoxLayout(card, Y_AXIS));
        card.setBorder(pad(18, 8, 18, 8));
        return card;
    }

    private static JLabel makeHeader(String text)
    {
        return bold(new JLabel(text), GATE_PT);
    }

    /** Same size + weight as {@link #makeHeader} but with a muted color
     *  — used on Confirm/Waiting/MeetAt where every line needs to read at
     *  button size per spec, but secondary lines (style/loc context,
     *  "Confirmed by other player", countdown) should still be visually
     *  de-emphasized vs the primary header + opponent name. */
    private static JLabel makeSubhead(String text)
    {
        JLabel l = makeHeader(text);
        l.setForeground(new Color(0xcccccc));
        return l;
    }

    /** Same visual weight as the gate's per-style toggle buttons so the fight
     *  setup feels like the same widget family. */
    private static JButton makeAction(String text, boolean enabled)
    {
        JButton b = maxH(bold(new JButton(text), 15f), 36);
        b.setMargin(new Insets(6, 12, 6, 12));
        b.setFocusPainted(false);
        b.setEnabled(enabled);
        return b;
    }

    /** Bottom exit button ("Back to queue"). Neutral default button
     *  colour — it deliberately does NOT set a background so it matches
     *  the colour the Confirm button used to be. The green tint moved to
     *  the Confirm CTA (see {@link #buildConfirm}) so green now
     *  reads exclusively as the prominent positive action and the exit
     *  is the secondary, de-emphasised affordance (2026-05-29 request). */
    private static JButton makeCancel(String text, Runnable onClick)
    {
        JButton b = maxH(bold(new JButton(text), 16f), 44);
        b.setMargin(new Insets(10, 12, 10, 12));
        b.setFocusPainted(false);
        b.addActionListener(e -> onClick.run());
        return b;
    }

    /** Two-column "label : value" row used in the Meet At terminal view. */
    private static JPanel makeMeetRow(String label, String value)
    {
        JPanel row = maxH(left(new JPanel(new BorderLayout(8, 0))), 32);
        row.setOpaque(false);
        JLabel v = bold(new JLabel(value), GATE_PT);
        v.setForeground(Color.WHITE);
        row.add(makeSubhead(label), WEST);
        row.add(v, CENTER);
        return row;
    }

    /** Wrap a fight-setup card in a scrollpane — RuneLite sidepanels can be
     *  short enough that the buttons + summary overflow vertically. */
    private static JComponent wrapInScroll(JPanel card)
    {
        var sp = new JScrollPane(card,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        sp.setBorder(createEmptyBorder());
        sp.getVerticalScrollBar().setUnitIncrement(16);
        return sp;
    }

    /** Live "current value" label for a rank-range endpoint — bold,
     *  painted in the rank's own colour so the user can spot which
     *  tier they're on without reading the text. 15pt matches the
     *  lobby's body-text scale (style toggles + presence label).
     *
     *  <p>Backed by {@link ChipLabel} (not vanilla JLabel) because
     *  Substance L&F's LabelUI was reporting an undersized preferred
     *  width for the slider's min / max value labels — visible to
     *  users as "Bronz\u2026" / "3rd A\u2026" ellipsis truncation
     *  even though there's plenty of horizontal slack inside the
     *  225px sidepanel. ChipLabel paints the text directly in
     *  paintComponent so the L&F's clip-and-ellipsify path is
     *  bypassed entirely; the alignment-aware draw inside
     *  ChipLabel honours the LEFT / RIGHT setHorizontalAlignment
     *  set on the min / max labels respectively. Shared with
     *  {@link QueueRangeSlider}. */
    static JLabel newRankLabel(int idx)
    {
        var l = new ChipLabel(RANK_LABELS[idx]);
        bold(l, 15f);
        l.setHorizontalAlignment(SwingConstants.RIGHT);
        l.setForeground(RankUtils.getRankColor(RANK_LABELS[idx]));
        l.setBorder(pad(0, 0, 0, 0));
        return l;
    }

    static void setRankLabel(JLabel l, int idx)
    {
        String label = RANK_LABELS[idx];
        l.setText(label);
        l.setForeground(RankUtils.getRankColor(label));
    }

}

package com.pvp.leaderboard.ui;

import com.google.gson.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import javax.swing.*;
import javax.swing.table.*;
import java.util.List;
import static com.pvp.leaderboard.ui.Ui.*;
import static com.pvp.leaderboard.util.JsonLenient.*;
import static javax.swing.SwingUtilities.*;

public class PerfStats extends JPanel
{
    /** Opponent tiers, highest first: the rank breakdown's sort order. */
    private static final List<String> TIERS = Arrays.asList("3rd Age", "Dragon", "Rune", "Adamant", "Mithril", "Black", "Steel", "Iron", "Bronze");

    private final JLabel totalsLabel = new JLabel("K: - D: - Winrate -%");
    private final JPanel bucketPicker;

    private final DefaultTableModel rankModel = new DefaultTableModel(new String[]{"Rank", "Wins", "Deaths", "KD"}, 0);

    private String currentBucket = "overall";

    /** All-time wins/losses/ties per bucket from {@code /user} →
     *  {@code cumulative_stats}. Source of truth for the K/D summary
     *  row — matches the website's {@code updatePerformanceOverviewDisplay}. */
    private Map<String, int[]> bucketTotals;

    // Cumulative opponent rank stats per bucket: bucket -> (rank -> [wins, losses])
    private Map<String, Map<String, int[]>> oppRankStats;

    public PerfStats()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createTitledBorder("Performance Breakdown"));

        // Three rows of two: every label, "Tournament" included, shows in full.
        bucketPicker = bucketBar("performance-bucket-selector", null, 3, 2, BUCKETS, this::setBucket);
        styleBucketBar(bucketPicker, "overall");
        maxH(bucketPicker, Math.max(90, bucketPicker.getPreferredSize().height));
        add(bucketPicker);

        // Summary row
        var summaryRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        totalsLabel.setFont(smallFont());
        summaryRow.add(totalsLabel);
        add(summaryRow);

        // Rank breakdown table
        add(createRanks());
    }

    private JPanel createRanks()
    {
        var table = new JTable(rankModel);
        table.setEnabled(false);
        for (int i = 0; i < 4; i++)
        {
            table.getColumnModel().getColumn(i).setPreferredWidth(i == 0 ? 90 : 45);
        }
        table.setAutoResizeMode(JTable.AUTO_RESIZE_ALL_COLUMNS);

        // The wrapper's size wins; the scroll pane fills it.
        var p = new JPanel(new BorderLayout());
        p.add(new JScrollPane(table));
        p.setPreferredSize(new Dimension(0, 340));
        return p;
    }

    /**
     * Switch to a different bucket for display.
     */
    public void setBucket(String bucket)
    {
        currentBucket = bucket;
        updateTotals();
        updateRanks();
        invokeLater(() -> styleBucketBar(bucketPicker, bucket));
    }

    /**
     * Receive all-time wins/losses/ties from {@code /user} →
     * {@code cumulative_stats}. Drives the K/D summary label for the
     * selected bucket. Matches the website's performance overview.
     */
    public void setTotals(JsonObject totalStats)
    {
        bucketTotals = parseTotals(totalStats);
        updateTotals();
    }

    private static Map<String, int[]> parseTotals(JsonObject totalStats)
    {
        Map<String, int[]> out = new HashMap<>();
        if (totalStats == null) return out;
        for (String bucket : totalStats.keySet())
        {
            JsonObject b = optObject(totalStats, bucket);
            if (b != null)
            {
                out.put(bucket.toLowerCase(), new int[]{optInt(b, "wins", 0),
                    optInt(b, "losses", 0), optInt(b, "ties", 0)});
            }
        }
        return out;
    }

    /**
     * Update the K/D summary from {@link #bucketTotals} (the
     * selected bucket, else Overall), falling back to summing
     * {@link #oppRankStats} when cumulative data is absent
     * (legacy /user payloads).
     */
    private void updateTotals()
    {
        int kills = 0, deaths = 0, ties = 0;
        if (bucketTotals != null && !bucketTotals.isEmpty())
        {
            int[] row = bucketTotals.getOrDefault(currentBucket, bucketTotals.get("overall"));
            if (row != null)
            {
                kills = row[0];
                deaths = row[1];
                ties = row[2];
            }
        }
        else if (oppRankStats != null)
        {
            for (int[] v : oppRankStats.getOrDefault(currentBucket, Collections.emptyMap()).values())
            {
                kills += v[0];
                deaths += v[1];
            }
        }
        int total = kills + deaths + ties;
        String text = String.format("K: %d D: %d Winrate %.1f%%", kills, deaths, total > 0 ? (double) kills / total * 100 : 0);
        invokeLater(() -> totalsLabel.setText(text));
    }

    /**
     * Rank -> [wins, losses] from a JsonObject of rank -> {wins, losses}
     * entries; only ranks with a win or a loss are kept.
     */
    private static Map<String, int[]> parseRanks(JsonObject rankData)
    {
        Map<String, int[]> result = new HashMap<>();
        for (String key : rankData.keySet())
        {
            JsonObject rs = optObject(rankData, key);
            int wins = optInt(rs, "wins", 0);
            int losses = optInt(rs, "losses", 0);
            if (wins > 0 || losses > 0)
            {
                result.put(key, new int[]{wins, losses});
            }
        }
        return result;
    }

    /**
     * Receive opponent rank stats from the /user API response.
     * Called from Dashboard.loadStats() after getProfile.
     * Updates the rank breakdown table with all-time stats per opponent tier+division.
     *
     * Handles two formats:
     * - New format: nested by bucket {"overall": {...}, "nh": {...}, ...}
     * - Old format: flat {rank -> stats} (wrapped in "overall" for all buckets)
     */
    public void setOppRanks(JsonObject opponentStats)
    {
        oppRankStats = new HashMap<>();
        if (opponentStats != null)
        {
            if (optObject(opponentStats, "overall") != null)
            {
                for (String bucket : opponentStats.keySet())
                {
                    JsonObject bucketData = optObject(opponentStats, bucket);
                    if (bucketData != null) oppRankStats.put(bucket, parseRanks(bucketData));
                }
            }
            else
            {
                Map<String, int[]> overall = parseRanks(opponentStats);
                for (String b : ExtraStats.bucketKeys())
                {
                    oppRankStats.put(b, overall);
                }
            }
        }
        updateRanks();
    }

    /**
     * Update the rank breakdown table from cumulative opponent rank stats for current bucket.
     * Sorts by rank tier (highest first, unknown tiers last) then by division
     * (1, 2, 3); the division is read only to break a tie.
     */
    private void updateRanks()
    {
        invokeLater(() ->
        {
            rankModel.setRowCount(0);
            Map<String, int[]> stats = oppRankStats == null ? Collections.emptyMap()
                : oppRankStats.getOrDefault(currentBucket, Collections.emptyMap());
            List<String> keys = new ArrayList<>(stats.keySet());
            keys.sort(Comparator.comparingInt(PerfStats::tierIndex).thenComparingInt(PerfStats::division));
            for (String key : keys)
            {
                int[] s = stats.get(key);
                String kd = s[1] > 0 ? String.format("%.2f", (double) s[0] / s[1]) : String.valueOf(s[0]);
                rankModel.addRow(new Object[]{key, s[0], s[1], kd});
            }
        });
    }

    private static int tierIndex(String key)
    {
        String family = key.split(" ")[0];
        int i = TIERS.indexOf(family.equals("3rd") ? "3rd Age" : family);
        return i < 0 ? 999 : i;
    }

    private static int division(String key)
    {
        String[] parts = key.split(" ");
        return parts.length > 1 ? Integer.parseInt(parts[parts.length - 1]) : 0;
    }

    public void reset()
    {
        oppRankStats = null;
        bucketTotals = null;
        currentBucket = "overall";
        invokeLater(() ->
        {
            totalsLabel.setText("K: - D: - Winrate -%");
            rankModel.setRowCount(0);
            styleBucketBar(bucketPicker, "overall");
        });
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.lobby.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.awt.event.*;
import java.util.function.*;
import javax.swing.*;
import javax.swing.border.*;
import static com.pvp.leaderboard.ui.Ui.*;
import static java.awt.RenderingHints.*;
import static javax.swing.SwingConstants.*;

/**
 * Roster entry. EAST chip cycles through three states (precedence top-down):
 * <ul>
 *   <li><b>[Invited M:SS]</b> — outgoing invite pending acceptance.
 *       Click cancels the invite (clears the 10-min block).</li>
 *   <li><b>[Lookup]</b> — outstanding incoming invite from this player
 *       (their card is up top). Click opens Player Lookup.</li>
 *   <li><b>[Fight]</b> (default) — opens the full-screen fight-setup card.</li>
 * </ul>
 *
 * <p>Clicking the profile area also opens Player Lookup — matches the
 * legacy right-click "PvP lookup" muscle memory.
 */
class PlayerCard extends CapPanel
{
    /** Single fixed border used in both idle and hover states; the hover
     *  outline is drawn in {@link #paintBorder(Graphics)}. */
    private static final Border ROW_BORDER = BorderFactory.createCompoundBorder(
        new MatteBorder(0, 0, 1, 0, DIVIDER),
        pad(4, 6, 4, 6));

    private final LobbyMember p;
    private final int fontBase;
    /** The chips' size. */
    private final int chipPt;
    private final Consumer<String> onOpenProfile;

    /** Tracks the cursor across child boundaries so child-to-child crossings
     *  don't false-trigger an unhover on the leaf JLabel. */
    private boolean hovered;

    /** A player's card: name and rank, then the player's own style and build
     *  chips; a click anywhere opens the profile. */
    PlayerCard(LobbyMember p, int fontBase, int chipPt, Consumer<String> onOpenProfile)
    {
        this.p = p;
        this.fontBase = fontBase;
        this.chipPt = chipPt;
        this.onOpenProfile = onOpenProfile;
        setLayout(new BorderLayout());
        setBackground(CARD_BG);
        setBorder(ROW_BORDER);
        setAlignmentX(LEFT_ALIGNMENT);
        var center = new JPanel();
        center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
        center.setOpaque(false);
        center.add(buildHeader());
        center.add(vgap(3));
        JPanel styles = chipRow();
        if (p.region != null && !p.region.trim().isEmpty()) styles.add(makeChip(p.region, Color.WHITE, chipPt));
        for (Style s : Style.values())
        {
            if (p.styles.contains(s)) styles.add(makeChip(s.label, new Color(0xffc107), chipPt));
        }
        center.add(styles);
        center.add(vgap(2));
        JPanel builds = chipRow();
        for (BuildType a : BuildType.values())
        {
            if (p.builds.contains(a)) builds.add(makeChip(a.label, new Color(0x4fc3f7), chipPt));
        }
        center.add(builds);
        add(center, BorderLayout.CENTER);
        installProfileInteraction(center);
    }

    @Override
    protected void paintBorder(Graphics g)
    {
        super.paintBorder(g);
        if (hovered)
        {
            g.setColor(Color.WHITE);
            g.drawRect(0, 0, getWidth() - 1, getHeight() - 1);
        }
    }

    /** Installs the hover / click handler on every component inside
     *  {@code root}: Swing dispatches mouse events to the deepest hit
     *  component, so the card alone would never see them. */
    private void installProfileInteraction(Container root)
    {
        MouseAdapter ma = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (onOpenProfile != null) onOpenProfile.accept(p.name);
            }
            @Override
            public void mouseEntered(MouseEvent e)
            {
                setHover(true);
            }
            @Override
            public void mouseExited(MouseEvent e)
            {
                Point inRow = SwingUtilities.convertPoint(
                    e.getComponent(), e.getPoint(), PlayerCard.this);
                if (!PlayerCard.this.contains(inRow)) setHover(false);
            }
        };
        addMouseListener(ma);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        attachAll(root, ma);
    }

    private static void attachAll(Container c, MouseListener ml)
    {
        for (Component child : c.getComponents())
        {
            child.addMouseListener(ml);
            if (child instanceof JComponent)
            {
                ((JComponent) child).setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            }
            if (child instanceof Container)
            {
                attachAll((Container) child, ml);
            }
        }
    }

    private void setHover(boolean on)
    {
        if (hovered == on) return;
        hovered = on;
        repaint();
    }

    /** The name (full row width, no ellipsis) with the rank drawn over its
     *  right end on the card's background; an unknown rank leaves the name alone. */
    private JComponent buildHeader()
    {
        boolean rankKnown = p.peakRankIdx >= 0 && p.peakRankIdx < RANK_LABELS.length;
        String rankLabel = rankKnown ? RANK_LABELS[p.peakRankIdx] : "";
        Color rankColor = rankKnown ? RankUtils.getRankColor(rankLabel) : Color.WHITE;
        String displayName = nameOf(p);
        var name = new FullLabel(displayName);
        name.setFont(name.getFont().deriveFont(Font.BOLD, (float) fontBase));
        name.setForeground(rankColor);
        name.setToolTipText(displayName);
        if (!rankKnown)
        {
            var placeholder = new JLabel("");
            placeholder.setOpaque(false);
            return new RightRow(name, placeholder);
        }
        var rank = new JLabel(rankLabel);
        rank.setFont(rank.getFont().deriveFont(Font.BOLD, (float) fontBase));
        rank.setForeground(rankColor);
        rank.setHorizontalAlignment(RIGHT);
        rank.setOpaque(true);
        rank.setBackground(CARD_BG);
        rank.setBorder(pad(0, 4, 0, 0));
        return new RightRow(name, rank);
    }

    private static JPanel chipRow()
    {
        var chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
        chips.setOpaque(false);
        chips.setBorder(pad(0, 0, 0, 0));
        return chips;
    }

    private static JLabel makeChip(String text, Color color, int fontPt)
    {
        var chip = new ChipLabel(text);
        chip.setFont(chip.getFont().deriveFont(Font.BOLD, (float) fontPt));
        chip.setForeground(color);
        chip.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(color, 1),
            pad(1, 5, 1, 5)));
        chip.setOpaque(false);
        return chip;
    }

    /** The lobby's rank labels ("Bronze 3" ... "3rd Age"), indexed like {@link RankUtils#THRESHOLDS}. */
    static final String[] RANK_LABELS = buildLabels();

    /** A member's name for the card: the display name, else the id, else "Unknown". */
    static String nameOf(LobbyMember m)
    {
        if (m == null) return "";
        String n = m.name;
        if (n != null && !n.isEmpty()) return n;
        String pid = m.playerId;
        if (pid != null && !pid.isEmpty()) return pid;
        return "Unknown";
    }

    /** Builds the human-readable rank labels (e.g. "Bronze 3", "3rd Age") in
     *  the same index order as {@link RankUtils#THRESHOLDS}. */
    private static String[] buildLabels()
    {
        var out = new String[RankUtils.THRESHOLDS.length];
        for (int i = 0; i < RankUtils.THRESHOLDS.length; i++)
        {
            String name = RankUtils.THRESHOLDS[i][0];
            String div = RankUtils.THRESHOLDS[i][1];
            out[i] = "0".equals(div) ? name : name + " " + div;
        }
        return out;
    }

    /** JLabel subclass whose {@link #paintComponent} bypasses the L&F UI
     *  delegate's text rendering — under Substance L&F (which RuneLite
     *  ships with), JLabels auto-truncate with {@code "…"} when their
     *  bounds are narrower than the rendered text's preferred width. By
     *  drawing the text ourselves with {@link Graphics2D#drawString}, the
     *  text simply clips at the component's right edge (no ellipsis).
     *
     *  Intended for player-name labels paired with an {@link RightRow}
     *  that lets the right-side rank chip visually mask the overflowing
     *  characters. Not a drop-in for general JLabels — single-line LTR
     *  text only, no icon, no border insets, vertical-centered baseline. */
    static final class FullLabel extends JLabel
    {
        FullLabel(String text)
        {
            super(text);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            var g2 = (Graphics2D) g.create();
            try
            {
                g2.setRenderingHint(KEY_TEXT_ANTIALIASING,
                    VALUE_TEXT_ANTIALIAS_ON);
                g2.setColor(getForeground());
                g2.setFont(getFont());
                FontMetrics fm = g2.getFontMetrics();
                int baselineY = (getHeight() + fm.getAscent() - fm.getDescent()) / 2;
                String t = getText();
                if (t != null) g2.drawString(t, 0, baselineY);
            }
            finally
            {
                g2.dispose();
            }
        }
    }

    /** Border-aware sibling of {@link FullLabel} used for the
     *  per-row style/build/region chips ([Main], [Pure], [Any Build],
     *  [NA-W], etc.). Same rationale as FullLabel — bypass the
     *  Substance L&F text-rendering path — but here the motivation is
     *  hover stability, not ellipsis suppression: under Substance, a
     *  vanilla JLabel parented inside a panel that has a row-level
     *  MouseListener fanout (PlayerRow's attachAll
     *  installs the same adapter on every descendant) repaints with a
     *  blank foreground on hover state changes, making chip text
     *  intermittently disappear while the cursor sits over a row.
     *
     *  <p>Painting the text directly in paintComponent skips
     *  Substance's LabelUI entirely. The chip's CompoundBorder
     *  (line + empty padding) still paints normally because
     *  {@link JComponent#paintBorder(Graphics)} is independent of the
     *  L&F text path. Honours horizontal-alignment + border insets so
     *  centred and left-aligned chip variants both render correctly. */
    static final class ChipLabel extends JLabel
    {
        ChipLabel(String text)
        {
            super(text);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            var g2 = (Graphics2D) g.create();
            try
            {
                g2.setRenderingHint(KEY_TEXT_ANTIALIASING,
                    VALUE_TEXT_ANTIALIAS_ON);
                g2.setColor(getForeground());
                g2.setFont(getFont());
                Insets in = getInsets();
                FontMetrics fm = g2.getFontMetrics();
                String t = getText();
                if (t == null || t.isEmpty()) return;
                int textW = fm.stringWidth(t);
                // Centre vertically inside the inner content box (height
                // minus border insets). Centre or left-align horizontally
                // based on the JLabel's horizontalAlignment setting so
                // makeActionChip-style centred chips and the default
                // left-aligned chips both render at the right x.
                int innerH = getHeight() - in.top - in.bottom;
                int baselineY = in.top + ((innerH - fm.getHeight()) / 2) + fm.getAscent();
                int x = in.left;
                if (getHorizontalAlignment() == CENTER)
                {
                    int innerW = getWidth() - in.left - in.right;
                    x = in.left + Math.max(0, (innerW - textW) / 2);
                }
                else if (getHorizontalAlignment() == RIGHT
                    || getHorizontalAlignment() == TRAILING)
                {
                    int innerW = getWidth() - in.left - in.right;
                    x = in.left + Math.max(0, innerW - textW);
                }
                g2.drawString(t, x, baselineY);
            }
            finally
            {
                g2.dispose();
            }
        }

        /** Substance L&F's LabelUI computes a preferred width using its
         *  own font metrics that under-report glyph widths for the
         *  derived bold 15pt run we use on the rank slider — the
         *  result is BorderLayout assigning a width slightly less
         *  than the rendered text needs, which Swing then clips at
         *  paint time. Recomputing preferred width from the actual
         *  AWT FontMetrics here gets the layout-time and paint-time
         *  metrics back in sync, so labels like "Bronze 3" /
         *  "3rd Age 1" get exactly the width they paint into.
         *
         *  Pure JLabels (no border, no icon) so the calc is just
         *  insets + text width + tiny safety margin. The +2px
         *  belt-and-braces guards against sub-pixel rounding when
         *  the parent uses a non-integer Graphics2D scale (HiDPI).
         *  Height defers to super so vertical-centring inside
         *  paintComponent agrees with the parent's row height. */
        @Override
        public Dimension getPreferredSize()
        {
            String t = getText();
            if (t == null || t.isEmpty()) return super.getPreferredSize();
            FontMetrics fm = getFontMetrics(getFont());
            Insets in = getInsets();
            int w = fm.stringWidth(t) + in.left + in.right + 2;
            int h = super.getPreferredSize().height;
            return new Dimension(w, h);
        }
    }

    /** Two-child header row where {@code base} spans the row's full width
     *  and {@code overlay} is right-anchored on top of it (in Swing
     *  z-order). The overlay must be opaque with the row's background
     *  colour — that's what visually masks any base content that would
     *  otherwise overflow into the overlay's territory.
     *
     *  Used for player-name rows so long names render their full text and
     *  visually clip under the rank/lookup cluster instead of ellipsizing.
     *  The 4px {@code EmptyBorder(0, 4, 0, 0)} the caller sets on the
     *  overlay provides the "minimal spacing" gap the user requested
     *  between the last visible character of the name and the rank text. */
    static final class RightRow extends CapPanel
    {
        private final JComponent base;
        private final JComponent overlay;

        RightRow(JComponent base, JComponent overlay)
        {
            setLayout(null); // manual layout — neither BorderLayout nor BoxLayout supports z-stacked overlap
            setOpaque(false);
            this.base = base;
            this.overlay = overlay;
            // Swing paints children in REVERSE component-array order, so
            // index 0 is drawn last (= on top). Add overlay first so it
            // wins the z-order against the base.
            add(overlay);
            add(base);
        }

        @Override
        public void doLayout()
        {
            int w = getWidth();
            int h = getHeight();
            Dimension op = overlay.getPreferredSize();
            int ow = Math.min(op.width, w);
            overlay.setBounds(w - ow, 0, ow, h);
            // Base spans the entire row; its right portion is visually
            // masked by the overlay's opaque background where they overlap.
            base.setBounds(0, 0, w, h);
        }

        @Override
        public Dimension getPreferredSize()
        {
            Dimension bp = base.getPreferredSize();
            Dimension op = overlay.getPreferredSize();
            // Preferred = base + overlay so the parent BoxLayout knows the
            // "natural" width. Actual width comes from the parent and may
            // be smaller, in which case base clips under overlay.
            return new Dimension(bp.width + op.width, Math.max(bp.height, op.height));
        }

        @Override
        public Dimension getMinimumSize()
        {
            // Allow the row to shrink horizontally to just the overlay's
            // width — the base happily clips under it.
            Dimension op = overlay.getPreferredSize();
            return new Dimension(op.width, getPreferredSize().height);
        }
    }
}

package com.pvp.leaderboard.ui;

import lombok.*;
import com.pvp.leaderboard.lobby.*;
import com.pvp.leaderboard.queue.*;
import java.awt.*;
import javax.swing.*;

public class QueueGateSection extends JPanel
{
    /** The one matchmaking action (operator 2026-09-22: exactly this text). */
    static final String BUTTON_TEXT = "Queue for Matchmaking";
    static final String WAIT_TITLE = "Willing to wait";

    /** Every queue join goes out with this style and build. */
    public static final Style QUEUE_STYLE = Style.NH;
    public static final BuildType QUEUE_BUILD = BuildType.MAIN;

    /** The wait preference a fresh install queues with (15 min). */
    static final int DEFAULT_WAIT_S = 900;

    private final LobbyPrefs prefs;
    private final JComboBox<String> waitCombo;
    private final QueueRangeSlider range;
    private final JButton queueBtn;
    /** The recent joins, under the queue button. */
    final RecentQueued recent = new RecentQueued();
    /** Told after a <b>local</b> wait pick / rank-range pick so the owner
     *  can write that ONE key of the shared row (G-2). Sending only the
     *  key the user touched is what stops a wait change from overwriting a
     *  rank range set on Discord. Never fired while {@link #applyPrefs}
     *  is running. */
    @Setter private Runnable onWaitChanged;
    @Setter private Runnable onRangeChanged;
    /** Suppresses {@link #announce} while a server push is applied,
     *  so a Discord-side change is not immediately echoed back. */
    private boolean applyingPush;

    public QueueGateSection(LobbyPrefs prefs, float headerPt, Runnable onQueue)
    {
        this.prefs = prefs == null ? LobbyPrefs.inMemory() : prefs;
        setName("matchmaking-queue-section");
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setAlignmentX(LEFT_ALIGNMENT);
        setOpaque(false);
        // Bottom gap lives inside the block so hiding the block hides the gap too.
        setBorder(Ui.pad(0, 0, 12, 0));

        var waitTitle = new JLabel(WAIT_TITLE);
        waitTitle.setName("matchmaking-queue-wait-title");
        add(Ui.bold(waitTitle, headerPt));
        add(Ui.lgap(4));

        waitCombo = new JComboBox<>(waitLabels());
        waitCombo.setName("matchmaking-queue-wait");
        waitCombo.setSelectedIndex(QueueService.waitIndex(this.prefs.getWaitPrefS(DEFAULT_WAIT_S)));
        Ui.left(Ui.maxH(Ui.plain(waitCombo, headerPt), 40));
        waitCombo.setToolTipText("Maximum time in the queue — shared with the Discord queue");
        waitCombo.addActionListener(e ->
        {
            this.prefs.setWaitPrefS(waitPrefS());
            announce(onWaitChanged);
        });
        add(waitCombo);
        add(Ui.lgap(14));

        queueBtn = new JButton(BUTTON_TEXT);
        queueBtn.setName("matchmaking-queue-button");
        Ui.bold(queueBtn, 16f);
        queueBtn.setMargin(new Insets(10, 12, 10, 12));
        Ui.maxH(queueBtn, 44);
        queueBtn.setFocusPainted(false);
        queueBtn.setForeground(Color.WHITE);
        queueBtn.setBackground(Ui.ACCENT);
        queueBtn.setOpaque(true);
        queueBtn.setBorderPainted(false);
        queueBtn.addActionListener(e -> { if (onQueue != null) onQueue.run(); });
        add(queueBtn);
        add(recent);

        // The owner places the rank-range row (above the gate's title).
        boolean rangeOn = this.prefs.getRangeOn();
        range = new QueueRangeSlider(rangeOn ? this.prefs.getMinRank(0) : 0,
            rangeOn ? this.prefs.getMaxRank(-1) : -1);
        range.setOnCommit(this::onRangeSet);
    }

    /** The picker's items, one per {@link QueueService#WAIT_CHOICES} entry. */
    static String[] waitLabels()
    {
        var out = new String[QueueService.WAIT_CHOICES.length];
        for (int i = 0; i < out.length; i++) out[i] = QueueText.waitLabel(QueueService.WAIT_CHOICES[i]);
        return out;
    }

    // ---------------------------------------------------------------- state

    /** The rank-range row this section keeps in step with the prefs. */
    public QueueRangeSlider rangeSlider()
    {
        return range;
    }

    /** The picked wait preference in seconds (one of the shared choices). */
    public int waitPrefS()
    {
        // The picker always holds one of the four choices.
        return QueueService.WAIT_CHOICES[waitCombo.getSelectedIndex()];
    }

    /** {@code true} while the slider is narrower than every rank. */
    public boolean rangeEnabled()
    {
        return range.narrowed();
    }

    public int rangeMinIdx()
    {
        return range.low();
    }

    public int rangeMaxIdx()
    {
        return range.high();
    }

    private void onRangeSet()
    {
        boolean on = range.narrowed();
        prefs.setRangeOn(on);
        if (on)
        {
            prefs.setMinRank(range.low());
            prefs.setMaxRank(range.high());
        }
        announce(onRangeChanged);
    }

    private void announce(Runnable listener)
    {
        if (applyingPush || listener == null) return;
        listener.run();
    }

    /** Applies a {@code queue/prefs} push (the shared row, possibly last
     *  written from Discord) onto the pickers and the persisted copy.
     *
     *  <p>Only the fields the push actually stated are touched — a
     *  {@link QueuePrefs} with no wait preference leaves the dropdown
     *  where the user put it. The outbound hook stays silent throughout,
     *  so applying a push never bounces back to the server. */
    public void applyPrefs(QueuePrefs incoming)
    {
        if (incoming == null) return;
        applyingPush = true;
        try
        {
            if (incoming.hasWaitPref())
            {
                waitCombo.setSelectedIndex(QueueService.waitIndex(incoming.waitPrefS));
                prefs.setWaitPrefS(waitPrefS());
            }
            if (incoming.rangeEnabled != null)
            {
                prefs.setRangeOn(incoming.rangeEnabled);
                if (incoming.rangeEnabled)
                {
                    prefs.setMinRank(incoming.minRankIdx);
                    prefs.setMaxRank(incoming.maxRankIdx);
                    range.setRange(incoming.minRankIdx, incoming.maxRankIdx);
                }
                else
                {
                    range.setRange(0, -1);
                }
            }
        }
        finally
        {
            applyingPush = false;
        }
    }
}

package com.pvp.leaderboard.ui;

import java.awt.*;
import javax.swing.*;
import javax.swing.border.*;

/**
 * The queue's rank range: a caption, the lowest and highest rank in their
 * rank colours, and one two-handle slider over every rank. The full span
 * means no rank limit.
 */
public class QueueRangeSlider extends JPanel
{
    static final String CAPTION = "Only match players in this rank range";

    private final int last;
    private final RangeSlider slider;
    private final JLabel minValue;
    private final JLabel maxValue;
    private Runnable onCommit;
    private boolean applying;

    QueueRangeSlider(int low, int high)
    {
        last = MatchmakingLobbyPanel.rankLabels().length - 1;
        int[] range = normalise(low, high);
        setName("matchmaking-queue-range");
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createCompoundBorder(
            new MatteBorder(1, 0, 1, 0, new Color(60, 60, 60)),
            Ui.pad(6, 2, 6, 2)));
        Ui.maxH(this, 110);

        var caption = new JLabel();
        caption.setName("matchmaking-queue-range-caption");
        Ui.bold(caption, 15f);
        Ui.wrap(caption, CAPTION);
        caption.setForeground(new Color(0xaaaaaa));
        caption.setBorder(Ui.pad(0, 2, 4, 2));

        minValue = MatchmakingLobbyPanel.newRankLabel(range[0]);
        minValue.setName("matchmaking-queue-range-min");
        minValue.setHorizontalAlignment(SwingConstants.LEFT);
        maxValue = MatchmakingLobbyPanel.newRankLabel(range[1]);
        maxValue.setName("matchmaking-queue-range-max");
        maxValue.setHorizontalAlignment(SwingConstants.RIGHT);

        var bounds = new JPanel(new BorderLayout());
        bounds.setOpaque(false);
        Ui.left(Ui.maxH(bounds, 22));
        bounds.setBorder(Ui.pad(0, 2, 0, 2));
        bounds.add(minValue, BorderLayout.WEST);
        bounds.add(maxValue, BorderLayout.EAST);

        slider = new RangeSlider(0, last, range[0], range[1]);
        slider.setName("matchmaking-queue-range-slider");
        slider.setToolTipText("Drag the handles to set the lowest and highest rank to match with");
        Ui.left(slider);
        slider.addChangeListener(e ->
        {
            MatchmakingLobbyPanel.setRankLabel(minValue, slider.getLow());
            MatchmakingLobbyPanel.setRankLabel(maxValue, slider.getHigh());
            if (!applying && !slider.getValueIsAdjusting() && onCommit != null) onCommit.run();
        });

        add(caption);
        add(bounds);
        add(slider);
    }

    /** Runs after the user releases a handle; never for {@link #setRange}. */
    void setOnCommit(Runnable listener)
    {
        onCommit = listener;
    }

    public int low()
    {
        return slider.getLow();
    }

    public int high()
    {
        return slider.getHigh();
    }

    /** {@code true} unless the slider spans every rank. */
    public boolean narrowed()
    {
        return low() > 0 || high() < last;
    }

    /** Moves both handles without reporting a user pick. A negative bound
     *  means unset: the low end starts at the first rank, the high end at
     *  the last. */
    void setRange(int low, int high)
    {
        int[] range = normalise(low, high);
        applying = true;
        try
        {
            slider.setHigh(last);
            slider.setLow(range[0]);
            slider.setHigh(range[1]);
        }
        finally
        {
            applying = false;
        }
    }

    private int[] normalise(int low, int high)
    {
        int lo = low < 0 ? 0 : Math.min(low, last);
        int hi = high < 0 ? last : Math.min(high, last);
        return lo <= hi ? new int[] {lo, hi} : new int[] {hi, lo};
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.queue.*;
import java.awt.*;
import javax.swing.*;

/**
 * The "Searching…" card of the matchmaking queue: the title and the
 * elapsed / limit clock, then the <b>Expand matchmaking range</b> and
 * <b>Leave queue</b> buttons, then the recent joins. Pure rendering of a
 * {@link QueueState}; the owning {@link MatchmakingLobbyPanel} sends the cmds.
 */
public class QueueSearchingPanel extends JPanel
{
    private final JLabel title = new JLabel("Searching…");
    private final JLabel clock = new JLabel(" ");
    private final JButton expand = new JButton("Expand matchmaking range");
    private final JButton leave = new JButton("Leave queue");
    /** The recent joins, under Leave queue. */
    final RecentQueued recent = new RecentQueued();
    private QueueState last;
    /** Seconds in the queue: the last push's, plus one per local tick. */
    private int elapsed;

    public QueueSearchingPanel(Runnable onExpand, Runnable onLeave)
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(Ui.pad(18, 8, 18, 8));
        title.setName("queue-title");
        add(row(Ui.bold(title, 18f)));
        add(Ui.vgap(6));
        clock.setName("queue-clock");
        add(row(Ui.bold(clock, 16f)));
        add(Ui.vgap(12));
        add(row(button(expand, "queue-expand", Ui.ACCENT, Color.WHITE, onExpand)));
        add(Ui.vgap(10));
        add(row(button(leave, "queue-leave", Ui.RED, Ui.RED_FG, onLeave)));
        add(recent);
    }

    /** A bold 14 pt flat button in {@code bg} / {@code fg} that runs {@code action} (when there is one). */
    private static JButton button(JButton b, String name, Color bg, Color fg, Runnable action)
    {
        b.setName(name);
        Ui.bold(b, 14f);
        b.setMargin(new Insets(8, 12, 8, 12));
        b.setBackground(bg);
        b.setForeground(fg);
        b.setOpaque(true);
        b.setBorderPainted(false);
        b.setFocusPainted(false);
        b.addActionListener(e -> { if (action != null) action.run(); });
        return b;
    }

    /** {@code c} (a label or a button: aligned left already) as wide as the card and 4 px taller than it wants. */
    private static <T extends JComponent> T row(T c)
    {
        return Ui.maxH(c, c.getPreferredSize().height + 4);
    }

    /** Re-render from a fresh {@code queue/state}. */
    public void render(QueueState s)
    {
        last = s;
        elapsed = s.elapsedS;
        clock.setText(Ui.mmss(elapsed) + " / " + Ui.mmss(s.waitPrefS));
        expand.setVisible(!(s.expanded || s.window == null));
        revalidate();
        repaint();
    }

    /** Local 1 Hz tick between server pushes: only the elapsed clock moves. */
    public void tick()
    {
        if (last == null) return;
        clock.setText(Ui.mmss(++elapsed) + " / " + Ui.mmss(last.waitPrefS));
    }
}

package com.pvp.leaderboard.ui;

import lombok.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import javax.swing.*;
import javax.swing.event.*;
import java.util.List;

/**
 * Single-track double-handled range slider. Drop-in replacement for two
 * {@link JSlider}s where you want a min and a max bound on the same scale.
 *
 * <p>Why a custom widget instead of {@link JSlider} × 2:
 * <ul>
 *   <li>Two stacked sliders take ~2× the vertical real estate of one
 *       range slider — the lobby panel is height-starved (community box +
 *       nav + filters + roster + chat all share ~700px).</li>
 *   <li>{@link JSlider} reserves a "thumb-radius" inset on each side of
 *       its track which makes the track visually offset from the panel's
 *       left edge — that was the source of the "left-side gap" the user
 *       called out. This widget paints the track edge-to-edge.</li>
 *   <li>The Substance L&F draws JSlider in a way that ignores opacity
 *       overrides, making it impossible to colour-match the lobby palette.</li>
 * </ul>
 *
 * <p>Values are integers in {@code [min, max]} (inclusive); high &ge; low is
 * always enforced. {@link ChangeListener}s fire on every drag tick so
 * callers should defer expensive work until {@link #getValueIsAdjusting()}
 * returns {@code false}.
 */
public class RangeSlider extends JComponent
{
    /** Track thickness in pixels. */
    private static final int TRACK_HEIGHT = 6;
    /** Thumb diameter — also dictates the left/right margin reserved so the
     *  thumbs can sit half-off the track at the extremes. */
    private static final int THUMB_SIZE = 14;
    /** Reserve room above + below the track so the thumbs aren't clipped. */
    private static final int PREF_HEIGHT = 24;

    private static final Color TRACK_COLOR = Ui.DIVIDER;
    private static final Color RANGE_COLOR = new Color(0xff6b00);
    private static final Color THUMB_COLOR = new Color(0xeeeeee);
    private static final Color THUMB_BORDER = new Color(0x222222);

    private final int min;
    private final int max;
    @Getter private int low;
    @Getter private int high;
    /** {@code 0} = low handle, {@code 1} = high handle, {@code -1} = no drag. */
    private int draggingHandle = -1;
    private boolean adjusting;
    private final List<ChangeListener> listeners = new ArrayList<>();

    public RangeSlider(int min, int max, int low, int high)
    {
        if (max <= min) throw new IllegalArgumentException("max must be > min");
        this.min = min;
        this.max = max;
        this.low = clamp(low, min, max);
        this.high = clamp(high, this.low, max);
        setPreferredSize(new Dimension(120, PREF_HEIGHT));
        setMinimumSize(new Dimension(60, PREF_HEIGHT));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, PREF_HEIGHT));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        installMouse();
    }
    public boolean getValueIsAdjusting() { return adjusting; }

    public void setLow(int v)
    {
        int nv = clamp(v, min, high);
        if (nv == low) return;
        low = nv;
        fireChange();
        repaint();
    }

    public void setHigh(int v)
    {
        int nv = clamp(v, low, max);
        if (nv == high) return;
        high = nv;
        fireChange();
        repaint();
    }

    public void addChangeListener(ChangeListener l)
    {
        listeners.add(l);
    }

    private void fireChange()
    {
        var ev = new ChangeEvent(this);
        for (ChangeListener l : listeners) l.stateChanged(ev);
    }

    // -------------------- Mouse handling --------------------

    private void installMouse()
    {
        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                draggingHandle = pickHandleAt(e.getX());
                adjusting = true;
                dragTo(e.getX());
            }

            @Override
            public void mouseReleased(MouseEvent e)
            {
                draggingHandle = -1;
                adjusting = false;
                fireChange();
            }
        });
        addMouseMotionListener(new MouseMotionAdapter()
        {
            @Override
            public void mouseDragged(MouseEvent e)
            {
                if (draggingHandle < 0) return;
                dragTo(e.getX());
            }
        });
    }

    /** Picks the handle nearest the click x. If the click lands inside the
     *  active range we pick the closer of low/high; outside the range we pick
     *  whichever handle the click is nearer to. */
    private int pickHandleAt(int xPx)
    {
        int xLow = valueToX(low);
        int xHigh = valueToX(high);
        return Math.abs(xPx - xLow) <= Math.abs(xPx - xHigh) ? 0 : 1;
    }

    /** Moves the dragged handle (0 = low, 1 = high; the only values while a
     *  drag runs) to the value under {@code xPx}, which is always within
     *  {@code [min, max]}, so the setters' clamp is the drag's own bound. */
    private void dragTo(int xPx)
    {
        int v = xToValue(xPx);
        if (draggingHandle == 0) setLow(v);
        else setHigh(v);
    }

    // -------------------- Geometry --------------------

    /** Effective track width. The track reserves THUMB_SIZE/2 on each side so
     *  a thumb centered on the extreme value sits flush with the panel edge. */
    private int trackWidth() { return Math.max(1, getWidth() - THUMB_SIZE); }

    private int valueToX(int v)
    {
        double t = (double) (v - min) / (max - min);
        return THUMB_SIZE / 2 + (int) Math.round(t * trackWidth());
    }

    private int xToValue(int x)
    {
        double t = (double) (x - THUMB_SIZE / 2) / trackWidth();
        t = Math.max(0.0, Math.min(1.0, t));
        return min + (int) Math.round(t * (max - min));
    }

    private static int clamp(int v, int lo, int hi)
    {
        return Math.max(lo, Math.min(hi, v));
    }

    // -------------------- Painting --------------------

    @Override
    protected void paintComponent(Graphics g)
    {
        var g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int trackY = getHeight() / 2 - TRACK_HEIGHT / 2;

            g2.setColor(TRACK_COLOR);
            g2.fillRoundRect(THUMB_SIZE / 2, trackY, trackWidth(), TRACK_HEIGHT, 4, 4);

            int xLow = valueToX(low);
            int xHigh = valueToX(high);
            g2.setColor(RANGE_COLOR);
            g2.fillRoundRect(xLow, trackY, Math.max(1, xHigh - xLow), TRACK_HEIGHT, 4, 4);

            paintThumb(g2, xLow);
            paintThumb(g2, xHigh);
        }
        finally
        {
            g2.dispose();
        }
    }

    private void paintThumb(Graphics2D g2, int xCenter)
    {
        int yCenter = getHeight() / 2;
        int r = THUMB_SIZE / 2;
        g2.setColor(THUMB_COLOR);
        g2.fillOval(xCenter - r, yCenter - r, THUMB_SIZE, THUMB_SIZE);
        g2.setColor(THUMB_BORDER);
        g2.setStroke(new BasicStroke(1f));
        g2.drawOval(xCenter - r, yCenter - r, THUMB_SIZE - 1, THUMB_SIZE - 1);
    }
}

package com.pvp.leaderboard.ui;

import lombok.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import javax.swing.*;
import javax.swing.plaf.basic.*;
import static com.pvp.leaderboard.ui.Ui.*;

/**
 * The Player Lookup rating rows: one block per bucket with the bucket
 * name, the rank line ({@code "Adamant 3 #731 Top 0.07%"}) and the
 * progress-to-next-rank bar.
 *
 * <p>The <b>Tournament Rating</b> row (index 1) sits between Overall and NH and is
 * hidden until the player has a tournament rating (the bucket is absent
 * from {@code /user} until their first tournament game). Every row also
 * carries two <b>streak lines</b> under the bar ({@code "Current Winstreak 4"}
 * above {@code "Longest Streak 12"}, at the title's size in plain weight),
 * shown only while {@link #setStreaksShown} is on. The streak labels are
 * added after the bar so the rank label stays the block's second
 * {@link JLabel}. Each row is capped at its own height, and keeps 16 px
 * clear on the right for the sidebar's scroll bar.
 */
public class RankProgress extends JPanel
{
    /** Row order on screen. Index 1 (tournament) is hidden until rated. */
    static final String[] BUCKET_KEYS = {"overall", "tournament", "nh", "veng", "multi", "dmm"};
    private static final String[] BUCKET_TITLES = {"Overall Rating", "Tournament Rating", "NH Rating", "Veng Rating", "Multi Rating", "DMM Rating"};
    private static final Color STREAK_FG = new Color(0xcccccc);

    private final JProgressBar[] progressBars = new JProgressBar[6];
    private final JLabel[] rankLabels = new JLabel[6];
    private final JLabel[] streakLabels = new JLabel[6];
    private final JLabel[] longestLabels = new JLabel[6];
    /** The Tournament row and the gap under it. */
    private JPanel tournamentRow;
    private Component tournamentGap;
    @Getter private boolean streaksShown;

    public RankProgress()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        var barSize = new Dimension(200, 16);
        for (int i = 0; i < BUCKET_KEYS.length; i++)
        {
            JPanel bucketPanel = new CapPanel();
            bucketPanel.setLayout(new BoxLayout(bucketPanel, BoxLayout.Y_AXIS));
            bucketPanel.setBorder(pad(0, 0, 0, 16));
            left(bucketPanel);
            bucketPanel.setName("rankBucket-" + BUCKET_KEYS[i]);

            var title = new JLabel(BUCKET_TITLES[i]);
            Font titleFont = title.getFont().deriveFont(Font.BOLD);
            title.setFont(titleFont);
            bucketPanel.add(title);

            rankLabels[i] = new JLabel(" ");
            rankLabels[i].setFont(rankLabels[i].getFont().deriveFont(Font.BOLD));
            bucketPanel.add(rankLabels[i]);

            var bar = new JProgressBar(0, 100);
            bar.setStringPainted(true);
            bar.setString("0%");
            bar.setPreferredSize(barSize);
            bar.setMinimumSize(barSize);
            bar.setMaximumSize(barSize);
            bar.setBorder(pad(0, 0, 0, 0));
            left(bar);
            bar.setUI(new BasicProgressBarUI()
            {
                @Override
                protected Color getSelectionForeground() { return Color.WHITE; }
                @Override
                protected Color getSelectionBackground() { return Color.WHITE; }
            });
            progressBars[i] = bar;
            bucketPanel.add(bar);

            // The streak lines sit after the bar so the rank label stays the block's second JLabel.
            streakLabels[i] = streakLabel("rankStreak-" + BUCKET_KEYS[i], titleFont);
            bucketPanel.add(streakLabels[i]);
            longestLabels[i] = streakLabel("rankStreakLongest-" + BUCKET_KEYS[i], titleFont);
            bucketPanel.add(longestLabels[i]);

            add(bucketPanel);
            Component gap = i < BUCKET_KEYS.length - 1 ? add(vgap(14)) : null;
            if (i == 1)
            {
                tournamentRow = bucketPanel;
                tournamentGap = gap;
            }
        }
        setTournamentRowVisible(false);
    }

    private static JLabel streakLabel(String name, Font titleFont)
    {
        var label = new JLabel(name.startsWith("rankStreakLongest-") ? bestText(0) : streakText(0, false));
        label.setFont(titleFont.deriveFont(Font.PLAIN));
        label.setForeground(STREAK_FG);
        label.setName(name);
        label.setVisible(false);
        return label;
    }

    private void setTournamentRowVisible(boolean visible)
    {
        tournamentRow.setVisible(visible);
        tournamentGap.setVisible(visible);
        revalidate();
        repaint();
    }

    /** Shows or hides the streak lines under every row (Swing thread). */
    public void setStreaksShown(boolean shown)
    {
        streaksShown = shown;
        for (int i = 0; i < BUCKET_KEYS.length; i++)
        {
            streakLabels[i].setVisible(shown);
            longestLabels[i].setVisible(shown);
        }
        revalidate();
        repaint();
    }

    /**
     * @param topPercent the player's "Top X.XX%" for this bucket (from the
     *                   rank histogram), or {@code null} to omit the suffix.
     *                   Renders {@code "Adamant 3 #731 Top X.XX%"}.
     */
    public void updateBucket(String bucket, String rankLabel, int division, double pct, int rankNumber, String topPercent)
    {
        updateBucket(bucket, rankLabel, division, pct, rankNumber, topPercent, -1, -1);
    }

    /**
     * Full form: {@code streak} / {@code bestStreak} feed the streak lines
     * under the bar; pass {@code -1} for either to leave the lines as they
     * are (the rank-only refreshes do). A {@code "—"} rank on the tournament
     * row hides that row; anything else shows it.
     */
    public void updateBucket(String bucket, String rankLabel, int division, double pct, int rankNumber, String topPercent,
                             int streak, int bestStreak)
    {
        int idx = getBucketIndex(bucket);
        if (idx < 0) return;
        SwingUtilities.invokeLater(() -> {
            Color rankColor = RankUtils.getRankColor(rankLabel);

            String displayRank = rankLabel + (division > 0 ? " " + division : "");
            if (rankNumber > 0)
            {
                displayRank += " #" + rankNumber;
            }
            if (topPercent != null && !topPercent.isEmpty())
            {
                displayRank += " " + topPercent;
            }
            rankLabels[idx].setText(displayRank);
            rankLabels[idx].setForeground(rankColor);

            progressBars[idx].setValue((int) pct);
            progressBars[idx].setString(Math.round(pct) + "%");
            progressBars[idx].setForeground(rankColor);

            if (streak >= 0 && bestStreak >= 0)
            {
                setStreaks(idx, streak, false, bestStreak);
            }
            if (idx == 1)
            {
                setTournamentRowVisible(rankLabel != null && !"—".equals(rankLabel) && !rankLabel.trim().isEmpty());
            }
        });
    }

    public void updateStreak(String bucket, int streak, boolean plus, int bestStreak)
    {
        int idx = getBucketIndex(bucket);
        if (idx < 0) return;
        SwingUtilities.invokeLater(() -> setStreaks(idx, streak, plus, bestStreak));
    }

    private void setStreaks(int idx, int streak, boolean plus, int bestStreak)
    {
        streakLabels[idx].setText(streakText(streak, plus));
        longestLabels[idx].setText(bestText(bestStreak));
        streakLabels[idx].setVisible(streaksShown);
        longestLabels[idx].setVisible(streaksShown);
    }

    /** {@code "Current Winstreak 4"} ({@code "100+"} when the loaded history ran out before a loss). */
    static String streakText(int streak, boolean plus)
    {
        return "Current Winstreak " + Math.max(0, streak) + (plus ? "+" : "");
    }

    /** {@code "Longest Streak 12"}. */
    static String bestText(int bestStreak)
    {
        return "Longest Streak " + Math.max(0, bestStreak);
    }

    public void reset()
    {
        SwingUtilities.invokeLater(() -> {
            for (int i = 0; i < BUCKET_KEYS.length; i++)
            {
                rankLabels[i].setText(" ");
                rankLabels[i].setForeground(UIManager.getColor("Label.foreground"));
                progressBars[i].setValue(0);
                progressBars[i].setString("0%");
                progressBars[i].setForeground(UIManager.getColor("ProgressBar.foreground"));
                streakLabels[i].setText(streakText(0, false));
                streakLabels[i].setVisible(false);
                longestLabels[i].setText(bestText(0));
                longestLabels[i].setVisible(false);
            }
            setTournamentRowVisible(false);
        });
    }

    private static int getBucketIndex(String bucket)
    {
        return Arrays.asList(BUCKET_KEYS).indexOf(bucket == null ? null : bucket.toLowerCase());
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.queue.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.time.*;
import java.util.List;
import javax.swing.*;

/** "Recently Queued", the time zone, then "Name - HH:mm" per join in the order given; hidden with no joins. */
class RecentQueued extends Ui.CapPanel
{
    RecentQueued()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(Ui.pad(12, 0, 0, 0));
        setOpaque(false);
        Ui.left(this);
        setVisible(false);
    }

    /** Shows {@code joins} in {@code clock}'s zone; an empty list hides the section. */
    void show(List<RecentJoin> joins, Clock clock)
    {
        removeAll();
        setVisible(!joins.isEmpty());
        if (!joins.isEmpty())
        {
            line(QueueText.RECENT, Font.BOLD, 16f, null);
            line(TimeText.zone(ZonedDateTime.now(clock)), Font.PLAIN, 13f, Ui.MUTED);
            for (RecentJoin j : joins) line(j.getName() + " - " + TimeText.hhmm(j.getAt(), clock.getZone()), Font.PLAIN, 14f, null);
        }
        revalidate();
        repaint();
    }

    /** A plain-text line: HTML is off before the text is set. */
    private void line(String text, int style, float pt, Color fg)
    {
        JLabel l = Ui.label(null, "", style, pt, fg);
        l.putClientProperty("html.disable", true);
        l.setText(text);
        add(l);
    }
}

package com.pvp.leaderboard.ui;

import java.awt.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import lombok.*;
import java.util.List;
import static com.pvp.leaderboard.ui.Ui.*;

/**
 * Width-driven font fit for a column of uniform rows, shared by
 * {@link TierPanel} and {@link TopPlayers}.
 *
 * <p>Both views face the same problem: a fixed point size either wastes
 * a wide sidepanel or ellipsizes text in a narrow one. So each row's text
 * columns are sized together: the largest point size (searching down from
 * the cap) at which every row's columns fit side by side, one size for the
 * whole list because mixed sizes down a column read as a rendering bug.
 * The widest row therefore governs the list. A panel describes its rows
 * once ({@code min} / {@code max} point size, the width a row loses to its
 * padding and gaps, and per text column a font style and how many points
 * below the row size it renders); this class owns the search, the
 * measuring and the applying. The tournament views use only the search and
 * the measuring (the no-argument constructor).
 *
 * <p>Not thread-safe, and not meant to be: the measuring label is
 * mutated per query, so use one instance per panel from the EDT.
 */
@RequiredArgsConstructor
final class RowTextFit
{
    /**
     * Off-tree label used to measure candidate sizes. Deliberately
     * parentless: it inherits the same Look-and-Feel text metrics as the
     * real labels, but mutating it can't revalidate anything mid-layout.
     */
    private final JLabel measurer = new JLabel();

    /** The point-size floor (a legibility limit: below it we'd rather clip
     *  than render text no one can read), the cap (only stops a very wide
     *  panel turning the list into an endless scroll), and the width each
     *  row loses to its padding and the gaps between its columns. */
    private final int min, max, gap;
    /** Text the first column is sized to so a column lines up down the
     *  list (Top players' {@code "#100"}), or {@code null}. */
    private final String fixed;
    /** Per text column: the font style, and how many points below the row size. */
    private final int[] styles, deltas;
    /** Every row: its panel, then its labels by column. */
    final List<JComponent[]> rows = new ArrayList<>();
    /** Point size currently applied to the rows; -1 until the first fit. */
    int applied = -1;

    /** Search and measuring only. */
    RowTextFit()
    {
        this(0, 0, 0, null, null, null);
    }

    /**
     * Largest point size in {@code [minPt, maxPt]} for which
     * {@code fitsAt} holds, searching downward from the cap and stopping
     * at the first fit. Falls back to {@code minPt} when nothing fits —
     * the floor is a legibility limit, so below it we'd rather clip than
     * render text no one can read.
     */
    int largestFitting(int minPt, int maxPt, IntPredicate fitsAt)
    {
        for (int pt = maxPt; pt > minPt; pt--)
        {
            if (fitsAt.test(pt))
            {
                return pt;
            }
        }
        return minPt;
    }

    /**
     * Width the layout will actually demand for {@code text} at
     * {@code font}.
     *
     * <p>Measured through a JLabel's own preferred size rather than
     * {@link java.awt.FontMetrics#stringWidth}, because that is what the
     * row's layout manager asks for when it sizes the cell. The two
     * disagree whenever the Look-and-Feel enables fractional metrics or
     * text antialiasing — RuneLite's does — and measuring the wrong one
     * lets the fit pick a size the layout can't honour, which Swing
     * renders as ellipsized text ("Adamant 1" → "Adaman...").
     */
    int textWidth(String text, Font font)
    {
        measurer.setFont(font);
        measurer.setText(text);
        return measurer.getPreferredSize().width;
    }

    /** Row height the layout will demand for {@code font}, measured the
     *  same way as {@link #textWidth} so a row can't cap its own text. */
    int textHeight(Font font)
    {
        measurer.setFont(font);
        measurer.setText("Ag");
        return measurer.getPreferredSize().height;
    }

    /** The Look-and-Feel label font every fitted size derives from. */
    static Font baseFont()
    {
        Font base = UIManager.getFont("Label.font");
        return base != null ? base : new Font("SansSerif", Font.PLAIN, 12);
    }

    /** A row named {@code name} holding {@code labels} WEST, CENTER and EAST
     *  in that order (4 px side and 2 px top/bottom padding, 6 px gaps),
     *  registered for the fit. */
    JPanel row(String name, JLabel... labels)
    {
        var row = new JPanel(new BorderLayout(6, 0));
        row.setName(name);
        row.setBorder(pad(2, 4, 2, 4));
        left(row);
        String[] where = {BorderLayout.WEST, BorderLayout.CENTER, BorderLayout.EAST};
        var r = new JComponent[labels.length + 1];
        r[0] = row;
        for (int i = 0; i < labels.length; i++)
        {
            row.add(labels[i], where[i]);
            r[i + 1] = labels[i];
        }
        rows.add(r);
        return row;
    }

    /** Brand-new labels carry no fitted font, so the fit starts again from
     *  the cap — a size "already applied" to discarded rows would otherwise
     *  short-circuit it — and then fits {@code width}. */
    void restart(int width)
    {
        applied = -1;
        apply(max);
        refit(width);
    }

    /**
     * Fits the rows to a panel {@code width} wide; nothing while the panel
     * is not laid out yet or has no rows.
     *
     * <p>Backstop: the search measures a stand-in label, but these are the
     * real components the layout will size. If the installed Look-and-Feel
     * makes them even slightly wider than the stand-in, step down until
     * they genuinely fit — a shortfall is what Swing renders as an
     * ellipsized name. Normally costs zero iterations.
     */
    void refit(int width)
    {
        int usable = width - gap;
        if (rows.isEmpty() || usable <= 0)
        {
            return;
        }
        apply(largestFitting(min, max, pt -> fits(pt, usable, false)));
        while (applied > min && !fits(applied, usable, true))
        {
            apply(applied - 1);
        }
    }

    /** Whether every row's columns fit {@code usable} side by side at
     *  {@code pt}: measured on the stand-in, or ({@code live}) on the labels
     *  at the size currently applied. */
    private boolean fits(int pt, int usable, boolean live)
    {
        Font[] f = fonts(pt);
        for (JComponent[] r : rows)
        {
            int needed = 0;
            for (int i = 1; i < r.length; i++)
            {
                needed += live ? r[i].getPreferredSize().width
                    : textWidth(i == 1 && fixed != null ? fixed : ((JLabel) r[i]).getText(), f[i - 1]);
            }
            if (needed > usable)
            {
                return false;
            }
        }
        return true;
    }

    /** Sets every row to {@code pt}: the column fonts, the fixed column's
     *  width, and the row's maximum height, which BoxLayout caps it at, so
     *  it has to track the font or taller glyphs get clipped. Idempotent —
     *  avoids a setFont/revalidate layout loop. */
    void apply(int pt)
    {
        if (pt == applied)
        {
            return;
        }
        applied = pt;
        Font[] f = fonts(pt);
        int h = 0;
        for (Font x : f)
        {
            h = Math.max(h, textHeight(x) + 4);
        }
        Dimension size = fixed == null ? null : new Dimension(textWidth(fixed, f[0]), h);
        var rowMax = new Dimension(Integer.MAX_VALUE, h);
        for (JComponent[] r : rows)
        {
            for (int i = 1; i < r.length; i++)
            {
                r[i].setFont(f[i - 1]);
                if (i == 1 && size != null)
                {
                    r[i].setPreferredSize(size);
                }
            }
            r[0].setMaximumSize(rowMax);
        }
    }

    private Font[] fonts(int pt)
    {
        var f = new Font[styles.length];
        for (int i = 0; i < f.length; i++)
        {
            f[i] = baseFont().deriveFont(styles[i], (float) (pt - deltas[i]));
        }
        return f;
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import java.util.concurrent.*;
import javax.swing.*;
import static com.pvp.leaderboard.ui.Ui.*;

/**
 * "What are the ranks" view: every tier from 3rd Age down to Bronze 3 with
 * a live "Top X%" derived from the infra-side rank histogram
 * ({@code rank_hist/<bucket>.json}, see {@code backend/core/rank_histogram.py}).
 *
 * <p>A bucket toggle ([Overall][NH][Veng][Multi][DMM], NH selected by
 * default) mirrors the Performance Breakdown selector in Player Lookup.
 * Switching buckets re-fetches that bucket's histogram (cached per bucket)
 * and recomputes the per-tier share of the population at or above each
 * tier's MMR cutoff.
 *
 * <p>Row text: the bold tier name is the row's primary element; the value
 * column renders one point below it, plain. The font cap (18 pt) matters
 * because 25 rows scale together: past it the list turns into a long scroll
 * and dwarfs the bucket toggles above it. The widest string in the view
 * governs the whole list — currently the "No one yet" placeholder.
 */
public class TierPanel extends RowsPanel
{
    private static final Color VALUE_COLOR = new Color(200, 200, 200);

    private final PvpApi pvpApi;

    private final JPanel bar;
    /** Tier name and value: 9-18 pt; a row loses 2 x 4 px padding and one 6 px gap. */
    private final RowTextFit fit = new RowTextFit(9, 18, 14, null, new int[]{Font.BOLD, Font.PLAIN}, new int[]{0, 1});
    /** bucket key → fetched histogram (avoids refetching on toggle). */
    private final Map<String, JsonObject> histCache = new ConcurrentHashMap<>();

    private volatile String selectedBucket = "nh";

    public TierPanel(PvpApi pvpApi)
    {
        this.pvpApi = pvpApi;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        // Two rows of 3 (Overall/NH/Veng · Multi/DMM) — five labels don't fit
        // on one row in the ~225px sidepanel.
        bar = left(maxH(bucketBar("rankTierBucketBar", "rankTierBucketBtn", 2, 3, Arrays.copyOf(BUCKETS, 5), this::loadBucket), 52));
        add(bar);
        add(buildTiers());
        styleBucketBar(bar, selectedBucket);
    }

    /**
     * Trigger (or refresh) the histogram load for the selected bucket.
     * Called by {@link Dashboard} when the view is revealed so no
     * network request happens until the user actually opens it. Cached
     * buckets render instantly; a previously-failed fetch is retried.
     */
    public void onShown()
    {
        loadBucket(selectedBucket);
    }

    /** One row per tier, 3rd Age first; row {@code j} is {@code THRESHOLDS[24 - j]}. */
    private JPanel buildTiers()
    {
        var list = new JPanel();
        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setName("rankTierList");
        left(list);

        String[][] thresholds = RankUtils.THRESHOLDS;
        for (int i = thresholds.length - 1; i >= 0; i--)
        {
            String rankName = thresholds[i][0];
            var nameLabel = new JLabel("3rd Age".equals(rankName) ? rankName : rankName + " " + thresholds[i][1]);
            nameLabel.setName("tierName");
            nameLabel.setForeground(RankUtils.getRankColor(rankName));

            // Right-aligned in CENTER (not EAST) so the value uses all the
            // space left of the inner edge: every row's value ends flush at
            // the same right margin (an "equalized" column) and a long
            // "No one yet" stays fully visible.
            var valueLabel = new JLabel("—");
            valueLabel.setName("tierValue");
            valueLabel.setForeground(VALUE_COLOR);
            valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);

            list.add(fit.row("tierRow", nameLabel, valueLabel));
        }
        // Rows start at the cap; the first layout narrows them to whatever
        // the real sidepanel width allows.
        fit.restart(getWidth());
        return list;
    }

    /**
     * Re-fit the row text to the panel's current width before laying out.
     *
     * <p>Hooked here rather than on a resize listener so the fit is driven
     * by the same pass that positions the rows — a test can drive it with
     * {@code setSize} + {@code doLayout} instead of pumping resize events,
     * and there's no window where the text is sized for a stale width.
     */
    @Override
    public void doLayout()
    {
        fit.refit(getWidth());
        super.doLayout();
    }

    /** {@code bucketKey} is a bar key or {@link #selectedBucket}: trimmed, lower case. */
    private void loadBucket(String bucketKey)
    {
        selectedBucket = bucketKey;
        styleBucketBar(bar, bucketKey);

        JsonObject cached = histCache.get(bucketKey);
        if (cached != null)
        {
            applyHist(cached);
            return;
        }

        if (pvpApi == null)
        {
            setAllValues("Unavailable");
            return;
        }

        setAllValues("…"); // ellipsis = loading
        CompletableFuture<JsonObject> future = pvpApi.getHistogram(bucketKey);
        if (future == null)
        {
            setAllValues("Unavailable");
            return;
        }
        future.thenAccept(hist -> SwingUtilities.invokeLater(() ->
        {
            if (hist != null && hist.has("bins"))
            {
                histCache.put(bucketKey, hist);
                if (bucketKey.equals(selectedBucket)) applyHist(hist);
            }
            else if (bucketKey.equals(selectedBucket))
            {
                setAllValues("Unavailable");
            }
        })).exceptionally(ex ->
        {
            SwingUtilities.invokeLater(() ->
            {
                if (bucketKey.equals(selectedBucket)) setAllValues("Unavailable");
            });
            return null;
        });
    }

    private void applyHist(JsonObject hist)
    {
        long total = RankUtils.histTotal(hist);
        String[][] t = RankUtils.THRESHOLDS;
        for (int i = 0; i < t.length; i++)
        {
            long atOrAbove = RankUtils.totalAbove(hist, Double.parseDouble(t[i][2]));
            ((JLabel) fit.rows.get(t.length - 1 - i)[2]).setText(RankUtils.formatTopPercent(atOrAbove, total));
        }
        // The values just changed width ("—" → "No one yet"),
        // so the fit is stale even though the panel hasn't resized.
        fit.refit(getWidth());
    }

    private void setAllValues(String text)
    {
        for (JComponent[] row : fit.rows)
        {
            ((JLabel) row[2]).setText(text);
        }
        fit.refit(getWidth());
    }
}

package com.pvp.leaderboard.ui;

import lombok.*;
import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import com.pvp.leaderboard.util.*;
import java.awt.*;
import java.util.*;
import java.util.concurrent.*;
import javax.swing.*;
import java.util.List;
import static com.pvp.leaderboard.ui.Ui.*;

/**
 * "Top players" view — a scrollable Top 100 leaderboard mirroring the website,
 * one row per account: <code>#rank &nbsp; Player Name &nbsp; Rank</code>, sized
 * to the largest font the sidepanel width allows.
 *
 * <p>Reads the exact same cached S3 artifact the website uses
 * ({@code /leaderboard[_<bucket>].json}) via
 * {@link PvpApi#getLeaderboard(String)} — a single CDN call cached
 * ~1 hour. A bucket toggle ([Overall][NH][Veng][Multi][DMM][Tournament], NH
 * by default) matches the website's leaderboard tabs and the sibling "What
 * are the ranks" view. Unlike the website, only the account's first/primary
 * name is shown.
 *
 * <p>Row text: the player name is the row's primary element; the rank number
 * and tier columns render one point below it, bold. The rank column is sized
 * to {@code "#100"}, the widest rank number a top-100 list can show, so the
 * names line up down the list. The font cap (20 pt) only stops a very wide
 * panel turning 100 rows into an endless scroll; width is meant to bind at
 * any realistic sidepanel size.
 */
public class TopPlayers extends RowsPanel
{
    private static final Color RANKNUM_COLOR = new Color(0xcfa84a); // muted gold

    /** One leaderboard row, derived purely from the cached JSON. */
    @AllArgsConstructor
    static final class Row
    {
        final int worldRank;
        final String name;
        final String rankFamily; // e.g. "Rune" / "3rd Age" — drives the colour
        final String tierLabel;  // e.g. "Rune 1" / "3rd Age"
    }

    private final PvpApi pvpApi;

    private final JPanel bar;
    private final JPanel listPanel = new JPanel();
    private final JLabel statusLabel = new JLabel();

    /** Rank number, name and tier: 9-20 pt; a row loses 2 x 4 px padding and two 6 px gaps. */
    private final RowTextFit fit = new RowTextFit(9, 20, 20, "#100",
        new int[]{Font.BOLD, Font.PLAIN, Font.BOLD}, new int[]{1, 0, 1});

    private volatile String selectedBucket = "nh";

    public TopPlayers(PvpApi pvpApi)
    {
        this.pvpApi = pvpApi;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));

        bar = left(maxH(bucketBar("topPlayersBucketBar", "topPlayersBucketBtn", 2, 3, BUCKETS, this::loadBucket), 52));
        add(bar);

        statusLabel.setName("topPlayersStatus");
        statusLabel.setForeground(Color.GRAY);
        statusLabel.setBorder(pad(2, 6, 4, 6));
        add(statusLabel);

        listPanel.setName("topPlayersList");
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        left(listPanel);
        add(listPanel);

        styleBucketBar(bar, selectedBucket);
    }

    /** Lazy load entry-point — called when the view is revealed. */
    public void onShown()
    {
        loadBucket(selectedBucket);
    }

    /** {@code bucketKey} is a bar key or {@link #selectedBucket}: trimmed, lower case. */
    private void loadBucket(String bucketKey)
    {
        selectedBucket = bucketKey;
        styleBucketBar(bar, bucketKey);

        if (pvpApi == null)
        {
            showStatus("Unavailable");
            return;
        }

        // Single source of truth for caching: PvpApi.getLeaderboard
        // is backed by the shared 60-minute shard cache (same hourly refresh
        // the website's CDN object uses). We deliberately keep NO long-lived
        // copy here — a per-panel cache would shadow that TTL and serve stale
        // rows for the whole session. Each tab visit / bucket toggle re-asks;
        // within the hour it's a cache hit (no network), after the hour it
        // refetches.
        CompletableFuture<JsonObject> future = pvpApi.getLeaderboard(bucketKey);
        if (future == null)
        {
            showStatus("Unavailable");
            return;
        }

        // Already cached (future completed) → render immediately, no flash.
        JsonObject ready = future.getNow(null);
        if (ready != null)
        {
            renderTop(ready);
            return;
        }

        showStatus("Loading…");
        future.thenAccept(data -> SwingUtilities.invokeLater(() ->
        {
            if (bucketKey.equals(selectedBucket)) renderTop(data);
        })).exceptionally(ex ->
        {
            SwingUtilities.invokeLater(() ->
            {
                if (bucketKey.equals(selectedBucket)) showStatus("Unavailable");
            });
            return null;
        });
    }

    /** Both callers have just checked that {@code data} is for the selected bucket. */
    private void renderTop(JsonObject data)
    {
        if (data != null && data.has("players"))
        {
            renderRows(parseTop(data, 100));
        }
        else
        {
            showStatus("Unavailable");
        }
    }

    private void showStatus(String text)
    {
        listPanel.removeAll();
        fit.rows.clear();
        statusLabel.setText(text);
        listPanel.revalidate();
        listPanel.repaint();
        revalidateUp();
    }

    private void renderRows(List<Row> rows)
    {
        listPanel.removeAll();
        fit.rows.clear();
        if (rows.isEmpty())
        {
            showStatus("No ranked players yet for this bucket.");
            return;
        }
        statusLabel.setText("Showing top " + rows.size());
        for (Row r : rows)
        {
            listPanel.add(buildRow(r));
        }
        // The rows that decide the fit only exist now, and the panel itself
        // hasn't resized, so nothing else would trigger it.
        fit.restart(getWidth());
        listPanel.revalidate();
        listPanel.repaint();
        revalidateUp();
    }

    /**
     * Rows load asynchronously after the view is first shown, but our enclosing
     * {@link JScrollPane} is a Swing "validate root" — so revalidating
     * {@code listPanel} alone re-lays-out the viewport WITHOUT resizing the
     * scroll pane itself within the lookup card (it stays stuck at whatever
     * height it had while empty/"Loading…", showing only a handful of rows).
     * Revalidating the scroll pane's parent forces the surrounding layout to
     * grow the view to the full row count immediately instead of waiting for an
     * unrelated outer resize/scroll event.
     */
    private void revalidateUp()
    {
        Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, this);
        Container target = (scrollPane != null) ? scrollPane.getParent() : getParent();
        if (target != null)
        {
            target.revalidate();
            target.repaint();
        }
    }

    private JPanel buildRow(Row r)
    {
        var rankNum = new JLabel("#" + r.worldRank);
        rankNum.setName("topPlayerRankNum");
        rankNum.setForeground(RANKNUM_COLOR);

        var name = new JLabel(r.name);
        name.setName("topPlayerName");
        name.setForeground(Color.WHITE);

        // Rank tier only — the in-tier "% to next" used to sit here, but it
        // was the widest thing in the row and bought the least: it pushed
        // the auto-fit down and squeezed the player name.
        var tier = new JLabel(r.tierLabel);
        tier.setName("topPlayerTier");
        tier.setForeground(RankUtils.getRankColor(r.rankFamily));
        tier.setHorizontalAlignment(SwingConstants.RIGHT);

        return fit.row("topPlayerRow", rankNum, name, tier);
    }

    /**
     * Re-fit the row text to the panel's current width before laying out.
     *
     * <p>Hooked here rather than on a resize listener so the fit is driven
     * by the same pass that positions the rows — there's no window where
     * the text is sized for a stale width.
     */
    @Override
    public void doLayout()
    {
        fit.refit(getWidth());
        super.doLayout();
    }

    /** Per-account aggregate built while de-duplicating the raw player rows. */
    private static final class Agg
    {
        final LinkedHashSet<String> names = new LinkedHashSet<>();
        double mmr = Double.NEGATIVE_INFINITY;
        String rank = null;
        int division = 0;
    }

    /**
     * Convert a cached leaderboard payload into the top {@code limit} display
     * rows, mirroring the website's {@code fetchLeaderboard} exactly:
     * <ol>
     *   <li>keep only rows with an account id + finite MMR;</li>
     *   <li>de-duplicate by account ({@code account_hash || account}) — the S3
     *       file can carry more than one row per account — unioning names in
     *       first-seen order and keeping the highest-MMR entry's rank/division;</li>
     *   <li>sort by MMR descending, assign world rank by position;</li>
     *   <li>take the top {@code limit}.</li>
     * </ol>
     * The plugin shows only the account's first/primary name (the website
     * joins them all).
     *
     * <p>Pure + null-safe so it's unit-testable without Swing/network.
     */
    static List<Row> parseTop(JsonObject data, int limit)
    {
        Map<String, Agg> byAccount = new LinkedHashMap<>();
        for (JsonElement el : JsonLenient.optArray(data, "players"))
        {
            if (!el.isJsonObject()) continue;
            JsonObject p = el.getAsJsonObject();
            double mmr = JsonLenient.optDouble(p, "mmr", JsonLenient.optDouble(p, "MMR", Double.NaN));
            String account = accountOf(p);
            if (!Double.isFinite(mmr) || account == null) continue;

            Agg agg = byAccount.computeIfAbsent(account, k -> new Agg());
            addNames(agg.names, p);
            if (mmr > agg.mmr)
            {
                agg.mmr = mmr;
                agg.rank = strOrNull(p, "rank");
                agg.division = JsonLenient.optInt(p, "division", 0);
            }
        }

        List<Agg> ranked = new ArrayList<>(byAccount.values());
        ranked.sort((a, b) -> Double.compare(b.mmr, a.mmr));

        List<Row> rows = new ArrayList<>();
        int n = Math.min(Math.max(0, limit), ranked.size());
        for (int i = 0; i < n; i++)
        {
            Agg a = ranked.get(i);
            String rankFamily = a.rank;
            int division = a.division;
            if (rankFamily == null)
            {
                RankInfo ri = RankUtils.toRankInfo(a.mmr);
                rankFamily = ri.rank;
                division = ri.division;
            }
            rows.add(new Row(i + 1, a.names.isEmpty() ? "Unknown" : a.names.iterator().next(), rankFamily,
                "3rd Age".equals(rankFamily) ? rankFamily : rankFamily + " " + division));
        }
        return rows;
    }

    /** Account id, mirroring the website's {@code account_hash || account}. */
    private static String accountOf(JsonObject p)
    {
        String a = strOrNull(p, "account_hash");
        return (a != null) ? a : strOrNull(p, "account");
    }

    private static void addNames(Set<String> out, JsonObject p)
    {
        try
        {
            for (JsonElement n : JsonLenient.optArray(p, "player_names"))
            {
                if (!n.isJsonNull() && !n.getAsString().trim().isEmpty()) out.add(n.getAsString());
            }
        }
        catch (RuntimeException ignore) { }
    }

    /** The key's text, or {@code null} when absent, not text, or blank. */
    private static String strOrNull(JsonObject p, String key)
    {
        String s = JsonLenient.optString(p, key);
        return s.trim().isEmpty() ? null : s;
    }
}

package com.pvp.leaderboard.ui;

import com.pvp.leaderboard.tournament.*;
import java.awt.*;
import java.time.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import java.util.List;
import static com.pvp.leaderboard.ui.TourneyPanel.*;
import static com.pvp.leaderboard.ui.Ui.*;
import static java.awt.Font.*;

final class TournamentInfoCard extends CapPanel
{
    static final String REPORT_LABEL = "Report an issue";
    static final String REPORT_TOOLTIP = "Report an issue with this tournament — the message goes to its host on Discord";
    static final String LOGIN_TIP = "Log in with Discord to contact the host";

    /** The lobby's chip palette: region white, style yellow, build cyan. */
    private static final Color CHIP_FORMAT = Color.WHITE;
    private static final Color CHIP_CATEGORY = new Color(0xffc107);
    private static final Color CHIP_BUILD = new Color(0x4fc3f7);
    private static final float LINE_PT = 15f;
    private static final float CHIP_PT = 14f;
    /** Card buttons: the full-width one, and the most / least the Report + Rules row may use. */
    static final float BUTTON_PT = 16f;
    /** The width a card's text wraps to (the side panel's card, inside its border). */
    static final int TEXT_WIDTH = 170;

    private final Tourney t;
    private final ZoneId zone;
    private final LongSupplier nowMs;
    private final JLabel when;
    /** {@code null} when the event has no registration window to show. */
    private final JLabel closes;
    private final JButton report;

    /** {@code myCount} is the player's own match count in the event's bucket
     *  ({@code null} when unknown); {@code refused} marks an event whose
     *  registration was refused for its minimum. */
    TournamentInfoCard(Tourney t, String myStatus, boolean discordLoggedIn, ZoneId zone, LongSupplier nowMs, TourneyPanel p,
                       Integer myCount, boolean refused)
    {
        this.t = t;
        this.zone = zone;
        this.nowMs = nowMs;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setName("tournament-card-" + t.tournamentId);
        cardStyle(this);

        header(myStatus);
        add(vgap(3));
        add(chips());
        add(vgap(3));
        addLine("tournament-players-", playersLine(t), INFO);
        String prize = prizeLine(t);
        if (!prize.isEmpty()) addLine("tournament-prize-", prize, INFO);
        String ranks = limitsLine(t);
        if (!ranks.isEmpty()) addLine("tournament-ranks-", ranks, MUTED);
        String need = minGamesLine(t);
        if (!need.isEmpty()) addLine("tournament-min-games-", need, MUTED);
        if (t.creatorName != null && !t.creatorName.trim().isEmpty()) addLine("tournament-host-", "Host: " + t.creatorName.trim(), MUTED);
        if (t.gearSet != null) addLine("tournament-kit-", kitLine(t), INFO);
        when = label("tournament-when-" + t.tournamentId, "", PLAIN, LINE_PT, null);
        add(when);
        if (closes(t, zone, nowMs.getAsLong()).isEmpty())
        {
            closes = null;
        }
        else
        {
            closes = label("tournament-closes-" + t.tournamentId, "", PLAIN, LINE_PT, MUTED);
            add(closes);
        }
        tick();
        add(vgap(6));
        report = tabButton(REPORT_LABEL, "tournament-report-" + t.tournamentId, () -> p.onReport(t.tournamentId));
        add(pairRow(report, tabButton("Rules", "tournament-rules-" + t.tournamentId, () -> p.openRules(t))));
        JComponent signUp = signUp(myStatus, p, myCount, refused);
        if (signUp != null)
        {
            add(vgap(4));
            add(signUp);
        }
        setReportEnabled(discordLoggedIn);
    }

    /** The Report gate: enabled + the host tooltip while logged in with
     *  Discord, disabled + the login hint otherwise. */
    void setReportEnabled(boolean discordLoggedIn)
    {
        report.setEnabled(discordLoggedIn);
        report.setToolTipText(discordLoggedIn ? REPORT_TOOLTIP : LOGIN_TIP);
    }

    /** Re-renders the two time lines (the panel's 1 Hz beat); a label is set only when its text moved. */
    void tick()
    {
        long now = nowMs.getAsLong();
        setWrapped(when, when(t, zone, now));
        if (closes != null) setWrapped(closes, closes(t, zone, now));
    }

    // ---------------------------------------------------------------- rows
    /** The event's name at the card's full width, then the player's status
     *  marker (if any) on its own line. */
    private void header(String myStatus)
    {
        JLabel name = label("tournament-name-" + t.tournamentId, "", BOLD, BUTTON_PT, Color.WHITE);
        wrap(name, t.name);
        add(name);
        if (myStatus != null && !myStatus.isEmpty())
        {
            boolean registered = "registered".equals(myStatus);
            add(label("tournament-my-" + t.tournamentId, registered ? "Registered" : "You: " + myStatus, BOLD, CHIP_PT, registered ? GREEN : MUTED));
            String meeting = meetingLine(t);
            if (registered && !meeting.isEmpty())
            {
                JLabel meet = label("tournament-meeting-" + t.tournamentId, "", PLAIN, CHIP_PT, MUTED);
                wrap(meet, meeting);
                add(meet);
            }
        }
    }

    /** [Swiss] [NH] [Main] — the lobby's [Region] [style] / [build] rows collapsed to one. */
    private JPanel chips()
    {
        var chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
        chips.setOpaque(false);
        chips.setName("tournament-chips-" + t.tournamentId);
        chips.add(chip(formatLabel(t), CHIP_FORMAT));
        chips.add(chip(t.categoryLabel(), CHIP_CATEGORY));
        chips.add(chip(t.buildLabel(), CHIP_BUILD));
        return pin(left(chips));
    }

    private void addLine(String namePrefix, String text, Color fg)
    {
        JLabel l = label(namePrefix + t.tournamentId, "", PLAIN, LINE_PT, fg);
        wrap(l, text);
        add(l);
    }

    /** Register or Withdraw, whichever the event and the player's status
     *  allow, as the card's full-width button; in Register's place the
     *  minimum's sentence when the player is below it; {@code null} for
     *  neither. */
    private JComponent signUp(String myStatus, TourneyPanel p, Integer myCount, boolean refused)
    {
        boolean registered = "registered".equals(myStatus);
        if (registered && (t.isRegOpen() || t.isRunning()))
        {
            JButton withdraw = tabButton("Withdraw", "tournament-withdraw-" + t.tournamentId, () -> p.service.withdraw(t.tournamentId));
            withdraw.setBackground(RED);
            withdraw.setForeground(RED_FG);
            return withdraw;
        }
        if (!registered && (t.isRegOpen() || (t.isRunning() && t.lateJoins)))
        {
            if (belowMinimum(t, myCount, refused))
            {
                JLabel blocked = label("tournament-min-games-blocked-" + t.tournamentId, "", PLAIN, LINE_PT, INFO);
                wrap(blocked, gamesRefusal(t));
                return blocked;
            }
            JButton register = tabButton("Register", "tournament-register-" + t.tournamentId, () -> p.register(t));
            register.setBackground(GREEN);
            register.setForeground(Color.BLACK);
            return register;
        }
        return null;
    }

    /** The pair's side margins: the narrow button takes 4 px a side from the wide one. */
    static final Insets WIDE_MARGIN = new Insets(6, 4, 6, 4);
    static final Insets SLIM_MARGIN = new Insets(6, 12, 6, 12);

    /** Two buttons on one row: {@code narrow} is as wide as its label at
     *  {@link #BUTTON_PT} with its insets plus 8 px of spare room, at
     *  every size; {@code wide} fills the rest, both at the largest size from
     *  {@link #BUTTON_PT} down that keeps {@code wide}'s label on one line;
     *  {@code narrow} gets the wider side margins. */
    static JPanel pairRow(JButton wide, JButton narrow)
    {
        wide.setMargin(WIDE_MARGIN);
        narrow.setMargin(SLIM_MARGIN);
        narrow.setPreferredSize(null);
        narrow.setFont(narrow.getFont().deriveFont(BUTTON_PT));
        int narrowWidth = narrow.getPreferredSize().width + 8;
        for (float pt = BUTTON_PT; pt >= CHIP_PT; pt--)
        {
            wide.setFont(wide.getFont().deriveFont(pt));
            narrow.setFont(narrow.getFont().deriveFont(pt));
            if (wide.getPreferredSize().width + narrowWidth + 4 <= TEXT_WIDTH) break;
        }
        narrow.setPreferredSize(new Dimension(narrowWidth, narrow.getPreferredSize().height));
        narrow.setMinimumSize(new Dimension(narrowWidth, narrow.getMinimumSize().height));
        var row = new JPanel(new BorderLayout(4, 0));
        row.setOpaque(false);
        row.add(wide, BorderLayout.CENTER);
        row.add(narrow, BorderLayout.EAST);
        return pin(left(row));
    }

    /** The lobby's chip: a tight bordered label, bold, coloured border + text. */
    private static JLabel chip(String text, Color color)
    {
        JLabel chip = label(null, text, BOLD, CHIP_PT, color);
        chip.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(color, 1), pad(1, 5, 1, 5)));
        chip.setOpaque(false);
        return chip;
    }

    // ---------------------------------------------------------------- pure text builders
    /** {@code "Swiss"} — the format capitalised, Swiss when unset. */
    static String formatLabel(Tourney t)
    {
        return t.format.isEmpty() ? "Swiss" : Character.toUpperCase(t.format.charAt(0)) + t.format.substring(1);
    }

    static String playersLine(Tourney t)
    {
        List<String> parts = new ArrayList<>();
        if (t.roundsAuto && t.isRegOpen()) parts.add("rounds: auto (set at the start)");
        else if (t.rounds > 0) parts.add(t.rounds + (t.rounds == 1 ? " round" : " rounds"));
        parts.add(t.maxPlayers > 0 ? t.regCount + " / " + t.maxPlayers + " players" : t.regCount + " registered");
        if (t.pluginRequired) parts.add("plugin required");
        return capitalise(String.join(" · ", parts));
    }

    static String prizeLine(Tourney t)
    {
        List<String> parts = new ArrayList<>();
        if (t.buyInGp > 0) parts.add("buy-in " + gp(t.buyInGp));
        String mode = t.prizeMode.trim().toLowerCase(Locale.ROOT);
        if (!"none".equals(mode))
        {
            int topX = Math.max(1, t.prizeTopX);
            parts.add("top_x_random_y".equals(mode)
                ? "prize: top " + topX + " + " + Math.max(0, t.prizeRandomY) + " random full participants"
                : "prize: top " + topX);
            if (t.prizePoolGp > 0) parts.add("prize pool " + gp(t.prizePoolGp));
        }
        return capitalise(String.join(" · ", parts));
    }

    /** {@code "Rank NH Rune 3 – Dragon 1"} / {@code "Min rank NH Rune 3"} / {@code "Max rank DMM Dragon 1"},
     *  one part per bucket ({@code _rank_limit_parts}); {@code ""} when the event has no limits. */
    static String limitsLine(Tourney t)
    {
        List<String> parts = new ArrayList<>();
        for (Tourney.RankLimit l : t.rankLimits)
        {
            String label = Tourney.categoryLabel(l.bucket);
            if (l.minIdx >= 0 && l.maxIdx >= 0) parts.add("rank " + label + " " + rankLabel(l.minIdx) + " – " + rankLabel(l.maxIdx));
            else if (l.minIdx >= 0) parts.add("min rank " + label + " " + rankLabel(l.minIdx));
            else if (l.maxIdx >= 0) parts.add("max rank " + label + " " + rankLabel(l.maxIdx));
        }
        return capitalise(String.join(" · ", parts));
    }

    /** {@code "50 NH matches required"}; {@code ""} when the event has no minimum. */
    static String minGamesLine(Tourney t)
    {
        if (t.minGames <= 0) return "";
        return t.minGames + " " + bucketWord(t) + "matches required";
    }

    /** {@code "You need 50 NH matches to join."} */
    static String gamesRefusal(Tourney t)
    {
        return "You need " + t.minGames + " " + bucketWord(t) + "matches to join.";
    }

    /** {@code true} when the event has a minimum and the player is below it:
     *  a known count under it, or a registration already refused for it.
     *  An unknown count is not below. */
    static boolean belowMinimum(Tourney t, Integer myCount, boolean refused)
    {
        if (t.minGames <= 0) return false;
        if (refused) return true;
        return myCount != null && myCount < t.minGames;
    }

    /** The event bucket's label and a space ({@code "NH "}), or nothing when the event names no bucket. */
    private static String bucketWord(Tourney t)
    {
        return t.category.trim().isEmpty() ? "" : Tourney.categoryLabel(t.category.trim()) + " ";
    }

    /** {@code "Meet on W578 · PvP Arena entrance"} ({@code "Meet on W578"} without a place); {@code ""} without a world. */
    static String meetingLine(Tourney t)
    {
        if (t.meetingWorld == null) return "";
        return "Meet on " + t.meetingWorld + (t.meetingPlace == null ? "" : " · " + t.meetingPlace);
    }

    static String kitLine(Tourney t)
    {
        List<String> parts = new ArrayList<>();
        parts.add("Kit: " + t.gearSet.name);
        parts.add(t.gearSet.buildLabel);
        if (t.gearSet.bookLabel != null) parts.add(t.gearSet.bookLabel);
        String where = t.location == null ? "" : t.location.trim().toLowerCase(Locale.ROOT);
        if (where.isEmpty() || where.contains("arena")) parts.add("PvP Arena duels");
        return String.join(" · ", parts);
    }

    /** {@code 18} → {@code "Rune 3"}, {@code 24} → {@code "3rd Age"}, out of range → {@code "?"}
     *  (the backend's {@code rank_label}). */
    static String rankLabel(int idx)
    {
        return idx < 0 || idx >= PlayerCard.RANK_LABELS.length ? "?" : PlayerCard.RANK_LABELS[idx];
    }

    /** Plain text as {@code <html>} lines joined by {@code <br>}, each no
     *  wider than {@code widthPx} at {@code font}; a word wider than that sits
     *  on its own line. Paragraphs start on a new line. */
    static String wrapHtml(Font font, int widthPx, String... paragraphs)
    {
        List<String> escaped = new ArrayList<>();
        for (String p : paragraphs) escaped.add(escape(p == null ? "" : p));
        return "<html>" + wrapLines(font, widthPx, escaped) + "</html>";
    }

    /** The {@code <br>}-joined lines of {@link #wrapEscaped}, without the
     *  {@code <html>} wrapper, for a label that adds its own markup after them. */
    static String wrapInner(Font font, int widthPx, String escaped)
    {
        return wrapLines(font, widthPx, Collections.singletonList(escaped == null ? "" : escaped));
    }

    /** {@link #wrapHtml} for text that is already escaped (entities, no tags). */
    static String wrapEscaped(Font font, int widthPx, String escaped)
    {
        return "<html>" + wrapInner(font, widthPx, escaped) + "</html>";
    }

    private static String wrapLines(Font font, int widthPx, List<String> paragraphs)
    {
        var fit = new RowTextFit();
        int budget = widthPx - 4;
        var out = new StringBuilder();
        for (String paragraph : paragraphs)
        {
            if (out.length() > 0) out.append("<br>");
            var line = new StringBuilder();
            for (String word : paragraph.split(" "))
            {
                if (word.isEmpty()) continue;
                String candidate = line.length() == 0 ? word : line + " " + word;
                if (line.length() > 0 && fit.textWidth(unescape(candidate), font) > budget)
                {
                    out.append(line).append("<br>");
                    line.setLength(0);
                    line.append(word);
                }
                else
                {
                    line.setLength(0);
                    line.append(candidate);
                }
            }
            out.append(line);
        }
        return out.toString();
    }

    private static String unescape(String s)
    {
        return s.replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&");
    }

    private static String capitalise(String s)
    {
        return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }
}

