        noShowBtn.setVisible(series != null && !told);
        noShowNote.setVisible(told);
        if (told) setWrapped(noShowNote, "Reported." + (noShowAt > 0 ? " It counts at " + TimeText.hhmm(noShowAt, zone) + " if the match has no result." : ""));
    }

