    /** "Registered for X. Meet on W578 at PvP Arena entrance when round 1 opens." — the meeting line
     *  when the push carries one, else the sentence about the round's own message. */
    static String regBanner(Tourney t)
    {
        String head = "Registered for " + escape(t.name) + ". ";
        if (t.meetingWorld != null) return head + "Meet on " + escape(t.meetingWorld) + (t.meetingPlace == null ? "" : " at " + escape(t.meetingPlace)) + " when round 1 opens.";
        return head + "Your opponent, world and meeting place arrive here when each round opens.";
    }

    @Override
    public void onWithdrawn(String tournamentId)
    {
        showBanner("You withdrew from the tournament.");
        if (tournamentId.equals(activeId)) clearActive();
        service.list();
        service.status();
    }

    @Override
    public void onTournamentState(List<Tourney> registrations, LiveTourney state)
    {
        myRegs = registrations;
        if (state == null || !state.isRunning())
        {
            if (activeId != null) clearActive();
            renderList();
            return;
        }
        activeId = state.tournamentId;
        activeName = state.name;
        round = state.round;
        rounds = state.rounds;
        myRank = state.myRank;
        series = state.series != null && state.series.isOpen() ? state.series : null;
        if (series != null) waitNext = false;
        bye = state.bye;
        breakUntilS = state.breakUntil;
        if (state.gearDeadline > 0) gearUntilS = state.gearDeadline;
        roundEndMs = state.etaS >= 0 ? nowMs.getAsLong() + state.etaS * 1000L : 0L;
        renderActive();
        renderBoard(state.standings);
        resubscribe();
        renderList();
    }

    @Override
    public void onStandings(TourneyBoard standings)
    {
        if (!standings.tournamentId.equals(activeId)) return;
        if (standings.round > 0 && standings.round != round)
        {
            round = standings.round;
            rounds = standings.rounds;
        }
        breakUntilS = standings.breakUntil;
        if (standings.gearDeadline > 0) gearUntilS = standings.gearDeadline;
        roundEndMs = standings.etaS >= 0 ? nowMs.getAsLong() + standings.etaS * 1000L : 0L;
        extendCount = Math.max(0, standings.extended);
        setWrapped(activeHeader, activeName + " · Round " + round + "/" + rounds);
        renderEta();
        renderBoard(standings.rows);
        if (standings.isFinished() || "cancelled".equals(standings.status))
        {
            // the dedicated finished / cancelled pushes drive the exit; the standings just stop moving
            setWrapped(activeEta, standings.isFinished() ? "Final standings" : "Cancelled");
        }
    }

    @Override
    public void onMatchAssigned(MatchSeries s)
    {
        boolean same = s.tournamentId.equals(activeId);
        if (activeId == null)
        {
            activeName = s.tournamentId;
            rounds = 0;
        }
        if (!same) myRank = -1;
        if (!same || s.round > 0) round = s.round;
        activeId = s.tournamentId;
        series = s;
        bye = false;
        waitNext = false;
        breakUntilS = 0L;
        gearUntilS = 0L;
        roundEndMs = s.deadlineAt > 0 ? s.deadlineAt * 1000L : 0L;
        extendCount = 0;
        roundEndBox.setVisible(false);
        showBanner("Round " + s.round + ": you face " + escape(s.opponentName) + " on " + s.worldLabel() + " at " + escape(s.meetingPlace == null ? "the arranged spot" : s.meetingPlace));
        renderActive();
        resubscribe();
        service.status();
    }

    /** The match is over: the card, the world and place lines and the status line go until the next round opens. */
    @Override
    public void onOpponentHighlightClear(String tournamentId, String seriesId)
    {
        if (series == null || !tournamentId.equals(activeId)) return;
        if (seriesId != null && !seriesId.isEmpty() && !seriesId.equals(series.seriesId)) return;
        series = null;
        waitNext = true;
        renderActive();
    }

    @Override
    public void onBye(String tournamentId, int round)
    {
        if (!tournamentId.equals(activeId)) return;
        series = null;
        bye = true;
        waitNext = false;
        extendCount = 0;
        // a bye is a point, never a rated game
        showBanner("Round " + round + ": you have a bye — it counts as a win (no rating change).");
        renderActive();
    }

    @Override
    public void onNoShowRecorded(String tournamentId, String seriesId, long effectiveAtS)
    {
        if (!tournamentId.equals(activeId) || series == null || !seriesId.equals(series.seriesId)) return;
        noShowSid = seriesId;
        noShowAt = effectiveAtS;
        syncNoShow();
    }

    /** Keeps the running event's kit window. */
    @Override
    public void onGearCheck(String tournamentId, int round, long untilEpochS)
    {
        if (!tournamentId.equals(activeId)) return;
        gearUntilS = untilEpochS;
        renderEta();
    }

    @Override
    public void onRoundEndCheck(String tournamentId, int round, String opponentName, long respondByS, String message)
    {
        if (!tournamentId.equals(activeId)) return;
        respondByMs = respondByS > 0 ? respondByS * 1000L : nowMs.getAsLong() + 30_000L;
        String sentence = message == null || message.trim().isEmpty() ? "Submit within 30 seconds or you may be removed." : message.trim();
        wrap(roundEndBox, endTitle(round, opponentName), sentence);
        roundEndBox.setVisible(true);
        showCard(CARD_ACTIVE);
        revalidate();
        repaint();
    }

    static String endTitle(int round, String opponentName)
    {
        String opponent = opponentName.trim().isEmpty() ? "your opponent" : opponentName;
        return "Round " + round + " has ended — your match vs " + opponent + " has no result yet";
    }

    @Override
    public void onRemoved(String tournamentId, String status, String reason, int round)
    {
        String what;
        switch (status)
        {
            case "dq": what = "You were disqualified"; break;
            case "kicked": what = "You were removed by the organizer"; break;
            case "dnf": what = "You were marked DNF"; break;
            case "withdrawn": what = "You withdrew"; break;
            case "dropped_unpaid": what = "You were dropped from the tournament (buy-in not paid)"; break;
            case "dropped_gear": what = null; break;
            default: what = "You were removed";
        }
        if (what == null)
        {
            showBanner("You were removed — your kit didn't match the required set when " + (round > 0 ? "round " + round : "the round") + " started.");
        }
        else
        {
            showBanner(what + (round > 0 ? " in round " + round : "") + (reason.isEmpty() ? "." : " — " + escape(reason) + "."));
        }
        if (mine(tournamentId)) clearActive();
        service.list();
    }

    @Override
    public void onCancelled(String tournamentId, String reason)
    {
        showBanner("Tournament cancelled" + (reason.isEmpty() ? "." : ": " + escape(reason)));
        if (mine(tournamentId)) clearActive();
        service.list();
    }

    /** The finish: the banner, and the final standings stay on screen until Back. */
    @Override
    public void onFinished(String tournamentId, JsonObject winners, List<StandingsRow> standings)
    {
        showBanner("Tournament finished" + winnersText(winners) + placeText(standings, selfNameSupplier.get()));
        if (mine(tournamentId))
        {
            fullId = tournamentId.isEmpty() ? activeId : tournamentId;
            showFinal(standings);
        }
        service.list();
    }

    private void showFinal(List<StandingsRow> standings)
    {
        String name = activeId == null ? null : activeName;
        reset(false);
        setWrapped(activeHeader, name == null ? " " : name);
        setWrapped(activeEta, "Final standings");
        activeMatch.setVisible(false);
        activeWhere.setVisible(false);
        activeStatus.setVisible(false);
        renderBoard(boardPanel, "standings-", standings, false);
        showCard(CARD_ACTIVE);
    }

    /** The winners clause of the finished banner — the placed winners and
     *  the random draw, mirroring the finished message's
     *  "Winners: … · Random draw: …". With an {@code amount_gp} on any winner
     *  the placed ones are numbered and each name carries its amount
     *  ("1. psyop9 - 25M gp"). {@code "."} when nobody is named. */
    static String winnersText(JsonObject winners)
    {
        List<JsonObject> top = named(winners, "top"), drawn = named(winners, "random");
        if (top.isEmpty()) return ".";
        boolean paid = false;
        for (JsonObject w : top) paid |= optWhole(w, "amount_gp") > 0;
        for (JsonObject w : drawn) paid |= optWhole(w, "amount_gp") > 0;
        List<String> placed = new ArrayList<>(), random = new ArrayList<>();
        for (JsonObject w : top) placed.add((paid ? placed.size() + 1 + ". " : "") + winner(w));
        for (JsonObject w : drawn) random.add(winner(w));
        return " — winners: " + String.join(", ", placed) + (random.isEmpty() ? "" : " · random draw: " + String.join(", ", random)) + ".";
    }

    /** The entries of a winners array with a {@code display_name}; non-objects and nameless entries are skipped. */
    private static List<JsonObject> named(JsonObject winners, String key)
    {
        List<JsonObject> out = new ArrayList<>();
        for (JsonElement e : optArray(winners, key)) if (e.isJsonObject() && e.getAsJsonObject().get("display_name") instanceof JsonPrimitive) out.add(e.getAsJsonObject());
        return out;
    }

    /** "psyop9 - 25M gp", or the name alone without a usable {@code amount_gp}. */
    private static String winner(JsonObject w)
    {
        long amount = optWhole(w, "amount_gp");
        return optString(w, "display_name") + (amount > 0 ? " - " + gp(amount) + " gp" : "");
    }

    static String placeText(List<StandingsRow> standings, String selfName)
    {
        String selfKey = NameUtils.canonicalKey(selfName);
        for (StandingsRow r : standings)
        {
            if (r.rank <= 0) continue;
            if (selfKey.equals(NameUtils.canonicalKey(r.displayName)))
            {
                return " You finished #" + r.rank + " with " + pointsText(r.points) + " point" + (r.points == 1.0 ? "" : "s") + ".";
            }
        }
        return "";
    }

    @Override
    public void onProblemAck()
    {
        showBanner("Problem report received — the organizer has been told.");
    }

    @Override
    public void onTournamentError(String code, String message, String cmd)
    {
        if ("tournament/gear_status".equals(cmd)) return;
        String pressed = null;
        if ("tournament/register".equals(cmd))
        {
            pressed = pendingReg;
            pendingReg = null;
        }
        if ("TOURNAMENT_MIN_GAMES".equals(code))
        {
            if (pressed != null)
            {
                gamesRefused.add(pressed);
                renderList();
            }
            return;
        }
        showBanner(friendlyError(code, message));
    }

    /** The banner for an {@code error/tournament}. The server's own sentence for the report gate
     *  ({@code DISCORD_NOT_LINKED}, {@code REPORT_RATE_LIMITED}: discord_tournament_messages
     *  REPORT_LINK_REQUIRED_TEXT / REPORT_RATE_LIMITED_TEXT), a state refusal and an update request. */
    static String friendlyError(String code, String message)
    {
        switch (code)
        {
            case "TOURNAMENT_FULL": return "Tournament full.";
            case "TOURNAMENT_REGISTRATION_CLOSED": return "Registration closed.";
            case "TOURNAMENT_PEAK_OUT_OF_RANGE": return "Your rank is outside this tournament's range.";
            case "TOURNAMENT_ALREADY_REGISTERED": return "You are already registered.";
            case "TOURNAMENT_NOT_REGISTERED": return "You are not registered.";
            case "TOURNAMENT_NOT_FOUND": return "Tournament not found.";
            case "DISCORD_NOT_LINKED":
            case "REPORT_RATE_LIMITED":
            case "TOURNAMENT_STATE":
            case "TOURNAMENT_PLUGIN_UPDATE_REQUIRED": return escape(message);
            default: return "Tournaments: " + (message.isEmpty() ? code : escape(message));
        }
    }

    /** No running event, an id-less push, or this event's push. */
    private boolean mine(String tournamentId)
    {
        return activeId == null || tournamentId.isEmpty() || tournamentId.equals(activeId);
    }

    private void clearActive()
    {
        reset(true);
        boardPanel.removeAll();
        boardPanel.rows.clear();
        showCard(CARD_LIST);
        renderList();
    }

    /** Leaves the running event; {@code live} = the next view is a live one (Report, Rules and Withdraw), else the final
     *  standings (Back). */
    private void reset(boolean live)
    {
        unsubscribe();
        activeId = null;
        series = null;
        bye = false;
        waitNext = false;
        breakUntilS = 0L;
        gearUntilS = 0L;
        roundEndMs = 0L;
        extendCount = 0;
        roundEndBox.setVisible(false);
        dropCard();
        syncNoShow();
        footer(live);
    }

    private void footer(boolean live)
    {
        activePair.setVisible(live);
        withdrawBtn.setVisible(live);
        backBtn.setVisible(!live);
        fullBtn.setVisible(!live);
    }
}

package com.pvp.leaderboard.ui;

import java.awt.*;
import java.awt.event.*;
import java.util.function.*;
import javax.swing.*;
import javax.swing.border.*;

/** Small Swing helpers shared by the side panel's views. */
public final class Ui
{
    private Ui()
    {
    }

    /** {@code c} aligned left in a BoxLayout column. */
    public static <T extends JComponent> T left(T c)
    {
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        return c;
    }

    /** {@code c} with its font derived to {@code style} and {@code pt}. */
    public static <T extends JComponent> T font(T c, int style, float pt)
    {
        c.setFont(c.getFont().deriveFont(style, pt));
        return c;
    }

    public static <T extends JComponent> T bold(T c, float pt)
    {
        return font(c, Font.BOLD, pt);
    }

    public static <T extends JComponent> T plain(T c, float pt)
    {
        return font(c, Font.PLAIN, pt);
    }

    /** {@code c} as wide as its parent allows and at most {@code h} high. */
    public static <T extends JComponent> T maxH(T c, int h)
    {
        c.setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
        return c;
    }

    public static Border pad(int top, int left, int bottom, int right)
    {
        return BorderFactory.createEmptyBorder(top, left, bottom, right);
    }

    /** {@code Box.createVerticalStrut(h)}. */
    public static Component vgap(int h)
    {
        return Box.createVerticalStrut(h);
    }

    /** A vertical strut aligned left, for columns whose other children are. */
    public static Component lgap(int h)
    {
        var s = (Box.Filler) Box.createVerticalStrut(h);
        s.setAlignmentX(Component.LEFT_ALIGNMENT);
        return s;
    }

    /** Runs {@code r} when {@code c} is clicked. */
    public static void onClick(Component c, Runnable r)
    {
        c.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                r.run();
            }
        });
    }

    /** The bucket buttons' labels in bar order; a label's key is its lower case. */
    public static final String[] BUCKETS = {"Overall", "NH", "Veng", "Multi", "DMM", "Tournament"};

    /** A selected bucket button's background. */
    static final Color SELECTED_BG = new Color(60, 60, 60);

    /** The Look-and-Feel label font one point smaller, never under 10 pt. */
    public static Font smallFont()
    {
        Font f = RowTextFit.baseFont();
        return f.deriveFont(Font.PLAIN, Math.max(10f, f.getSize2D() - 1f));
    }

    /** A {@code rows} x {@code cols} grid of bucket buttons named {@code btn};
     *  a click hands the button's key (its lower-case label) to {@code pick}. */
    public static JPanel bucketBar(String name, String btn, int rows, int cols, String[] labels, Consumer<String> pick)
    {
        var bar = new JPanel(new GridLayout(rows, cols, 2, 2));
        bar.setName(name);
        Font small = smallFont();
        for (String l : labels)
        {
            var b = new JButton(l);
            b.setName(btn);
            b.setFont(small);
            b.setMargin(new Insets(2, 2, 2, 2));
            b.setFocusPainted(false);
            String key = l.toLowerCase();
            b.addActionListener(e -> pick.accept(key));
            bar.add(b);
        }
        return bar;
    }

    /** The {@code active} bucket's button white on dark grey, the rest grey on the theme's button colour. */
    public static void styleBucketBar(Container bar, String active)
    {
        for (Component c : bar.getComponents())
        {
            boolean on = ((JButton) c).getText().equalsIgnoreCase(active);
            c.setForeground(on ? Color.WHITE : Color.GRAY);
            c.setBackground(on ? SELECTED_BG : UIManager.getColor("Button.background"));
        }
    }

    /** A modeless dialog centred on {@code c}'s window, disposed when closed. */
    public static JDialog dialog(Component c, String title, int w, int h)
    {
        Window owner = SwingUtilities.getWindowAncestor(c);
        var d = new JDialog(owner, title, Dialog.ModalityType.MODELESS);
        d.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        d.setSize(w, h);
        d.setLocationRelativeTo(owner);
        return d;
    }

    /** A panel never taller than its preferred height, so a BoxLayout column
     *  cannot hand it the column's spare height. */
    public static class CapPanel extends JPanel
    {
        @Override
        public Dimension getMaximumSize()
        {
            return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
        }
    }

    /** A column of rows inside a scroll pane: it tracks the viewport's width
     *  (rows never overflow sideways) and scrolls vertically. */
    public static class RowsPanel extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle r, int o, int d)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle r, int o, int d)
        {
            return o == SwingConstants.VERTICAL ? r.height : r.width;
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }

    // ---- Plan 46 S2 (the Tournaments tab): a shared palette and the helpers below.

    /** Muted grey text. */
    public static final Color MUTED = new Color(0x9a9a9a);
    public static final Color GREEN = new Color(0x3ecf8e);
    public static final Color AMBER = new Color(0xffb347);
    /** A red button's background and its text. */
    public static final Color RED = new Color(0x5a2a2a);
    public static final Color RED_FG = new Color(0xffb3b3);
    /** Light grey body text. */
    public static final Color INFO = new Color(0xdddddd);
    /** The lobby row's card background and the divider under it. */
    public static final Color CARD_BG = new Color(0x2b2b2b);
    public static final Color DIVIDER = Color.DARK_GRAY;
    /** The active tab's underline and the green action buttons. */
    public static final Color ACCENT = new Color(0x2e7d32);

    /** A panel that stacks its children top-down. */
    public static JPanel column()
    {
        var p = new JPanel();
        p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
        return p;
    }

    /** {@code s} with {@code &}, {@code <} and {@code >} as HTML entities; {@code ""} for null. */
    static String escape(String s)
    {
        return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    /** {@code "M:SS"} for {@code seconds}; {@code "0:00"} below zero. */
    static String mmss(long seconds)
    {
        long s = Math.max(0L, seconds);
        return (s / 60) + ":" + String.format(java.util.Locale.ROOT, "%02d", s % 60);
    }

    /** {@code view} in a borderless scroll pane that never scrolls sideways. */
    public static JScrollPane scroll(JComponent view)
    {
        var s = new JScrollPane(view);
        s.setBorder(BorderFactory.createEmptyBorder());
        s.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        return s;
    }

    /** A label named {@code name} (unnamed for null) showing {@code text} at {@code style} / {@code pt}, in {@code fg}
     *  (the look and feel's colour for null). */
    public static JLabel label(String name, String text, int style, float pt, Color fg)
    {
        JLabel l = font(new JLabel(text), style, pt);
        if (name != null) l.setName(name);
        if (fg != null) l.setForeground(fg);
        return l;
    }

    /** {@code l}'s text: {@code text} as {@code <html>} lines wrapped to the side panel's text width at its font. */
    public static void wrap(JLabel l, String... text)
    {
        l.setText(TournamentInfoCard.wrapHtml(l.getFont(), TournamentInfoCard.TEXT_WIDTH, text));
    }

    /** The lobby row's card look: the card background, a divider under 4 / 6 / 6 / 6 padding, aligned left. */
    public static void cardStyle(JComponent c)
    {
        c.setBackground(CARD_BG);
        c.setOpaque(true);
        c.setBorder(BorderFactory.createCompoundBorder(new MatteBorder(0, 0, 1, 0, DIVIDER), pad(4, 6, 6, 6)));
        left(c);
    }

    /** {@code c} as wide as its column allows and no taller than it prefers now. */
    public static <T extends JComponent> T pin(T c)
    {
        return maxH(c, c.getPreferredSize().height);
    }
}

package com.pvp.leaderboard.ui;

import com.google.gson.*;
import java.awt.*;
import java.util.*;
import javax.swing.*;
import java.util.List;
import static com.pvp.leaderboard.util.JsonLenient.*;

/** The Advanced Stats win-rate line. Its size is the dashboard's (200 px
 *  high, the column's width), whatever the number of matches. */
public class WinRateChart extends JPanel
{
    private List<Double> winRates = new ArrayList<>();

    public void setMatches(JsonArray matches)
    {
        winRates = winRatesOf(matches);
        repaint();
    }

    private List<Double> winRatesOf(JsonArray matches)
    {
        List<Double> history = new ArrayList<>();
        if (matches == null || matches.size() == 0) return history;

        // Sort by time ascending
        List<JsonObject> sorted = new ArrayList<>();
        for (int i = 0; i < matches.size(); i++) sorted.add(matches.get(i).getAsJsonObject());
        sorted.sort(Comparator.comparingDouble(m -> optDouble(m, "when", 0)));

        int wins = 0;
        int total = 0;
        for (JsonObject m : sorted)
        {
            String result = optString(m, "result").toLowerCase();
            if ("win".equals(result)) wins++;
            if ("win".equals(result) || "loss".equals(result))
            {
                total++;
                if (total >= 10) // Only show after 10 games to avoid noise
                {
                    history.add((double) wins / total * 100.0);
                }
            }
        }
        return history;
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        super.paintComponent(g);
        var g2 = (Graphics2D) g;
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        int width = getWidth() - 40;
        int height = getHeight() - 40;

        if (width <= 0 || height <= 0) return;

        // Draw axes
        g2.setColor(Color.LIGHT_GRAY);
        g2.drawLine(20, height + 20, width + 20, height + 20);
        g2.drawLine(20, 20, 20, height + 20);

        // Draw grid lines and Y-axis labels
        for (int i = 0; i <= 10; i++)
        {
            int y = 20 + (i * height / 10);
            g2.setColor(Color.GRAY);
            g2.drawLine(20, y, width + 20, y);
            g2.setColor(Color.WHITE);
            g2.drawString((100 - i * 10) + "%", 2, y + 5);
        }

        // Draw X-axis labels and win rate line
        if (winRates.size() > 1)
        {
            // Draw win rate line
            g2.setColor(new Color(0xffd700)); // Gold color
            g2.setStroke(new BasicStroke(2));
            for (int i = 0; i < winRates.size() - 1; i++)
            {
                int x1 = 20 + (i * width / (winRates.size() - 1));
                int y1 = height + 20 - (int)(winRates.get(i) * height / 100);
                int x2 = 20 + ((i + 1) * width / (winRates.size() - 1));
                int y2 = height + 20 - (int)(winRates.get(i + 1) * height / 100);
                g2.drawLine(x1, y1, x2, y2);
            }
        }
        else
        {
            g2.setColor(Color.GRAY);
            g2.drawString("No match data available", width / 2 - 60, height / 2);
        }
    }
}

package com.pvp.leaderboard.util;

import com.google.gson.*;
import java.util.function.*;

/**
 * Null- and type-tolerant readers for server-pushed JSON (Plan 10,
 * 2026-09-21). Every socket push is parsed on OkHttp's read-loop thread,
 * where a {@code ClassCastException} from a missing or re-typed key would
 * be swallowed by the event bus and silently drop the frame; these
 * helpers make a partial payload degrade to a neutral value instead.
 * Shared by the queue and tournament wire adapters.
 */
public final class JsonLenient
{
    private static JsonElement get(JsonObject o, String key)
    {
        return o == null ? null : o.get(key);
    }

    /** {@code read} of the primitive at {@code key}; {@code def} when there is
     *  no object, no such key, JSON null, an object or array, or {@code read}
     *  throws (a string that is not a number). */
    private static <T> T opt(JsonObject o, String key, T def, Function<JsonPrimitive, T> read)
    {
        JsonElement e = get(o, key);
        if (e == null || !e.isJsonPrimitive()) return def;
        try { return read.apply(e.getAsJsonPrimitive()); } catch (RuntimeException ex) { return def; }
    }

    public static String optString(JsonObject o, String key, String def)
    {
        return opt(o, key, def, JsonPrimitive::getAsString);
    }

    /** {@link #optString(JsonObject, String, String)} with {@code ""} for none. */
    public static String optString(JsonObject o, String key)
    {
        return optString(o, key, "");
    }

    public static int optInt(JsonObject o, String key, int def)
    {
        Integer v = optInteger(o, key);
        return v == null ? def : v;
    }

    public static Integer optInteger(JsonObject o, String key)
    {
        return opt(o, key, null, p -> (int) p.getAsDouble());
    }

    public static long optLong(JsonObject o, String key, long def)
    {
        return opt(o, key, def, p -> (long) p.getAsDouble());
    }

    public static double optDouble(JsonObject o, String key, double def)
    {
        return opt(o, key, def, JsonPrimitive::getAsDouble);
    }

    /** A whole JSON number of at least 1; -1 for anything else (a numeric string, a fraction, 0, a boolean, absent). */
    public static long optWhole(JsonObject o, String key)
    {
        double v = opt(o, key, 0.0, p -> p.isNumber() ? p.getAsDouble() : 0.0);
        return v >= 1 && v % 1 == 0 ? (long) v : -1;
    }

    /** A real boolean, or the strings {@code "true"} / {@code "false"}; anything
     *  else (numbers, other strings, arrays) is the default — Gson's own
     *  {@code getAsBoolean()} would silently read {@code "yes"} as false. */
    public static boolean optBool(JsonObject o, String key, boolean def)
    {
        return opt(o, key, def, p ->
        {
            if (p.isBoolean()) return p.getAsBoolean();
            String s = p.getAsString().trim();
            return "true".equalsIgnoreCase(s) || !"false".equalsIgnoreCase(s) && def;
        });
    }

    /** The nested object, or {@code null} when absent / not an object. */
    public static JsonObject optObject(JsonObject o, String key)
    {
        JsonElement e = get(o, key);
        return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
    }

    /** The nested array, or an empty array when absent / not an array. */
    public static JsonArray optArray(JsonObject o, String key)
    {
        JsonElement e = get(o, key);
        return e != null && e.isJsonArray() ? e.getAsJsonArray() : new JsonArray();
    }

    /** The element's text when it is a JSON string, else {@code null} (a number or an object is not text). */
    public static String str(JsonElement e)
    {
        return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
    }
}

package com.pvp.leaderboard.util;

import java.util.*;

public final class NameUtils
{

	public static String normalizeDisplayName(String name)
	{
		if (name == null)
		{
			return "";
		}
		// RuneLite nameplates (Player.getName(), menu targets, chat) separate
		// name words with a NON-BREAKING SPACE (\u00A0). Java's \s does NOT
		// match it (ASCII-only without UNICODE_CHARACTER_CLASS) and trim()
		// does not strip it, so it must be unified to a regular space FIRST —
		// otherwise every multi-word in-scene name fails membership checks
		// and shard lookups against backend-canonical names ("run piggy").
		return name.replace('\u00A0', ' ').trim().replaceAll("\\s+", " ");
	}

	public static String canonicalKey(String name)
	{
		String display = normalizeDisplayName(name);
		// Treat names case-insensitively for lookups, caching and API queries
		return display.toLowerCase(Locale.ROOT);
	}
}

package com.pvp.leaderboard.util;

import java.util.*;

/**
 * The backend's Overall rating, mirrored for the tier graph's locally
 * computed "Overall" history (parity gap G-16, operator decision
 * 2026-09-22). Keep in step with {@code backend/core/buckets.py}
 * ({@code STANDARD_WEIGHTS}, {@code TOURNAMENT_WEIGHT},
 * {@code with_tournament}, {@code missing_overrides}) and
 * {@code backend/core/mmr.compute_overall_with_tournament} — the same
 * obligation {@link RankUtils} carries for the rank thresholds.
 *
 * <p>The formula is a plain weighted SUM, never normalised: the four
 * standard buckets at {@code nh 0.55 / veng 0.30 / multi 0.05 / dmm 0.10}
 * (a bucket with no rating counts as {@link #DEFAULT_MU}), plus
 * {@code 0.10 × tournament} <b>on top</b> of that 100 %. The tournament
 * term exists only once the player has a tournament match — on the
 * backend a sign-up seed alone contributes nothing, and locally there is
 * no seed at all, only match points — so a history with no tournament
 * game keeps exactly the legacy Overall.
 *
 * <p>An accumulator ({@link #record}, {@link #overall()}) that walks a
 * match history in order.
 */
public final class OverallMmr
{
    public static final String TOURNEY_KEY = "tournament";
    public static final double DEFAULT_MU = 1000.0;
    public static final double TOURNAMENT_WEIGHT = 0.10;

    /** {@code nh 0.55 / veng 0.30 / multi 0.05 / dmm 0.10}, summed in that order. */
    private static final String[] STANDARD = {"nh", "veng", "multi", "dmm"};
    private static final double[] WEIGHTS = {0.55, 0.30, 0.05, 0.10};

    private final Map<String, Double> lastMu = new HashMap<>();

    /** The five buckets a match can be rated in (case-insensitive). */
    public static boolean isRated(String bucket)
    {
        String b = key(bucket);
        return TOURNEY_KEY.equals(b) || Arrays.asList(STANDARD).contains(b);
    }

    /** The last recorded mu for the bucket, {@code null} when none was —
     *  a standard bucket then counts as 1000, the tournament bucket as
     *  nothing. */
    public Double lastMu(String bucket)
    {
        return lastMu.get(key(bucket));
    }

    /** Records a match's post-game mu; ignored for a bucket the formula
     *  does not know or a non-finite value. */
    public void record(String bucket, double mu)
    {
        String b = key(bucket);
        if (isRated(b) && Double.isFinite(mu)) lastMu.put(b, mu);
    }

    /** The Overall of everything recorded so far: a standard bucket with no
     *  record counts as 1000, a tournament bucket with none contributes
     *  nothing. */
    public double overall()
    {
        double sum = 0.0;
        for (int i = 0; i < 4; i++)
        {
            Double mu = lastMu.get(STANDARD[i]);
            sum += (mu == null ? DEFAULT_MU : mu) * WEIGHTS[i];
        }
        Double tournament = lastMu.get(TOURNEY_KEY);
        if (tournament != null) sum += tournament * TOURNAMENT_WEIGHT;
        return sum;
    }

    private static String key(String bucket)
    {
        if (bucket == null) return null;
        String b = bucket.trim().toLowerCase(Locale.ROOT);
        return b.isEmpty() ? null : b;
    }
}

package com.pvp.leaderboard.util;

import com.google.gson.*;
import com.pvp.leaderboard.service.*;
import java.awt.*;
import java.util.*;
import static java.lang.Math.*;

public class RankUtils
{
    private static final Map<String, Color> RANK_COLORS = new HashMap<>();

    public static final String[][] THRESHOLDS = {
        {"Bronze", "3", "0"}, {"Bronze", "2", "170"}, {"Bronze", "1", "240"},
        {"Iron", "3", "310"}, {"Iron", "2", "380"}, {"Iron", "1", "450"},
        {"Steel", "3", "520"}, {"Steel", "2", "590"}, {"Steel", "1", "660"},
        {"Black", "3", "730"}, {"Black", "2", "800"}, {"Black", "1", "870"},
        {"Mithril", "3", "940"}, {"Mithril", "2", "1010"}, {"Mithril", "1", "1080"},
        {"Adamant", "3", "1150"}, {"Adamant", "2", "1250"}, {"Adamant", "1", "1350"},
        {"Rune", "3", "1450"}, {"Rune", "2", "1550"}, {"Rune", "1", "1650"},
        {"Dragon", "3", "1750"}, {"Dragon", "2", "1850"}, {"Dragon", "1", "1950"},
        {"3rd Age", "0", "2100"}
    };

    static
    {
        RANK_COLORS.put("Bronze", new Color(0xb87333));
        RANK_COLORS.put("Iron", Color.LIGHT_GRAY);
        RANK_COLORS.put("Steel", new Color(154, 162, 166));
        RANK_COLORS.put("Black", Color.GRAY);
        RANK_COLORS.put("Mithril", new Color(98, 104, 199));
        RANK_COLORS.put("Adamant", new Color(26, 139, 111));
        RANK_COLORS.put("Rune", new Color(78, 159, 227));
        RANK_COLORS.put("Dragon", new Color(0xe53935));
        RANK_COLORS.put("3rd", Color.WHITE);
    }

    /** The colour of a rank label's first word (the rank family); grey when unknown. */
    public static Color getRankColor(String rankName)
    {
        return RANK_COLORS.getOrDefault(rankName == null ? null : rankName.split(" ")[0], new Color(0x666666));
    }

    public static String formatTier(String raw)
    {
        if (raw == null) return null;
        String s = raw.trim();
        if (s.equalsIgnoreCase("3rdAge")) return "3rd Age";
        return s.replaceAll("([A-Za-z]+)(\\d+)$", "$1 $2");
    }

    /** Maps a backend tier string (e.g. {@code "Adamant2"}, {@code "3rdAge"})
     *  to its index in {@link #THRESHOLDS}, or {@code -1} if the tier
     *  doesn't match any known threshold. Used by the lobby gate to
     *  surface the local player's rank in their own self-profile
     *  preview row.
     *
     *  <p>Tolerates both compact ({@code "Adamant2"}) and spaced
     *  ({@code "Adamant 2"}) forms by normalising via
     *  {@link #formatTier(String)} first. Comparison is
     *  case-insensitive on the rank-family name and exact on the
     *  division number — a malformed input returns {@code -1} rather
     *  than guessing. 3rd Age (division "0" in THRESHOLDS) also matches
     *  in its single-token form. */
    public static int indexOfTier(String raw)
    {
        String f = raw == null ? null : formatTier(raw);
        for (int i = 0; f != null && i < THRESHOLDS.length; i++)
        {
            String[] t = THRESHOLDS[i];
            if (f.equalsIgnoreCase(t[0] + " " + t[1]) || "0".equals(t[1]) && f.equalsIgnoreCase(t[0]))
            {
                return i;
            }
        }
        return -1;
    }

    /** True for no object, and for the default initialization (Bronze 3 at 0 MMR) - not a real rank. */
    public static boolean isUnranked(JsonObject obj)
    {
        if (obj == null) return true;
        double mmr = obj.has("mmr") && !obj.get("mmr").isJsonNull() ? obj.get("mmr").getAsDouble() : 0.0;
        String rank = obj.has("rank") && !obj.get("rank").isJsonNull() ? obj.get("rank").getAsString() : "";
        int div = obj.has("division") && !obj.get("division").isJsonNull() ? obj.get("division").getAsInt() : 0;
        return abs(mmr) < 0.001 && "Bronze".equalsIgnoreCase(rank) && div == 3;
    }

    /** The THRESHOLDS index of {@code mmr}: the highest threshold at or
     *  below it; Bronze 3 (0) below zero. */
    private static int tierIdx(double mmr)
    {
        int k = 0;
        while (k < 24 && mmr >= Double.parseDouble(THRESHOLDS[k + 1][2]))
        {
            k++;
        }
        return k;
    }

    /** How far {@code mmr} is from tier {@code k} (below 3rd Age, index 24) to
     *  the next, as a fraction of the span: 0 at the tier, 1 at the next. */
    private static double frac(double mmr, int k)
    {
        double c = Double.parseDouble(THRESHOLDS[k][2]);
        return (mmr - c) / (Double.parseDouble(THRESHOLDS[k + 1][2]) - c);
    }

    public static RankInfo toRankInfo(double mmrVal)
    {
        // Do not arbitrarily treat 0 as null; 0 is a valid MMR (Bronze 3).
        // The caller is responsible for determining if data is missing (e.g. JSON missing "mmr" field).
        int k = tierIdx(mmrVal);
        return new RankInfo(THRESHOLDS[k][0], Integer.parseInt(THRESHOLDS[k][1]),
            k == 24 ? 100 : max(0, min(100, frac(mmrVal, k) * 100)));
    }

    // Encode MMR to rank-scale value (the THRESHOLDS index + progress to the next)
    // Returns 0.0 to 24.0
    public static double tierValueOf(double mmr)
    {
        int k = tierIdx(mmr);
        return k == 24 ? k : k + max(0.0, min(1.0, frac(mmr, k)));
    }

    /** Sort key of a "Family Division" label: the family's order (Bronze 0 to
     *  3rd Age 8, -1 unknown) x 10, plus 4 - division. */
    public static int getRankOrder(String rank)
    {
        String[] parts = rank.split(" ");
        int division = parts.length > 1 ? Integer.parseInt(parts[1]) : 0;
        int order = -1;
        for (int i = 0; i < 9; i++)
        {
            if (THRESHOLDS[i * 3][0].equals(parts[0]))
            {
                order = i;
            }
        }
        return order * 10 + (4 - division);
    }

    /**
     * Total population recorded in a rank histogram artifact
     * ({@code rank_hist/<bucket>.json}, produced by the infra-side
     * {@code backend/core/rank_histogram.py}). Returns {@code 0} for a
     * {@code null}, empty, or malformed histogram (all of which throw
     * below) so callers can render "No one yet" without special-casing
     * failures.
     */
    public static long histTotal(JsonObject hist)
    {
        try
        {
            return max(0L, hist.get("total").getAsLong());
        }
        catch (RuntimeException e)
        {
            return 0L;
        }
    }

    /**
     * Number of players whose MMR is at or above {@code mmrThreshold},
     * read from the cumulative histogram's {@code bins} array. Each bin is
     * {@code [floor, count, count_above]} sorted ascending by floor, where
     * {@code count_above} is the population of all strictly-higher bins.
     *
     * <p>Because every rank cutoff in {@link #THRESHOLDS} is a multiple of
     * the 10-MMR bin width, a threshold always lands on a bin boundary —
     * so the first bin whose floor is {@code >= mmrThreshold} gives an
     * exact at-or-above count of {@code count + count_above}. Malformed
     * rows and missing/empty histograms degrade to {@code 0}.
     */
    public static long totalAbove(JsonObject hist, double mmrThreshold)
    {
        for (JsonElement el : JsonLenient.optArray(hist, "bins"))
        {
            try
            {
                JsonArray bin = el.getAsJsonArray();
                if (bin.get(0).getAsDouble() >= mmrThreshold)
                {
                    return max(0L, bin.get(1).getAsLong() + bin.get(2).getAsLong());
                }
            }
            catch (RuntimeException e)
            {
                // Skip a corrupt row (not an array, short, or a bad value)
                // rather than failing the whole lookup.
            }
        }
        return 0L;
    }

    /**
     * Human-readable "Top X%" label for a tier, given how many players are
     * at or above that tier and the total population. Returns
     * {@code "No one yet"} when the tier is empty (or the population is
     * unknown), matching the "What are the ranks" design.
     *
     * <p>The empty-tier label is kept short on purpose: it's the widest
     * string in that view, and the view sizes all 25 rows to fit its
     * widest row, so every extra character shrinks every rank name on
     * screen. The previous "No one currently here" cost ~5pt across the
     * whole list.
     *
     * <p>Precision scales with the magnitude so the exclusive top tiers stay
     * legible: whole numbers at/above 10%, one decimal in {@code [1%, 10%)},
     * two decimals below 1% (e.g. {@code "Top 0.01%"}), and {@code "Top
     * <0.01%"} for a share too small to show at two decimals.
     */
    public static String formatTopPercent(long aboveCount, long total)
    {
        if (total <= 0L || aboveCount <= 0L)
        {
            return "No one yet";
        }
        double pct = (double) aboveCount / (double) total * 100.0;
        if (pct >= 10.0)
        {
            return "Top " + String.format(Locale.US, "%.0f%%", pct);
        }
        if (pct >= 1.0)
        {
            return "Top " + String.format(Locale.US, "%.1f%%", pct);
        }
        return formatTopPercentPrecise(aboveCount, total);
    }

    /**
     * Fixed two-decimal "Top X.XX%" used by the Player Lookup ratings, where
     * the user wants a consistent precision per rating (unlike
     * {@link #formatTopPercent}'s magnitude-scaled precision used by the
     * rank-tier explainer). Returns {@code null} when the share can't be
     * determined (no/zero total, or the player isn't counted) so the caller
     * can simply omit the suffix rather than print a misleading value. A
     * non-zero share that rounds below 0.01% renders {@code "Top <0.01%"}.
     *
     * @param aboveCount players at or above the player's MMR (inclusive)
     * @param total          bucket population from the histogram
     */
    public static String formatTopPercentPrecise(long aboveCount, long total)
    {
        if (total <= 0L || aboveCount <= 0L)
        {
            return null;
        }
        double pct = (double) aboveCount / (double) total * 100.0;
        if (pct > 100.0)
        {
            pct = 100.0;
        }
        String twoDp = String.format(Locale.US, "%.2f", pct);
        if ("0.00".equals(twoDp))
        {
            return "Top <0.01%";
        }
        return "Top " + twoDp + "%";
    }
}

package com.pvp.leaderboard.util;

import java.time.*;
import java.time.format.*;
import java.time.temporal.*;
import java.util.*;

/**
 * Discord-style timestamps for the side panel (operator decision
 * 2026-09-22): an epoch the server already sends is rendered the way a
 * Discord {@code <t:X:f>} / {@code <t:X:R>} pair renders — in the viewer's
 * own zone, with a relative phrase that the caller re-renders on its
 * existing tick — so a "registration closes in N minutes" never has to be
 * pushed and never goes stale.
 *
 * <p>Pure: the zone and "now" are arguments (the panel passes its injected
 * clock), so the same epoch renders identically in a test and in game.
 * A {@code null}, zero or negative epoch renders nothing.
 *
 * <p>The relative ladder is moment.js {@code fromNow} (what a Discord
 * {@code <t:X:R>} renders), with compact units for a 240 px panel. Each
 * unit is rounded half-up first, then: {@code < 45 s} "in a moment" /
 * "just now" · minutes {@code <= 1} "1 min" · minutes {@code < 45}
 * "N min" · hours {@code <= 1} "1 h" · hours {@code < 22} "N h" · days
 * {@code <= 1} "1 day" · days {@code < 26} "N days" · months {@code <= 1}
 * "1 month" · months {@code < 11} "N months" · years {@code <= 1}
 * "1 year" · else "N years". So the switches fall at 45 s, 90 s,
 * 44.5 min, 90 min, 21.5 h, 36 h, 25.5 days, ~45.7 days (a month is
 * 30.44 days), ~320 days and ~548 days.
 */
public final class TimeText
{
    private static final DateTimeFormatter SAME_YEAR = DateTimeFormatter.ofPattern("EEE d MMM HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter OTHER_YEAR = DateTimeFormatter.ofPattern("EEE d MMM yyyy HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter ZONE = DateTimeFormatter.ofPattern("zzz", Locale.ENGLISH);

    private static final long MINUTE = 60L;
    private static final long HOUR = 60L * MINUTE;
    private static final long DAY = 24L * HOUR;
    /** moment.js: 146097 days per 4800 months. */
    private static final double MONTH = 146097.0 / 4800.0 * DAY;
    private static final double YEAR = 365.25 * DAY;

    /** {@code <t:X:f>} in the viewer's zone: {@code "today 19:00"},
     *  {@code "tomorrow 09:30"}, {@code "yesterday 23:59"},
     *  {@code "Thu 24 Sep 19:00"}, or with the year when it differs from
     *  now's ({@code "Fri 1 Jan 2027 00:00"}). {@code ""} for no epoch. */
    public static String local(Long epochS, ZoneId zone, long nowMs)
    {
        if (epochS == null || epochS <= 0L) return "";
        ZoneId z = zone == null ? ZoneId.systemDefault() : zone;
        ZonedDateTime target = Instant.ofEpochSecond(epochS).atZone(z);
        ZonedDateTime now = Instant.ofEpochMilli(nowMs).atZone(z);
        long dayDiff = ChronoUnit.DAYS.between(now.toLocalDate(), target.toLocalDate());
        if (dayDiff == 0) return "today " + TIME.format(target);
        if (dayDiff == 1) return "tomorrow " + TIME.format(target);
        if (dayDiff == -1) return "yesterday " + TIME.format(target);
        return (target.getYear() == now.getYear() ? SAME_YEAR : OTHER_YEAR).format(target);
    }

    /** {@code <t:X:R>}: {@code "in 12 min"}, {@code "3 h ago"},
     *  {@code "in 3 days"}, {@code "in a moment"} / {@code "just now"}
     *  inside 45 s. {@code ""} for no epoch. */
    public static String relative(Long epochS, long nowMs)
    {
        if (epochS == null || epochS <= 0L) return "";
        long deltaS = epochS - Math.floorDiv(nowMs, 1000L);
        boolean future = deltaS >= 0;
        long d = Math.abs(deltaS);
        if (d < 45) return future ? "in a moment" : "just now";
        long minutes = round(d, MINUTE), hours = round(d, HOUR), days = round(d, DAY), months = round(d, MONTH), years = round(d, YEAR);
        String unit;
        if (minutes <= 1) unit = "1 min";
        else if (minutes < 45) unit = minutes + " min";
        else if (hours <= 1) unit = "1 h";
        else if (hours < 22) unit = hours + " h";
        else if (days <= 1) unit = "1 day";
        else if (days < 26) unit = days + " days";
        else if (months <= 1) unit = "1 month";
        else if (months < 11) unit = months + " months";
        else if (years <= 1) unit = "1 year";
        else unit = years + " years";
        return future ? "in " + unit : unit + " ago";
    }

    /** {@link #local} + {@code " · "} + {@link #relative}, e.g.
     *  {@code "Thu 24 Sep 19:00 · in 3 days"}. {@code ""} for no epoch. */
    public static String describe(Long epochS, ZoneId zone, long nowMs)
    {
        if (epochS == null || epochS <= 0L) return "";
        return local(epochS, zone, nowMs) + " · " + relative(epochS, nowMs);
    }

    /** {@code "23:05"}: {@code epochS} on a 24-hour clock in {@code zone}. */
    public static String hhmm(long epochS, ZoneId zone)
    {
        return TIME.format(Instant.ofEpochSecond(epochS).atZone(zone));
    }

    /** The zone's short name at {@code t} ({@code "EDT"}, {@code "EST"}), or its offset
     *  ({@code "GMT+03:00"}) when it has none. */
    public static String zone(ZonedDateTime t)
    {
        return ZONE.format(t);
    }

    private static long round(long seconds, double unitSeconds)
    {
        return Math.round(seconds / unitSeconds);
    }
}

